// The defect, and beside it the move that keeps a commit nobody pushed.
declare function git(...args: string[]): Promise<boolean>;
declare const branch: string;
declare const base: string;

await git("checkout", "-B", branch, `origin/${base}`);
await git("checkout", branch) && git("merge", "--ff-only", `origin/${branch}`);

export {};

// The defect, and beside it the fold that says what empty means.
type Approval = { approved: boolean };
export const approved = (approvals: Approval[]) => approvals.every((a) => a.approved);
export const reviewed = (approvals: Approval[]) => approvals.length > 0 && approvals.every((a) => a.approved);

// The defect in a fold, and beside it a decision, where the same read is right.
export const decide = {
  received: (record: { state: string }) => (record.state === "received" ? "advance" : "settled"),
};
export const remember = (record: { state: string; paged?: boolean }) =>
  record.state === "received" ? { ...record, paged: true } : record;

