import fs from "node:fs";
import path from "node:path";
import { CommandRunner, type ConfigSchema, Mounted, Plugin, mountedActions } from "@amykit/core";
import { classify } from "./spec.js";
import { PLUGINS_ROOT_FLAGS, packageManager, shellCommand } from "./install.js";
import { drawn } from "./drawn.js";
import {
  Forked,
  NEVER_FORKED,
  SourceAt,
  buildFork,
  forkPlace,
  gitDirectory,
  installProfileRoot,
  profileForkDirectories,
  sourceOfManifest,
  takeFork,
} from "./fork.js";
import { paths } from "./paths.js";
import { Profile } from "./profiles.js";

/**
 * What one spec argument turns into, when the point is adding it.
 *
 * The one decision `classify` leaves to its caller: for a git URL and a
 * tarball, the name the config will carry is not knowable until the package
 * is on disk. Reading the installed manifest is not a second classification
 * but the same one, finished — the shape npm accepted said what it took, and
 * the manifest says what it turned out to be called.
 */
export interface Picked {
  kind: "name" | "range" | "git" | "tarball" | "path";
  /** The string npm installs. */
  readonly install: string;
  /** The string the config names, once the package is on disk. */
  readonly imported: string;
  /** The directory the package landed in, when one was named. */
  readonly absolute?: string;
}

/** The profile key a workflow package contributes when `amy add` writes it. */
export function workflowProfileName(imported: string): string {
  return path.parse(imported).name.replace(/^workflow-/, "");
}

/** Refuses a new workflow that would overwrite another workflow's profile. */
export function workflowProfileConflict(
  workflows: Readonly<Record<string, { workflow: string }>>,
  imported: string,
): string | undefined {
  const profile = workflowProfileName(imported);
  const existing = workflows[profile];
  return existing && existing.workflow !== imported
    ? `the workflow profile \`${profile}\` already names ${existing.workflow}`
    : undefined;
}

/**
 * Decides what a spec argument is, and what each form becomes.
 *
 * A name is already its own imported form. A path spec is resolved now, so a
 * package that is not one is refused before anything is run; what the config
 * carries for it is the *name* the package declares, read off its own
 * manifest — a URL into the directory would make the config mean one place
 * on one machine, and the package is a name to any other. The directory is
 * the import: the loader passes it to `import()` as itself, and a directory
 * is not something `import()` takes.
 *
 * A git URL and a tarball defer to the manifest the install writes.
 */
export function whatPackageIs(spec: string, cwd: string, _root: string): Picked {
  const resolved = classify(spec, cwd);

  if (resolved.kind === "git" || resolved.kind === "tarball") {
    // Before installation there is no manifest to read. Keep the name blank;
    // `nameInstalledPackage` fills it from the package npm just added.
    return { kind: resolved.kind, install: resolved.install, imported: "" };
  }

  if (resolved.kind === "path") {
    const directory = resolved.absolute!;
    const name = manifestName(directory) ?? path.basename(directory);
    return { kind: "path", install: directory, imported: name, absolute: directory };
  }

  return { kind: resolved.kind, install: resolved.install, imported: resolved.imported! };
}

/** The name a package on this disk declares, by its manifest. */
function manifestName(directory: string): string | undefined {
  try {
    const manifest = JSON.parse(fs.readFileSync(path.join(directory, "package.json"), "utf-8")) as {
      name?: string;
    };
    return typeof manifest.name === "string" ? manifest.name : undefined;
  } catch {
    return undefined;
  }
}

/** Every package a private npm root holds, including a direct package's dependencies. */
export function installedPackageNames(root: string): string[] {
  return packageNamesOnDisk(root);
}

/**
 * The direct package an install wrote, read off the root's manifest.
 *
 * A git or tarball package can bring dependencies, and npm may hoist those
 * alongside it. The root manifest is npm's declaration of which package was
 * requested directly; intersecting it with the complete pre-install snapshot
 * distinguishes that package from its newly written dependencies.
 */
export function nameInstalledPackage(root: string, before: readonly string[]): string {
  const added = new Set(packageNamesOnDisk(root).filter((name) => !before.includes(name)));
  const direct = packageNamesInManifest(root).filter((name) => added.has(name));
  if (direct.length !== 1) throw new Error(`the install did not add one direct package amy can name`);
  return direct[0]!;
}

/** The names the private root itself asks npm to install. */
function packageNamesInManifest(root: string): string[] {
  try {
    const manifest = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf-8")) as Record<string, unknown>;
    const names = new Set<string>();
    for (const field of ["dependencies", "devDependencies", "optionalDependencies"]) {
      const dependencies = manifest[field];
      if (typeof dependencies !== "object" || dependencies === null || Array.isArray(dependencies)) continue;
      for (const name of Object.keys(dependencies)) names.add(name);
    }
    return [...names];
  } catch {
    return [];
  }
}

function packageNamesOnDisk(root: string): string[] {
  const nodeModules = path.join(root, "node_modules");
  const names: string[] = [];
  for (const entry of read(nodeModules)) {
    if (entry.startsWith("@")) {
      for (const inner of read(path.join(nodeModules, entry))) names.push(`${entry}/${inner}`);
    } else if (!entry.startsWith(".")) {
      names.push(entry);
    }
  }
  return names.filter((name) => {
    try {
      return JSON.parse(fs.readFileSync(path.join(nodeModules, ...name.split("/"), "package.json"), "utf-8")) !== null;
    } catch {
      return false;
    }
  });
}

/** Returns nothing rather than throwing: a directory that is not there is an answer. */
function read(directory: string): string[] {
  try {
    return fs.readdirSync(directory);
  } catch {
    return [];
  }
}

/**
 * Imports one package by what the config will carry, through the resolver.
 *
 * `load()` is the boot-time loader over a whole config, and a refusal there
 * is a boot refusal — a machine that cannot start. Adding a package is not
 * booting: the import runs before the config names anything, so its failure
 * is a command refusal, and the loader's "not installed" sentinel would read
 * as one.
 */
export async function importPluginBySpec(
  imported: string,
  resolve: (spec: string) => string,
): Promise<{ ok: true; plugin: Plugin } | { ok: false; problem: string }> {
  try {
    const specifier = resolve(imported);
    const module = (await import(specifier)) as { plugin?: Plugin };
    if (!module.plugin) return { ok: false, problem: `${imported}: imported, but exports no \`plugin\`` };
    // The boot resolves the same import through `drawn`, which shapes the
    // plugin by the `workflow.mmd` beside the entry. The probe mounts what
    // the boot would mount, so a workflow whose shape lives in a diagram
    // cannot be judged by a shapeless stand-in of itself.
    return { ok: true, plugin: drawn(module.plugin, specifier) };
  } catch (error) {
    const why = error instanceof Error ? error.message : String(error);
    return { ok: false, problem: `${imported}: could not be imported — ${why}` };
  }
}

/**
 * Whether this package registers a workflow, asked the way the boot asks.
 *
 * `mount()` answers this at boot, but a boot needs every port the workflow
 * needs mounted by somebody — and the package being added is the thing that
 * would bring them, written by this very command after the answer. So the
 * probe runs `register` once against a registry and a context of stand-ins:
 * the registry marks what the plugin says it is, and the context answers any
 * port with one whose every method answers, so a workflow that is waiting on
 * its providers still says what it is without mounting a machine that does
 * not exist. Nothing the register builds is ever run: the runners are the
 * ones a mount never uses, and the state paths are a throwaway.
 */
export async function whatMountingSays(
  plugin: Plugin,
  home: string,
): Promise<{ ok: true; workflow: boolean } | { ok: false; problems: string[] }> {
  const throwaway = path.join(home, "add-probe");
  let workflow = false;
  try {
    // No method on the registry refuses: the whole machine with its one
    // workflow is what the boot check judges after the write, and a package
    // that would refuse there is refused there, rolled back with it.
    const registry = new Proxy({}, { get: (_, method) => (method === "workflow" ? () => { workflow = true; } : () => {}) });
    // A port whose methods answer functions: a need that requires methods is
    // satisfied shape-wise, and the implementations are never called.
    const portStub = new Proxy({}, { get: (_, method) => (typeof method === "string" ? async () => undefined : undefined) });
    const ctx = {
      // The configuration a shipped install would hand the register: the
      // defaults its schema fills in, and a stand-in of the right shape for
      // what it requires. The register reads configuration to build runners
      // — a notifier that counts `ctx.config.models.length` during
      // registration dies on an empty map, not on a real missing setting.
      config: standInConfig(plugin.configSchema),
      // Registration is inspected, not booted.  Give executable probes a
      // compatible shape so a plugin can describe its contributions here;
      // the real post-install boot still executes its actual compatibility
      // check against the operator's executable.
      runner: { run: async (command: string) => ({
        ok: true,
        exitCode: 0,
        stdout: command === "codex" ? "codex-cli 0.166.0" : "",
        stderr: "",
      }) },
      now: () => new Date(),
      log: undefined,
      paths: { state: throwaway },
      contributions: () => new Map<string, object>(),
      port: () => portStub,
      workflow: () => undefined,
      workflowPort: () => undefined,
      checkouts: () => portStub,
    };
    await plugin.register(registry as never, ctx as never);
    return { ok: true, workflow };
  } catch (error) {
    return { ok: false, problems: [`${plugin.name}: failed to register — ${error instanceof Error ? error.message : String(error)}`] };
  } finally {
    fs.rmSync(throwaway, { recursive: true, force: true });
  }
}

/**
 * The configuration the register meets: what the schema defaults, plus a
 * shapeless stand-in for each required leaf. A stand-in answers "a value of
 * the type asked for" and nothing more — the probe judges whether the
 * register works, not whether a setting's value does.
 */
function standInConfig(schema: ConfigSchema | undefined): Record<string, unknown> {
  if (schema === undefined) return {};
  const config: Record<string, unknown> = {};
  for (const [dotted, spec] of Object.entries(schema)) {
    const value = spec.default !== undefined ? spec.default : spec.required ? standin[spec.type] : undefined;
    if (value === undefined) continue;
    const path = dotted.split(".");
    const leaf = path.pop()!;
    let node = config;
    for (const segment of path) {
      const existing = node[segment];
      if (!isRecord(existing)) node[segment] = {};
      node = node[segment] as Record<string, unknown>;
    }
    node[leaf] = value;
  }
  return config;
}

const standin = {
  string: "",
  number: 0,
  boolean: false,
  "string[]": [],
  record: {},
} as const;

/** Whether a value is a mapping a dotted path can be written into. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export interface BootCheck {
  ok: boolean;
  /** The mount's own refusals, named. */
  problems: string[];
  /** What the machine would carry, when it comes up. */
  mounted?: Mounted;
}

/**
 * Whether the install the config would become still boots, and what the
 * machine would leave unmounted when it does not.
 *
 * The same question `assemble()` answers for a tick, asked on demand: the
 * probe above mounts one package alone, and a package that mounts alone can
 * still take a port the rest of the machine was contributing — a removal the
 * machine cannot survive is found here, before the config is touched.
 */
export async function whatBoots(
  assemble: () => Promise<BootCheck>,
): Promise<BootCheck> {
  return assemble();
}

/**
 * The missing port a removal would leave behind, named the way the mount
 * names it.
 *
 * `unmetNeeds` names an action and the port nothing mounted; this is what the
 * `remove` command prints, so the operator reads which action the remaining
 * workflow would lose the port for — the refusal the boot writes, moved to
 * the moment somebody can still change their mind.
 */
export function unmetAction(mounted: Mounted, unmet: readonly string[]): string {
  const actions = mounted.workflow ? mountedActions(mounted, mounted.workflow) : [];
  const named = unmet.find((problem) => actions.some((action) => problem.includes(`\`${action}\``)));
  return named ?? unmet[0] ?? "nothing is missing";
}

/**
 * Removes packages from amy's npm root even when npm accepts `file:` but
 * silently leaves it in the manifest. npm 10's uninstall is not an inverse
 * for that form, so make the manifest authoritative and let prune/install
 * rebuild both node_modules and the lock from it.
 */
export async function uninstallFromPluginsRoot(
  runner: CommandRunner,
  root: string,
  packages: readonly string[],
): Promise<{ ok: boolean; command: string; output: string }> {
  const manifest = path.join(root, "package.json");
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(fs.readFileSync(manifest, "utf-8")) as Record<string, unknown>;
  } catch (error) {
    return {
      ok: false,
      command: "",
      output: `could not read ${manifest}: ${error instanceof Error ? error.message : String(error)}`,
    };
  }

  for (const field of ["dependencies", "devDependencies", "optionalDependencies"] as const) {
    const dependencies = parsed[field];
    if (typeof dependencies !== "object" || dependencies === null || Array.isArray(dependencies)) continue;
    for (const name of packages) delete (dependencies as Record<string, unknown>)[name];
  }
  fs.writeFileSync(manifest, `${JSON.stringify(parsed, null, 2)}\n`, "utf-8");

  const pruneArgs = ["prune", "--prefix", root, ...PLUGINS_ROOT_FLAGS];
  const installArgs = ["install", "--prefix", root, ...PLUGINS_ROOT_FLAGS];
  const command = [shellCommand(packageManager(), pruneArgs), shellCommand(packageManager(), installArgs)].join(" && ");
  const prune = await runner.run(packageManager(), pruneArgs, { timeoutMs: 10 * 60 * 1000 });
  if (!prune.ok) return { ok: false, command, output: outputOf(prune) };

  const install = await runner.run(packageManager(), installArgs, { timeoutMs: 10 * 60 * 1000 });
  return { ok: install.ok, command, output: [outputOf(prune), outputOf(install)].filter(Boolean).join("\n") };
}

function outputOf(result: { stdout: string; stderr: string }): string {
  return [result.stdout, result.stderr].filter(Boolean).join("\n").trim();
}

/** What remains of the config's names after one goes, so the caller can refuse the one that breaks. */
export function withoutSpec(specs: readonly string[], spec: string): string[] {
  return specs.filter((name) => name !== spec);
}
export interface ForkAdd {
  readonly runner: CommandRunner;
  readonly home: string;
  readonly profile: Profile;
  /** What the profile mounts once the fork is in, so what imports it lands beside it. */
  readonly specs: readonly string[];
  readonly spec: string;
  readonly cwd: string;
  /** The directory forks go into, from `--to`, then the config's `forks`. */
  readonly to?: string;
  readonly forks?: string;
}

/**
 * Where a spec's source is (S12): a git URL that names a directory is its own
 * answer and reaches no registry; a package name is read off the copy the
 * machine has installed, or asked of the registry when it has none, and its
 * `repository` field says the rest.
 */
async function forkSource(options: ForkAdd): Promise<SourceAt> {
  const resolved = classify(options.spec, options.cwd);
  if (resolved.kind === "git") {
    const at = gitDirectory(options.spec);
    if (!at) throw new Error(`${options.spec} names a repository, not a directory of one: fork it as <url>#path:<directory>, or <url>#<ref>&path:<directory>`);
    return at;
  }
  if (resolved.kind === "path" || resolved.kind === "tarball") {
    throw new Error(`${options.spec} is not forked: a fork is taken from a package's repository, and a ${resolved.kind} is source you already hold`);
  }
  const name = resolved.imported!;
  if ((NEVER_FORKED as readonly string[]).includes(name)) throw new Error(`${name} is not forked: it resolves from amy's own install in every profile`);
  const installed = resolved.kind === "name" ? installedManifest(paths(options.home).plugins, name) : undefined;
  if (installed) return sourceOfManifest(installed, options.spec);
  const asked = await options.runner.run(packageManager(), ["view", options.spec, "name", "version", "repository", "--json"]);
  if (!asked.ok) throw new Error(`the registry does not answer for ${options.spec}: ${(asked.stderr || asked.stdout).trim()}`);
  const parsed = JSON.parse(asked.stdout) as Record<string, unknown> | Record<string, unknown>[];
  const manifest = Array.isArray(parsed) ? parsed.at(-1)! : parsed;
  return sourceOfManifest(manifest, options.spec);
}

function installedManifest(pluginsRoot: string, name: string): Record<string, unknown> | undefined {
  try {
    return JSON.parse(fs.readFileSync(path.join(pluginsRoot, "node_modules", ...name.split("/"), "package.json"), "utf-8")) as Record<string, unknown>;
  } catch {
    return undefined;
  }
}

/**
 * `amy add <package> --fork`: takes the package's source into the place the
 * profile's forks go, builds it, and installs the profile's root so the name
 * resolves to it for this profile alone. A refusal anywhere leaves the root as
 * it was and removes the fork it had just written, which nobody has edited yet.
 */
export async function addFork(options: ForkAdd): Promise<Forked> {
  const at = await forkSource(options);
  const pluginsRoot = paths(options.home).plugins;
  const existing = profileForkDirectories(options.home, options.profile.name);
  const forked = await takeFork(options.runner, at, options.spec, (name) => {
    const held = existing.get(name);
    const place = forkPlace(options.home, options.profile, name, { to: options.to, forks: options.forks });
    if (held) throw new Error(`the profile \`${options.profile.name}\` already forks ${name} at ${held}; a second fork at ${place} would be two answers for one name`);
    return place;
  });
  const undo = async (why: string): Promise<never> => {
    fs.rmSync(forked.directory, { recursive: true, force: true });
    await installProfileRoot(options.runner, options.home, pluginsRoot, options.profile.name, existing, options.specs);
    throw new Error(why);
  };
  const built = await buildFork(options.runner, forked.directory);
  if (!built.ok) return undo(`${forked.name}: the fork at ${forked.directory} does not build:\n${built.output || "its build said nothing"}`);
  const forks = new Map([...existing, [forked.name, forked.directory]]);
  const installed = await installProfileRoot(options.runner, options.home, pluginsRoot, options.profile.name, forks, [...options.specs, forked.name]);
  if (!installed.ok) return undo(`${installed.command} failed:\n${installed.output || "it said nothing"}`);
  return forked;
}

import path from "node:path";
import { CommandRunner, Engine, EventLog, Mounted, Plugin, WorkflowPlugin, mount, unmetNeeds } from "@amykit/core";
import { AmyConfig } from "./config.js";
import { isFilesystemWorkflow, LoadResult } from "./loader.js";
import { profilePaths } from "./paths.js";
import { Profile } from "./profiles.js";
import { composeProject, composedPluginName, projectSpecs, ProjectPhase, resolvePhases } from "./project.js";
import { hostPaths, pluginList, pluginSlices } from "./slices.js";

/** What assembling needs from the process running it, and nothing it decides. */
export interface AssemblyServices {
  readonly runner: CommandRunner;
  readonly load: (specs: readonly string[]) => Promise<LoadResult>;
  /** The event log for one file, which is the budget ledger of that profile. */
  readonly log: (file: string) => EventLog;
  /** The host's own glue, mounted after everything the config asked for. */
  readonly host: readonly Plugin[];
  readonly readOnly?: boolean;
}

export type Assembled = { ok: true; engine: Engine; mounted: Mounted; workflowPlugin?: Plugin } | { ok: false; problems: string[] };

/**
 * Loads the plugins the config asks for and assembles them.
 *
 * Every refusal happens here, by name, before a ticket is touched: a plugin
 * that will not import, a setting that is not one it has, two plugins
 * claiming the same port, an action the workflow emits that nothing can run.
 *
 * A project assembles its one workflow out of the phases its folders export:
 * the phases are called and never mounted on their own, and the composed
 * workflow takes the configured folder's place in the mount order, so the
 * consumers that capture a workflow's terminal states still follow it.
 */
export async function assembleProfile(
  home: string,
  config: AmyConfig,
  profile: Profile,
  services: AssemblyServices,
): Promise<Assembled> {
  const place = profilePaths(home, profile);
  const specs = pluginList(config, profile);

  if (!profile.project) {
    const loaded = await services.load(specs);
    if (loaded.problems.length > 0) return { ok: false, problems: loaded.problems };
    return await assemble(
      [...loaded.plugins, ...services.host],
      pluginSlices(config, profile, home, new Map([[profile.workflow, loaded.bySpec.get(profile.workflow)?.name ?? profile.workflow]])),
      config, place, profile, services, undefined,
    );
  }

  const loaded = await services.load(unique([...specs, ...projectSpecs(profile.project.root)]));
  if (loaded.problems.length > 0) return { ok: false, problems: loaded.problems };
  const prepared = await walkOf(config, profile, home, loaded, specs);
  if (prepared.ok === false) return { ok: false, problems: [...prepared.problems] };
  return await assemble(
    [...prepared.plugins, ...services.host],
    prepared.slices,
    config, place, profile, services,
    { workflowLabel: `the project at ${profile.project.root}`, workflowPlugin: prepared.plugin },
  );
}

async function assemble(
  plugins: readonly Plugin[],
  slices: Record<string, unknown>,
  config: AmyConfig,
  place: ReturnType<typeof profilePaths>,
  profile: Profile | undefined,
  services: AssemblyServices,
  requirements: { readonly workflowLabel: string; readonly workflowPlugin: Plugin } | undefined,
): Promise<Assembled> {
  const outcome = await mount(plugins, slices, {
    runner: services.runner,
    now: () => new Date(),
    log: services.log(place.log),
    paths: hostPaths(place.base, profile),
    readOnly: services.readOnly,
  }, requirements);

  if (!outcome.ok) return { ok: false, problems: outcome.problems };

  const { mounted } = outcome;
  if (!mounted.engine) {
    return { ok: false, problems: ["no plugin mounted an engine, so nothing can advance work"] };
  }
  if (!mounted.workflow) {
    return { ok: false, problems: ["no plugin mounted a workflow, so there is no order to follow"] };
  }

  const unmet = unmetNeeds(mounted, mounted.workflow);
  if (unmet.length > 0) return { ok: false, problems: unmet };

  return { ok: true, engine: mounted.engine, mounted, ...(requirements ? { workflowPlugin: requirements.workflowPlugin } : {}) };
}

/**
 * The project's walk: the phases it drives, the one workflow that walks them,
 * and the slices the machine hands the plugins — computed against the composed
 * name, so the phases' settings ride the calls that run them.
 */
async function walkOf(
  config: AmyConfig,
  profile: Profile,
  home: string,
  loaded: LoadResult,
  specs: readonly string[],
): Promise<{ ok: true; plugin: Plugin; plugins: readonly Plugin[]; slices: Record<string, unknown> } | { ok: false; problems: readonly string[] }> {
  const project = profile.project!;
  const loadedByKey = new Map([...loaded.bySpec].map(([spec, plugin]) => [keyOf(spec), plugin]));
  const anchor = loadedByKey.get(keyOf(profile.workflow));
  if (!anchor) return { ok: false, problems: [`${project.phase}/: configured workflow plugin is not mounted`] };
  const anchorPlugin = anchor as WorkflowPlugin;
  if (!anchorPlugin.workflow) return { ok: false, problems: [declaredWorkflowProblem(project.phase)] };

  const resolved = resolvePhases(project.root, anchorPlugin.phases);
  if (resolved.problems.length > 0) return { ok: false, problems: resolved.problems };

  const walking: ProjectPhase[] = [];
  for (const { phase, spec } of resolved.walking) {
    const plugin = loadedByKey.get(keyOf(spec)) as WorkflowPlugin | undefined;
    if (!plugin || !plugin.workflow) return { ok: false, problems: [declaredWorkflowProblem(phase)] };
    walking.push({ phase, plugin, name: plugin.name });
  }

  const name = composedPluginName(profile);
  const slices = pluginSlices(
    config, profile, home,
    new Map([[profile.workflow, name]]),
    { name, callees: walking.map((one) => one.name) },
  );
  const composed = composeProject({
    profile,
    slices,
    phases: walking,
    absent: resolved.absent,
    root: project.root,
  });
  if (composed.problems.length > 0) return { ok: false, problems: composed.problems };

  return { ok: true, plugin: composed.plugin, plugins: mountListFor(loaded, specs, composed.plugin, profile), slices };
}

/** The plugins that mount: the config's, with the composed workflow in the configured phase's slot. */
function mountListFor(
  loaded: LoadResult,
  specs: readonly string[],
  composed: Plugin,
  profile: Profile,
): readonly Plugin[] {
  const phases = new Set(projectSpecs(profile.project!.root).map((spec) => keyOf(spec)));
  const list: Plugin[] = [];
  const seen = new Set<string>();
  for (const spec of unique(specs)) {
    const key = keyOf(spec);
    if (phases.has(key)) {
      if (!seen.has(key) && key === keyOf(profile.workflow)) {
        seen.add(key);
        list.push(composed);
      }
      continue;
    }
    const plugin = loaded.bySpec.get(spec);
    if (plugin && !seen.has(key)) {
      seen.add(key);
      list.push(plugin);
    }
  }
  if (!list.includes(composed)) list.push(composed);
  return list;
}

/** The project's phases are called, and a call needs the declaration a mount does not. */
function declaredWorkflowProblem(phase: string): string {
  return `\`${phase}/\` exports no workflow declared with \`defineWorkflow\`: a project's walk calls its phases, and a call needs the workflow's declaration`;
}

/** Deduplicates specs that name one folder: a configured spelling and the phase's own are the same folder. */
function unique(specs: readonly string[]): readonly string[] {
  const seen = new Set<string>();
  for (const spec of specs) seen.add(keyOf(spec));
  const kept = new Map<string, string>();
  for (const spec of specs) {
    const key = keyOf(spec);
    if (!kept.has(key)) kept.set(key, spec);
  }
  return [...kept.values()];
}

/** One spec's identity: the folder it resolves to, or the package spelled as it was. */
function keyOf(spec: string): string {
  return isFilesystemWorkflow(spec) ? path.resolve(spec) : spec;
}

import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { AmyConfig } from "./config.js";

/** The per-profile count belongs beside the profile's other durable state. */
export function autoUpdatePath(home: string, profile: string): string {
  return path.join(home, "workflows", profile, "auto-update.json");
}

/** A due daemon update is held until the child has fully exited. */
function daemonUpdatePath(home: string, profile: string): string {
  return path.join(home, "workflows", profile, "auto-update-daemon");
}

function readRuns(home: string, profile: string): number {
  try {
    const parsed = JSON.parse(fs.readFileSync(autoUpdatePath(home, profile), "utf8")) as { runs?: unknown };
    return typeof parsed.runs === "number" && Number.isSafeInteger(parsed.runs) && parsed.runs >= 0
      ? parsed.runs
      : 0;
  } catch {
    return 0;
  }
}

function writeRuns(home: string, profile: string, runs: number): void {
  const file = autoUpdatePath(home, profile);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify({ runs }, null, 2)}\n`, "utf8");
}

export interface AutoUpdateInvocation {
  home: string;
  profile: string;
  config: AmyConfig;
  update: () => Promise<number>;
  work: () => Promise<void>;
}

export interface ScheduledAutoUpdate {
  due: boolean;
  timing: "before" | "after";
}

/** Records one invocation and tells its caller whether an update is due. */
export function beginAutoUpdateInvocation(home: string, profile: string, config: AmyConfig): ScheduledAutoUpdate {
  const runs = readRuns(home, profile) + 1;
  writeRuns(home, profile, runs);
  return {
    due: config.autoUpdate.enabled && runs % config.autoUpdate.everyRuns === 0,
    timing: config.autoUpdate.timing,
  };
}

/** Remembers an after-timed daemon update until the parent stops its child. */
export function markDaemonUpdate(home: string, profile: string): void {
  const file = daemonUpdatePath(home, profile);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, "due\n", "utf8");
}

/** Whether an exited daemon still has a reaper-owned update to run. */
export function hasDaemonUpdate(home: string, profile: string): boolean {
  const file = daemonUpdatePath(home, profile);
  return fs.existsSync(file) || fs.existsSync(`${file}.claiming`) || fs.existsSync(`${file}.claimed`);
}

/** Takes a due after-timed daemon update exactly once, retaining its claim while it runs. */
export function takeDaemonUpdate(home: string, profile: string): boolean {
  const file = daemonUpdatePath(home, profile);
  recoverDaemonUpdateClaim(file);
  const staging = `${file}.claiming`;
  const prepared = `${staging}.${process.pid}.${randomUUID()}`;
  try {
    // Link a fully-written owner into place: another starter can never recover
    // an empty staging file between its creation and its first write.
    fs.writeFileSync(prepared, `${process.pid}\n`, "utf8");
    fs.linkSync(prepared, staging);
    fs.rmSync(prepared, { force: true });
    // A claimant may arrive after the owner moved staging to claimed but before
    // it consumed due. It must leave that owner and its due marker untouched.
    if (!fs.existsSync(file) || fs.existsSync(`${file}.claimed`)) {
      fs.rmSync(staging, { force: true });
      return false;
    }
    fs.renameSync(staging, `${file}.claimed`);
    fs.unlinkSync(file);
    return true;
  } catch {
    return false;
  } finally {
    fs.rmSync(prepared, { force: true });
  }
}

/** Returns an abandoned claim to due state without stealing a live updater. */
function recoverDaemonUpdateClaim(file: string): void {
  const claims = [`${file}.claimed`, `${file}.claiming`];
  const claim = claims.find((candidate) => fs.existsSync(candidate));
  if (!claim) return;
  const owner = Number.parseInt(fs.readFileSync(claim, "utf8").trim(), 10);
  if (Number.isSafeInteger(owner) && owner > 0) {
    try {
      process.kill(owner, 0);
      return;
    } catch (error: unknown) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === "EPERM") return;
      if (code !== "ESRCH") throw error;
    }
  }
  try {
    if (claim.endsWith(".claimed")) fs.renameSync(claim, file);
    else fs.rmSync(claim, { force: true });
  } catch {
    // Another recovery settled the stale claim first.
  }
}

/** Releases the durable reaper claim only after the scheduled update settled. */
export function finishDaemonUpdate(home: string, profile: string): void {
  fs.rmSync(`${daemonUpdatePath(home, profile)}.claimed`, { force: true });
}

/** Makes a claimed update due again when a shared daemon boundary blocked it. */
export function retryDaemonUpdate(home: string, profile: string): void {
  const file = daemonUpdatePath(home, profile);
  try {
    fs.renameSync(`${file}.claimed`, file);
  } catch {
    // Another recovery owner already settled it; either result is safe.
  }
}

/** Settles an interrupted after-daemon update before a new daemon starts. */
export async function settleDaemonUpdate(home: string, profile: string, update: () => Promise<number>): Promise<boolean> {
  if (!hasDaemonUpdate(home, profile)) return true;
  // A stale staging claim can be the last marker. Recovery removes it, so a
  // failed take is settled when no due or claim marker remains to be claimed.
  if (!takeDaemonUpdate(home, profile)) return !hasDaemonUpdate(home, profile);
  if (await update() === 0) {
    finishDaemonUpdate(home, profile);
    return true;
  }
  retryDaemonUpdate(home, profile);
  return false;
}

/**
 * Counts one lifecycle invocation, then places a due update at its requested
 * boundary. The count is written before the update so a failed attempt remains
 * an invocation after a restart rather than becoming due forever.
 */
export async function runWithAutoUpdate({ home, profile, config, update, work }: AutoUpdateInvocation): Promise<void> {
  const schedule = beginAutoUpdateInvocation(home, profile, config);

  if (schedule.due && schedule.timing === "before") await updateOrThrow(update);
  await work();
  if (schedule.due && schedule.timing === "after") await updateOrThrow(update);
}

async function updateOrThrow(update: () => Promise<number>): Promise<void> {
  if (await update() !== 0) throw new Error("amy update failed");
}

import { usageThenNow, type SubscriptionUsage } from "./status-page.js";
import {
  BUDGET_WINDOWS,
  BudgetLimits,
  Event,
  Spend,
  budgetDecision,
  ceilingFor,
  spendSince,
} from "@amykit/core";

/**
 * `amy budget`'s report: the provider windows first, then the ledger read at
 * the moment they have answered. An account request can take seconds, and a
 * clock read before it would keep counting a run that left a window during
 * the wait.
 */
export async function budgetReport(input: {
  readonly limits: BudgetLimits;
  readonly usage: () => Promise<readonly SubscriptionUsage[]>;
  readonly events: (since: Date) => readonly Event[];
  readonly clock: () => Date;
}): Promise<string[]> {
  const { usage, now } = await usageThenNow(input.usage, input.clock);
  // Read once, over the longest window any ceiling could be set on, rather
  // than once per window: two reads of a growing file can disagree, and a
  // report whose windows disagree is worse than a slower one.
  const longest = Math.max(...BUDGET_WINDOWS.map((window) => window.ms));
  return budgetLines(input.events(new Date(now.getTime() - longest)), input.limits, now, usage);
}

/**
 * What `amy budget` prints, as lines, so the arithmetic is testable.
 *
 * A pure function of the log rather than a method on the ledger: the ledger
 * answers one question — may this run start — and this answers the other one,
 * which is what a person asks when the answer to the first was no.
 */
export function budgetLines(
  events: readonly Event[],
  limits: BudgetLimits,
  now: Date,
  usage: readonly SubscriptionUsage[] = [],
): string[] {
  const lines: string[] = [];

  for (const window of BUDGET_WINDOWS) {
    const since = new Date(now.getTime() - window.ms);
    const spend = spendSince(events, since);
    const ceiling = ceilingFor(limits, window.name);

    lines.push(
      `${window.name.padEnd(14)} ${String(spend.runs).padStart(4)} run(s)  ` +
        `${against(spend.tokens, ceiling?.tokens, "tokens")}  ` +
        `${against(spend.costUsd, ceiling?.costUsd, "USD")}`,
    );
    const prevented = events.filter((event) =>
      event.kind === "progress.parked" && new Date(event.at).getTime() >= since.getTime(),
    ).length;
    lines.push(`${" ".repeat(14)} ${prevented} prevented start(s) from no new evidence`);

    const caveat = unpricedNote(spend, ceiling?.costUsd);
    if (caveat) lines.push(`${" ".repeat(14)} ${caveat}`);
  }

  const decision = budgetDecision(events, limits, now);
  lines.push(
    decision.ok
      ? "\nnew work: allowed"
      : `\nnew work: parked, ${decision.reason} ` +
          `(room again in ${Math.round(decision.retryAfterMs / 60000)} min)`,
  );

  lines.push(...usageLines(usage));
  return lines;
}

/** Provider windows are shown beside, never folded into, Amy's own ledger. */
function usageLines(usage: readonly SubscriptionUsage[]): string[] {
  if (usage.length === 0) return [];
  const lines = ["", "subscription usage:"];
  for (const { subscription, result } of usage) {
    if ("unavailable" in result) {
      lines.push(`${subscription}: unavailable — ${result.unavailable}`);
      continue;
    }
    const marker = result.unofficial ? " unofficial" : "";
    for (const window of result.windows) {
      const period = window.startsAt || window.resetsAt
        ? [window.startsAt ? `starts ${window.startsAt}` : "", window.resetsAt ? `resets ${window.resetsAt}` : ""].filter(Boolean).join(", ")
        : "period unknown";
      lines.push(`${subscription}${marker} ${window.label}: ${window.usedPercent}% (${period})`);
    }
  }
  return lines;
}

/**
 * How many runs in the window carry no price, where that changes the reading.
 *
 * Only under a dollar ceiling, because that is the only place the omission
 * misleads: a window metered in tokens has counted every run it saw. Under a
 * dollar ceiling the figure beside it is the spend of the priced runs and not
 * the spend of the window, and saying so is the difference between a number
 * that is arithmetically true and one that can be acted on.
 */
function unpricedNote(spend: Spend, ceiling: number | undefined): string | null {
  if (ceiling === undefined || spend.unpriced === 0) return null;

  return (
    `note: ${spend.unpriced} of those ${spend.runs} run(s) carry no price, so the USD ` +
    "figure is lower than the truth by an unknown amount. `amy models refresh` fixes a rate " +
    "the table has fallen behind on; a model it has no row for at all needs one adding to " +
    "`.amy/model-specs.json`, because a refresh re-rates what is there and never adds."
  );
}

/** `1,234 / 2,000 tokens (62%)`, or the spend alone when nothing caps it. */
function against(used: number, limit: number | undefined, unit: string): string {
  const spent = unit === "USD" ? `$${used.toFixed(2)}` : used.toLocaleString();
  if (limit === undefined) return `${spent} ${unit} (no ceiling)`;

  const cap = unit === "USD" ? `$${limit.toFixed(2)}` : limit.toLocaleString();
  const share = limit === 0 ? 100 : Math.round((used / limit) * 100);
  return `${spent} of ${cap} ${unit} (${share}%)`;
}

import { ConfigSchema } from "@amykit/core";
import { load } from "./loader.js";
import { machineSchema, type AmyConfig } from "./config.js";
import type { Profile } from "./profiles.js";
import { pluginList, pluginSlices } from "./slices.js";

/**
 * `amy config explain`, as data rather than as stdout.
 *
 * The command prints lines; the tests need what the lines say without a
 * subprocess, and the gate needs the same report from another process than
 * this one's console. One producer, three consumers.
 */
export type ExplainReport = {
  /** Console-ready lines, machine first, then each mounted plugin. */
  lines: string[];
  /** What would not load, said the way the boot would say it. */
  problems: string[];
  /** The ask named nothing mounted. */
  refused?: string;
};

/**
 * Every setting one schema carries, on one line each.
 *
 * The line is what an operator reads to decide a value: what it is called,
 * what kind of thing it takes, whether the machine carries a value for it
 * right now, and what happens when it is left out — the schema's shape, the
 * machine's effective choice beside it.
 */
export function describeEntries(schema: ConfigSchema, given?: Readonly<Record<string, unknown>>): string[] {
  return Object.entries(schema).map(([key, spec]) => {
    const at = pathOf(given, key);
    const supplied = at === nothing ? undefined : `set ${stringOf(at)}`;
    const when = supplied ?? (spec.required ? "required" : spec.default === undefined ? "not set" : `default ${stringOf(spec.default)}`);
    return `  ${key.padEnd(40)}${spec.type.padEnd(10)}${when.padEnd(24)}${spec.description}`;
  });
}

/** What a nested settings mapping carries at a dotted path, or `nothing` when it carries none of it. */
const nothing = Symbol("not supplied");

function pathOf(given: Readonly<Record<string, unknown>> | undefined, dotted: string): unknown {
  if (given === undefined) return nothing;
  let node: unknown = given;
  for (const segment of dotted.split(".")) {
    if (typeof node !== "object" || node === null || Array.isArray(node)) return nothing;
    node = (node as Record<string, unknown>)[segment];
  }
  return node === undefined ? nothing : node;
}

function stringOf(value: unknown): string {
  if (Array.isArray(value)) return JSON.stringify(value);
  if (typeof value === "object" && value !== null) return JSON.stringify(value);
  return String(value);
}

/**
 * Who this machine would read, machine first, then what it mounts.
 *
 * Narrowing to one plugin exists because a machine mounts plenty — a
 * workflow, the engine, the tracker, the file log — and an operator tuning
 * one of them wants that one's settings, with the mounted order preserved so
 * the report reads the way the boot does.
 */
export async function explainReport(config: AmyConfig, profile: Profile, plugin: string | undefined, resolve: (spec: string) => string = (spec) => spec, pluginsRoot?: string): Promise<ExplainReport> {
  // Discovering a setting here is the reason the top level stopped carrying
  // any workflow's vocabulary: the machine's own settings are one short list,
  // and everything a workflow answers belongs to the thing that answers.
  const lines: string[] = ["machine:"];
  // The machine's own settings are the short list the top level always was:
  // named, typed, defaulted — a profile's settings are dumped in full under
  // the plugin they belong to, and a machine record here would bury the one
  // value the operator is looking for under every other profile's noise.
  for (const line of describeEntries(machineSchema)) lines.push(line);

  const specs = pluginList(config, profile);
  const loaded = await load(specs, resolve, pluginsRoot);
  // What the machine would actually mount, not what its schema asks for: an
  // operator tuning one setting wants the value the mount would hand the
  // plugin, with the schema's default named for what the machine left out.
  // The mount reads each plugin by its own name, so the profile's workflow
  // — a local one can be spelled by path — answers to the name the loader
  // produced, the same map the boot passes.
  const slots = pluginSlices(config, profile, undefined, new Map([[profile.workflow, loaded.bySpec.get(profile.workflow)?.name ?? profile.workflow]]));

  if (plugin !== undefined && !specs.includes(plugin)) {
    return {
      lines,
      problems: loaded.problems,
      refused: `nothing mounted names ${plugin}. Mounted: ${specs.join(", ")}`,
    };
  }

  const chosen = plugin === undefined ? specs : specs.filter((spec) => spec === plugin);
  for (const spec of chosen) lines.push(...describeMounted(loaded, slots, spec));

  return { lines, problems: loaded.problems };
}

/** One plugin's section of the report: what it carries, and what the mount would hand it. */
function describeMounted(
  loaded: Awaited<ReturnType<typeof load>>,
  slots: Record<string, unknown>,
  spec: string,
): string[] {
  const module = loaded.bySpec.get(spec);
  const schema = module?.configSchema;
  const effective = slots[module?.name ?? spec];
  const lines = ["", `${spec}${schema === undefined ? " (no settings of its own)" : ":"}`];
  if (schema !== undefined && Object.keys(schema).length > 0) {
    for (const line of describeEntries(schema, isMapping(effective) ? effective : undefined)) lines.push(line);
  }
  return lines;
}

/** Whether a value is the mapping a slice's settings arrive as. */
function isMapping(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { ConfigSchema, mount, MountOutcome, NodeCommandRunner } from "@amykit/core";
import { FileEventLog } from "@amykit/plugin-file-log";
import { type AmyConfig, EXAMPLE_CONFIG, loadConfigFrom } from "./config.js";
import { loadEnv } from "./env.js";
import { load } from "./loader.js";
import { profiles } from "./profiles.js";
import { hostPaths, pluginList, pluginSlices } from "./slices.js";

/**
 * One settings surface: a schema for a block of the config, and where it sits.
 *
 * The top level is the machine schema, and the workflow the template's
 * example mounts carries its own. The check reads only what the schema
 * declares, so a setting that exists is a setting some schema declares.
 */
export interface SettingsSurface {
  /** Where the block sits, dotted. Empty for the top level. */
  readonly at: string;
  readonly schema: ConfigSchema;
  /** The block as the template set it, or undefined if it set none. */
  readonly given: object | undefined;
}

/**
 * Whether the config `amy init` writes is one this build can read, and one
 * whose settings are all explained by the schemas that declare them.
 *
 * The loud failure is unchanged: the template carried `agent:` twice, YAML
 * refused a duplicate key rather than merging it, so `amy init` wrote a file
 * `loadConfig` threw on and every command died on a fresh install. No test
 * had ever parsed the template.
 *
 * The quiet one changes shape. It used to be "a setting the template never
 * names" — the template is where a setting was supposed to be found. Finding
 * a setting has since moved to `amy config explain`, which reads it off the
 * schemas the machine actually mounts, and a workflow's vocabulary lives in
 * the profile that drives it rather than in front of everybody. What the
 * build owes now is that every setting a schema declares is described by the
 * schema that declares it: a field with no description is a setting nobody
 * can discover from the machine that has it.
 */
export function checkConfigTemplate(
  surfaces: readonly SettingsSurface[],
  parseErrors: readonly string[],
): string[] {
  const problems = parseErrors.map(
    (error) =>
      `the template does not parse, so \`amy init\` writes a file nothing can read — ${error}`,
  );

  // Everything below reads the parsed document, so a template that does not
  // parse is reported once rather than as a cascade of missing blocks.
  if (problems.length > 0) return problems;

  for (const surface of surfaces) {
    for (const key of Object.keys(surface.given ?? {})) {
      // A nested block is written at its head — `agent:` for `agent.ladder` —
      // so a key is a setting either when the schema declares it whole or when
      // the schema names its leaves.
      const declares = Object.hasOwn(surface.schema, key) ||
        Object.keys(surface.schema).some((name) => name.startsWith(`${key}.`));
      if (!declares) {
        problems.push(
          `\`${named(surface.at, key)}\` is in the template and is not a setting — nothing would read it`,
        );
      }
    }

    for (const [key, spec] of Object.entries(surface.schema)) {
      if (typeof spec.description !== "string" || spec.description.trim().length === 0) {
        problems.push(
          `\`${named(surface.at, key)}\` is a setting and its schema says nothing about it — give it a description, the words \`amy config explain\` prints`,
        );
      }
    }
  }

  return problems;
}

function named(at: string, key: string): string {
  return at ? `${at}.${key}` : key;
}

export interface BootCheck {
  ok: boolean;
  problems: string[];
}

/**
 * The workflow the boot check mounts, transcribed from the example the
 * template ships commented out.
 *
 * `amy init` writes a config that drives nothing, and that is the point of it:
 * the machine arrives carrying no process, and a machine with none mounted is
 * diagnosed rather than refused. So the boot half cannot assemble the file
 * exactly as written — there would be no workflow to mount, and the check
 * would pass having proven nothing, while the ladder, the budget, the gate and
 * the skills, every setting the template does ship live, went unassembled.
 * That is the shape the duplicate `claude:opus` rung hid in.
 *
 * What it mounts instead is the machine the operator has one uncomment later:
 * the example block, over the settings the template ships live. Transcribed
 * rather than unpicked from the comment, because separating `#` that is
 * commented config from `#` that is prose would be exactly the second
 * interpretation of the config this module exists not to have — and
 * `namesTheExample` keeps the transcription honest instead.
 */
const EXAMPLE_WORKFLOW = {
  name: "ticket-to-qa",
  workflow: "@amykit/workflow-ticket-to-qa",
  /**
   * The settings the example block teaches, and what the boot half mounts.
   *
   * The workflow's schema asks for a QA status name, and the machine can no
   * longer hand it one from the top level: a workflow's vocabulary lives in
   * the profile that drives it, and this one is the profile the operator has
   * one uncomment later.
   */
  settings: {
    qaStatusName: "In QA",
  },
} as const;

/**
 * The template still says the words the transcription above copied.
 *
 * The one thing a transcription can do that parsing cannot is go stale. If the
 * example block is renamed or repointed, this is what says so, rather than the
 * check quietly mounting a workflow the template no longer offers.
 */
export function namesTheExample(template: string): string[] {
  return [EXAMPLE_WORKFLOW.name, EXAMPLE_WORKFLOW.workflow]
    .filter((word) => !template.includes(word))
    .map(
      (word) =>
        `the boot check mounts the template's \`${EXAMPLE_WORKFLOW.name}\` example and the template no longer names \`${word}\` — retranscribe \`EXAMPLE_WORKFLOW\` in config-template.ts`,
    );
}

/**
 * The template's settings under the workflow its commented example names.
 *
 * Shared with the tests rather than transcribed twice: the negative cases
 * assemble a mutated template and have to reach the same mount this does, or
 * they would be proving something about a different machine.
 */
export function withExampleWorkflow(config: AmyConfig): AmyConfig {
  return {
    ...config,
    workflows: {
      [EXAMPLE_WORKFLOW.name]: {
        workflow: EXAMPLE_WORKFLOW.workflow,
        settings: { ...EXAMPLE_WORKFLOW.settings },
      },
    },
    defaultWorkflow: EXAMPLE_WORKFLOW.name,
  };
}

/**
 * Whether the config `amy init` writes is one that boots.
 *
 * The check above proves the file parses and names every setting; this proves
 * the one thing that matters most: assembling it against the plugins it names
 * produces a working host. Both syntax half and boot half live in one module
 * because they are one claim about one file — `npm run check:config` runs
 * them in that order, and the unit tests hold them side by side.
 *
 * Assembled against the build rather than parsed as text, so a template bug
 * is caught by the same `mount` that will refuse it on somebody's laptop —
 * there is no second interpretation of the config to drift apart.
 */
export async function checkConfigBoots(configRoot: string): Promise<BootCheck> {
  const drifted = namesTheExample(EXAMPLE_CONFIG);
  if (drifted.length > 0) return { ok: false, problems: drifted };

  // `amy init` writes the example; the loader reads it back the way any
  // command would. Failures here are the parse half of the check, which is
  // `checkConfigTemplate`'s to report — this is the boot half.
  const config = withExampleWorkflow(loadConfigFrom(configRoot, EXAMPLE_CONFIG));

  // The example workflow is the one whose mount the template has to guarantee,
  // because it is the one the template offers. A workflow somebody writes
  // themselves is their config, not template text, and is theirs to refuse on
  // the day they add it.
  const profile = profiles(config)[config.defaultWorkflow];
  if (!profile) return { ok: false, problems: ["the template declares no workflow to drive"] };

  // The environment a real machine boots from, read the way every command
  // reads it — from the config root it was handed, not from wherever the
  // caller happened to be standing. A check whose answer moved with the
  // working directory would pass on the machine that ran it and nowhere else.
  //
  // What a fresh install starts without is the operator's first errand —
  // `amy doctor` says FAIL and names the key — not a fault in the text `amy
  // init` wrote, so a credential this machine has not been given yet is stood
  // in for rather than reported as a template bug. Only when absent: a value
  // already exported stays the one the check means.
  const credentials: Record<string, string> = { LINEAR_API_KEY: "lin_api_boot-check" };
  const borrowed = borrowEnv(credentials);
  // `loadEnv` only sets a name nothing had set, so the names it reports back
  // are exactly the ones to unset again.
  const fromFile = loadEnv(configRoot);

  // A state directory of its own, outside the checkout: the mount writes the
  // empty log a fresh install would have, and a check that littered the
  // source tree would be a finding the next `sf check` would rightly report
  // (L4.ROOT_FILES_ARE_DECLARED).
  const state = fs.mkdtempSync(path.join(os.tmpdir(), "amy-boot-check-"));

  // Everything borrowed above is given back below, on every path out. A check
  // is an observation: run twice it answers the same, and the process it ran
  // in is left as it was found — this one runs inside `amy doctor` and inside
  // a test suite whose next case must not inherit its stand-in credential.
  try {
    const specs = pluginList(config, profile);
    const loaded = await load(specs);
    // Nothing below means anything if a named plugin is missing: that is an
    // install problem, said in the loader's own words, and the caller decides
    // whether it is this check's to enforce.
    if (loaded.problems.length > 0) return { ok: false, problems: loaded.problems };

    const outcome: MountOutcome = await mount(
      loaded.plugins,
      pluginSlices(config, profile),
      {
        // A runner a boot never uses: registration wires the CLIs, the ladder
        // is judged from the rungs' names, and the engine is built at boot
        // without running anything. The real one shells out; this one is the
        // real adapter and reaches nothing, because nothing here asks it to.
        runner: new NodeCommandRunner(),
        now: () => new Date(),
        // The budget is read off a log at boot; an empty one is what a fresh
        // install has.
        log: new FileEventLog(path.join(state, "events"), () => new Date()),
        paths: hostPaths(state),
      },
    );

    return outcome.ok ? { ok: true, problems: [] } : { ok: false, problems: outcome.problems };
  } finally {
    fs.rmSync(state, { recursive: true, force: true });
    restoreEnv(borrowed);
    for (const key of fromFile) delete process.env[key];
  }
}

/**
 * Sets the names the mount needs and remembers what was there, so a caller can
 * put the environment back exactly as it found it — including unsetting a name
 * that was never set.
 */
function borrowEnv(values: Record<string, string>): Map<string, string | undefined> {
  const before = new Map<string, string | undefined>();

  for (const [key, value] of Object.entries(values)) {
    before.set(key, process.env[key]);
    if (process.env[key] === undefined) process.env[key] = value;
  }

  return before;
}

function restoreEnv(before: Map<string, string | undefined>): void {
  for (const [key, value] of before) {
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
  }
}

import fs from "node:fs";
import yaml from "yaml";
import path from "node:path";
import { ConfigSchema } from "@amykit/core";
import { paths } from "./paths.js";

/**
 * The workflow's own settings, checked against its configSchema at mount.
 *
 * This is what `amy add <workflow>` writes when the schema asks for a setting
 * nothing else fills in: one entry per required field that carries an
 * `example`, the value the plugin itself says it would mount with.
 */
export type ProfileSettings = Record<string, unknown>;

/**
 * One profile: which workflow drives, and what mounts under it.
 *
 * This is what makes `--workflow oncall` a thing an operator can add rather
 * than a thing this package has to ship. The name is the key, and it is also
 * the directory the profile's records and queue live in.
 */
export interface WorkflowProfile {
  /** The package contributing `plan()` and the runtime that answers it. */
  workflow: string;
  /** What to mount, in order. Empty means the recommended set. */
  plugins?: string[];
  /**
   * The package providing durable briefs for this workflow. When omitted,
   * legacy explicit profiles that still name file-store receive the local
   * file provider they had before briefs became their own mount.
   */
  briefStore?: string;
  /** Whether `amy note` files friction onto this profile's queue. */
  notes?: boolean;
  /** Whether `amy btw` puts a task onto this profile's queue. */
  tasks?: boolean;
  /** A profile may spend differently from the machine-wide default. */
  agent?: Partial<AmyConfig["agent"]>;
  /**
   * The workflow's own settings, over what its schema and the machine fill in.
   *
   * Whichever workflow the profile drives owns this block; a setting a
   * workflow's schema does not declare is refused at mount, naming the key.
   */
  settings?: ProfileSettings;
}

interface NotifyConfig {
  /** A Hermes delivery target, e.g. `telegram`. Null disables the channel. */
  hermes: string | null;
  /** A file on disk plus a desktop notification. */
  inbox: boolean;
}

/** When the machine refreshes its installed packages around workflow work. */
interface AutoUpdateConfig {
  enabled: boolean;
  timing: "before" | "after";
  everyRuns: number;
}

const DEFAULT_AUTO_UPDATE: AutoUpdateConfig = {
  enabled: true,
  timing: "before",
  everyRuns: 20,
};

/** The host-owned schedule is checked before any workflow is allowed to run. */
function autoUpdateProblems(value: unknown): string[] {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return ["`autoUpdate` must be a mapping"];
  }
  const schedule = value as Partial<AutoUpdateConfig>;
  const problems: string[] = [];
  if (typeof schedule.enabled !== "boolean") problems.push("`autoUpdate.enabled` must be true or false");
  if (schedule.timing !== "before" && schedule.timing !== "after") {
    problems.push("`autoUpdate.timing` must be `before` or `after`");
  }
  if (!Number.isSafeInteger(schedule.everyRuns) || (schedule.everyRuns ?? 0) <= 0) {
    problems.push("`autoUpdate.everyRuns` must be a positive integer");
  }
  return problems;
}

/** Validates the words the operator wrote, before the safe runtime defaults. */
export function configuredAutoUpdateProblems(config: AmyConfig): string[] {
  return autoUpdateProblems(config.autoUpdateSource === undefined ? config.autoUpdate : config.autoUpdateSource);
}

export interface AmyConfig {
  /**
   * The workflows this install can drive, by the name typed after
   * `--workflow`. Merged over the shipped two, so naming one replaces it and
   * naming a third adds it.
   */
  workflows: Record<string, WorkflowProfile>;
  /** Which profile runs when nothing is named. Empty means the first. */
  defaultWorkflow: string;
  /**
   * Plugins mounted under every profile, named here or added with
   * `amy add`. A workflow's own plugins stay in its profile; this is the
   * list for what somebody mounted on top, and it is kept apart so a
   * profile left on the recommended set stays on it.
   */
  extraPlugins: string[];
  /**
   * What `amy add <package>` does with no flag: install the published package
   * (`package`), or take its source as a fork the profile owns (`fork`).
   * Read as written, so a mode amy does not know is refused naming this key.
   */
  add: unknown;
  /**
   * Where forks go when `--to` names no place; empty means the default — the
   * project of a workflow of your own, or the profile's directory in AMY_HOME.
   */
  forks: string;
  /** One machine-wide cadence, persisted separately for every profile. */
  autoUpdate: AutoUpdateConfig;
  /** A scalar/null source value retained so malformed YAML cannot become valid. */
  autoUpdateSource?: unknown;

  retentionDays: number;
  staleClaimMs: number;
  maxItemAttempts: number;
  agent: {
    model?: string;
    /** Model tiers offered to the relay, cheapest first. */
    models?: string[];
    /**
     * Which contributed agents to try, in order, such as
     * `[claude:sonnet, claude:opus, codex:gpt-5]`. Empty means every agent
     * that was contributed, in mounting order.
     *
     * Naming a harness here is also what mounts it, so a ladder is the one
     * place an operator says which harnesses they have.
     */
    ladder?: string[];
    /**
     * A ladder for one step, keyed by the workflow's action name, overriding
     * the one above.
     *
     * Reading a ticket to decide whether it is clear enough to start is not
     * the same job as writing the change, and one list for both means paying
     * the expensive model to do the cheap step. A name here mounts its
     * harness exactly as a name in `ladder` does.
     */
    ladderByStep?: Record<string, string[]>;
    reviewerHints?: Record<string, string>;
    timeoutMs?: number;
    /**
     * What the agents may spend, per window. Read by the relay, which is the
     * only thing here that spends one. Shape checked at boot, not here.
     */
    budget?: Record<string, unknown>;
  };
  /**
   * Which skills answer for a step, in the order they are tried, keyed by the
   * workflow's action name. A skill named here has to be installed.
   */
  skills: Record<string, string[]>;
  notify: NotifyConfig;
  /**
   * One slice per plugin, keyed by package name.
   *
   * The host never reads inside a slice. Each plugin declares what its own
   * looks like, and `amy doctor` refuses a slice that does not match.
   */
  plugins: Record<string, unknown>;
}

