export type AddMode = "fork" | "package";

/**
 * What one `amy add` does (S13): the flag when one is given, the config's
 * `add` otherwise. A mode the config names that amy does not know is refused
 * naming the key, flag or not, because the next add without one would read it.
 */
export function addModeFor(config: Pick<AmyConfig, "add">, flags: { fork?: boolean; package?: boolean }): AddMode {
  const configured = config.add ?? "package";
  if (configured !== "fork" && configured !== "package") {
    throw new Error(`\`add\` in the config is \`${String(configured)}\`, and it is \`fork\` or \`package\``);
  }
  if (flags.fork && flags.package) throw new Error("`--fork` and `--package` ask for opposite things; name one");
  if (flags.fork) return "fork";
  if (flags.package) return "package";
  return configured;
}

/**
 * Parses one config document through the loader's own merge.
 *
 * `loadConfig` reads the file an install has; this reads the one `amy init`
 * *would write* — the same words, from a string. The boot check assembles the
 * template through this rather than through any second parser, because a
 * template check that parsed the file differently from the machine would
 * prove the wrong file.
 */
export function loadConfigFrom(root: string, text: string): AmyConfig {
  const parsed = (yaml.parse(text) ?? {}) as Partial<AmyConfig>;

  return fromParsed(root, parsed);
}

export function loadConfig(root: string): AmyConfig {
  const file = paths(root).config;
  if (!fs.existsSync(file)) {
    return DEFAULT_CONFIG;
  }

  const parsed = (yaml.parse(fs.readFileSync(file, "utf-8")) ?? {}) as Partial<AmyConfig>;

  return fromParsed(root, parsed);
}

/**
 * The merge behind both readers, so there is exactly one.
 *
 * No reader gets to bend a field on its way through: `loadConfigFrom` exists
 * to read the same words the same way `loadConfig` does, and a `workspaceRoot`
 * expanded here and substituted there would make the boot check prove a config
 * no install has.
 */
function autoUpdateFrom(parsed: Partial<AmyConfig>): Pick<AmyConfig, "autoUpdate" | "autoUpdateSource"> {
  const rawAutoUpdate = Object.hasOwn(parsed, "autoUpdate") ? parsed.autoUpdate : undefined;
  // Only a plain object is a mapping an operator wrote: an array is an
  // object at runtime but not a mapping, so it stays the malformed source
  // the validator refuses, instead of being silently replaced by defaults.
  const autoUpdate = typeof rawAutoUpdate === "object" && rawAutoUpdate !== null && !Array.isArray(rawAutoUpdate)
    ? { ...DEFAULT_AUTO_UPDATE, ...(rawAutoUpdate as Partial<AutoUpdateConfig>) }
    : DEFAULT_AUTO_UPDATE;
  const autoUpdateSource = rawAutoUpdate === null || (rawAutoUpdate !== undefined && typeof rawAutoUpdate !== "object")
    ? { autoUpdateSource: rawAutoUpdate }
    : Array.isArray(rawAutoUpdate)
      ? { autoUpdateSource: rawAutoUpdate }
      : {};
  return { autoUpdate, ...autoUpdateSource };
}

/**
 * The top-level keys the machine no longer carries, and where each went —
 * a workflow's own vocabulary, and the workspace with its gate.
 *
 * A config written for the old shape boots nowhere useful — the workflow or
 * plugin it tuned reads a block it no longer finds — so the loader refuses
 * the file by name, saying where the setting lives now, and `amy update` is
 * the move that rewrites it.
 */
const MOVED_KEYS: ReadonlyMap<string, string> = new Map([
  ["policy", "under the profile mounting @amykit/workflow-ticket-to-qa, as that workflow's settings.policy"],
  ["qaStatusName", "under that profile, as settings.qaStatusName"],
  ["plans", "under the profile mounting @amykit/workflow-note-to-plan, as settings.repos and settings.check"],
  ["errands", "under the profile mounting @amykit/workflow-errand, as settings.policy"],
  ["workingStatusName", "under plugins: \"@amykit/plugin-linear\", as workingStatusName"],
  ["repoByTeam", "under plugins: \"@amykit/plugin-linear\", as repoByTeam"],
  // The workspace is a capability now: the repositories, where their
  // checkouts live, their branches and their worktrees are the file-worktree
  // plugin's slice, and the gate commands are the command-gate plugin's. The
  // machine reads none of the seven.
  ["repos", "under plugins: \"@amykit/plugin-file-worktree\", as repos"],
  ["workspaceRoot", "under plugins: \"@amykit/plugin-file-worktree\", as workspaceRoot"],
  ["checkouts", "under plugins: \"@amykit/plugin-file-worktree\", as checkouts"],
  ["defaultBranch", "under plugins: \"@amykit/plugin-file-worktree\", as defaultBranch"],
  ["baseBranch", "under plugins: \"@amykit/plugin-file-worktree\", as baseBranch"],
  ["worktrees", "under plugins: \"@amykit/plugin-file-worktree\", as root and retentionDays"],
  ["gate", "under plugins: \"@amykit/plugin-command-gate\", as gate"],
]);

function refusedMovedKeys(parsed: Partial<AmyConfig>): void {
  for (const [key, where] of MOVED_KEYS) {
    if (!Object.hasOwn(parsed, key)) continue;
    throw new Error(`\`${key}\` at the top level of the config is where it used to live — it moved ${where}; \`amy update\` moves an old install`);
  }
}

function fromParsed(root: string, parsed: Partial<AmyConfig>): AmyConfig {
  refusedMovedKeys(parsed);
  return {
    ...DEFAULT_CONFIG,
    ...parsed,
    ...mountingFrom(root, parsed),
    ...autoUpdateFrom(parsed),
    notify: { ...DEFAULT_CONFIG.notify, ...(parsed.notify ?? {}) },
    skills: parsed.skills ?? {},
    plugins: parsed.plugins ?? {},
    agent: { ...DEFAULT_CONFIG.agent, ...(parsed.agent ?? {}) },
  };
}

/**
 * What a profile is read from, defaulted together.
 *
 * The three fields the profiles table and the mounting list are built from:
 * they arrive as one block in the config and one of them missing is the same
 * edit for all three, which is why they default in one place.
 */
function mountingFrom(
  root: string,
  parsed: Partial<AmyConfig>,
): Pick<AmyConfig, "workflows" | "defaultWorkflow" | "extraPlugins"> {
  return {
    workflows: Object.fromEntries(Object.entries(parsed.workflows ?? {}).map(([name, profile]) => [name, {
      ...profile,
      // Keep the operator's spelling in the configuration model. Runtime
      // profile construction resolves filesystem specs against this home, but
      // config writers and removal matching must not turn a portable `./…`
      // setting into the absolute path of this particular machine.
      workflow: profile.workflow,
    }])),
    defaultWorkflow: parsed.defaultWorkflow ?? "",
    extraPlugins: parsed.extraPlugins ?? [],
  };
}

export const EXAMPLE_CONFIG = `# The workflows this install can drive. The name is what goes after
# --workflow, and it is also the directory the profile's records and queue
# live in, so switching between two of them never loses the state of either.
#
# Declared here, not shipped: this machine drives nothing until a workflow is
# named. \`amy add <package>\` installs one and writes the profile block for
# you, from what the workflow's own schema asks for — the settings below are
# the example that teaches, and \`amy config explain\` names every setting the
# machine could take, with its type, its default and why it is there.
#
#   workflows:
#     ticket-to-qa:
#       workflow: "@amykit/workflow-ticket-to-qa"
#       settings:
#         # The status a ticket moves to when it is handed to QA.
#         qaStatusName: In QA
#         # The ceilings the ticket workflow's decisions read live here too —
#         # every one has a default, so naming a block is starting a tune.
#         # policy:
#         #   maxImplementAttempts: 3
#         #   pollBackoffMs: 300000
#
# A workflow of your own is the same shape, under ~/.amy/workflows;
# \`amy workflow new <name>\` writes one.
#
# Which one runs when --workflow is not given. The first, if this is empty.
# defaultWorkflow: ticket-to-qa
#
# Plugins mounted under every workflow, named here or added with \`amy add\`.
# Kept apart from a profile's own \`plugins:\` so a profile left on the
# recommended set stays on it and gains one, rather than having the whole
# recommendation copied into the config behind your back.
# extraPlugins: []
#
# Keep the packages this machine mounts current around workflow invocations.
# The count is kept per workflow profile under ~/.amy, so restarting does not
# reset it. Set enabled false to leave updates entirely to the operator.
autoUpdate:
  enabled: true
  timing: before
  everyRuns: 20

# Finished queue items are only useful for reading the log afterwards.
retentionDays: 7

# What the engine does with an item that went wrong rather than with the work
# itself. A claim older than staleClaimMs belonged to a worker that is no
# longer running, so the item is handed back; past maxItemAttempts the item is
# dropped and you are told, rather than retried forever in silence.
staleClaimMs: 1800000
maxItemAttempts: 5

# Which agents to try, cheapest first. Naming a harness here is what mounts
# it, so leaving codex and hermes out means they are never required to be
# installed. A failure moves to the next model of the same harness and then to
# the next harness; a rate limit skips the rest of that harness, because a
# bigger model behind the same quota is still blocked.
#
# ladderByStep overrides the list for one step, keyed by the workflow's action
# name — reading a ticket and writing the change are not the same job, and one
# list for both pays the expensive model to do the cheap step.
agent:
  ladder: [claude:sonnet, claude:opus]
  ladderByStep:
    triage: [claude:haiku]
    implement: [claude:opus]
  # Long flag: the claude CLI does not accept -m.
  model: sonnet
  # What the agents may spend. Two ceilings per window and the first one to
  # blow parks the work: tokens are what a subscription meters, dollars are
  # what an API key costs. A run whose cost nobody reported moves the token
  # ceiling and not the dollar one. Leave the whole block out for no ceiling.
  budget:
    perFiveHours: { tokens: 2000000, costUsd: 20 }
    perWeek: { tokens: 30000000, costUsd: 150 }
    # The fraction of a ceiling at which new work stops being started.
    stopAt: 0.9
  # Guidance appended when answering a particular reviewer, by host login.
  # A reviewer with known habits is cheaper to satisfy on the first pass.
  reviewerHints:
    edsger: >-
      Delete anything that is not needed. No variable that aliases an existing
      value, no check the types already guarantee, no comment stating the
      obvious, no non-null assertions.

# Who does each step. A step with no entry is done by the agent in amy's own
# words, which is every step until you say otherwise. A skill named here must
# be installed under ~/.claude/skills, or the mount is refused at boot: a
# ladder that quietly means less than it says would first show up as a ticket
# escalating for no reason.
#
# The skills are tried in order, and each one is tried across the harness
# ladder above before the next gets a turn. Only the three steps an agent
# performs can be handed over: triage, implement, address-threads.
# skills:
#   address-threads: [/northwind-code-review, /logion]
#   triage: [/logion]

# Where the machine reaches you. It needs at least one of these.
#
# There is no tracker line any more. A tracker comment is for a question that
# needs a person, and the workflow posts those itself; progress notices belong
# on the operator's channels, which are the two below. That removes the
# pollution rather than teaching every reader to filter it.
notify:
  hermes: slack:my-channel   # a Hermes delivery target, or null
  inbox: true        # a file in .amy/needs-input plus a desktop notification

# Any command line tool, reached by a name. One adapter for all of them: the
# machine learns that a name maps to a line somebody wrote down, and nothing
# about what pup or ntn mean.
#
# The line comes only from here, and only the arguments may come from a
# workflow. A line assembled from a ticket body would be a machine that runs
# whatever a stranger can type into an issue.
#
#   "@amykit/plugin-command":
#     allow:
#       datadog: pup monitors list --json
#       notion: ntn page get
#
# The machine carries none of the vocabulary of a particular plugin: what the
# agents spend is the only top-level block left here, and the workspace — the
# repositories, where their checkouts live, their branches and their worktrees —
# is the file-worktree plugin's slice, the gate commands the command-gate
# plugin's. \`amy update\` moves an old install, \`amy config explain\`
# lists every slice's settings, and an install that drives no code mounts no
# workspace and is asked for none of it.
#
#   plugins:
#     "@amykit/plugin-file-worktree":
#       repos:
#         - Northwind/northwind-backend
#         - Northwind/northwind-frontend
#       workspaceRoot: ~/workspaces/northwind
#       defaultBranch: main
#     "@amykit/plugin-command-gate":
#       gate:
#         Northwind/northwind-backend:
#           - npm run --workspace @northwind/api lint
#           - npm run --workspace @northwind/api typecheck
#
# The tracker's settings and every workflow's own live with what mounts them.
# plugins:
#   "@amykit/plugin-notify-hermes":
#     target: slack:my-channel
#   "@amykit/plugin-file-queue":
#     retentionDays: 7
#   "@amykit/plugin-linear":
#     workingStatusName: In Progress
#     repoByTeam:
#       PROJ: Northwind/northwind-backend
`;



/**
 * The file without one top-level block, its indented lines included.
 *
 * A line walk rather than one multi-line pattern: a quantifier over indented
 * lines nested inside another is the shape that backtracks forever, and a
 * config file is not worth a regular expression nobody can reason about.
 */
function withoutBlock(text: string, header: string): string {
  const kept: string[] = [];
  let inside = false;

  for (const line of text.split("\n")) {
    if (inside && (/^[ \t]+\S/.test(line) || line.trim() === "")) continue;
    inside = line.startsWith(header);
    if (!inside) kept.push(line);
  }

  return kept.join("\n");
}

/**
 * Rewrites one top-level block, leaving every other line as it was.
 *
 * The one writer the profile and the extra list share: the block is the
 * thing being edited and there is no way to edit it without re-emitting it,
 * while everything beside it — the comments that explain what each setting
 * is for — is most of the file's value and is kept as it was.
 */
function writeBlock(root: string, header: string, block: string): void {
  const file = paths(root).config;
  const existing = fs.existsSync(file) ? fs.readFileSync(file, "utf-8") : "";
  const without = withoutBlock(existing, header).replace(/\n{3,}$/, "\n\n");

  fs.mkdirSync(paths(root).base, { recursive: true });
  fs.writeFileSync(file, `${without.replace(/\n*$/, "\n")}\n${block}`.trimEnd() + "\n", "utf-8");
}

/**
 * Adds one workflow profile without rewriting the rest of the operator's config.
 *
 * `settings` are the placeholders the workflow's own schema asked for: every
 * required field it carries an `example` for, written with that example — a
 * value the plugin says it would mount with, and one the operator edits. The
 * rest of the schema's settings stay out: they have defaults, and the mount
 * fills them in.
 */
export function writeWorkflowProfile(
  root: string,
  profile: string,
  workflow: string,
  config: AmyConfig,
  settings: ProfileSettings = {},
): void {
  const entry: Record<string, unknown> = { workflow, ...(Object.keys(settings).length > 0 ? { settings } : {}) };
  const workflows = { ...config.workflows, [profile]: entry };
  const defaultLine = config.defaultWorkflow || Object.keys(config.workflows).length > 0
    ? ""
    : `\ndefaultWorkflow: ${profile}\n`;

  writeBlock(
    root,
    "workflows:",
    `${yaml.stringify({ workflows })}${defaultLine}`.trimEnd(),
  );
}

/**
 * The settings one workflow's schema asks the profile to carry.
 *
 * Only the required ones without a default are the operator's to start: a
 * required setting whose machine hands it over gets no entry here, and one
 * with a default gets no entry either — leaving it out IS its default. What
 * is written is the schema's own `example`, so the value that lands in the
 * config is one the plugin itself said it would mount with.
 */
export function profileSettingsFrom(schema: ConfigSchema): ProfileSettings {
  const settings: ProfileSettings = {};
  for (const [key, spec] of Object.entries(schema)) {
    if (key.includes(".")) continue;
    if (spec.required && spec.default === undefined && spec.example !== undefined) {
      settings[key] = spec.example;
    }
  }
  return settings;
}

export function writeProfilePlugins(
  root: string,
  profile: string,
  specs: readonly string[],
  config: AmyConfig,
  briefStore = config.workflows[profile]?.briefStore,
): void {
  const declared = { ...config.workflows };
  const entry = declared[profile];
  if (!entry) throw new Error(`there is no \`${profile}\` workflow to add a plugin to`);

  const workflow = entry.workflow;
  const workflowAtRoot = workflow.startsWith(".") ? path.resolve(root, workflow) : workflow;
  // Live profiles normalize relative filesystem plugins for mounting. Preserve
  // their configured spelling when this writer serializes the profile again.
  const portableSpecs = specs.map((spec) => spec === workflowAtRoot ? workflow : spec);
  declared[profile] = { ...entry, plugins: portableSpecs, ...(briefStore !== entry.briefStore ? { briefStore } : {}) };

  writeBlock(root, "workflows:", yaml.stringify({ workflows: declared }));
}

/**
 * Drops a profile from the config, leaving every other line as it was.
 *
 * The entry only, never the state: what a profile did is in the log, which is
 * append-only because the budget is read off it.
 */
export function removeProfile(root: string, profile: string, config: AmyConfig): void {
  const declared = { ...config.workflows };
  delete declared[profile];

  writeBlock(
    root,
    "workflows:",
    Object.keys(declared).length > 0 ? yaml.stringify({ workflows: declared }) : "",
  );
  // A default is a pointer into this table. Leaving it behind reads fine now
  // but refuses a later command, so removal clears its own orphan.
  if (config.defaultWorkflow === profile) writeBlock(root, "defaultWorkflow:", "");
}

/**
 * Adds one package to the machine-wide plugin list, without rewriting the
 * rest of the operator's config.
 */
export function writeExtraPlugins(
  root: string,
  specs: readonly string[],
): void {
  writeBlock(root, "extraPlugins:", yaml.stringify({ extraPlugins: [...specs] }));
}

/**
 * Drops one package from the machine-wide plugin list.
 */
export function removeExtraPlugin(
  root: string,
  spec: string,
): void {
  const kept = loadConfig(root).extraPlugins.filter((name) => name !== spec);
  writeBlock(root, "extraPlugins:", yaml.stringify({ extraPlugins: kept }));
}

import fs from "node:fs";
import path from "node:path";

/**
 * What is written down about the loop that is running.
 *
 * A file rather than a lock: it survives the process that wrote it, which is
 * the case worth handling — a machine that was rebooted mid-run leaves one
 * behind, and a second `amy start` has to be able to tell that from a loop
 * that is genuinely up.
 */
export interface DaemonRecord {
  pid: number;
  /** Which profile it is driving, so `amy status` says so without guessing. */
  workflow: string;
  startedAt: string;
}

export function readDaemon(file: string): DaemonRecord | undefined {
  try {
    return JSON.parse(fs.readFileSync(file, "utf-8")) as DaemonRecord;
  } catch {
    return undefined;
  }
}

export function writeDaemon(file: string, record: DaemonRecord): void {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify(record, null, 2)}\n`, "utf-8");
}

export function clearDaemon(file: string): void {
  fs.rmSync(file, { force: true });
}

/** Claims a stopped daemon record without removing a newer loop's record. */
export function claimExitedDaemon(file: string, pid: number): DaemonRecord | undefined {
  const claim = `${file}.exited-${process.pid}`;
  try {
    fs.renameSync(file, claim);
  } catch {
    return undefined;
  }

  const record = readDaemon(claim);
  if (!record || record.pid !== pid || isAlive(record.pid)) {
    if (!fs.existsSync(file)) fs.renameSync(claim, file);
    else fs.rmSync(claim, { force: true });
    return undefined;
  }

  fs.rmSync(claim, { force: true });
  return record;
}

/**
 * Claims the short boundary where a loop becomes visible, or an update owns
 * the machine. `open(..., "wx")` is atomic: a start cannot slip between an
 * update's running check and its package move. The owner is written before
 * the descriptor closes, so a file that exists is a file with an owner: a
 * crash in that window leaves nothing on disk, because the write and the
 * existence share the one syscall pair nobody else can see between.
 */
export function claimDaemonBoundary(pidFile: string): (() => void) | undefined {
  const lock = `${pidFile}.lock`;
  fs.mkdirSync(path.dirname(lock), { recursive: true });
  for (let attempt = 0; attempt < 2; attempt += 1) {
    let descriptor: number | undefined;
    try {
      descriptor = fs.openSync(lock, "wx");
      fs.writeFileSync(descriptor, `${process.pid}\n`, "utf-8");
      fs.closeSync(descriptor);
      return () => fs.rmSync(lock, { force: true });
    } catch (error) {
      if (descriptor !== undefined) {
        try { fs.closeSync(descriptor); } catch { /* already closed */ }
      }
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      // The owner may release the lock between our refused open and this
      // read: a disappearing lock is a claim that came free, not a crash,
      // so it is retried like a stale claim is. Any other read error is
      // ours, and says so.
      let owner: number;
      try {
        owner = Number(fs.readFileSync(lock, "utf-8").trim());
      } catch (readError) {
        if ((readError as NodeJS.ErrnoException).code !== "ENOENT") throw readError;
        continue;
      }
      // A pid of 0 is a malformed record, not an owner: kill(0, 0) asks
      // about the process group and would report a live lock nobody owns.
      if ((!Number.isSafeInteger(owner) || owner <= 0 || !isAlive(owner))) {
        fs.rmSync(lock, { force: true });
        continue;
      }
      return undefined;
    }
  }
  return undefined;
}

/**
 * Whether a process id belongs to something still running.
 *
 * Signal 0 checks for the process without touching it. A process somebody
 * else owns answers `EPERM`, which is still an answer: it exists.
 */
export function isAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as { code?: string }).code === "EPERM";
  }
}

/** The loop that is running, or nothing — a record naming a dead pid is nothing. */
export function running(file: string): DaemonRecord | undefined {
  const record = readDaemon(file);
  if (!record) return undefined;
  if (isAlive(record.pid)) return record;

  // Cleared here rather than reported, because a stale file is not news: it
  // is what a reboot leaves behind, and the next `amy start` should just work.
  clearDaemon(file);
  return undefined;
}

/** A live record belongs to the profile that wrote it, not merely its path. */
export function runningForWorkflow(file: string, workflow: string): DaemonRecord | undefined {
  const record = running(file);
  return record?.workflow === workflow ? record : undefined;
}

/** What one loop needs from the process around it, so the order of its moves can be driven in a test. */
export interface Loop {
  readonly idleMs: number;
  stopping(): boolean;
  paused(): boolean;
  /** One pass: discovery, then a tick. Idle when there was nothing to do. */
  turn(): Promise<{ idle: boolean }>;
  /** Whether a fork or a workflow of your own changed since it was mounted. */
  changed(): boolean;
  /** Mounts again from the config alone; only ever called between two turns. */
  remount(): Promise<void>;
  sleep(ms: number): Promise<void>;
}

/**
 * The daemon's loop. A change to what is mounted is noticed at the top of a
 * pass and answered there (S17): a tick in progress always finishes on the
 * mount it started with, and the next one starts on the new mount.
 */
export async function runLoop(loop: Loop): Promise<void> {
  while (!loop.stopping()) {
    if (loop.paused()) {
      await loop.sleep(loop.idleMs);
      continue;
    }
    if (loop.changed()) {
      await loop.remount();
      if (loop.stopping()) break;
    }
    const { idle } = await loop.turn();
    if (idle) await loop.sleep(loop.idleMs);
  }
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { Check, checkoutFor, CommandRunner, ConfigSchema, Workflow, validateConfig } from "@amykit/core";
import { AmyConfig, configuredAutoUpdateProblems } from "./config.js";
import { strayState } from "./home.js";
import { LEGACY_DIRECTORIES } from "./profiles.js";
import { paths } from "./paths.js";

export type { Check } from "@amykit/core";

export interface DoctorDeps {
  /** Where amy keeps its state, machine-wide. */
  home: string;
  config: AmyConfig;
  runner: CommandRunner;
  env: NodeJS.ProcessEnv;
  now: Date;
  /** Where the command was typed, which is not where amy keeps anything. */
  cwd: string;
  /**
   * What each plugin said its settings look like, by package name.
   *
   * Handed in rather than looked up, because the only honest source is the
   * plugins this install actually loaded. A table compiled in here would
   * describe a machine other than the one being diagnosed.
   */
  schemas: Readonly<Record<string, ConfigSchema>>;
  /**
   * The notification port, if this install mounted one.
   *
   * Handed in for the same reason the schemas are: whether a target is
   * reachable is the mounted channel's own knowledge, not something the host
   * re-derives by importing one notifier's reader. Undefined means no channel
   * was mounted, which is its own answer.
   */
  notifyPort?: object;
  /**
   * The gate port, if this install mounted one; absent means no workflow
   * here hands work to a gate, and the machine is asked nothing about how
   * work gets vouched for.
   */
  gatePort?: object;
  /**
   * The workspace port, if this install mounted one; absent means the
   * machine drives no code, and it is asked nothing about repositories,
   * checkouts or worktrees at all.
   */
  workspacePort?: object;
  /**
   * What each mounted plugin reads from the process's environment, by package
   * name. The doctor asks exactly these, one variable at a time; a machine
   * that mounted none of them is asked none of them.
   */
  environments?: Readonly<Record<string, readonly string[]>>;
  /**
   * The conversation port, if this install mounted one.
   *
   * Asked for its own checks for the same reason the notification port is
   * asked whether its target is reachable: which scopes a Slack token needs
   * is the adapter's knowledge, and the host imports no adapter to learn it.
   */
  conversationPort?: object;
  /** The selected workflow's declared external-write surface, if it mounted. */
  workflow?: Workflow;
}

/**
 * Everything the machine depends on, asked one at a time.
 *
 * A list of small checks rather than one long function, so adding a
 * dependency to worry about costs one entry and the whole thing stays
 * readable and testable. It returns the answers instead of printing them,
 * which is why it can be tested at all.
 */
export async function diagnose(deps: DoctorDeps): Promise<Check[]> {
  return [
    configFile(deps),
    ...configContents(deps),
    autoUpdateSettings(deps.config),
    ...pluginSettings(deps),
    workflowWrites(deps.workflow),
    ...leftBehind(deps),
    ...environment(deps),
    ...(await tools(deps)),
    ...(await hermes(deps)),
    ...(await conversation(deps)),
    ...checkouts(deps),
    ...worktrees(deps),
  ];
}

function configFile({ home }: DoctorDeps): Check {
  const file = paths(home).config;
  return { label: "config file", ok: fs.existsSync(file), detail: file };
}

function configContents({ config, gatePort, workspacePort }: DoctorDeps): Check[] {
  const checks: Check[] = [
    {
      label: "a notification channel is on",
      ok: config.notify.inbox || Boolean(config.notify.hermes),
    },
  ];

  // A gate's commands are the machine's only while a workflow here hands
  // work to one: a machine that mounted no gate cannot vouch for a change
  // either way, and a checklist it can never satisfy is a red dot the
  // operator learns to scroll past.
  if (gatePort) {
    checks.push({ label: "gate configured", ok: Object.keys(gateCommands(config)).length > 0 });
  }

  // The same word the workspace is asked with: a machine that drives no code
  // mounts no workspace, and a repositories check it can never pass is a red
  // dot the operator learns to scroll past.
  if (workspacePort) {
    const repos = workspaceRepos(config);
    checks.push({
      label: "repos configured",
      ok: repos.length > 0,
      detail: repos.join(", "),
    });
  }

  return checks;
}

function workflowWrites(workflow: Workflow | undefined): Check {
  if (!workflow) return { label: "workflow write surface", ok: true, detail: "no workflow assembled" };
  const tracker = workflow.trackerWrites ?? [];
  const codeHost = workflow.codeHostWrites ?? [];
  return {
    label: "workflow write surface",
    ok: true,
    detail: tracker.length === 0 && codeHost.length === 0
      ? "read-only: it cannot write the tracker or code host"
      : `tracker: ${tracker.join(", ") || "none"}; code host: ${codeHost.join(", ") || "none"}`,
  };
}

/**
 * Each plugin's own settings, against the schema that plugin declared.
 *
 * A plugin with no slice configured is fine: its defaults apply. A slice for
 * a plugin this build does not have is not fine, because it is a setting
 * somebody wrote expecting it to do something.
 */
function autoUpdateSettings(config: AmyConfig): Check {
  const problems = configuredAutoUpdateProblems(config);
  return {
    label: "auto update settings",
    ok: problems.length === 0,
    detail: problems.join("; "),
  };
}

function pluginSettings({ config, schemas }: DoctorDeps): Check[] {
  const checks: Check[] = [];

  for (const [plugin, given] of Object.entries(config.plugins)) {
    const schema = schemas[plugin];
    if (!schema) {
      checks.push({
        label: `settings for ${plugin}`,
        ok: false,
        detail: "nothing mounted declares these settings",
      });
      continue;
    }

    const result = validateConfig(plugin, schema, given);
    checks.push({
      label: `settings for ${plugin}`,
      ok: result.ok,
      detail: result.ok ? "" : result.problems.join("; "),
    });
  }

  return checks;
}

/**
 * State written by a version that kept one pair of directories per install.
 *
 * Reported rather than moved: it is somebody's work in flight, and the one
 * command that puts it where the new layout looks is cheaper to read than a
 * migration that ran without being asked. A name the current config declares
 * is a profile, not a leftover — the operator chose it, and its directory is
 * where this layout looks.
 */
function leftBehind({ home, cwd, config }: DoctorDeps): Check[] {
  const base = paths(home).base;
  const stray = strayState(cwd, base);

  const here: Check[] = stray
    ? [
        {
          label: "state in the working directory",
          ok: false,
          detail: `${stray} is not read any more; amy keeps everything in ${base}`,
        },
      ]
    : [];

  return here.concat(
    Object.entries(LEGACY_DIRECTORIES)
      .filter(([old]) => fs.existsSync(path.join(base, old)))
      .filter(([old]) => !(old in config.workflows))
      .map(([old, now]) => ({
        label: `state left in ${old}`,
        ok: false,
        detail: `run \`amy init\`, then: mv ${path.join(base, old)} ${path.join(base, now)}`,
      })),
  );
}

/**
 * What the machine's mounted plugins read from the process's environment,
 * one variable at a time: the plugin that needs it names it, and a machine
 * that mounted none of them carries none of these checks at all.
 */
function environment({ environments, env }: DoctorDeps): Check[] {
  return [...new Set(Object.values(environments ?? {}).flat())]
    .sort()
    .map((name) => ({ label: name, ok: Boolean(env[name]) }));
}

const REQUIRED_TOOLS: readonly [string, readonly string[]][] = [
  ["claude", ["--version"]],
];

/**
 * The tools only work in a repository needs: asked of an install that mounts
 * a workspace, so a machine that drives no code is not told it is broken for
 * want of a GitHub login.
 */
const WORKSPACE_TOOLS: readonly [string, readonly string[]][] = [
  ["gh", ["auth", "status"]],
  ["git", ["--version"]],
];

async function tools({ runner, workspacePort }: DoctorDeps): Promise<Check[]> {
  const checks: Check[] = [];

  for (const [tool, args] of [...(workspacePort ? WORKSPACE_TOOLS : []), ...REQUIRED_TOOLS]) {
    const result = await runner.run(tool, args, { timeoutMs: 30_000 });
    checks.push({
      label: `${tool} available`,
      ok: result.ok,
      detail: result.ok ? "" : (result.stderr.split("\n")[0] ?? ""),
    });
  }

  return checks;
}

/**
 * Whether the notification port this install mounted can reach the target.
 *
 * The question is asked of the port, not of one notifier's reader: the host
 * carrying `@amykit/plugin-notify-hermes` in its dependencies was the host
 * holding a plugin's knowledge, and the machine installing only the command
 * paid for a package it had never chosen. A mount with no channel is an
 * install that has not turned one on — the check above already says so —
 * and nothing is asked of a port that was never mounted.
 */
type Reachable = { isReachable(target: string): Promise<boolean> | boolean };

async function hermes({ config, notifyPort }: DoctorDeps): Promise<Check[]> {
  const target = config.notify.hermes;
  if (!target) return [];
  if (!notifyPort) {
    return [
      {
        label: `hermes target ${target}`,
        ok: false,
        detail: "no notification channel is mounted, so nothing could ask whether it is reachable",
      },
    ];
  }

  const reachable = notifyPort as Reachable;
  try {
    const known = await reachable.isReachable(target);
    return [
      {
        label: `hermes target ${target}`,
        ok: known,
        detail: known ? "" : "hermes does not have this target configured",
      },
    ];
  } catch (error) {
    return [
      {
        label: `hermes target ${target}`,
        ok: false,
        detail: error instanceof Error ? error.message : "the channel could not be asked",
      },
    ];
  }
}

/** A conversation adapter that can say whether it can reach its thread. */
type SelfChecking = { checks(): Promise<Check[]> };

async function conversation({ conversationPort }: DoctorDeps): Promise<Check[]> {
  const port = conversationPort as Partial<SelfChecking> | undefined;
  if (typeof port?.checks !== "function") return [];
  try {
    return await port.checks();
  } catch (error) {
    return [
      {
        label: "conversation",
        ok: false,
        detail: error instanceof Error ? error.message : "the conversation could not be asked",
      },
    ];
  }
}

function checkouts({ config, workspacePort }: DoctorDeps): Check[] {
  if (!workspacePort) return [];
  const { repos, workspaceRoot, checkouts: perRepo } = workspacePaths(config);
  // The same function the machine resolves through, so what the doctor names
  // is the root that was actually asked rather than a second derivation.
  return repos.map((repo) => {
    const checkout = checkoutFor({ workspaceRoot, checkouts: perRepo, defaultBranch: "main" }, repo);
    const asked = repo in perRepo ? `its own root (${checkout})` : `the workspace root (${workspaceRoot})`;
    return {
      label: `checkout ${repo}`,
      ok: fs.existsSync(path.join(checkout, ".git")),
      detail: `asked ${asked}`,
    };
  });
}

function worktrees({ config, workspacePort, home }: DoctorDeps): Check[] {
  if (!workspacePort) return [];
  const root = workspaceSlice(config).root || path.join(home, "worktrees");
  return [
    {
      label: "worktrees root",
      ok: true,
      detail: `${root} (checkouts stay in ${workspacePaths(config).workspaceRoot})`,
    },
  ];
}

/** The workspace slice, read the way the provider's schema spells it. */
function workspaceSlice(config: AmyConfig): { root: string; workspaceRoot: string; repos: string[]; checkouts: Record<string, string> } {
  const given = config.plugins["@amykit/plugin-file-worktree"];
  const slice = typeof given === "object" && given !== null && !Array.isArray(given)
    ? (given as Record<string, unknown>)
    : {};
  const strings = (value: unknown): string[] => (Array.isArray(value) ? value.filter((one): one is string => typeof one === "string") : []);
  const map = (value: unknown): Record<string, string> => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) return {};
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).filter(([, one]) => typeof one === "string") as [string, string][],
    );
  };
  const repos = strings(slice.repos);
  const checkouts = map(slice.checkouts);
  return {
    root: typeof slice.root === "string" ? slice.root : "",
    workspaceRoot: expandHome(typeof slice.workspaceRoot === "string" && slice.workspaceRoot !== "" ? slice.workspaceRoot : "."),
    repos,
    checkouts: Object.fromEntries(Object.entries(checkouts).map(([repo, one]) => [repo, expandHome(one)])),
  };
}

/** The workspace's repositories, as the doctor prints them. */
function workspaceRepos(config: AmyConfig): string[] {
  return workspaceSlice(config).repos;
}

/** The workspace's paths, expanded the way the provider expands them. */
function workspacePaths(config: AmyConfig): { workspaceRoot: string; checkouts: Record<string, string>; repos: string[] } {
  const { workspaceRoot, checkouts, repos } = workspaceSlice(config);
  return { workspaceRoot, checkouts, repos };
}

/** The gate commands, read from the plugin whose slice carries them. */
function gateCommands(config: AmyConfig): Record<string, string[]> {
  const given = config.plugins["@amykit/plugin-command-gate"];
  const slice = typeof given === "object" && given !== null && !Array.isArray(given)
    ? (given as Record<string, unknown>)
    : {};
  const gate = slice.gate;
  if (typeof gate !== "object" || gate === null || Array.isArray(gate)) return {};
  return gate as Record<string, string[]>;
}

/** `~/workspaces/northwind` becomes an absolute path. */
function expandHome(value: string): string {
  if (value === "~") return os.homedir();
  if (value.startsWith("~/")) return path.join(os.homedir(), value.slice(2));
  return value;
}

import path from "node:path";
import { fileURLToPath } from "node:url";
import { Plugin, declaredWorkflowsOnly, withDiagramBeside } from "@amykit/core";

/**
 * The plugin, shaped by the `workflow.mmd` beside the entry it was imported
 * from, the way the entry itself was found: beside a workflow of your own,
 * or at the root of the package. Nothing names the file. A workflow with
 * none beside it is refused when it mounts, naming the file it needs, and a
 * plugin that registers a workflow by hand is refused: every workflow amy
 * mounts from an install is a `defineWorkflow` with a diagram.
 */
export function drawn(plugin: Plugin, specifier: string): Plugin {
  const entry = entryOf(specifier);
  return declaredWorkflowsOnly(entry ? withDiagramBeside(plugin, entry) : plugin);
}

/** The file an import specifier names, or nothing when it cannot be told. */
function entryOf(specifier: string): string | undefined {
  if (specifier.startsWith("file:")) return fileURLToPath(specifier);
  if (path.isAbsolute(specifier)) return specifier;
  try {
    const resolved = import.meta.resolve(specifier);
    return resolved.startsWith("file:") ? fileURLToPath(resolved) : undefined;
  } catch {
    return undefined;
  }
}

import fs from "node:fs";
import path from "node:path";

/**
 * Parses a .env file.
 *
 * Deliberately small and its own function rather than a dependency, because
 * the only thing it has to hold is an API key and the failure mode of a
 * clever parser is a credential that silently does not load.
 */
export function parseEnv(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line === "" || line.startsWith("#")) continue;

    const withoutExport = line.startsWith("export ") ? line.slice(7).trim() : line;
    const equals = withoutExport.indexOf("=");
    if (equals <= 0) continue;

    const key = withoutExport.slice(0, equals).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;

    values[key] = unquote(withoutExport.slice(equals + 1).trim());
  }

  return values;
}

function unquote(value: string): string {
  const quoted =
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"));

  return quoted && value.length >= 2 ? value.slice(1, -1) : value;
}

/**
 * Loads a .env from the working directory into the environment.
 *
 * An entry already present in the environment wins, so exporting a key for
 * one command stays a reliable way to override the file.
 *
 * Returns the names it set, never the values, so a caller can report what
 * happened without printing a secret.
 */
export function loadEnv(root: string): string[] {
  const file = path.join(root, ".env");
  if (!fs.existsSync(file)) return [];

  const applied: string[] = [];

  for (const [key, value] of Object.entries(parseEnv(fs.readFileSync(file, "utf-8")))) {
    if (process.env[key] === undefined) {
      process.env[key] = value;
      applied.push(key);
    }
  }

  return applied;
}

import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { CommandRunner } from "@amykit/core";
import { PLUGINS_ROOT_FLAGS, packageManager, shellCommand } from "./install.js";
import { profileForks, profileRoot } from "./paths.js";
import { compareVersions } from "./update.js";
import { Profile } from "./profiles.js";
import { fileURLToPath } from "node:url";
import { localWorkflow } from "./workflow.js";

/**
 * A fork is a package's source, taken from its repository at the tag its
 * version was released under, kept under the package's own name, and
 * resolved for one profile instead of the published copy.
 *
 * Design: docs/design/a-plugin-is-installed-into-a-workflow.md.
 */

/** The file a fork records its base in, beside the source it was taken from. */
export const FORK_RECORD = ".amy-fork.json";

/** What a fork was taken from: enough to fetch the same source again. */
interface ForkBase {
  readonly package: string;
  readonly version: string;
  readonly commit: string;
  readonly url: string;
  /** The package's directory inside the repository; empty for its root. */
  readonly directory: string;
  /** The tag or ref the source was fetched at. */
  readonly ref: string;
}

export interface ForkRecord {
  readonly base: ForkBase;
  /** The source digest the last successful build was taken from. */
  readonly built?: string;
}

/** Where one package's source lives: a directory of a repository at a ref. */
export interface SourceAt {
  readonly url: string;
  readonly directory: string;
  readonly ref: string;
}

/** The two packages a profile root never holds: both resolve from amy's own install. */
export const NEVER_FORKED = ["@amykit/core", "@amykit/cli"] as const;

/** What never belongs to a fork's source: what npm or a build writes, and amy's record. */
const NOT_SOURCE = new Set(["node_modules", "dist", ".git", FORK_RECORD]);

interface Manifest {
  name?: string;
  version?: string;
  repository?: string | { type?: string; url?: string; directory?: string };
  scripts?: Record<string, string>;
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  peerDependencies?: Record<string, string>;
}

function readManifest(directory: string): Manifest | undefined {
  try {
    return JSON.parse(fs.readFileSync(path.join(directory, "package.json"), "utf-8")) as Manifest;
  } catch {
    return undefined;
  }
}

/**
 * The repository URL git can fetch, from the forms a `repository` field takes:
 * npm's `git+` prefix, the `github:` shorthand and a bare `owner/repo`.
 */
function gitUrl(url: string): string {
  const trimmed = url.trim();
  if (trimmed.startsWith("github:")) return `https://github.com/${trimmed.slice("github:".length)}.git`;
  if (/^[\w.-]+\/[\w.-]+$/.test(trimmed)) return `https://github.com/${trimmed}.git`;
  return trimmed.replace(/^git\+/, "");
}

/**
 * Where a released version's source is, read off its manifest (S12): the
 * repository's URL and directory, at the tag `<name>@<version>` every release
 * is cut under. A package that declares no repository has no source to fork,
 * and that is refused naming the field and what was asked.
 */
export function sourceOfManifest(manifest: Manifest, asked: string): SourceAt {
  const name = manifest.name ?? asked;
  const repository = manifest.repository;
  const url = typeof repository === "string" ? repository : repository?.url;
  if (!url) {
    throw new Error(`${name}@${manifest.version ?? "?"} declares no \`repository\` in its package.json, so there is no source to fork it from (asked: ${asked})`);
  }
  if (!manifest.version) throw new Error(`${name} declares no \`version\`, so there is no tag to fork it at (asked: ${asked})`);
  const directory = typeof repository === "object" ? (repository.directory ?? "") : "";
  return { url: gitUrl(url), directory: trimSlashes(directory), ref: `${name}@${manifest.version}` };
}

/**
 * A git URL that names a directory of its repository: `<url>#path:<dir>`, or
 * `<url>#<ref>&path:<dir>` for a ref other than the default branch. The form
 * pnpm reads for a package inside a repository, so it is not a new word.
 */
export function gitDirectory(spec: string): SourceAt | undefined {
  const hash = spec.indexOf("#");
  if (hash < 0) return undefined;
  let ref = "";
  let directory: string | undefined;
  for (const part of spec.slice(hash + 1).split("&")) {
    if (part.startsWith("path:")) directory = trimSlashes(part.slice("path:".length));
    else if (part) ref = part;
  }
  return directory === undefined ? undefined : { url: gitUrl(spec.slice(0, hash)), directory, ref };
}

function trimSlashes(value: string): string {
  return value.replace(/^\/+/, "").replace(/\/+$/, "");
}

/** One fetched source, in a scratch directory the caller disposes of. */
export interface Fetched {
  /** The package's directory inside the fetched tree. */
  readonly directory: string;
  /** The repository's root, for what the package extends from outside itself. */
  readonly root: string;
  readonly commit: string;
  dispose(): void;
}

/**
 * Fetches one directory of a repository at a ref, into a scratch directory,
 * and refuses before anything is written when the repository cannot be
 * reached, the tag is not there, or the directory is not a package.
 */
export async function fetchSource(runner: CommandRunner, at: SourceAt, asked: string): Promise<Fetched> {
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "amy-fork-"));
  const dispose = () => fs.rmSync(scratch, { recursive: true, force: true });
  try {
    if (at.ref && !/^[0-9a-f]{40}$/.test(at.ref)) {
      const listed = await runner.run("git", ["ls-remote", at.url, `refs/tags/${at.ref}`, `refs/heads/${at.ref}`]);
      if (!listed.ok) throw new Error(`could not reach ${at.url} to fetch ${at.ref} (asked: ${asked}): ${(listed.stderr || listed.stdout).trim()}`);
      if (listed.stdout.trim() === "") throw new Error(`the tag ${at.ref} does not exist at ${at.url} (asked: ${asked})`);
    }
    const git = async (args: readonly string[], what: string) => {
      const ran = await runner.run("git", args, { cwd: scratch, timeoutMs: 10 * 60 * 1000 });
      if (!ran.ok) throw new Error(`${what} ${at.url}${at.ref ? ` at ${at.ref}` : ""} failed (asked: ${asked}): ${(ran.stderr || ran.stdout).trim()}`);
      return ran.stdout.trim();
    };
    await git(["init", "-q"], "preparing to fetch");
    await git(["fetch", "-q", "--depth", "1", at.url, at.ref || "HEAD"], "fetching");
    await git(["-c", "advice.detachedHead=false", "checkout", "-q", "FETCH_HEAD"], "checking out");
    const commit = await git(["rev-parse", "HEAD"], "reading the commit of");
    const directory = path.join(scratch, at.directory);
    if (!fs.existsSync(path.join(directory, "package.json"))) {
      throw new Error(`${at.directory || "the root"} of ${at.url} at ${at.ref || "HEAD"} is not a package: it has no package.json (asked: ${asked})`);
    }
    return { directory, root: scratch, commit, dispose };
  } catch (error) {
    dispose();
    throw error;
  }
}

/** A tree of files by relative path, the way a fork's source is compared and merged. */
export type Tree = Map<string, Buffer>;

/** Reads a directory's source, leaving out what npm or a build wrote and amy's own record. */
export function readTree(directory: string): Tree {
  const tree: Tree = new Map();
  const walk = (at: string) => {
    for (const entry of fs.readdirSync(at, { withFileTypes: true })) {
      if (NOT_SOURCE.has(entry.name) || entry.name.endsWith(".tsbuildinfo")) continue;
      const full = path.join(at, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.isFile()) tree.set(path.relative(directory, full).split(path.sep).join("/"), fs.readFileSync(full));
    }
  };
  if (fs.existsSync(directory)) walk(directory);
  return tree;
}

/** One digest for a tree: what changes when a person saves a file in a fork. */
export function treeDigest(tree: Tree): string {
  const hash = createHash("sha256");
  for (const file of [...tree.keys()].sort()) {
    hash.update(file).update("\0").update(tree.get(file)!).update("\0");
  }
  return hash.digest("hex");
}

/** Writes a tree into a directory, removing the source files it no longer has. */
export function writeTree(directory: string, tree: Tree): void {
  for (const file of readTree(directory).keys()) {
    if (!tree.has(file)) fs.rmSync(path.join(directory, file), { force: true });
  }
  for (const [file, content] of tree) {
    const to = path.join(directory, file);
    fs.mkdirSync(path.dirname(to), { recursive: true });
    if (!fs.existsSync(to) || !fs.readFileSync(to).equals(content)) fs.writeFileSync(to, content);
  }
}

export function readRecord(fork: string): ForkRecord | undefined {
  try {
    return JSON.parse(fs.readFileSync(path.join(fork, FORK_RECORD), "utf-8")) as ForkRecord;
  } catch {
    return undefined;
  }
}

export function writeRecord(fork: string, record: ForkRecord): void {
  fs.writeFileSync(path.join(fork, FORK_RECORD), `${JSON.stringify(record, null, 2)}\n`, "utf-8");
}

/**
 * Where a fork goes when nothing names a place (S14): inside the project of a
 * workflow of your own, outside what it publishes, and under the profile in
 * AMY_HOME for a workflow somebody else published. A configured `forks`
 * directory or `--to` replaces the default place; neither is a path code reads.
 */
export function forkPlace(home: string, profile: Profile, name: string, options: { to?: string; forks?: string } = {}): string {
  const unscoped = name.split("/").at(-1)!;
  if (options.to) return path.join(path.resolve(withHome(options.to)), unscoped);
  if (options.forks) return path.join(path.resolve(home, withHome(options.forks)), profile.name, unscoped);
  const own = ownedDirectory(home, profile);
  return own ? path.join(own, "forks", unscoped) : path.join(profileForks(home, profile.name), unscoped);
}

/** A leading `~` is the person's home directory, the way a shell would have read it. */
function withHome(place: string): string {
  return place === "~" || place.startsWith("~/") ? path.join(os.homedir(), place.slice(1)) : place;
}

/** The project a workflow of your own lives in, or nothing for a published one. */
function ownedDirectory(home: string, profile: Profile): string | undefined {
  if (profile.project) return profile.project.root;
  const local = localWorkflow(home, profile.workflow);
  if (local) return path.dirname(fileURLToPath(local));
  const spec = profile.workflow;
  if (!path.isAbsolute(spec) && !spec.startsWith("./") && !spec.startsWith("../")) return undefined;
  const resolved = path.resolve(spec);
  if (!fs.existsSync(resolved)) return undefined;
  return fs.statSync(resolved).isDirectory() ? resolved : path.dirname(resolved);
}

/**
 * Makes a source taken out of a monorepo build on its own: a `tsconfig.json`
 * that extends a file outside the package is flattened, its project
 * references dropped, and a package with no build script is given one. These
 * are a fork's first edits, made after the base is recorded, so an update
 * keeps them the way it keeps anything else a person changed.
 */
function standalone(fork: string, repositoryRoot: string, source: string): void {
  const original = readManifest(fork) ?? {};
  const manifest: Manifest = { ...original };
  // A workspace's private packages were never published: a fork outside the
  // workspace cannot install them, and what it needs to compile is public.
  const unpublished = privatePackages(repositoryRoot);
  if (manifest.devDependencies) {
    manifest.devDependencies = Object.fromEntries(Object.entries(manifest.devDependencies).filter(([name]) => !unpublished.has(name)));
  }
  const tsconfig = path.join(fork, "tsconfig.json");
  if (fs.existsSync(tsconfig)) {
    const flattened = flattenTsconfig(path.join(source, "tsconfig.json"), repositoryRoot);
    delete flattened.references;
    const options = (flattened.compilerOptions ?? {}) as Record<string, unknown>;
    delete options.composite;
    flattened.compilerOptions = options;
    fs.writeFileSync(tsconfig, `${JSON.stringify(flattened, null, 2)}\n`, "utf-8");
    if (!manifest.scripts?.build) {
      manifest.scripts = { ...manifest.scripts, build: "tsc -p tsconfig.json" };
      const typescript = readManifest(repositoryRoot)?.devDependencies?.typescript ?? "^5";
      manifest.devDependencies = { ...manifest.devDependencies, typescript: manifest.devDependencies?.typescript ?? typescript };
    }
  }
  if (JSON.stringify(manifest) === JSON.stringify(original)) return;
  fs.writeFileSync(path.join(fork, "package.json"), `${JSON.stringify(manifest, null, 2)}\n`, "utf-8");
}

/** The names of every package a repository marks private, two directories deep. */
export function privatePackages(repositoryRoot: string): Set<string> {
  const names = new Set<string>();
  const visit = (directory: string, depth: number) => {
    const manifest = readManifest(directory) as (Manifest & { private?: boolean }) | undefined;
    if (manifest?.private && manifest.name) names.add(manifest.name);
    if (depth === 0) return;
    for (const entry of entriesOf(directory)) {
      if (entry.isDirectory() && entry.name !== "node_modules" && !entry.name.startsWith(".")) visit(path.join(directory, entry.name), depth - 1);
    }
  };
  visit(repositoryRoot, 2);
  return names;
}

function entriesOf(directory: string): fs.Dirent[] {
  try {
    return fs.readdirSync(directory, { withFileTypes: true });
  } catch {
    return [];
  }
}

/** A tsconfig with every relative `extends` inside the repository folded in. */
function flattenTsconfig(file: string, repositoryRoot: string): Record<string, unknown> {
  const own = JSON.parse(fs.readFileSync(file, "utf-8")) as Record<string, unknown>;
  const extended = typeof own.extends === "string" && own.extends.startsWith(".") ? path.resolve(path.dirname(file), own.extends) : undefined;
  if (!extended || path.relative(repositoryRoot, extended).startsWith("..") || !fs.existsSync(extended)) return own;
  const parent = flattenTsconfig(extended, repositoryRoot);
  const merged: Record<string, unknown> = { ...parent, ...own };
  delete merged.extends;
  merged.compilerOptions = { ...(parent.compilerOptions as object | undefined), ...(own.compilerOptions as object | undefined) };
  return merged;
}

/** Copies a fetched package's source into the place a fork lives. */
function copySource(from: string, to: string): void {
  fs.mkdirSync(to, { recursive: true });
  writeTree(to, readTree(from));
}

export interface Forked {
  readonly name: string;
  readonly directory: string;
  readonly record: ForkRecord;
}

/**
 * Takes a fork: fetches the source, refuses a place that already holds
 * something, copies it there with its base recorded, and makes it build on
 * its own. Nothing is written until the fetch has succeeded.
 */
export async function takeFork(
  runner: CommandRunner,
  at: SourceAt,
  asked: string,
  place: (name: string) => string,
): Promise<Forked> {
  const fetched = await fetchSource(runner, at, asked);
  try {
    const manifest = readManifest(fetched.directory) ?? {};
    const name = manifest.name;
    if (!name) throw new Error(`${at.url}${at.directory ? `#path:${at.directory}` : ""} holds a package.json with no name (asked: ${asked})`);
    if ((NEVER_FORKED as readonly string[]).includes(name)) {
      throw new Error(`${name} is not forked: it resolves from amy's own install in every profile`);
    }
    const directory = place(name);
    if (fs.existsSync(directory)) throw new Error(`${directory} already exists; a fork is taken into an empty place`);
    copySource(fetched.directory, directory);
    const record: ForkRecord = {
      base: { package: name, version: manifest.version ?? "", commit: fetched.commit, url: at.url, directory: at.directory, ref: at.ref },
    };
    writeRecord(directory, record);
    standalone(directory, fetched.root, fetched.directory);
    return { name, directory, record };
  } finally {
    fetched.dispose();
  }
}

/** The manifest amy writes at a profile root: what it depends on, and which names it overrides. */
export interface RootManifest {
  name: string;
  private: true;
  dependencies: Record<string, string>;
  overrides: Record<string, string>;
}

/**
 * The forks a profile resolves, by package name: the names its root
 * overrides, each mapped to the directory its `file:` dependency names.
 */
export function profileForkDirectories(home: string, profile: string): Map<string, string> {
  const manifest = readRootManifest(home, profile);
  const forks = new Map<string, string>();
  if (!manifest) return forks;
  const root = profileRoot(home, profile);
  for (const name of Object.keys(manifest.overrides ?? {})) {
    const spec = manifest.dependencies?.[name];
    if (spec?.startsWith("file:")) forks.set(name, path.resolve(root, spec.slice("file:".length)));
  }
  return forks;
}

export function readRootManifest(home: string, profile: string): RootManifest | undefined {
  try {
    return JSON.parse(fs.readFileSync(path.join(profileRoot(home, profile), "package.json"), "utf-8")) as RootManifest;
  } catch {
    return undefined;
  }
}

/** Whether a profile root holds this name as one of its own, ahead of the machine's. */
export function heldByProfile(home: string, profile: string, name: string): boolean {
  return Object.hasOwn(readRootManifest(home, profile)?.dependencies ?? {}, name);
}

/**
 * The packages of a profile that must sit in its root for an import of a
 * forked name to reach the fork: every one installed in the machine's root
 * that depends on a forked name, directly or through another installed one.
 */
function dependentsOf(pluginsRoot: string, specs: readonly string[], forked: ReadonlySet<string>): string[] {
  const reaching = new Map<string, boolean>();
  const reaches = (name: string, seen: Set<string>): boolean => {
    if (forked.has(name)) return true;
    const known = reaching.get(name);
    if (known !== undefined) return known;
    if (seen.has(name)) return false;
    seen.add(name);
    const manifest = readManifest(path.join(pluginsRoot, "node_modules", ...name.split("/")));
    const names = Object.keys({ ...manifest?.dependencies, ...manifest?.peerDependencies });
    const answer = names.some((dependency) => reaches(dependency, seen));
    reaching.set(name, answer);
    return answer;
  };
  return specs.filter((spec) => !forked.has(spec) && readManifest(path.join(pluginsRoot, "node_modules", ...spec.split("/"))) !== undefined && reaches(spec, new Set()));
}

export interface RootOutcome {
  readonly ok: boolean;
  readonly command: string;
  readonly output: string;
}

/**
 * Writes a profile's root and installs it (S11): each fork under
 * `dependencies` as a `file:` spec and `$`-referred to under `overrides`, so
 * a package that imports the name reaches the fork too; each package of the
 * profile that imports a forked name installed beside it. Then the core and
 * the cli are taken out (S19), so what the root holds resolves them from the
 * machine's root it sits inside. No fork left removes the root.
 */
export async function installProfileRoot(
  runner: CommandRunner,
  home: string,
  pluginsRoot: string,
  profile: string,
  forks: ReadonlyMap<string, string>,
  specs: readonly string[],
): Promise<RootOutcome> {
  const root = profileRoot(home, profile);
  if (forks.size === 0) {
    fs.rmSync(root, { recursive: true, force: true });
    return { ok: true, command: "", output: "" };
  }
  const { dependencies, overrides } = rootDeclaration(pluginsRoot, forks, specs);
  const manifest: RootManifest = { name: `amy-profile-${profile}`, private: true, dependencies, overrides };
  fs.mkdirSync(root, { recursive: true });
  fs.writeFileSync(path.join(root, "package.json"), `${JSON.stringify(manifest, null, 2)}\n`, "utf-8");
  // A `file:` package installed as a copy is not copied again while one is
  // there; the copy of a fork is always taken fresh.
  for (const name of Object.keys(dependencies)) fs.rmSync(path.join(root, "node_modules", ...name.split("/")), { recursive: true, force: true });

  const args = ["install", "--prefix", root, ...PLUGINS_ROOT_FLAGS];
  const command = shellCommand(packageManager(), args);
  const ran = await runner.run(packageManager(), args, { timeoutMs: 10 * 60 * 1000 });
  const output = [ran.stdout, ran.stderr].filter(Boolean).join("\n").trim();
  if (!ran.ok) return { ok: false, command, output };
  pruneHostPackages(path.join(root, "node_modules"));
  return { ok: true, command, output };
}

/** What a profile root declares: each fork and its override, and each installed package that imports one. */
function rootDeclaration(pluginsRoot: string, forks: ReadonlyMap<string, string>, specs: readonly string[]): Pick<RootManifest, "dependencies" | "overrides"> {
  const dependencies: Record<string, string> = {};
  const overrides: Record<string, string> = {};
  for (const [name, directory] of [...forks].sort(([a], [b]) => a.localeCompare(b))) {
    dependencies[name] = `file:${directory}`;
    overrides[name] = `$${name}`;
  }
  for (const dependent of dependentsOf(pluginsRoot, specs, new Set(forks.keys())).sort()) {
    dependencies[dependent] = `file:${path.join(pluginsRoot, "node_modules", ...dependent.split("/"))}`;
  }
  return { dependencies, overrides };
}

/**
 * Whether a profile root still says what the profile mounts: the same
 * declaration, and every copy of an installed package at the version the
 * machine's root holds now. A new consumer, or one the machine updated,
 * makes it stale even when no fork moved.
 */
function rootIsCurrent(home: string, pluginsRoot: string, profile: string, forks: ReadonlyMap<string, string>, specs: readonly string[]): boolean {
  const written = readRootManifest(home, profile);
  const wanted = rootDeclaration(pluginsRoot, forks, specs);
  if (JSON.stringify(written?.dependencies) !== JSON.stringify(wanted.dependencies)) return false;
  if (JSON.stringify(written?.overrides) !== JSON.stringify(wanted.overrides)) return false;
  const root = profileRoot(home, profile);
  return Object.keys(wanted.dependencies).filter((name) => !forks.has(name)).every((name) => {
    const copy = readManifest(path.join(root, "node_modules", ...name.split("/")))?.version;
    return copy !== undefined && copy === readManifest(path.join(pluginsRoot, "node_modules", ...name.split("/")))?.version;
  });
}

/** Removes every copy of the core and the cli a profile root's install put down, however deep. */
function pruneHostPackages(modules: string): void {
  if (!fs.existsSync(modules)) return;
  for (const name of NEVER_FORKED) fs.rmSync(path.join(modules, ...name.split("/")), { recursive: true, force: true });
  for (const entry of fs.readdirSync(modules)) {
    const inner = path.join(modules, entry);
    const packages = entry.startsWith("@") ? fs.readdirSync(inner).map((name) => path.join(inner, name)) : [inner];
    for (const directory of packages) {
      const nested = path.join(directory, "node_modules");
      if (fs.existsSync(nested)) pruneHostPackages(nested);
    }
  }
}

export interface Built {
  readonly ok: boolean;
  /** Whether a build ran at all: an unchanged source is not built again. */
  readonly ran: boolean;
  readonly output: string;
}

/**
 * Builds a fork with its own build script when its source digest moved since
 * the last build (S17), and records the digest it built. A fork with no build
 * script is its own output.
 */
export async function buildFork(runner: CommandRunner, fork: string): Promise<Built> {
  const record = readRecord(fork);
  const digest = treeDigest(readTree(fork));
  if (record?.built === digest) return { ok: true, ran: false, output: "" };
  const manifest = readManifest(fork);
  if (manifest?.scripts?.build) {
    const run = async (args: readonly string[]) => runner.run(packageManager(), args, { cwd: fork, timeoutMs: 10 * 60 * 1000 });
    if (!fs.existsSync(path.join(fork, "node_modules"))) {
      const installed = await run(["install", "--no-audit", "--no-fund"]);
      if (!installed.ok) return { ok: false, ran: true, output: [installed.stdout, installed.stderr].filter(Boolean).join("\n").trim() };
    }
    const built = await run(["run", "build"]);
    if (!built.ok) return { ok: false, ran: true, output: [built.stdout, built.stderr].filter(Boolean).join("\n").trim() };
  }
  // Read after the build, not before it: a build that writes beside its
  // source would otherwise look like an edit, and build again every boot.
  if (record) writeRecord(fork, { ...record, built: treeDigest(readTree(fork)) });
  return { ok: true, ran: true, output: "" };
}

/**
 * Builds every fork of a profile whose source moved, and refreshes the copies
 * the profile root resolves when one did. A failing build is the boot's
 * refusal, naming the fork and what its build said.
 */
export async function prepareForks(
  runner: CommandRunner,
  home: string,
  pluginsRoot: string,
  profile: string,
  specs: readonly string[],
): Promise<{ ok: true } | { ok: false; problems: string[] }> {
  const forks = profileForkDirectories(home, profile);
  let rebuilt = false;
  for (const [name, fork] of forks) {
    if (!fs.existsSync(fork)) return { ok: false, problems: [`${name}: the fork at ${fork} is gone; \`amy remove ${name}\` drops it from the profile`] };
    const built = await buildFork(runner, fork);
    if (!built.ok) return { ok: false, problems: [`${name}: the fork at ${fork} does not build:\n${built.output || "its build said nothing"}`] };
    rebuilt ||= built.ran;
  }
  if (!rebuilt && (forks.size === 0 || rootIsCurrent(home, pluginsRoot, profile, forks, specs))) return { ok: true };
  const installed = await installProfileRoot(runner, home, pluginsRoot, profile, forks, specs);
  return installed.ok ? { ok: true } : { ok: false, problems: [`${installed.command} failed:\n${installed.output || "it said nothing"}`] };
}

/** The labels a marked merge names its three sides by. */
export interface MergeLabels {
  readonly ours: string;
  readonly base: string;
  readonly theirs: string;
}

/**
 * A three-way merge of one text file, line by line (S15): a change on one
 * side is taken, the same change on both is taken once, and two different
 * changes to the same lines are a conflict, written with the markers
 * `git merge-file --diff3` writes.
 */
export function mergeText(base: string, ours: string, theirs: string, labels: MergeLabels): { text: string; conflicted: boolean } {
  if (ours === theirs || theirs === base) return { text: ours, conflicted: false };
  if (ours === base) return { text: theirs, conflicted: false };
  return mergeLines(base.split("\n"), ours.split("\n"), theirs.split("\n"), labels);
}

/** The walk behind `mergeText`: stable lines both sides kept, and the chunks between them. */
function mergeLines(b: readonly string[], o: readonly string[], t: readonly string[], labels: MergeLabels): { text: string; conflicted: boolean } {
  const toOurs = matches(b, o);
  const toTheirs = matches(b, t);
  const out: string[] = [];
  let conflicted = false;
  let [i, j, k] = [0, 0, 0];
  while (i < b.length || j < o.length || k < t.length) {
    if (i < b.length && toOurs[i] === j && toTheirs[i] === k) {
      out.push(b[i]!);
      [i, j, k] = [i + 1, j + 1, k + 1];
      continue;
    }
    const stable = nextStable(i, b.length, toOurs, toTheirs);
    const oursEnd = stable < b.length ? toOurs[stable]! : o.length;
    const theirsEnd = stable < b.length ? toTheirs[stable]! : t.length;
    const chunk = resolveChunk(b.slice(i, stable), o.slice(j, oursEnd), t.slice(k, theirsEnd), labels);
    out.push(...chunk.lines);
    conflicted ||= chunk.conflicted;
    [i, j, k] = [stable, oursEnd, theirsEnd];
  }
  return { text: out.join("\n"), conflicted };
}

/** The next line of the base both sides kept, from `from` on. */
function nextStable(from: number, length: number, toOurs: Int32Array, toTheirs: Int32Array): number {
  let at = from;
  while (at < length && (toOurs[at] === -1 || toTheirs[at] === -1)) at += 1;
  return at;
}

/** One unstable chunk: one side's change is taken, the same change once, and two changes are a conflict. */
function resolveChunk(was: string[], mine: string[], upstream: string[], labels: MergeLabels): { lines: string[]; conflicted: boolean } {
  if (same(mine, was)) return { lines: upstream, conflicted: false };
  if (same(upstream, was) || same(mine, upstream)) return { lines: mine, conflicted: false };
  return {
    lines: [`<<<<<<< ${labels.ours}`, ...mine, `||||||| ${labels.base}`, ...was, "=======", ...upstream, `>>>>>>> ${labels.theirs}`],
    conflicted: true,
  };
}

function same(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((line, index) => line === b[index]);
}

/** Past this many cells the table is not built, and the whole middle counts as changed. */
const LARGEST_TABLE = 25_000_000;

/**
 * For each line of `a`, the line of `b` it is matched to in a longest common
 * subsequence, or -1. The common head and tail are matched first, so the
 * table only spans what actually differs.
 */
function matches(a: readonly string[], b: readonly string[]): Int32Array {
  const matched = new Int32Array(a.length).fill(-1);
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) {
    matched[start] = start;
    start += 1;
  }
  let endA = a.length;
  let endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA -= 1;
    endB -= 1;
    matched[endA] = endB;
  }
  matchMiddle(a.slice(start, endA), b.slice(start, endB), start, matched);
  return matched;
}

/** Matches what differs between the common head and tail, through a table of common lengths. */
function matchMiddle(a: readonly string[], b: readonly string[], offset: number, matched: Int32Array): void {
  const width = b.length + 1;
  if (a.length === 0 || b.length === 0 || (a.length + 1) * width > LARGEST_TABLE) return;
  const table = new Uint32Array((a.length + 1) * width);
  for (let r = a.length - 1; r >= 0; r -= 1) {
    for (let c = b.length - 1; c >= 0; c -= 1) {
      table[r * width + c] = a[r] === b[c] ? table[(r + 1) * width + c + 1]! + 1 : Math.max(table[(r + 1) * width + c]!, table[r * width + c + 1]!);
    }
  }
  let [r, c] = [0, 0];
  while (r < a.length && c < b.length) {
    if (a[r] === b[c]) {
      matched[offset + r] = offset + c;
      [r, c] = [r + 1, c + 1];
    } else if (table[(r + 1) * width + c]! >= table[r * width + c + 1]!) r += 1;
    else c += 1;
  }
}

function equal(a: Buffer | undefined, b: Buffer | undefined): boolean {
  return a === undefined ? b === undefined : b !== undefined && a.equals(b);
}

function isText(content: Buffer): boolean {
  return !content.includes(0);
}

interface MergedTree {
  readonly tree: Tree;
  /** The files two sides changed differently; their merged text carries the markers. */
  readonly conflicts: string[];
}

/**
 * Merges a fork's tree with a new upstream tree over the base both came
 * from, file by file. A file only one side changed (or added, or deleted)
 * is that side's; one both changed is merged by line when all three are text,
 * and is a conflict otherwise.
 */
function mergeTrees(base: Tree, fork: Tree, upstream: Tree, labels: MergeLabels): MergedTree {
  const tree: Tree = new Map();
  const conflicts: string[] = [];
  const files = [...new Set([...base.keys(), ...fork.keys(), ...upstream.keys()])].sort();
  for (const file of files) {
    const merged = mergeFile(base.get(file), fork.get(file), upstream.get(file), labels);
    if (merged.content) tree.set(file, merged.content);
    if (merged.conflicted) conflicts.push(file);
  }
  return { tree, conflicts };
}

/** One file of the merge: its content afterwards (none when it is deleted), and whether it conflicted. */
function mergeFile(was: Buffer | undefined, mine: Buffer | undefined, theirs: Buffer | undefined, labels: MergeLabels): { content?: Buffer; conflicted: boolean } {
  if (equal(mine, theirs) || equal(theirs, was)) return { content: mine, conflicted: false };
  if (equal(mine, was)) return { content: theirs, conflicted: false };
  if (was && mine && theirs && [was, mine, theirs].every(isText)) {
    const merged = mergeText(was.toString("utf-8"), mine.toString("utf-8"), theirs.toString("utf-8"), labels);
    return { content: Buffer.from(merged.text, "utf-8"), conflicted: merged.conflicted };
  }
  return { content: mine ?? theirs, conflicted: true };
}

/** One fork's update, computed before anything on disk moves. */
export interface ForkUpdate {
  readonly name: string;
  readonly fork: string;
  readonly from: string;
  readonly to: string;
  readonly merged: MergedTree;
  readonly record: ForkRecord;
}

export interface ForkTarget {
  readonly name: string;
  readonly fork: string;
  readonly version: string;
}

/**
 * Merges each fork with the version it moves to (S15): the base it was taken
 * from and the new version are fetched by their tags, and the fork is merged
 * over them. Nothing is written here: a conflict anywhere is returned with
 * every other merge, so the caller stops the whole update untouched.
 */
export async function mergeForks(runner: CommandRunner, targets: readonly ForkTarget[]): Promise<ForkUpdate[]> {
  const updates: ForkUpdate[] = [];
  for (const target of targets) {
    const record = readRecord(target.fork);
    if (!record || !record.base.version || record.base.version === target.version) continue;
    const base = record.base;
    const nextRef = `${base.package}@${target.version}`;
    const before = await fetchSource(runner, { url: base.url, directory: base.directory, ref: base.ref || base.commit }, base.package);
    try {
      const after = await fetchSource(runner, { url: base.url, directory: base.directory, ref: nextRef }, nextRef);
      try {
        const merged = mergeTrees(readTree(before.directory), readTree(target.fork), readTree(after.directory), {
          ours: `fork ${target.fork}`,
          base: `${base.package}@${base.version}`,
          theirs: nextRef,
        });
        updates.push({
          name: target.name,
          fork: target.fork,
          from: base.version,
          to: target.version,
          merged,
          record: { base: { ...base, version: target.version, commit: after.commit, ref: nextRef } },
        });
      } finally {
        after.dispose();
      }
    } finally {
      before.dispose();
    }
  }
  return updates;
}

/** Where the marked merge of a fork that conflicted is written: beside it, never in it. */
export function markedMergePlace(fork: string): string {
  return `${fork}.merge`;
}

/**
 * Writes the marked merge of every conflicting fork beside it, and nothing
 * else: the fork stays byte for byte as it was. Returns what to tell the person.
 */
export function writeMarkedMerges(updates: readonly ForkUpdate[]): string[] {
  const said: string[] = [];
  for (const update of updates) {
    if (update.merged.conflicts.length === 0) continue;
    const place = markedMergePlace(update.fork);
    fs.rmSync(place, { recursive: true, force: true });
    fs.mkdirSync(place, { recursive: true });
    writeTree(place, update.merged.tree);
    said.push(`${update.name} ${update.from} → ${update.to}: your fork and the new version changed the same lines in ${update.merged.conflicts.join(", ")}; the marked merge is at ${place}`);
  }
  return said;
}

/** Applies merges that had no conflict: the fork takes the merged tree and its new base. */
export function applyForkUpdates(updates: readonly ForkUpdate[]): void {
  for (const update of updates) {
    writeTree(update.fork, update.merged.tree);
    writeRecord(update.fork, update.record);
    fs.rmSync(markedMergePlace(update.fork), { recursive: true, force: true });
  }
}


/**
 * The forks an update would move, across every profile: each one whose base
 * is behind the version the machine now names for its package.
 */
export function forkTargets(home: string, profiles: readonly string[], versionOf: (name: string) => string | undefined): ForkTarget[] {
  const targets: ForkTarget[] = [];
  for (const profile of profiles) {
    for (const [name, fork] of profileForkDirectories(home, profile)) {
      const version = versionOf(name);
      const base = readRecord(fork)?.base.version;
      if (version && base && compareVersions(version, base) > 0) targets.push({ name, fork, version });
    }
  }
  return targets;
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * A harness this machine has, and where it looks for skills.
 *
 * Not every harness has the same idea of what a skill is. The two here read
 * a `SKILL.md` per directory; a harness that reads something else is a
 * translation rather than a copy, and it is left out until somebody writes
 * that translation rather than being half-supported.
 */
export interface Harness {
  readonly name: string;
  /** What proves it is installed: its own directory, not a binary on PATH. */
  readonly marker: string;
  readonly skills: string;
}

export function harnesses(home: string = os.homedir()): Harness[] {
  return [
    { name: "claude", marker: path.join(home, ".claude"), skills: path.join(home, ".claude", "skills") },
    { name: "hermes", marker: path.join(home, ".hermes"), skills: path.join(home, ".hermes", "skills") },
  ];
}

/** The ones actually on this machine, which is what a menu should offer. */
export function installedHarnesses(home?: string): Harness[] {
  return harnesses(home).filter((harness) => fs.existsSync(harness.marker));
}

/**
 * Writes every skill into one harness's directory.
 *
 * A skill is one directory holding one `SKILL.md`, which is what both of
 * these read. Overwriting is deliberate: these are amy's own, they travel
 * with the version installed, and a skill telling you to run a command your
 * `amy` predates is worse than no skill.
 */
export function install(into: string, skills: readonly [string, string][]): string[] {
  const files: string[] = [];

  for (const [name, body] of skills) {
    const directory = path.join(into, name);
    fs.mkdirSync(directory, { recursive: true });
    const file = path.join(directory, "SKILL.md");
    fs.writeFileSync(file, body, "utf-8");
    files.push(file);
  }

  return files;
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/** The directory everything amy knows lives in. */
const AMY_DIR = ".amy";

/**
 * Where this machine's amy keeps its state.
 *
 * One amy per machine, not one per directory. It drives work in repositories
 * all over the disk and it is reached from whichever harness you happen to be
 * in, so its memory cannot depend on where you were standing when you typed
 * the command — an `amy status` run from the wrong directory that answered
 * "nothing tracked yet" would be a lie with a plausible explanation.
 *
 * `AMY_HOME` overrides, which is what a test, a second machine-wide install
 * or a scratch run uses.
 */
export function amyHome(env: NodeJS.ProcessEnv = process.env): string {
  const named = env.AMY_HOME?.trim();
  if (named) return path.resolve(named);

  return path.join(os.homedir(), AMY_DIR);
}

/**
 * The state a directory kept before amy became machine-wide.
 *
 * Reported rather than adopted. Picking it up silently would mean the same
 * command answering differently depending on the directory, which is the
 * behaviour this moved away from.
 */
export function strayState(cwd: string, home: string): string | undefined {
  const here = path.join(cwd, AMY_DIR);
  if (!fs.existsSync(here)) return undefined;

  // Resolved, not compared as strings. On macOS `/var` is a symlink to
  // `/private/var`, so standing in your own state directory looked like
  // standing beside a stray one — and the answer was to move a directory
  // onto itself.
  return real(here) === real(home) ? undefined : here;
}

function real(directory: string): string {
  try {
    return fs.realpathSync(directory);
  } catch {
    return path.resolve(directory);
  }
}

