workflowCommand
  .command("export")
  .description("Print a workflow's diagram, which renders wherever Mermaid does")
  .argument("<name>", "the configured workflow to export")
  .option("--work <id>", "mark the state this piece of work is in")
  .option("--expand", "draw each call as the workflow it calls, for reading; with --work, mark the work at every depth")
  .action(async (name: string, options: { work?: string; expand?: boolean }) => {
    try {
      const config = loadConfig(home);
      const profile = profiles(config, home)[name];
      const record = options.work === undefined || !profile ? undefined : new FileStore<AnyRecord>(profilePaths(home, profile).records).load(options.work);
      if (options.work !== undefined && !record) throw new Error(`${name} keeps no record for ${options.work}`);
      process.stdout.write(await exportWorkflow(home, name, config, {
        ...(record ? { record: record as WorkRecord } : {}),
        ...(options.expand ? { expand: true } : {}),
        resolve: pluginsRootResolver(home, paths(home).plugins),
      }));
    } catch (error) {
      console.error(error instanceof Error ? error.message : String(error));
      process.exitCode = 1;
    }
  });

workflowCommand
  .command("list", { isDefault: true })
  .description("Every workflow this install can drive")
  .action(async () => {
    const config = loadConfig(home);
    const known = profiles(config, home);
    const asked = resolveProfile(config, undefined, home);
    const present = installedPlugins(paths(home).plugins);

    for (const profile of Object.values(known)) {
      const place = profilePaths(home, profile);
      const live = runningProfileDaemon(profile)?.record;
      const held = fs.existsSync(place.records) ? fs.readdirSync(place.records).length : 0;
      const marks = [
        asked.ok && asked.profile.name === profile.name ? "default" : "",
        live?.workflow === profile.name ? "running" : "",
        localWorkflow(home, profile.workflow) ? `local: ${workflowsDirectory(home)}` : "",
        present.includes(profile.workflow) || localWorkflow(home, profile.workflow) || isFilesystemWorkflow(profile.workflow) ? "" : "not installed",
      ].filter(Boolean);

      console.log(
        `${profile.name.padEnd(18)} ${profile.workflow.padEnd(32)} ` +
          `${String(held).padStart(3)} record(s)  ${marks.join(", ")}`,
      );
    }
  });

const queueCommand = program.command("queue").description("Inspect and tidy the queue");

queueCommand
  .command("prune")
  .description("Delete finished queue items past their retention")
  .option("--days <n>", "override the configured retention")
  .action(async (options: { days?: string }) => {
    const config = loadConfig(home);
    const days = options.days ? Number(options.days) : config.retentionDays;
    const now = new Date();
    const profile = selected();
    const removed = new FileQueue(profilePaths(home, profile).queue).prune(days, now);
    const assembled = await assemble(profile);
    const briefStore = assembled.ok ? (assembled.mounted.ports.get("brief") as BriefStore | undefined) : undefined;
    const records = assembled.ok ? assembled.mounted.store : undefined;
    const terminal = assembled.ok ? new Set(assembled.mounted.workflow?.terminalStates ?? []) : new Set<string>();
    // A shared project brief may still explain live work in another phase.
    // Until the project has one cross-phase retention view, auto-pruning it
    // would be destructive; ordinary profile-local briefs retain their
    // existing retention behaviour.
    const retired = !profile.project && briefStore && records
      ? await briefStore.retired((id) => terminal.has(records.load(id)?.state ?? ""), days * 86_400_000, now)
      : [];
    await Promise.all(retired.map((id) => briefStore!.remove(id)));
    console.log(`removed ${removed} finished item(s) and ${retired.length} retired brief(s) older than ${days} day(s)`);
  });

queueCommand
  .command("recover")
  .description("Return items abandoned by a dead worker")
  .action(() => {
    const config = loadConfig(home);
    const recovered = new FileQueue(profilePaths(home, selected()).queue).recover(
      config.staleClaimMs,
      new Date(),
    );
    console.log(`returned ${recovered.length} abandoned item(s)`);
  });

function report(result: TickResult): void {
  switch (result.kind) {
    case "idle":
      console.log("nothing due");
      break;
    case "stopped":
      console.log(`stopped: ${result.reason}`);
      break;
    case "worked": {
      const move = result.from === result.to ? result.from : `${result.from} -> ${result.to}`;
      const held = result.retryAfterMs ? ` (looking again in ${result.retryAfterMs / 1000}s)` : "";
      console.log(`${result.workId}  ${move}  ${result.why}${held}`);
      break;
    }
    case "parked":
      console.log(
        `${result.workId}  ${result.state}  parked: ${result.reason} ` +
          `(looking again in ${Math.round(result.retryAfterMs / 1000)}s)`,
      );
      break;
    case "failed":
      console.error(`${result.workId}  ${result.state}  failed: ${result.error}`);
      process.exitCode = 1;
      break;
  }
}

/**
 * The command line the configured machine brings, read before anything is
 * mounted.
 *
 * Declared here rather than compiled in, because the command a machine has is
 * the command it mounted: `amy btw` belongs to the errand it captures, `amy
 * note` to the one that writes plans, and a machine driving neither has
 * neither. Read at startup so `amy --help` is the truth about
 * this install rather than a list of everything this repository publishes.
 */
/**
 * What the profiles contribute, read once their forks are built. A process
 * keeps every module it imports, so a fork read here before its edit is built
 * would be the fork every later mount in this process sees. A fork that does
 * not build is the mount's to refuse, by name.
 */
async function gatherBuilt(config: AmyConfig, known: readonly Profile[]): Promise<Awaited<ReturnType<typeof gather>>> {
  for (const profile of known) {
    if (profileForkDirectories(home, profile.name).size > 0) await prepareForks(runner, home, paths(home).plugins, profile.name, pluginList(config, profile));
  }
  return gather(config, known, loadMountable);
}

async function pluginContributions(): Promise<readonly Contribution[]> {
  let gathered;
  try {
    const config = loadConfig(home);
    gathered = await gatherBuilt(config, Object.values(profiles(config, home)));
  } catch {
    // A config this process cannot read is `doctor`'s to report, not a reason
    // `amy --help` stops working: the command line that would say what is
    // wrong has to come up on the machine that is wrong.
    return [];
  }

  if (gathered.problems.length > 0) {
    for (const problem of gathered.problems) console.error(problem);
    process.exit(1);
  }

  return gathered.contributions;
}

/** A plugin command runs under one profile, or says which ones may run it. */
function profileForContribution(contribution: Contribution): { ok: true; profile: Profile } | { ok: false; problem: string } {
  const config = loadConfig(home);
  const asked = program.opts<{ workflow?: string }>().workflow;

  if (asked) {
    const resolution = resolveProfile(config, asked, home);
    if (!resolution.ok) return { ok: false, problem: resolution.problem };
    if (!contribution.profiles.some((profile) => profile.name === resolution.profile.name)) {
      return {
        ok: false,
        problem: `\`${contribution.owner}\` is not mounted by ${resolution.profile.name}; it runs on: ${contribution.profiles.map((profile) => profile.name).join(", ")}`,
      };
    }
    return { ok: true, profile: resolution.profile };
  }

  if (contribution.profiles.length === 1) return { ok: true, profile: contribution.profiles[0]! };

  return {
    ok: false,
    problem: `\`${contribution.owner}\` is mounted by ${contribution.profiles.map((profile) => profile.name).join(", ")}; name one with --workflow`,
  };
}

const commandOut = {
  line: (text = "") => console.log(text),
  error: (text: string) => console.error(text),
};

const contributions = await pluginContributions();

/** What a plugin command needs from this process, built once. */
function commandEnvironment(): CommandEnvironment {
  return {
    home,
    // Read when a command asks for it, not before the command runs: `amy
    // update` is the command that moves a config whose shape was retired, and
    // a config read at register time would refuse, before the migration, the
    // one command built to fix it.
    get config() {
      return loadConfig(home);
    },
    profileFor: profileForContribution,
    mount: async (profile) => {
      const assembled = await assemble(profile);
      return assembled.ok ? { ok: true, ports: assembled.mounted.ports } : { ok: false, problems: assembled.problems };
    },
    out: commandOut,
  };
}

register(program, contributions, commandEnvironment());

program
  .command("contract")
  .description("This install's whole contract, amy's services and every mounted plugin's operations, as an OpenAPI document")
  .option("--check", "say whether the contract builds, and refuse one that does not")
  .action((options: { check?: boolean }) => {
    let document: Record<string, unknown>;
    try {
      document = installContract(contributions);
    } catch (error) {
      console.error(`the contract does not build: ${error instanceof Error ? error.message : String(error)}`);
      process.exitCode = 1;
      return;
    }
    if (!options.check) {
      console.log(JSON.stringify(document, null, 2));
      return;
    }
    const paths = Object.values((document.paths ?? {}) as Record<string, Record<string, unknown>>);
    console.log(`the contract builds: ${paths.reduce((count, methods) => count + Object.keys(methods).length, 0)} operation(s)`);
  });

// So a name this machine does not provide can be answered here rather than by
// commander's bare "unknown command", which reads as if amy had never heard of
// it. Help and version still leave through the same door, with status 0.
program.exitOverride();
program.configureOutput({
  writeErr: (text) => {
    if (/^error: unknown command /.test(text)) return;
    process.stderr.write(text);
  },
});

program.parseAsync(process.argv).catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  // A command belongs to the workflow that provides it, so on a machine that
  // mounts none of them the command is not unknown to amy — it is absent, and
  // the fix is to mount the thing that carries it. Saying which one is the
  // config's job; saying where to look is this one's.
  const code = (error as { code?: string }).code;
  if (code === "commander.helpDisplayed" || code === "commander.version") {
    process.exitCode = 0;
    return;
  }
  const unknown = /^error: unknown command '([^']+)'/.exec(message);
  if (unknown) {
    console.error(`unknown command '${unknown[1]}': nothing on this machine provides it.`);
    console.error("`amy init` writes a config that names the workflows and what each provides — uncomment one, or run `amy add`.");
    process.exitCode = 1;
    return;
  }
  // An operation's command has already said what it refused, in the manner
  // it was asked for; a second line would break a reader of --json.
  if (code !== ANSWERED) console.error(message);
  // An operation's command exits 2 for an argument commander refused, which
  // is an input refused; every other command keeps 1.
  const exit = (error as { exitCode?: unknown }).exitCode;
  process.exitCode = typeof exit === "number" && exit > 0 ? exit : 1;
});

import fs from "node:fs";
import path from "node:path";
import { CommandRunner } from "@amykit/core";

/**
 * The package manager, by the name this platform actually has for it.
 *
 * `spawn` without a shell will not find `npm` on Windows, because what is on
 * the PATH there is `npm.cmd`. Getting this wrong is not a subtle failure —
 * it is `ENOENT` on the one command that was supposed to make installing
 * easy — but it is invisible on the machine most of this was written on.
 */
export function packageManager(platform: string = process.platform): string {
  return platform === "win32" ? "npm.cmd" : "npm";
}

export function shellCommand(command: string, args: readonly string[], platform: string = process.platform): string {
  return [command, ...args].map((value) => shellQuote(value, platform)).join(" ");
}

function shellQuote(value: string, platform: string): string {
  if (platform === "win32") {
    const escaped = value.replaceAll("^", "^^").replace(/["&|<>%!()]/gu, "^$&");
    return /[\s"%!...&|<>^()]/u.test(value) ? `"${escaped}"` : escaped;
  }
  return /^[A-Za-z0-9_./:@=-]+$/.test(value) ? value : `'${value.replaceAll("'", "'\"'\"'")}'`;
}

/**
 * What every install into amy's own root says: no audit or funding noise,
 * and a package given as a path installed as a copy with its dependencies
 * rather than a link. Every workflow imports the core it is declared with,
 * and a link resolves that import from wherever the path lies, where there
 * is none.
 */
export const PLUGINS_ROOT_FLAGS = ["--no-audit", "--no-fund", "--install-links"] as const;

export interface InstallOutcome {
  ok: boolean;
  /** What was run, so a failure can be retried by hand. */
  command: string;
  output: string;
}

/**
 * Installs packages into amy's own npm root — `<home>/plugins`.
 *
 * A plugin is resolved by name at run time, but not by walking up from this
 * file: amy's loader resolves through that root explicitly, so the packages
 * belong to amy's state directory rather than to a global prefix every other
 * tool on the machine shares. A plugin installed here is one `npm install -g`
 * never has to be asked about, and `npm prefix -g` can point anywhere without
 * amy caring.
 *
 * Ten minutes rather than the runner's default, because a cold npm cache on a
 * slow connection is not a hang, and killing it half way leaves a root
 * somebody has to repair by hand.
 */
export async function installIntoPluginsRoot(
  runner: CommandRunner,
  root: string,
  packages: readonly string[],
): Promise<InstallOutcome> {
  const args = ["install", "--prefix", root, ...PLUGINS_ROOT_FLAGS, "--", ...packages];
  const command = shellCommand(packageManager(), args);

  const result = await runner.run(packageManager(), args, { timeoutMs: 10 * 60 * 1000 });

  return {
    ok: result.ok,
    command,
    // Both streams: npm says the interesting part on stderr about half the
    // time, and a summary that drops the line that mattered is worse than
    // the noise.
    output: [result.stdout, result.stderr].filter(Boolean).join("\n").trim(),
  };
}

/**
 * The manifest a plugin root resolves through, written before its first
 * install.
 *
 * npm reads the `package.json` it finds at the prefix; without one it walks
 * up looking for the nearest project, which on a scratch machine could be
 * anything. This makes the root a real, private npm root from the moment
 * amy needs it, and re-writing it loses nothing: it never carries anything
 * but amy's own word `private`.
 */
export function ensurePluginsRoot(root: string): string {
  const manifest = path.join(root, "package.json");
  if (!fs.existsSync(manifest)) {
    fs.mkdirSync(root, { recursive: true });
    fs.writeFileSync(manifest, `${JSON.stringify({ name: "amy-plugins", private: true }, null, 2)}\n`, "utf-8");
  }
  return root;
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { Plugin } from "@amykit/core";
import { drawn } from "./drawn.js";
import { localWorkflow } from "./workflow.js";
import { packageEntrySpecifier } from "./spec.js";
import { heldByProfile } from "./fork.js";
import { profileRoot } from "./paths.js";

export interface LoadResult {
  plugins: Plugin[];
  problems: string[];
  // What was asked for, against what came back. A plugin's own `name` is not
  // the spec that found it — a workflow of your own is asked for by its
  // directory, `oncall`, and calls itself `workflow-oncall` — so a caller
  // matching one against the other reports a plugin it just loaded as missing.
  bySpec: Map<string, Plugin>;
}

/**
 * Imports each plugin by name and takes its `plugin` export.
 *
 * Nothing is compiled in. A plugin is a package the package manager put on
 * disk, or a path, and it resolves at run time like any other import — which
 * is what lets an install carry a plugin this repository has never heard of,
 * and lets a machine skip the ones it has no use for.
 *
 * Resolution is explicit rather than inherited: a package is looked up in the
 * npm root amy's state directory holds, exactly the way Node would resolve it
 * from inside that root, so where this file happens to sit has nothing to do
 * with what an install can mount.
 */
export async function load(
  specs: readonly string[],
  resolve: (spec: string) => string = (spec) => spec,
  pluginsRoot?: string,
): Promise<LoadResult> {
  const plugins: Plugin[] = [];
  const problems: string[] = [];
  const bySpec = new Map<string, Plugin>();

  for (const spec of specs) {
    try {
      const specifier = resolve(spec);
      const module = (await import(specifier)) as { plugin?: Plugin };
      if (!module.plugin) {
        problems.push(`${spec}: imported, but exports no \`plugin\``);
        continue;
      }
      const plugin = drawn(module.plugin, specifier);
      plugins.push(plugin);
      bySpec.set(spec, plugin);
    } catch (error) {
      problems.push(missing(spec, error, pluginsRoot));
    }
  }

  return { plugins, problems, bySpec };
}

/**
 * What a refusal says when the package is simply not there.
 *
 * The failure the compiled-in table used to make impossible, and the one it
 * leaves behind: a config naming something nobody installed. Said in the same
 * words every time so a caller can tell it from a plugin that threw, and
 * answer it once with what *is* installed.
 */
export const NOT_INSTALLED = "not installed";
const PLUGIN_NOT_INSTALLED = "AMY_PLUGIN_NOT_INSTALLED";

function missing(spec: string, error: unknown, pluginsRoot?: string): string {
  const why = error instanceof Error ? error.message : String(error);
  if (!isUnresolved(error, pluginsRoot)) return `${spec}: could not be imported — ${why}`;

  return `${spec}: ${NOT_INSTALLED} — install it, or drop it from the config${pluginsRoot ? ` (${pluginsRoot})` : ""}`;
}

/** Node's own word for "no such package", told apart from a plugin that threw. */
function isUnresolved(error: unknown, pluginsRoot?: string): boolean {
  const code = (error as { code?: string })?.code;
  return code === PLUGIN_NOT_INSTALLED || (!pluginsRoot && code === "ERR_MODULE_NOT_FOUND");
}

/**
 * What this install could mount, read off one directory rather than walked.
 *
 * The npm root amy keeps under its state directory holds the packages amy's
 * config may name, and the walk Node does from this module's own location
 * cannot see it — the command's file sits in a checkout or an install
 * prefix, and the root sits in `.amy`. Reading it directly makes the listing
 * an answer instead of a heuristic that pattern-matches whatever a parent
 * walk happened to find, and stops the refusal's "installed instead" list
 * depending on how amy itself was put on the machine.
 */
export function installedPlugins(root: string): string[] {
  const found = new Set<string>();

  for (const name of packagesIn(path.join(root, "node_modules"))) {
    if (/(^|\/)(plugin|workflow)-/.test(name)) found.add(name);
  }

  return [...found].sort();
}

/** Every package name in one `node_modules`, scopes walked one level in. */
function packagesIn(directory: string): string[] {
  const names: string[] = [];

  for (const entry of read(directory)) {
    if (entry.startsWith("@")) {
      names.push(...read(path.join(directory, entry)).map((inner) => `${entry}/${inner}`));
      continue;
    }
    if (!entry.startsWith(".")) names.push(entry);
  }

  return names;
}

/** Returns nothing rather than throwing: a directory that is not there is an answer. */
function read(directory: string): string[] {
  try {
    return fs.readdirSync(directory);
  } catch {
    return [];
  }
}

/**
 * The resolver that turns a spec into something `import()` takes, through the
 * npm root amy's state directory keeps.
 *
 * `createRequire(<root>/package.json)` is Node's resolution algorithm anchored
 * at that root, so a name resolves to the file inside it exactly as it would
 * for a module living there — the same walk, made explicit instead of
 * inherited from wherever amy's own file happens to sit. The file Node names
 * is then imported as a `file:` URL. A workflow of your own is resolved by
 * its directory first, and a spec that is a path resolves as itself; both
 * arrive here already a specifier, because that is what the resolver contract
 * has always handed `import()`.
 */
export function pluginsRootResolver(home: string, pluginsRoot: string, profile?: string): (spec: string) => string {
  return (spec: string) => {
    const local = localWorkflow(home, spec);
    if (local) return local;

    // A specifier that is already a URL — a path spec the CLI resolved to its
    // own entry — is not Node's to walk, and handing it to the resolver
    // rooted at `<root>/package.json` would answer nothing useful.
    if (isFilesystemWorkflow(spec)) {
      const resolved = path.resolve(spec);
      return fs.statSync(resolved).isDirectory() ? directoryEntrySpecifier(resolved) : pathToFileURL(resolved).href;
    }
    if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(spec)) return spec;

    // A profile's own root answers first, for the names it holds: a fork,
    // and what imports one. Everything else is the machine's.
    const own = profile === undefined ? undefined : profileRoot(home, profile);
    const directory = own && heldByProfile(home, profile!, spec) ? packageDirectory(own, spec) : packageDirectory(pluginsRoot, spec);
    if (!fs.existsSync(directory)) throw pluginNotInstalled(spec);
    return packageEntrySpecifier(directory);
  };
}

function pluginNotInstalled(spec: string): Error & { code: string } {
  const error = new Error(`${spec} is not in amy's plugins root`) as Error & { code: string };
  error.code = PLUGIN_NOT_INSTALLED;
  return error;
}

/** A configured path that the loader can import without installing a package. */
export function isFilesystemWorkflow(spec: string): boolean {
  if (!path.win32.isAbsolute(spec) && !path.isAbsolute(spec) && !spec.startsWith("./") && !spec.startsWith("../")) return false;
  try {
    // Any existing file or directory: a phase folder with no manifest or index
    // yet is refused by the entry resolver naming what it lacks, not reported
    // as a package nobody installed.
    return fs.existsSync(path.resolve(spec));
  } catch {
    return false;
  }
}

/** A phase directory may be a package, or a plain editable workflow. */
function directoryEntrySpecifier(directory: string): string {
  if (fs.existsSync(path.join(directory, "package.json"))) return packageEntrySpecifier(directory);
  for (const name of ["index.ts", "index.js"]) {
    const entry = path.join(directory, name);
    if (fs.existsSync(entry)) return pathToFileURL(entry).href;
  }
  throw new Error(`${directory} is a directory with neither package.json nor index.js/index.ts`);
}

/** The directory npm gives one exact package name beneath this root. */
function packageDirectory(root: string, spec: string): string {
  const parts = spec.startsWith("@") ? spec.split("/", 2) : [spec.split("/", 1)[0]!];
  return path.join(root, "node_modules", ...parts);
}

/** The manifest belongs to the resolved package, never an ancestor of a bare path. */
export function pluginVersion(home: string, root: string, spec: string): string | undefined {
  try {
    const local = localWorkflow(home, spec);
    let directory: string;
    if (local) directory = path.dirname(fileURLToPath(local));
    else if (isFilesystemWorkflow(spec)) {
      const target = path.resolve(spec);
      directory = fs.statSync(target).isDirectory() ? target : path.dirname(target);
    } else if (spec.startsWith("file:")) directory = path.dirname(fileURLToPath(spec));
    else directory = packageDirectory(root, spec);
    const manifest = JSON.parse(fs.readFileSync(path.join(directory, "package.json"), "utf-8")) as { version?: unknown };
    return typeof manifest.version === "string" ? manifest.version : undefined;
  } catch {
    return undefined;
  }
}

import { defineContract, invoke, isStream } from "@amykit/core";
import type { ErrorEnvelope, Invocation, Operation, OperationContext, StreamItem } from "@amykit/core";
import { spelledAs } from "./argv.js";
import { draw, drawEvent } from "./draw.js";
import { Json, jsonSchemaOf } from "./schema.js";

/**
 * The exit code is the outcome: an output, a declared error, an input the
 * schema refused, or something the operation never declared.
 */
export const EXIT = { output: 0, error: 1, refused: 2, internal: 70 } as const;

/** Where an answer is written: the output to one stream, an error to the other. */
export interface Speaker {
  line(text?: string): void;
  error(text: string): void;
}

/** How the answer is written: as JSON for whatever reads it, or drawn for a person. */
export interface Manner {
  readonly json: boolean;
  readonly color: boolean;
}

/**
 * Runs one operation through `invoke` and writes what it answered, returning
 * the exit code.
 *
 * With `json`, an output is JSON on stdout, a stream one JSON line per event,
 * and an error the envelope on stderr. Without it, the output is drawn from
 * itself and its schema, and an error is its message.
 */
export async function answer(operation: Operation, input: unknown, context: OperationContext, manner: Manner, out: Speaker): Promise<number> {
  const ran = await invoke(defineContract([operation]), operation.id, input, context);
  return speak(operation, ran, manner, out);
}

async function speak(operation: Operation, ran: Invocation, manner: Manner, out: Speaker): Promise<number> {
  switch (ran.kind) {
    case "output":
      return printed(operation, ran.output, manner, out);
    case "stream":
      return streamed(operation, ran.events, manner, out);
    case "error":
      return refuse(ran.error, EXIT.error, manner, out);
    case "refused":
      return refuse(namingFlags(operation, ran.error), EXIT.refused, manner, out);
    case "internal":
      return refuse(ran.error, EXIT.internal, manner, out);
  }
}

function printed(operation: Operation, output: unknown, manner: Manner, out: Speaker): number {
  if (manner.json) out.line(JSON.stringify(output, null, 2));
  else for (const line of draw(output, outputSchemaOf(operation), manner.color)) out.line(line);
  return EXIT.output;
}

/** Each event as it arrives; an error that ends the stream is written after the events before it. */
async function streamed(operation: Operation, events: AsyncIterable<StreamItem>, manner: Manner, out: Speaker): Promise<number> {
  for await (const item of events) {
    if (item.kind !== "event") return refuse(item.error, item.kind === "error" ? EXIT.error : EXIT.internal, manner, out);
    if (manner.json) out.line(JSON.stringify({ event: item.event, data: item.data }));
    else for (const line of drawEvent(item.event, item.data, eventSchemaOf(operation, item.event), manner.color)) out.line(line);
  }
  return EXIT.output;
}

/** Writes an error, as the envelope or as its message, and answers its exit code. */
export function refuse(error: ErrorEnvelope, code: number, manner: Pick<Manner, "json">, out: Speaker): number {
  out.error(manner.json ? JSON.stringify(error) : error.message);
  return code;
}

/**
 * An input the schema refused, said in the words it was typed in: each issue
 * names the flag or the argument, never the field behind it.
 */
function namingFlags(operation: Operation, error: ErrorEnvelope): ErrorEnvelope {
  if (error.code !== "amy.input" || !Array.isArray(error.details)) return error;
  const issues = error.details as { message: string; path: string[] }[];
  const said = issues.map((issue) => {
    const [field, ...rest] = issue.path;
    if (field === undefined) return issue.message;
    return `${spelledAs(operation, field)}${rest.length > 0 ? `.${rest.join(".")}` : ""}: ${issue.message}`;
  });
  return { ...error, message: `\`amy ${(operation.cli?.words ?? [operation.id]).join(" ")}\` refused its input: ${said.join("; ")}` };
}

function outputSchemaOf(operation: Operation): Json | undefined {
  if (isStream(operation)) return undefined;
  return jsonSchemaOf(operation.output, "output");
}

function eventSchemaOf(operation: Operation, event: string): Json | undefined {
  if (!isStream(operation) || !Object.hasOwn(operation.events, event)) return undefined;
  return jsonSchemaOf(operation.events[event]!, "output");
}

import { Command, Option } from "commander";
import type { Operation } from "@amykit/core";
import { Json, flagOf, inputSchemaOf, resolved, typeOf } from "./schema.js";

/** One input field as the command line spells it. */
interface Field {
  readonly name: string;
  readonly schema: Json;
  readonly required: boolean;
  /** Its place among the positional arguments, when it is taken by position. */
  readonly position?: number;
  /** The option's attribute in commander's parsed options, for a flag. */
  readonly attribute?: string;
}

/** The fields of an operation's input, in the order its schema declares them. */
function fieldsOf(operation: Operation): Field[] {
  // The root may itself be a reference into its own definitions: its fields
  // are read where it points, and every reference resolves against the whole.
  const whole = inputSchemaOf(operation);
  const root = resolved(whole, whole) ?? whole;
  const properties = (root.properties ?? {}) as Record<string, Json>;
  const required = new Set((root.required ?? []) as string[]);
  const positional = operation.cli?.positional ?? [];
  return Object.entries(properties).map(([name, schema]) => {
    const position = positional.indexOf(name);
    return {
      name,
      schema: inlined(schema, whole),
      required: required.has(name),
      ...(position >= 0 ? { position } : { attribute: new Option(flagOf(name)).attributeName() }),
    };
  });
}

/**
 * A field's schema with its references followed against the input's root,
 * its array items' too: a field lifted out of the root no longer carries the
 * `$defs` a `#/$defs/...` item points at.
 */
function inlined(schema: Json, root: Json): Json {
  const own = resolved(schema, root) ?? schema;
  if (!own.items || typeof own.items !== "object") return own;
  return { ...own, items: inlined(own.items as Json, root) };
}

/** What the help says beside a field: its description, its values, its default. */
function helpOf(field: Field): string {
  const said = typeof field.schema.description === "string" ? field.schema.description : "";
  const values = Array.isArray(field.schema.enum) ? `one of: ${(field.schema.enum as unknown[]).map(String).join(", ")}` : undefined;
  const items = resolved(field.schema.items as Json | undefined, field.schema);
  const repeated = typeOf(field.schema) === "array" && field.position === undefined ? "repeat it for more than one" : undefined;
  const itemValues = Array.isArray(items?.enum) ? `each one of: ${(items.enum as unknown[]).map(String).join(", ")}` : undefined;
  const fallback = field.schema.default !== undefined && typeOf(field.schema) !== "boolean" ? `default: ${JSON.stringify(field.schema.default)}` : undefined;
  const required = field.required && field.position === undefined ? "required" : undefined;
  const notes = [values, itemValues, repeated, fallback, required].filter((one): one is string => one !== undefined);
  return notes.length > 0 ? `${said} (${notes.join("; ")})`.trim() : said;
}

/** The placeholder a flag's value is written as in the help. */
function placeholderOf(schema: Json): string {
  switch (typeOf(schema)) {
    case "number":
    case "integer":
      return "<number>";
    case "array":
      return placeholderOf(resolved(schema.items as Json | undefined, schema) ?? {});
    case "object":
      return "<json>";
    default:
      return "<value>";
  }
}

/**
 * The arguments and flags an operation takes, onto its command: each
 * positional field an argument in the order its binding names them, and
 * every other input field a flag, its description the help.
 */
export function declareInput(command: Command, operation: Operation): void {
  const fields = fieldsOf(operation);
  const positional = fields.filter((field) => field.position !== undefined).sort((a, b) => a.position! - b.position!);
  for (const field of positional) {
    const name = typeOf(field.schema) === "array" ? `${field.name}...` : field.name;
    command.argument(field.required ? `<${name}>` : `[${name}]`, helpOf(field));
  }
  for (const field of fields.filter((one) => one.position === undefined)) {
    const flag = flagOf(field.name);
    if (typeOf(field.schema) === "boolean") {
      // A bare flag says true and its `--no-` form says false, so both values
      // can be typed; left out, the field is the schema's to default.
      if (field.schema.default !== true) command.addOption(new Option(flag, helpOf(field)));
      command.addOption(new Option(`--no-${flag.slice(2)}`, field.schema.default === true ? helpOf(field) : `the opposite of ${flag}`));
      continue;
    }
    const option = new Option(`${flag} ${placeholderOf(field.schema)}`, helpOf(field));
    // An array repeats: every value typed is kept, in order.
    if (typeOf(field.schema) === "array") option.argParser((value: string, previous: unknown) => [...(Array.isArray(previous) ? previous : []), value]);
    command.addOption(option);
  }
}

/** The input assembled from argv, or the field that refused it and why. */
export type Assembled =
  | { readonly ok: true; readonly input: Record<string, unknown> }
  | { readonly ok: false; readonly field: string; readonly why: string };

/**
 * The operation's input, read from what was typed and parsed as each field's
 * schema says: a number is parsed, a boolean is a bare flag, an array is
 * every value repeated, an enum is one of its values. A value its type
 * refuses names the flag and why; everything else is the schema's to judge.
 */
export function assembleInput(operation: Operation, args: readonly unknown[], options: Readonly<Record<string, unknown>>): Assembled {
  const input: Record<string, unknown> = {};
  for (const field of fieldsOf(operation)) {
    const raw = field.position !== undefined ? args[field.position] : options[field.attribute!];
    if (raw === undefined) continue;
    const parsed = parse(field.schema, raw);
    if (!parsed.ok) return { ok: false, field: field.name, why: parsed.why };
    input[field.name] = parsed.value;
  }
  return { ok: true, input };
}

type Parsed = { ok: true; value: unknown } | { ok: false; why: string };

/** One parser per type a field's schema names; a type with none passes as typed. */
const PARSERS: Readonly<Record<string, (schema: Json, raw: unknown) => Parsed>> = {
  number: (_schema, raw) => number(raw, false),
  integer: (_schema, raw) => number(raw, true),
  boolean: (_schema, raw) => boolean(raw),
  enum: (schema, raw) => oneOf(schema, raw),
  array: (schema, raw) => each(schema, raw),
  object: (_schema, raw) => json(raw),
};

function parse(schema: Json, raw: unknown): Parsed {
  const parser = PARSERS[typeOf(schema) ?? ""];
  return parser ? parser(schema, raw) : { ok: true, value: raw };
}

function number(raw: unknown, whole: boolean): Parsed {
  const typed = String(raw).trim();
  const value = typeof raw === "number" ? raw : Number(typed);
  if (typed === "" || !Number.isFinite(value)) return { ok: false, why: `takes a number, and \`${String(raw)}\` is not one` };
  if (whole && !Number.isInteger(value)) return { ok: false, why: `takes a whole number, and \`${String(raw)}\` is not one` };
  return { ok: true, value };
}

function boolean(raw: unknown): Parsed {
  if (typeof raw === "boolean") return { ok: true, value: raw };
  if (raw === "true" || raw === "false") return { ok: true, value: raw === "true" };
  return { ok: false, why: `takes true or false, and \`${String(raw)}\` is neither` };
}

function oneOf(schema: Json, raw: unknown): Parsed {
  const declared = schema.enum as unknown[];
  const values = declared.map(String);
  const at = values.indexOf(String(raw));
  if (at < 0) return { ok: false, why: `is one of ${values.join(", ")}, and \`${String(raw)}\` is not` };
  return { ok: true, value: declared[at] };
}

function each(schema: Json, raw: unknown): Parsed {
  const items = resolved(schema.items as Json | undefined, schema) ?? {};
  const values: unknown[] = [];
  for (const one of Array.isArray(raw) ? raw : [raw]) {
    const parsed = parse(items, one);
    if (!parsed.ok) return parsed;
    values.push(parsed.value);
  }
  return { ok: true, value: values };
}

function json(raw: unknown): Parsed {
  try {
    return { ok: true, value: typeof raw === "string" ? JSON.parse(raw) : raw };
  } catch {
    return { ok: false, why: "takes a JSON object, and what was typed does not parse" };
  }
}

/** How a field is typed on this operation's command line: `<text>` or `--repo`. */
export function spelledAs(operation: Operation, field: string): string {
  const position = (operation.cli?.positional ?? []).indexOf(field);
  return position >= 0 ? `<${field}>` : flagOf(field);
}

import { Command, CommanderError } from "commander";
import type { Operation, OperationContext, PortKind } from "@amykit/core";
import { CommandEnvironment, Contribution, forProfile, namedProfile, settingsFor, stateDirectory } from "../plugin-commands.js";
import type { Profile } from "../profiles.js";
import { EXIT, answer, refuse } from "./answer.js";
import { assembleInput, declareInput, spelledAs } from "./argv.js";
import { mayColor } from "./draw.js";

/**
 * The command line a machine's plugins bring, drawn from their operations:
 * each operation with `cli` words a command, marked with its package, its
 * summary the help.
 *
 * A command the machine never mounted does not exist, and it is nobody's
 * before that: what a machine can do is what it mounted, which is the
 * difference between a framework and a program with plugins attached.
 */
export function register(program: Command, contributions: readonly Contribution[], env: CommandEnvironment): void {
  const names = namesOf(contributions);
  for (const contribution of contributions) {
    const groups = new Map<string, Command>();
    for (const operation of contribution.operations) {
      if (!operation.cli || operation.cli.words.length === 0) continue;
      const words = operation.cli.words;
      let parent = program;
      for (let depth = 1; depth < words.length; depth += 1) parent = groupAt(parent, groups, words.slice(0, depth));
      declare(parent, operation, contribution, env, names);
    }
    for (const [path, group] of groups) group.description(`${groupSummary(contribution, path)} (from ${contribution.owner})`);
  }
}

/** The command a group of words is, made the first time an operation is spelled under it. */
function groupAt(parent: Command, groups: Map<string, Command>, words: readonly string[]): Command {
  const path = words.join(" ");
  const held = groups.get(path);
  if (held) return held;
  const group = parent.command(words[words.length - 1]!);
  groups.set(path, group);
  return group;
}

/** What a group says in the help: its default operation's summary, or the operations under it. */
function groupSummary(contribution: Contribution, path: string): string {
  const under = contribution.operations.filter((operation) => operation.cli && operation.cli.words.slice(0, -1).join(" ") === path);
  const chosen = under.find((operation) => operation.cli?.default);
  if (chosen) return chosen.summary;
  return `${under.map((operation) => operation.cli!.words[operation.cli!.words.length - 1]).join(", ")}`;
}

/**
 * What the config named each package by, and what its module answered: the
 * settings a profile carries land on the name the mount reads the plugin by.
 */
function namesOf(contributions: readonly Contribution[]): ReadonlyMap<string, string> {
  return new Map(contributions.map((one) => [one.spec, one.owner]));
}

function declare(parent: Command, operation: Operation, contribution: Contribution, env: CommandEnvironment, names: ReadonlyMap<string, string>): void {
  const words = operation.cli!.words;
  const command = parent
    .command(words[words.length - 1]!, operation.cli!.default ? { isDefault: true } : undefined)
    .description(`${operation.summary} (from ${contribution.owner})`);
  declareInput(command, operation);
  command.option("--json", "print the output as JSON, a stream as JSON Lines, and an error as the envelope on stderr");
  // An argument commander itself refuses — one missing, one too many, a flag
  // nobody declared — is an input refused: said here, as the envelope under
  // --json, and exits as one. Commander's own line is not printed beside it.
  command.configureOutput({ outputError: () => {} });
  command.exitOverride((error) => {
    if (error.code === "commander.helpDisplayed" || error.code === "commander.help" || error.code === "commander.version") throw error;
    const message = error.message.replace(/^error: /, "");
    refuse({ code: "amy.input", message }, EXIT.refused, { json: askedForJson(command) }, env.out);
    throw new CommanderError(EXIT.refused, ANSWERED, message);
  });
  command.action(async (...passed: unknown[]) => {
    const invoked = passed[passed.length - 1] as Command;
    const { json, ...options } = invoked.opts<Record<string, unknown>>();
    process.exitCode = await run(contribution, operation.id, { args: invoked.processedArgs, options }, json === true, env, names);
  });
}

/** The code of an error already said to the person: the entry point exits with it and says nothing more. */
export const ANSWERED = "amy.answered";

/** Whether the command line that reached this command asked for --json, read before commander could parse it. */
function askedForJson(command: Command): boolean {
  let root = command;
  while (root.parent) root = root.parent;
  return ((root as unknown as { rawArgs?: readonly string[] }).rawArgs ?? []).includes("--json");
}

/** What was typed at one operation's command. */
interface Typed {
  readonly args: readonly unknown[];
  readonly options: Readonly<Record<string, unknown>>;
}

/**
 * Runs one operation from argv under the profile it belongs to, writing its
 * answer, and returns the exit code.
 */
async function run(contribution: Contribution, id: string, typed: Typed, json: boolean, env: CommandEnvironment, names: ReadonlyMap<string, string>): Promise<number> {
  const manner = { json, color: !json && mayColor(process.stdout) };
  const chosen = env.profileFor(contribution);
  if (!chosen.ok) return refuse({ code: "amy.input", message: chosen.problem }, EXIT.refused, manner, env.out);

  const operation = ownOperation(contribution, chosen.profile, id);
  if (!operation) {
    return refuse({ code: "amy.unknown_operation", message: `\`${id}\` is not declared by the ${contribution.owner} that ${chosen.profile.name} mounts` }, EXIT.refused, manner, env.out);
  }

  const input = assembleInput(operation, typed.args, typed.options);
  if (!input.ok) {
    return refuse({ code: "amy.input", message: `${spelledAs(operation, input.field)} ${input.why}`, details: [{ path: [input.field], message: input.why }] }, EXIT.refused, manner, env.out);
  }

  const context = await contextFor(contribution, operation, chosen.profile, env, names);
  if (!context.ok) return refuse(context.error, EXIT.internal, manner, env.out);
  return answer(operation, input.input, context.context, manner, env.out);
}

/** The operation the chosen profile's own implementation declares under this id. */
function ownOperation(contribution: Contribution, profile: Profile, id: string): Operation | undefined {
  return forProfile(contribution, profile).operations.find((operation) => operation.id === id);
}

type Prepared =
  | { ok: true; context: OperationContext }
  | { ok: false; error: { code: string; message: string } };

/**
 * What the operation is handed: the profile's directory, the machine root and
 * its plugin's settings, and the mounted ports for one declaring `mount: true`
 * — or the reason the machine did not come up. Never half a machine: an
 * operation that needs the ports and has half of them would report something
 * other than why it is broken.
 */
async function contextFor(
  contribution: Contribution,
  operation: Operation,
  profile: Profile,
  env: CommandEnvironment,
  names: ReadonlyMap<string, string>,
): Promise<Prepared> {
  const own = forProfile(contribution, profile);
  let settings: Record<string, unknown>;
  try {
    settings = settingsFor(own, profile, env.home, env.config, names);
  } catch (error) {
    return { ok: false, error: { code: "amy.internal", message: error instanceof Error ? error.message : String(error) } };
  }

  let ports: ReadonlyMap<PortKind, object> | undefined;
  if (operation.mount) {
    const outcome = await env.mount(profile);
    if (!outcome.ok) {
      return {
        ok: false,
        error: {
          code: "amy.unmounted",
          message: `\`amy ${operation.cli?.words.join(" ") ?? operation.id}\` needs the machine ${profile.name} drives, which did not come up: ${outcome.problems.join("; ")}`,
        },
      };
    }
    ports = outcome.ports;
  }

  return {
    ok: true,
    context: {
      port: (name) => {
        if (!ports) throw new Error(`\`${operation.id}\` does not declare mount: true, so it is handed no port; asked for \`${name}\``);
        return ports.get(name);
      },
      plugin: { state: stateDirectory(env.home, profile), home: env.home, settings },
    },
  };
}

/**
 * Runs one operation by id for a caller that is not a person — the host
 * keeping the price table current — answering its exit code. Whatever it
 * says is drawn the way a command's would be.
 */
export async function runById(
  contributions: readonly Contribution[],
  id: string,
  input: Record<string, unknown>,
  env: CommandEnvironment,
  /** Named by a caller that is not a person, so nothing can be ambiguous. */
  profileName?: string,
): Promise<number | undefined> {
  const contribution = contributions.find((one) => one.operations.some((operation) => operation.id === id));
  if (!contribution) return undefined;
  const chosen = profileName ? namedProfile(contribution, profileName) : env.profileFor(contribution);
  const manner = { json: false, color: false };
  if (!chosen.ok) return refuse({ code: "amy.input", message: chosen.problem }, EXIT.refused, manner, env.out);
  const operation = ownOperation(contribution, chosen.profile, id);
  if (!operation) return undefined;
  const context = await contextFor(contribution, operation, chosen.profile, env, namesOf(contributions));
  if (!context.ok) return refuse(context.error, EXIT.internal, manner, env.out);
  return answer(operation, input, context.context, manner, env.out);
}

import { services, servicesDocument } from "@amykit/services";
import type { DeclaredOperation } from "@amykit/core";
import type { Contribution } from "../plugin-commands.js";

/**
 * The install's whole contract as an OpenAPI document: amy's own services,
 * and every operation a plugin some profile mounts declares. A plugin's
 * operation is local-only unless it says otherwise, so installing one never
 * opens a route over TCP by surprise.
 *
 * Throws, naming what clashed, when the operations do not make one contract:
 * an id declared twice, or two operations taking one path and method.
 */
export function installContract(contributions: readonly Contribution[]): Record<string, unknown> {
  const own: DeclaredOperation[] = [...services.operations.values()];
  const brought = contributions.flatMap((contribution) => contribution.operations);
  return servicesDocument([...own, ...brought]);
}

import { Json, labelOf, resolved } from "./schema.js";

/**
 * An operation's output, drawn for a person from the output and its schema
 * alone: an object as labelled fields, an array of objects as a table, an
 * enum's values coloured, each field labelled by its title or description.
 *
 * No operation draws itself. One renderer for every output is what keeps a
 * plugin's command looking like amy's, and what keeps a plugin from writing
 * to the terminal at all.
 */
export function draw(value: unknown, schema: Json | undefined, color: boolean): string[] {
  const root = schema;
  const at = resolved(schema, root);
  if (Array.isArray(value)) return drawArray(value, at, root, color, "");
  if (isRecord(value)) return drawFields(value, at, root, color, "");
  return [scalar(value, at, color)];
}

/** One event of a stream, drawn as its name and then its data. */
export function drawEvent(event: string, data: unknown, schema: Json | undefined, color: boolean): string[] {
  const drawn = draw(data, schema, color);
  if (drawn.length === 1) return [`${paint(event, BOLD, color)}  ${drawn[0]}`];
  return [paint(event, BOLD, color), ...drawn.map((line) => `  ${line}`)];
}

const BOLD = "1";
const PALETTE = ["32", "33", "36", "35", "34", "31"];

function paint(text: string, code: string, color: boolean): string {
  return color ? `\u001b[${code}m${text}\u001b[0m` : text;
}

function visible(text: string): number {
  // eslint-disable-next-line no-control-regex -- an ANSI escape is a control character, and measuring a cell has to skip it
  return text.replace(/\u001b\[[0-9;]*m/g, "").length;
}

function pad(text: string, width: number): string {
  return text + " ".repeat(Math.max(0, width - visible(text)));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** A value with no structure of its own, as it reads in a field or a cell. */
function scalar(value: unknown, schema: Json | undefined, color: boolean): string {
  if (value === undefined || value === null) return "—";
  if (Array.isArray(schema?.enum)) {
    const index = (schema.enum as unknown[]).indexOf(value);
    return paint(String(value), PALETTE[Math.max(0, index) % PALETTE.length]!, color);
  }
  if (typeof value === "boolean") return value ? "yes" : "no";
  if (typeof value === "string" || typeof value === "number") return String(value);
  if (Array.isArray(value)) {
    if (value.length === 0) return "(none)";
    const items = resolved(schema?.items as Json | undefined, schema);
    return value.map((one) => scalar(one, items, color)).join(", ");
  }
  return JSON.stringify(value);
}

/** The fields of a property, in the order its schema declares them, then any it does not. */
function keysOf(value: Record<string, unknown>, schema: Json | undefined): string[] {
  const declared = Object.keys((schema?.properties ?? {}) as Json);
  return [...declared, ...Object.keys(value).filter((key) => !declared.includes(key))];
}

function propertyOf(schema: Json | undefined, key: string, root: Json | undefined): Json | undefined {
  const properties = (schema?.properties ?? {}) as Record<string, Json>;
  return resolved(properties[key], root);
}

/** Whether a value is drawn as a block of its own rather than on its label's line. */
function isBlock(value: unknown): boolean {
  return isRecord(value) || (Array.isArray(value) && value.length > 0 && value.every(isRecord));
}

function drawFields(value: Record<string, unknown>, schema: Json | undefined, root: Json | undefined, color: boolean, indent: string): string[] {
  const keys = keysOf(value, schema).filter((key) => value[key] !== undefined);
  const width = Math.max(0, ...keys.filter((key) => !isBlock(value[key])).map((key) => labelOf(key, propertyOf(schema, key, root)).length));
  const lines: string[] = [];
  for (const key of keys) {
    const field = propertyOf(schema, key, root);
    const label = labelOf(key, field);
    const one = value[key];
    if (isRecord(one)) {
      lines.push(`${indent}${paint(label, BOLD, color)}`, ...drawFields(one, field, root, color, `${indent}  `));
    } else if (isBlock(one)) {
      lines.push(`${indent}${paint(label, BOLD, color)}`, ...drawArray(one as unknown[], field, root, color, `${indent}  `));
    } else {
      lines.push(`${indent}${pad(label, width)}  ${scalar(one, field, color)}`.trimEnd());
    }
  }
  return lines;
}

function drawArray(value: readonly unknown[], schema: Json | undefined, root: Json | undefined, color: boolean, indent: string): string[] {
  const items = resolved(schema?.items as Json | undefined, root);
  if (value.length === 0) return [`${indent}(none)`];
  if (!value.every(isRecord)) return value.map((one) => `${indent}${scalar(one, items, color)}`);
  return table(value as Record<string, unknown>[], items, root, color, indent);
}

/** Rows of objects as a table: one column per field any row carries, headed by its label. */
function table(rows: readonly Record<string, unknown>[], schema: Json | undefined, root: Json | undefined, color: boolean, indent: string): string[] {
  const keys = keysOf(Object.assign({}, ...rows) as Record<string, unknown>, schema).filter((key) => rows.some((row) => row[key] !== undefined));
  const headers = keys.map((key) => paint(labelOf(key, propertyOf(schema, key, root)), BOLD, color));
  const cells = rows.map((row) => keys.map((key) => scalar(row[key], propertyOf(schema, key, root), color)));
  const widths = keys.map((_, column) => Math.max(visible(headers[column]!), ...cells.map((row) => visible(row[column]!))));
  const line = (row: readonly string[]): string => `${indent}${row.map((cell, column) => pad(cell, widths[column]!)).join("  ")}`.trimEnd();
  return [line(headers), ...cells.map(line)];
}

/** Whether this process may colour what it draws. */
export function mayColor(stream: { isTTY?: boolean }): boolean {
  return stream.isTTY === true && process.env.NO_COLOR === undefined && process.env.TERM !== "dumb";
}

import type { Operation, OperationSchema } from "@amykit/core";

/** A JSON Schema, as the library that declared the operation wrote it. */
export type Json = Record<string, unknown>;

const TARGET = { target: "draft-2020-12" } as const;

/** The schema of one side of an operation, straight from the library that declared it. */
export function jsonSchemaOf(schema: OperationSchema, side: "input" | "output"): Json {
  return schema["~standard"].jsonSchema[side](TARGET);
}

/** The input schema of an operation. */
export function inputSchemaOf(operation: Operation): Json {
  return jsonSchemaOf(operation.input, "input");
}

/**
 * A schema with its reference followed and its optional half dropped: what a
 * value of it actually looks like. `root` is where `#/$defs/...` resolves.
 */
export function resolved(schema: Json | undefined, root: Json | undefined): Json | undefined {
  let current = schema;
  for (let depth = 0; current && depth < 16; depth += 1) {
    const ref = current.$ref;
    if (typeof ref === "string" && ref.startsWith("#/$defs/") && root) {
      const defs = (root.$defs ?? {}) as Record<string, Json>;
      current = { ...defs[ref.slice("#/$defs/".length)], ...withoutKey(current, "$ref") };
      continue;
    }
    const branches = (current.anyOf ?? current.oneOf) as Json[] | undefined;
    if (Array.isArray(branches)) {
      const real = branches.filter((branch) => branch.type !== "null");
      if (real.length === 1) {
        current = { ...withoutKey(withoutKey(current, "anyOf"), "oneOf"), ...real[0] };
        continue;
      }
    }
    return current;
  }
  return current;
}

function withoutKey(schema: Json, key: string): Json {
  const { [key]: _dropped, ...rest } = schema;
  return rest;
}

/** The one type a schema names, `null` dropped from a list of them. */
export function typeOf(schema: Json | undefined): string | undefined {
  if (!schema) return undefined;
  if (Array.isArray(schema.enum)) return "enum";
  const type = schema.type;
  if (typeof type === "string") return type;
  if (Array.isArray(type)) return (type as string[]).find((one) => one !== "null");
  if (schema.properties) return "object";
  return undefined;
}

/** What a person reads a field as: its title, its description, or its name. */
export function labelOf(name: string, schema: Json | undefined): string {
  if (typeof schema?.title === "string" && schema.title !== "") return schema.title;
  if (typeof schema?.description === "string" && schema.description !== "") return schema.description;
  return name;
}

/** `staleAfter` as a flag: `--stale-after`. */
export function flagOf(field: string): string {
  return `--${field.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/_/g, "-").toLowerCase()}`;
}

import path from "node:path";
import { Profile, artifactDirectory, directoriesFor, projectStateKey } from "./profiles.js";

/**
 * What every profile shares, under one state directory.
 *
 * The config, the log, the handbrake, the notes and the inbox are shared on
 * purpose. One log means one budget, and one handbrake means
 * `amy pause` stops the machine rather than the workflow you happened to name.
 */
export function paths(home: string) {
  return {
    base: home,
    config: path.join(home, "config.yaml"),
    notes: path.join(home, "notes"),
    needsInput: path.join(home, "needs-input"),
    log: path.join(home, "log"),
    stop: path.join(home, "PAUSED"),
    /** Written by the daemon, so a second one refuses rather than doubles up. */
    pid: path.join(home, "daemon.pid"),
    /**
     * The npm root amy's plugins are installed into and resolved from.
     *
     * Part of the state like everything else here, so `AMY_HOME` moves it with
     * the rest: a plugin follows its machine's state directory, not a global
     * prefix shared with whatever else npm has put there.
     */
    plugins: path.join(home, "plugins"),
  };
}

/**
 * The npm root one profile resolves its own packages through, nested inside
 * the machine's: a name it does not hold walks up to `<home>/plugins`, which
 * is how a profile root holds no core and still reaches the one the machine
 * has.
 */
export function profileRoot(home: string, profile: string): string {
  return path.join(paths(home).plugins, "profiles", profile);
}

/** Where the forks of a profile whose workflow is installed rather than yours live. */
export function profileForks(home: string, profile: string): string {
  return path.join(home, "profiles", profile, "forks");
}

/** The directories that belong to one profile and to nothing else. */
export function profilePaths(home: string, profile: string | Profile) {
  return { ...paths(home), ...statePaths(home, profile) };
}

function statePaths(home: string, profile: string | Profile) {
  const dirs = directoriesFor(profile);
  const project = phaseState(profile);
  const artifacts = projectArtifacts(profile);

  return {
    records: path.join(home, dirs.records),
    queue: path.join(home, dirs.queue),
    // Plugin-owned state follows the project the way its queue does.
    tasks: path.join(home, project ?? "", "tasks"),
    // One Slack identity per machine, so one thread map: splitting this per
    // profile would forget the threads a running install already answered in.
    slack: path.join(home, project ?? "", "slack"),
    // A project's Telegram topics are its own; the bot's reader is shared.
    telegram: path.join(home, project ?? "", "telegram"),
    ...(artifacts ? { artifacts: path.join(home, artifacts) } : {}),
    ...(project ? { log: path.join(home, project, "log"), pid: profileDaemonPid(home, profile) } : {}),
  };
}

/**
 * A daemon is owned by the configured profile, not its current project path.
 *
 * Project state can deliberately move when a profile is repointed; a live
 * process must stay visible to stop, removal and update checks through that
 * transition so a second worker cannot take its place.
 */
function profileDaemonPid(home: string, profile: string | Profile): string {
  return typeof profile === "string" ? path.join(home, "daemon.pid") : path.join(home, "profiles", profile.name, "daemon.pid");
}

/**
 * Every PID location a profile may own across a packaged/project transition.
 *
 * A project is one profile now, and its phases walk as child records of one
 * record; what moved at the update is the profile's own layout.
 */
export function profileDaemonPids(home: string, profile: string | Profile): readonly string[] {
  if (typeof profile === "string") return [path.join(home, "daemon.pid")];
  const current = profilePaths(home, profile).pid;
  const previous = profile.project ? paths(home).pid : profileDaemonPid(home, profile);
  return current === previous ? [current] : [current, previous];
}

function phaseState(profile: string | Profile): string | undefined {
  return typeof profile === "string" || !profile.project ? undefined : projectStateKey(profile.project, profile.name);
}

function projectArtifacts(profile: string | Profile): string | undefined {
  return typeof profile === "string" ? undefined : artifactDirectory(profile);
}

/**
 * What `amy workflow rm` may delete: the directories no other profile reads.
 *
 * A project owns its tasks, Slack threads and Telegram topics as well as its
 * records and queue; an ordinary profile shares those with its neighbours.
 * Never the log: it is append-only because the budget is measured off it.
 */
export function profileOwnedDirectories(home: string, profile: Profile): string[] {
  const place = profilePaths(home, profile);
  return profile.project ? [place.records, place.queue, place.tasks, place.slack, place.telegram] : [place.records, place.queue];
}

/** The repository's plan board is a small, pure consistency check. */
interface PlanGate {
  readonly name: string;
  readonly plan: string;
  readonly requiredAssertions: readonly string[];
}

export interface PlanBoardInput {
  readonly gates: readonly PlanGate[];
  /** Paths to markdown files currently present under plans/. */
  readonly planFiles: readonly string[];
  /** Paths linked by the active and parked tables in next-steps.md. */
  readonly listedPlans: readonly string[];
  /** Contents of design notes, keyed by their repository-relative path. */
  readonly designNotes: Readonly<Record<string, string>>;
  /** Each plan's parsed YAML declaration, keyed by its path under plans/. */
  readonly declarations?: Readonly<Record<string, unknown>>;
}

function entries(declaration: unknown, key: string): unknown[] | undefined {
  if (typeof declaration !== "object" || declaration === null) return undefined;
  const value: unknown = (declaration as Record<string, unknown>)[key];
  return Array.isArray(value) && value.length > 0 ? value : undefined;
}

function says(entry: unknown, key: string): boolean {
  if (typeof entry !== "object" || entry === null) return false;
  const value: unknown = (entry as Record<string, unknown>)[key];
  return typeof value === "string" && value.trim() !== "";
}

/**
 * A plan names the failures it does not hold against and answers what it
 * crosses before work starts, so its review has a scope: without them a
 * reviewer finds the failure model one round at a time.
 */
function checkDeclaration(plan: string, declaration: unknown): string[] {
  const problems: string[] = [];
  if (entries(declaration, "crosses") === undefined) {
    problems.push(`${plan} answers no mechanism under crosses`);
  }
  const guarantee = entries(declaration, "guarantee");
  if (guarantee === undefined) {
    problems.push(`${plan} declares no guarantee, so its review has no failure model`);
  } else {
    guarantee.forEach((entry, index) => {
      if (!says(entry, "holds") || !says(entry, "not_against")) {
        problems.push(`${plan} guarantee ${index + 1} needs both holds and not_against`);
      }
    });
  }
  return problems;
}

/**
 * Keeps delivered work out of the execution board without letting its proof
 * disappear with the plan that introduced it.
 */
export function checkPlanBoard(input: PlanBoardInput): string[] {
  const problems: string[] = [];
  const listed = new Set(input.listedPlans);

  for (const gate of input.gates) {
    if (gate.plan.startsWith("plans/")) {
      problems.push(`gate ${gate.name} still points at ${gate.plan}`);
      continue;
    }

    const note = input.designNotes[gate.plan];
    if (note === undefined) {
      problems.push(`gate ${gate.name} points at missing design note ${gate.plan}`);
      continue;
    }

    for (const assertion of gate.requiredAssertions) {
      if (!note.includes(assertion)) {
        problems.push(`gate ${gate.name} requires ${assertion}, but ${gate.plan} does not name it`);
      }
    }
  }

  for (const plan of input.planFiles) {
    if (plan === "plans/next-steps.md") continue;
    if (!listed.has(plan)) {
      problems.push(`${plan} is not listed in plans/next-steps.md`);
    }
    if (input.declarations !== undefined) {
      problems.push(...checkDeclaration(plan, input.declarations[plan]));
    }
  }

  return problems;
}

import fs from "node:fs";
import path from "node:path";
import {
  Check,
  CommandOutput,
  DeclaredOperation,
  Operation,
  Plugin,
  PluginCheck,
  CommandRunner,
  PluginFile,
  PluginSetup,
  PortKind,
  validateConfig,
} from "@amykit/core";
import { AmyConfig } from "./config.js";
import { LoadResult } from "./loader.js";
import { Profile, directoriesFor } from "./profiles.js";
import { pluginList, pluginSlices } from "./slices.js";

/**
 * The names the host owns on every install.
 *
 * A plugin cannot take one: `amy doctor` that a package can replace is a
 * command whose meaning depends on what somebody installed, and the first
 * symptom would be a machine that stopped answering.
 */
export const BUILT_IN_COMMANDS: readonly string[] = [
  "init", "doctor", "add", "remove", "update", "start", "stop", "status",
  "tick", "run", "look", "queue", "budget", "brief", "skills", "workflow", "plugin",
  "contract", "config", "mount-check",
  // Hidden from `amy --help`, and still the host's: a script's way to queue
  // work without moving any, and the two halves of the loop a supervisor runs.
  "discover", "daemon", "after-daemon",
];

/** Everything one package brings to the command line. */
export interface Contribution {
  /** The package's own name: what `amy --help` marks the commands with. */
  readonly owner: string;
  /** The spec the config named it by, which a local workflow spells differently. */
  readonly spec: string;
  readonly plugin: Plugin;
  /** Every configured profile that mounts it, which is who may run it. */
  readonly profiles: readonly Profile[];
  /** Every operation it declares: each with `cli` words is a command too. */
  readonly operations: readonly Operation[];
  readonly checks: readonly PluginCheck[];
  readonly files: readonly PluginFile[];
  readonly setup: readonly PluginSetup[];
  /**
   * What each profile mounts under this name, when it is its own: a profile
   * that forked the package gets the fork's operations, checks, files and setup.
   */
  readonly byProfile?: ReadonlyMap<string, Contribution>;
}

/** The implementation one profile mounts under a contribution's name. */
export function forProfile(contribution: Contribution, profile: Pick<Profile, "name">): Contribution {
  return contribution.byProfile?.get(profile.name) ?? contribution;
}

export interface Gathered {
  readonly contributions: readonly Contribution[];
  /**
   * Names two owners both claim, and a plugin still declaring the commands
   * amy no longer reads: refused before anything runs.
   */
  readonly problems: readonly string[];
}

/**
 * Everything the configured profiles mount, read without mounting any of it.
 *
 * A command has to answer while the machine will not come up, so the modules
 * are imported and their declarations read; nothing here calls `register`.
 * A package that will not import is left out and named by `amy doctor`, not
 * refused here: one missing plugin must not take the whole command line with
 * it.
 */
export async function gather(
  config: AmyConfig,
  known: readonly Profile[],
  load: (specs: readonly string[], profile?: string) => Promise<LoadResult>,
): Promise<Gathered> {
  // Each profile is read through its own resolver: a profile that forked a
  // package mounts the fork, so what it contributes is the fork's.
  const contributions = new Map<string, Contribution>();
  const byProfile = new Map<string, Map<string, Contribution>>();
  for (const profile of known) {
    const specs = pluginList(config, profile);
    const loaded = await load(specs, profile.name);
    for (const spec of specs) {
      const plugin = loaded.bySpec.get(spec);
      if (!plugin) continue;
      const own = contributionOf(plugin, spec, [profile]);
      const existing = contributions.get(plugin.name);
      contributions.set(plugin.name, existing ? { ...merged(existing, own), profiles: [...existing.profiles, profile] } : own);
      byProfile.set(plugin.name, (byProfile.get(plugin.name) ?? new Map()).set(profile.name, own));
    }
  }
  const all = [...contributions.values()].map((contribution) => ({ ...contribution, byProfile: byProfile.get(contribution.owner) }));
  return { contributions: all, problems: [...retired(all), ...conflicts(all)] };
}

/**
 * A plugin that still declares `commands`, named with the member amy no
 * longer reads. Refused rather than ignored: a plugin whose commands quietly
 * vanished would read as a machine that lost them.
 */
function retired(contributions: readonly Contribution[]): string[] {
  const plugins = contributions.flatMap((contribution) => [contribution.plugin, ...[...(contribution.byProfile?.values() ?? [])].map((own) => own.plugin)]);
  const named = new Set(plugins.filter((plugin) => (plugin as { commands?: unknown }).commands !== undefined).map((plugin) => plugin.name));
  return [...named].map((name) =>
    `${name} declares \`commands\`, which amy no longer reads: a plugin declares \`operations\`, and the command line is drawn from them`,
  );
}

function contributionOf(plugin: Plugin, spec: string, profiles: readonly Profile[]): Contribution {
  return {
    owner: plugin.name,
    spec,
    plugin,
    profiles,
    operations: (plugin.operations ?? []) as readonly DeclaredOperation[] as readonly Operation[],
    checks: plugin.checks ?? [],
    files: plugin.files ?? [],
    setup: plugin.setup ?? [],
  };
}

/** Two profiles mounting one name: the first one's declarations, unless it brought none. */
function merged(existing: Contribution, own: Contribution): Contribution {
  return {
    ...existing,
    // Every profile's operations, by id: a fork that adds one brings its
    // command and its contract entry like any other, and the first profile's
    // declaration answers for an id two of them share.
    operations: [...existing.operations, ...own.operations.filter((operation) => !existing.operations.some((held) => held.id === operation.id))],
    checks: existing.checks.length > 0 ? existing.checks : own.checks,
    files: existing.files.length > 0 ? existing.files : own.files,
    setup: existing.setup.length > 0 ? existing.setup : own.setup,
  };
}

/**
 * An operation id and a command's first word each belong to one owner, and the
 * host's names are not on offer. Within one package, a group of words is a
 * group or an operation, never both, and has at most one default.
 */
function conflicts(contributions: readonly Contribution[]): string[] {
  const ids = new Map<string, string>();
  const words = new Map<string, string>();
  const problems: string[] = [];

  for (const contribution of contributions) {
    const own = new Set<string>();
    for (const operation of contribution.operations) {
      // One package declaring an id twice would run the first handler under
      // the second's words.
      if (own.has(operation.id)) problems.push(`${contribution.owner} declares the operation \`${operation.id}\` twice; an id is one operation`);
      own.add(operation.id);
      const heldId = ids.get(operation.id);
      if (heldId && heldId !== contribution.owner) {
        problems.push(`the operation \`${operation.id}\` is declared by both ${heldId} and ${contribution.owner}; an id is owned once`);
      } else {
        ids.set(operation.id, contribution.owner);
      }

      const first = operation.cli?.words[0];
      if (first === undefined) continue;
      if (BUILT_IN_COMMANDS.includes(first)) {
        problems.push(
          `${contribution.owner} declares \`amy ${first}\`, which this host already owns; a plugin cannot replace a built-in command`,
        );
        continue;
      }
      const held = words.get(first);
      if (held && held !== contribution.owner) {
        problems.push(`\`amy ${first}\` is declared by both ${held} and ${contribution.owner}; a name is owned once`);
        continue;
      }
      words.set(first, contribution.owner);
    }
    problems.push(...spellings(contribution));
  }

  return problems;
}

/** One package's words: no path spelled twice, no path both an operation and a group, one default a group. */
function spellings(contribution: Contribution): string[] {
  const problems: string[] = [];
  const spelled = contribution.operations.filter((operation) => operation.cli && operation.cli.words.length > 0);
  const paths = new Map<string, string>();
  const defaults = new Map<string, string>();
  for (const operation of spelled) {
    const words = operation.cli!.words;
    const path = words.join(" ");
    const held = paths.get(path);
    if (held) problems.push(`${contribution.owner} spells both \`${held}\` and \`${operation.id}\` as \`amy ${path}\`; a command runs one operation`);
    paths.set(path, operation.id);
    if (operation.cli!.default) {
      const group = words.slice(0, -1).join(" ");
      const before = defaults.get(group);
      if (before) problems.push(`${contribution.owner} makes both \`${before}\` and \`${operation.id}\` the default of \`amy ${group}\`; a group has one`);
      defaults.set(group, operation.id);
    }
    if (inputFieldsOf(operation).includes("json")) {
      problems.push(`\`${operation.id}\` takes an input field named \`json\`, which every command keeps for --json`);
    }
  }
  for (const operation of spelled) {
    const path = operation.cli!.words.join(" ");
    const under = [...paths.keys()].find((other) => other.startsWith(`${path} `));
    if (under) problems.push(`${contribution.owner} spells \`${operation.id}\` as \`amy ${path}\`, which is also the group \`amy ${under}\` sits under`);
  }
  return problems;
}

function inputFieldsOf(operation: Operation): string[] {
  try {
    const schema = operation.input["~standard"].jsonSchema.input({ target: "draft-2020-12" });
    return Object.keys((schema.properties ?? {}) as Record<string, unknown>);
  } catch {
    return [];
  }
}

/** What a command needs from the process that registered it. */
export interface CommandEnvironment {
  readonly home: string;
  readonly config: AmyConfig;
  /** The profile a contribution should run under, or why there is not one. */
  profileFor(contribution: Contribution): { ok: true; profile: Profile } | { ok: false; problem: string };
  /** The mounted ports of one profile, or why the machine did not come up. */
  mount(profile: Profile): Promise<{ ok: true; ports: ReadonlyMap<PortKind, object> } | { ok: false; problems: readonly string[] }>;
  readonly out: CommandOutput;
}

/** The directory one profile owns: its records and queue live one level down. */
export function stateDirectory(home: string, profile: Profile): string {
  return path.join(home, path.dirname(directoriesFor(profile).records));
}

/** The settings this plugin's slice carries, refused by name when they are wrong. */
export function settingsFor(contribution: Contribution, profile: Profile, home: string, config: AmyConfig, pluginNames?: ReadonlyMap<string, string>): Record<string, unknown> {
  // The settings a profile carries land on the name the mount reads the
  // plugin by — the same name-or-spec question a local workflow poses, and
  // the same map that answers it: what the config named, and what the
  // module answered when it was imported.
  const given = (pluginSlices(config, profile, home, pluginNames)[contribution.owner] ?? {}) as Record<string, unknown>;
  const schema = contribution.plugin.configSchema;
  if (!schema) return given;

  const validated = validateConfig(contribution.owner, schema, given);
  // The validated block, not the one on disk: a setting left out falls back to
  // the schema's default, which is exactly what the mounted plugin receives.
  if (validated.ok) return validated.config;
  throw new Error(`${contribution.owner} cannot run on ${profile.name}: ${validated.problems.join("; ")}`);
}

/**
 * Writes the files a profile's plugins bring, and never one that is there.
 *
 * `amy init` and `amy add` are the two moments a machine gains a plugin, so
 * they are the two moments its files arrive. What is already on disk is
 * somebody's edit, and an installer that overwrote it would be an installer
 * that loses work.
 */
export function writeFiles(
  home: string,
  config: AmyConfig,
  profile: Profile,
  contributions: readonly Contribution[],
  out: CommandOutput,
): string[] {
  const state = stateDirectory(home, profile);
  const written: string[] = [];

  for (const contribution of mountedBy(profile, contributions)) {
    for (const file of contribution.files) {
      // A plugin names a file inside the profile that mounted it, and nowhere
      // else: `..` or an absolute path would let one profile write another's
      // state, which is the one thing per-profile state exists to prevent.
      const target = insideProfile(state, contribution.owner, file.path);

      try {
        // Exclusive, so the promise holds even when two `init`s race or an
        // operator saves the file while its content is being composed.
        fs.writeFileSync(target, contentOf(file, contribution, profile, home, config, contributions), { encoding: "utf-8", flag: "wx" });
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
        throw error;
      }
      out.line(`wrote  ${target}`);
      written.push(target);
    }
  }

  return written;
}

/**
 * Runs what a profile's plugins prepare outside amy's state, after their files.
 *
 * The same two moments as the files, for the same reason. A setup that
 * throws is answered red under its owner's name rather than taking `init`
 * down with it: the next plugin's setup still has its own work to do, and
 * the doctor will say what this one left undone.
 */
export async function runSetup(
  home: string,
  config: AmyConfig,
  profile: Profile,
  contributions: readonly Contribution[],
  out: CommandOutput,
  runner: CommandRunner,
): Promise<Check[]> {
  const answered: Check[] = [];

  for (const contribution of mountedBy(profile, contributions)) {
    for (const setup of contribution.setup) {
      let answer: Check;
      try {
        answer = await setup.run({
          state: stateDirectory(home, profile),
          home,
          settings: settingsFor(contribution, profile, home, config, new Map(contributions.map((one) => [one.spec, one.owner]))),
          out,
          runner,
        });
      } catch (error) {
        answer = { label: setup.name, ok: false, detail: error instanceof Error ? error.message : String(error) };
      }
      const said = `${answer.ok ? "set up" : "could not set up"} ${contribution.owner}: ${answer.label}`;
      out.line(answer.detail ? `${said} — ${answer.detail}` : said);
      answered.push({ ...answer, label: `${contribution.owner}: ${answer.label}` });
    }
  }

  return answered;
}

/** Where a plugin's file goes, refused when it would leave this profile. */
function insideProfile(state: string, owner: string, relative: string): string {
  const target = path.resolve(state, relative);
  const inside = path.relative(state, target);
  if (inside.startsWith("..") || path.isAbsolute(inside)) {
    throw new Error(`${owner} names a file outside the profile: ${relative}`);
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  return target;
}

/** The file's content, composed from the settings the mounted plugin sees. */
function contentOf(
  file: PluginFile,
  contribution: Contribution,
  profile: Profile,
  home: string,
  config: AmyConfig,
  contributions: readonly Contribution[],
): string {
  if (typeof file.content !== "function") return file.content;
  return file.content(settingsFor(contribution, profile, home, config, new Map(contributions.map((one) => [one.spec, one.owner]))));
}

/** The contributions one profile actually mounts, and nobody else's. */
function mountedBy(profile: Profile, contributions: readonly Contribution[]): Contribution[] {
  return contributions
    .filter((contribution) => contribution.profiles.some((mounted) => mounted.name === profile.name))
    .map((contribution) => forProfile(contribution, profile));
}

/** Every plugin check for one profile, labelled with the package that brought it. */
export async function checks(
  home: string,
  config: AmyConfig,
  profile: Profile,
  contributions: readonly Contribution[],
  out: CommandOutput,
): Promise<Check[]> {
  const answered: Check[] = [];

  for (const contribution of mountedBy(profile, contributions)) {
    for (const check of contribution.checks) {
      try {
        const answer = await check.run({
          state: stateDirectory(home, profile),
          home,
          settings: settingsFor(contribution, profile, home, config, new Map(contributions.map((one) => [one.spec, one.owner]))),
          out,
        });
        answered.push({ ...answer, label: `${contribution.owner}: ${answer.label}` });
      } catch (error) {
        answered.push({
          label: `${contribution.owner}: ${check.name}`,
          ok: false,
          detail: error instanceof Error ? error.message : String(error),
        });
      }
    }
  }

  return answered;
}

/** The profile a caller named, refused when that profile does not mount it. */
export function namedProfile(
  contribution: Contribution,
  name: string,
): { ok: true; profile: Profile } | { ok: false; problem: string } {
  const profile = contribution.profiles.find((candidate) => candidate.name === name);
  if (profile) return { ok: true, profile };
  return {
    ok: false,
    problem: `\`${contribution.owner}\` is not mounted by ${name}; it runs on: ${contribution.profiles.map((candidate) => candidate.name).join(", ")}`,
  };
}

/**
 * A file at the root is one file for the machine, and a workflow reads its own
 * profile's state directory; an updater that only changed the reader would
 * leave every existing machine with a check that reads nothing where the file
 * was. The copy lands exclusive, so what a profile already carries — written
 * there by the command that added the plugin, or edited since — is never
 * overwritten. The old name is renamed rather than deleted, which is what
 * keeps the content findable and lets the doctor's red check name the move;
 * the second run sees no old name and changes nothing.
 *
 * Every copy happens before any retirement: two contributions that named the
 * same root file for two profiles each get theirs, where moving after the
 * first would leave the second's source gone and its profile empty. And the
 * rename refuses a name that is already retired — an old command or a synced
 * folder can put the same root file back, and the machine is the last place
 * one copy of a team's list is overwritten by another.
 */
export function migrateRootFiles(
  home: string,
  contributions: readonly Contribution[],
  out: CommandOutput,
): string[] {
  const copied: string[] = [];

  // The two names the host itself serves at the root, in addition to holding
  // them: config.yaml (the mount's grammar) and .env (the environment the
  // host reads on every invocation). A plugin may still declare such a name
  // and its example is written into profiles, but the machine's own copy is
  // nobody's legacy to move: retiring it would starve the host's own reader
  // of credentials on the next invocation.
  const hostOwnedRootNames = new Set(["config.yaml", ".env"]);

  const roots = contributions.flatMap((contribution) =>
    contribution.files
      .filter(
        (file) =>
          // Only a file that used to live at the root can have moved from it:
          // one segment, and never one of the names the host serves itself.
          path.dirname(file.path) === "." && !hostOwnedRootNames.has(path.basename(file.path)),
      )
      .map((file) => ({ file, contribution })),
  );

  /** The machine-side path of one such file, and the name it retires into. */
  const fromOf = (root: (typeof roots)[number]): string =>
    path.join(home, path.basename(root.file.path));

  // Every copy first: two contributions may give the same root file to two
  // profiles, and the first retirement must not leave the second's source
  // gone with its profile empty.
  for (const root of roots) {
    const from = fromOf(root);
    if (!fs.existsSync(from)) continue;

    for (const profile of root.contribution.profiles) {
      const target = insideProfile(
        stateDirectory(home, profile),
        root.contribution.owner,
        root.file.path,
      );
      try {
        // Exclusive: an edit made between the check and the copy wins, and
        // the same path rule as any other write applies to the copy too.
        fs.copyFileSync(from, target, fs.constants.COPYFILE_EXCL);
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
        throw error;
      }
      out.line(`kept  ${target}, from ${from}`);
      copied.push(target);
    }
  }

  // Then every retirement, once per root name: a machine keeps the content it
  // had for whoever still looked for it there, and the check the mounted
  // workflow runs can name where it went. The name is gone, so nothing reads
  // the root file as current a second time. When the name is already
  // retired, the machine's own copy stays where it is: the archive may be
  // the older list, and a person chooses between the two.
  const retiredBy = new Set<string>();

  for (const root of roots) {
    const from = fromOf(root);
    const retired = `${from}.moved`;
    if (!fs.existsSync(from) || retiredBy.has(from)) continue;
    retiredBy.add(from);

    if (fs.existsSync(retired)) {
      out.line(
        `kept  ${from}; ${retired} is already an archived copy of it — review both, then decide which is the machine's`,
      );
      continue;
    }

    try {
      fs.renameSync(from, retired);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") continue;
      throw error;
    }
    out.line(`moved ${from} to ${retired}; the profile's own copy is the one it reads`);
    copied.push(retired);
  }

  return copied;
}

import { EnqueueRequest, QueueItem } from "@amykit/core";

/**
 * The little of a queue a poke touches.
 *
 * Structural rather than the `Queue` port, because `running()` is not on it:
 * whether something is mid-flight is a question this asks of a queue that can
 * answer it, not a promise every queue has to keep.
 */
export interface Pokeable {
  running(): QueueItem[];
  pending(): QueueItem[];
  promote(workId: string, now: Date): number;
  enqueue(request: EnqueueRequest, now: Date): QueueItem;
}

export type PokeOutcome =
  /** Being worked on now, so its next look is already chained. */
  | { kind: "running" }
  /** Looks that were held back, moved to now. */
  | { kind: "brought-forward"; moved: number }
  /** On the queue and already due. Nothing to bring forward. */
  | { kind: "already-due" }
  /** Nothing knew about it, so it was put on the queue. */
  | { kind: "queued" };

/**
 * Looks at one piece of work now instead of when it was next due.
 *
 * The order of the three questions is the whole logic, and each answer is a
 * different reason for doing nothing more:
 *
 * 1. **Claimed** — a step is running, and the step that finishes enqueues the
 *    next look itself. Touching the queue here is what forks it: the running
 *    step's successor and this one would both be waiting, and both would
 *    chain their own.
 * 2. **Held back** — the case this exists for. The look moves; no second item
 *    is made.
 * 3. **Neither** — nothing on the queue knows about this work, so a poke is
 *    the trigger. This is what turns any webhook into a push without an
 *    endpoint: whatever heard the event runs `amy poke`.
 *
 * Poking work that has already settled costs one look and no agent: the
 * decision function answers `settled`, and the engine completes it without
 * chaining anything. Cheap enough not to need a record loaded to find out.
 */
export function poke(queue: Pokeable, workId: string, now: Date): PokeOutcome {
  if (queue.running().some((item) => item.workId === workId)) return { kind: "running" };

  const moved = queue.promote(workId, now);
  if (moved > 0) return { kind: "brought-forward", moved };

  if (queue.pending().some((item) => item.workId === workId)) return { kind: "already-due" };

  queue.enqueue({ workId, reason: "poked" }, now);
  return { kind: "queued" };
}

/** What the operator is told, in the same words for the same outcome. */
export function describePoke(workId: string, outcome: PokeOutcome): string {
  switch (outcome.kind) {
    case "running":
      return `${workId} is being worked on now — its next look is already chained`;
    case "brought-forward":
      return `${workId} is due now (${outcome.moved} look(s) brought forward)`;
    case "already-due":
      return `${workId} is on the queue and already due`;
    case "queued":
      return `${workId} queued`;
  }
}

import { CommandEnvironment, Contribution } from "./plugin-commands.js";
import { runById } from "./operations/commands.js";

/**
 * How old a price table may be before the machine refreshes it.
 *
 * A week: prices move when a provider ships a model, and a table that is a
 * month old prices today's work with last month's numbers without saying so.
 */
export const STALE_AFTER_DAYS = 7;

/** The operation that owns the price table, when a mounted relay offers it. */
const REFRESH = "models.refresh-prices";

/**
 * Keeps the shared price table current, through the operation that owns it.
 *
 * The host does not know what a model costs or where a price table lives; it
 * knows that an install whose agents are about to run should not price them
 * off a table from last month. A machine that mounted no relay has no such
 * operation, and nothing is asked of it.
 */
export async function refreshPricesWhenStale(
  contributions: readonly Contribution[],
  env: CommandEnvironment,
): Promise<void> {
  const owner = contributions.find((contribution) => contribution.operations.some((operation) => operation.id === REFRESH));
  if (!owner) return;

  const before = process.exitCode;
  try {
    // The table is the machine's, not a profile's, and nobody is here to
    // answer a question: take the first mount in config order rather than
    // letting the interactive ambiguity refusal skip the refresh entirely.
    // Quiet when it worked: a table refreshed or already fresh is nothing a
    // start has to say. A refresh that failed still says why.
    const quiet = { ...env, out: { line: () => {}, error: (text: string) => env.out.error(text) } };
    await runById(contributions, REFRESH, { staleAfter: STALE_AFTER_DAYS }, quiet, owner.profiles[0]?.name);
  } catch (error) {
    // Said, and never fatal: the move or the loop that asked for it already
    // succeeded, and the table is repaired next time.
    env.out.error(`the price table was left as it was: ${error instanceof Error ? error.message : String(error)}`);
  }
  process.exitCode = before;
}

/**
 * This repository is public and some of the work that drove it is not. This
 * is the check that keeps the two apart.
 *
 * The forbidden terms are carried as digests rather than as words, for two
 * reasons that are really one. A list of a company's private names, written
 * out in a public repository, is the leak it exists to prevent; and a check
 * that spells out what it forbids reports itself on every run. So the policy
 * carries `sha256(term)` with the term's length, and the text is reduced to
 * the same shape before it is compared.
 *
 * Matching is by window rather than by word, so a term glued into a longer
 * identifier — `AcmeDeps`, `workflow-acme`, `ACME-7716` — is found the same
 * way a term standing on its own is. That is what makes the length a part of
 * the policy: without it there is no window to hash.
 *
 * The examples above are fictional on purpose: this file is read by the check
 * it implements, and a real term in a comment here is the leak.
 */

export interface DeniedTerm {
  /** Length of the term, which is the width of the window to hash. */
  readonly length: number;
  /** Lowercase hex sha256 of the lowercased term. */
  readonly sha256: string;
}

export interface PrivateRefsInput {
  /** File contents, keyed by repository-relative path. */
  readonly files: Readonly<Record<string, string>>;
  readonly denied: readonly DeniedTerm[];
  /** Hex sha256 of a string. Injected so the rule itself stays pure. */
  readonly digest: (value: string) => string;
}

export interface PrivateRef {
  readonly file: string;
  /** 1-indexed, so the report is something an editor can be pointed at. */
  readonly line: number;
  /** The word the term was found inside, so a person knows what to remove. */
  readonly word: string;
}

/**
 * Every place a denied term appears, in reading order. An empty policy finds
 * nothing and says nothing — refusing it is the caller's job, because only
 * the caller knows whether an empty list means "nothing to hide" or "the file
 * did not load".
 */
export function findPrivateReferences(input: PrivateRefsInput): PrivateRef[] {
  const found: PrivateRef[] = [];
  const widths = [...new Set(input.denied.map((term) => term.length))].sort((a, b) => a - b);
  const digests = new Set(input.denied.map((term) => term.sha256.toLowerCase()));
  const narrowest = widths[0];
  if (narrowest === undefined) return found;

  // A repository repeats its vocabulary constantly, and hashing is the only
  // expensive thing here. One answer per distinct word is the difference
  // between a check in the pre-commit hook and a check nobody runs.
  const judged = new Map<string, boolean>();
  const carriesATerm = (word: string): boolean => {
    const remembered = judged.get(word);
    if (remembered !== undefined) return remembered;

    let hit = false;
    for (const width of widths) {
      for (let at = 0; at + width <= word.length; at += 1) {
        if (digests.has(input.digest(word.slice(at, at + width)))) {
          hit = true;
          break;
        }
      }
      if (hit) break;
    }

    judged.set(word, hit);
    return hit;
  };

  for (const [file, text] of Object.entries(input.files)) {
    const lines = text.split("\n");
    for (let index = 0; index < lines.length; index += 1) {
      for (const word of lines[index]!.toLowerCase().match(/[a-z0-9]+/g) ?? []) {
        if (word.length >= narrowest && carriesATerm(word)) {
          found.push({ file, line: index + 1, word });
        }
      }
    }
  }

  return found;
}

import { createHash } from "node:crypto";
import path from "node:path";
import type { AmyConfig, WorkflowProfile } from "./config.js";

/**
 * The phase folders a project may carry, in walk order: the brief's, the
 * work's and the proving one's. A folder named any of these is a phase of
 * the project its parent folder is; the walk of the project calls the
 * workflows its folders export.
 */
export const PROJECT_PHASES = ["brief", "workflow", "prove"] as const;
type ProjectPhase = (typeof PROJECT_PHASES)[number];

/**
 * A project, inferred from the folder a phase spec names.
 *
 * `project` is the whole project's identity — the root directory its phases
 * walk, not a case in a switch — and the phase the spec named, which tells a
 * refusal which folder was expected to say so.
 */
export interface ProjectIdentity {
  readonly root: string;
  readonly phase: ProjectPhase;
}

/**
 * Which workflow this invocation drives.
 *
 * A profile is a name in the config, not a case in a switch. `amy --workflow
 * oncall` works the moment a config declares `oncall`, because nothing here
 * enumerates what is allowed: the table below is what a config with no
 * `workflows:` block gets, which is a default rather than an inventory.
 *
 * One workflow per invocation, because `mount()` claims a single one. What is
 * shared is everything that matters — the same engine, the same log and
 * therefore the same budget, the same relay, the same forge, one handbrake.
 */
export interface Profile {
  /** What is typed after `--workflow`, and the directory its state lives in. */
  readonly name: string;
  /** The package contributing `plan()` and the runtime that answers it. */
  readonly workflow: string;
  /** What to mount. Empty means the recommended set for this workflow. */
  readonly plugins: readonly string[];
  /** The brief provider this profile explicitly chose, if any. */
  readonly briefStore?: string;
  /** Whether `amy note` files friction onto this profile's queue. */
  readonly takesNotes: boolean;
  /** Whether `amy btw` puts a task onto this profile's queue. */
  readonly takesTasks: boolean;
  /** The project artifact boundary inferred from a phase directory. */
  readonly project?: ProjectIdentity;
  /** Per-profile model and budget overrides, merged by the CLI before mount. */
  readonly agent?: WorkflowProfile["agent"];
  /**
   * The workflow's own settings, checked against its configSchema at mount.
   *
   * Whatever the profile drives may tune here — the ceilings its decisions
   * read, the status its tracker hands work to — and everything else it takes
   * from the machine's top level or its own schema's defaults.
   */
  readonly settings: Readonly<Record<string, unknown>>;
}

/**
 * What a fresh install can drive, before anybody writes a `workflows:` block.
 *
 * Nothing: the machine that arrives carries no process, and the first one on
 * it is the one the person there names or writes. `amy workflow new` and
 * `amy add` both end in a config block, which is the only place a profile
 * has ever come from.
 */
const SHIPPED_PROFILES: Record<string, WorkflowProfile> = {};

/**
 * What every profile mounts, whichever workflow is driving.
 *
 * This list is the point of the whole plugin model: the queue, the store, the
 * notes, the forge, the harnesses, the relay that composes them, the ceiling
 * it carries, every notification channel, and the engine. Not one of them is
 * duplicated for a second workflow, and not one changed to take it.
 */
const PROVIDERS: readonly string[] = [
  "@amykit/plugin-file-queue",
  "@amykit/plugin-file-store",
  // A BriefStore is intentionally its own mount: a Git-backed adapter can
  // replace this local default without the record store claiming its port.
  "@amykit/plugin-file-brief-store",
  "@amykit/plugin-file-notes",
  "@amykit/plugin-github",
];

/** Mount after the workflow declares terminal states, before its consumers capture Git. */
const WORKTREE_AND_CONSUMERS: readonly string[] = [
  "@amykit/plugin-file-worktree",
  "@amykit/plugin-claude",
  "@amykit/plugin-codex",
  "@amykit/plugin-hermes-agent",
  // The only thing that mounts the `agent` port. The harnesses above merely
  // contribute themselves to it, so dropping this from a config leaves every
  // agent action without a port and the mount is refused at boot.
  "@amykit/plugin-agent-relay",
  "@amykit/plugin-notify-fanout",
  "@amykit/plugin-notify-hermes",
  "@amykit/plugin-notify-inbox",
  "@amykit/plugin-serial-engine",
];

/**
 * What a shipped workflow needs beside the shared set.
 *
 * Keyed by the workflow package rather than by the profile name: what a
 * workflow depends on travels with the workflow, so renaming a profile in a
 * config changes nothing about what mounts under it.
 */
const NEEDS: Record<string, readonly string[]> = {
  "@amykit/workflow-ticket-to-qa": ["@amykit/plugin-linear", "@amykit/plugin-command-gate"],
  "@amykit/workflow-note-to-plan": ["@amykit/plugin-plan-check"],
  "@amykit/workflow-errand": ["@amykit/plugin-file-tasks"],
  "@amykit/workflow-feature-grooming": ["@amykit/plugin-linear"],
};

/** What `amy init` suggests installing for a profile that lists nothing. */
export function recommendedFor(profile: Profile): readonly string[] {
  return recommendedPluginsFor(profile.workflow);
}

/** What a workflow would mount, named by its spec: the recommendation the boot would read. */
function recommendedPluginsFor(workflow: string): readonly string[] {
  const needs = NEEDS[workflow] ?? [];
  // Workflow ports need their providers during registration, while the
  // worktree captures the workflow's terminal states and must follow it.
  const prerequisites = needs.filter((plugin) => plugin === "@amykit/plugin-linear");
  const consumers = needs.filter((plugin) => plugin !== "@amykit/plugin-linear");
  return [...PROVIDERS, ...prerequisites, workflow, ...WORKTREE_AND_CONSUMERS, ...consumers];
}

/** Every profile this install can drive: the shipped ones, plus the config's. */
export function profiles(config: AmyConfig, home?: string): Record<string, Profile> {
  const declared = { ...SHIPPED_PROFILES, ...config.workflows };
  // Profile names come from configuration. A null prototype makes every
  // accepted name an own entry rather than inheriting Object's vocabulary.
  const resolved = Object.create(null) as Record<string, Profile>;

  for (const [name, entry] of Object.entries(declared)) {
    assertProfileName(name);
    const workflow = filesystemWorkflow(home, entry.workflow);
    resolved[name] = {
      name,
      workflow,
      // The configured spelling remains in config, but the plugin loader and
      // the required-workflow check must agree on the live absolute spec.
      plugins: (entry.plugins ?? []).map((plugin) => plugin === entry.workflow ? workflow : plugin),
      briefStore: entry.briefStore,
      takesNotes: entry.notes ?? false,
      takesTasks: entry.tasks ?? false,
      project: projectFor(workflow),
      agent: entry.agent,
      settings: entry.settings ?? {},
    };
  }

  // A project is one profile and one daemon: its phases are child records of
  // the project's record, walked in the one walk the project's workflow
  // declares. Two profiles naming one project would run the same walk twice,
  // and the second would find the work of the first already under way.
  const roots = new Map<string, string[]>();
  for (const [name, profile] of Object.entries(resolved)) {
    if (!profile.project) continue;
    const names = roots.get(profile.project.root) ?? [];
    names.push(name);
    roots.set(profile.project.root, names);
  }
  for (const [root, names] of roots) {
    if (names.length < 2) continue;
    throw new Error(
      `the project at ${root} is one profile: ${names.map((name) => `\`${name}\``).join(" and ")} both name it — a project walks its phases as child records of one profile, so fold them into the one entry naming its workflow/ (the update's migration folds such a config)`,
    );
  }

  return resolved;
}

export type Resolution = { ok: true; profile: Profile } | { ok: false; problem: string };

/**
 * The profile a name asks for, or why there is none.
 *
 * A name nobody declared is refused with the list of names there were, which
 * is the difference between a typo you can fix and a command that does
 * nothing. No name at all takes `defaultWorkflow`, and then the first one
 * declared, so an install with one workflow never has to name it.
 */
export function resolveProfile(config: AmyConfig, asked?: string, home?: string): Resolution {
  const known = profiles(config, home);
  const names = Object.keys(known);
  const wanted = (asked ?? config.defaultWorkflow ?? "").trim() || names[0];

  if (!wanted) {
    return {
      ok: false,
      problem:
        "no workflow is configured, so there is nothing to drive — `amy workflow new` writes one, `amy add` names an existing package",
    };
  }

  const profile = known[wanted];
  if (!profile) {
    return { ok: false, problem: `there is no \`${wanted}\` workflow. Try: ${names.join(", ")}` };
  }

  // A config that names a `test/` folder as its workflow is the legacy
  // proving-phase anchor, and it is refused with the rename: under the
  // project vocabulary the proving phase is `prove/`, and a `test/` spec
  // would otherwise mount as an ordinary workflow without a word about it.
  const spec = filesystemWorkflow(home, profile.workflow);
  if (path.basename(spec) === "test") {
    return {
      ok: false,
      problem: `\`${profile.workflow}\` is the old proving phase's folder, and the phase is named \`prove/\` now — rename the folder to \`prove/\`, or name another workflow`,
    };
  }

  return { ok: true, profile };
}

/** Resolve a portable filesystem spec only while constructing its live profile. */
function filesystemWorkflow(home: string | undefined, workflow: string): string {
  // The home resolves a workflow-of-your-own; a package named by spec comes
  // through untouched, with or without a home to resolve against.
  return workflow.startsWith(".") && home ? path.resolve(home, workflow) : workflow;
}

/**
 * Where a project keeps its records and its queue, under one `.amy`.
 *
 * A project is one profile now: its phases are child records of the
 * project's record, not profiles of their own, so every phase shares the
 * one state key the project has. Everything else under `.amy` stays shared:
 * one log means one budget, and one handbrake means `amy stop` stops the
 * project's daemon.
 */
export function directoriesFor(profile: string | Pick<Profile, "name" | "project">): { records: string; queue: string } {
  if (typeof profile !== "string" && profile.project) {
    const base = projectStateKey(profile.project, profile.name);
    return { records: `${base}/records`, queue: `${base}/queue` };
  }
  const name = typeof profile === "string" ? profile : profile.name;
  return { records: `${name}/records`, queue: `${name}/queue` };
}

/**
 * The shared project root is inferred from a phase directory, never from `..`
 * configuration. Every `brief/`, `workflow/` or `prove/` is a phase, alone or
 * not: a folder a project lacks is a part of the work nobody drives.
 */
function projectFor(workflow: string): ProjectIdentity | undefined {
  if (!workflow.startsWith(".") && !path.isAbsolute(workflow)) return undefined;
  const phase = path.basename(workflow) as ProjectPhase;
  if (!PROJECT_PHASES.includes(phase)) return undefined;
  return { root: path.resolve(workflow, ".."), phase };
}

/** A stable, path-safe state name that cannot make a profile leave Amy home. */
export function projectStateKey(project: ProjectIdentity, profile?: string): string {
  return `${projectRootKey(project)}${profile ? `/${profile}` : ""}`;
}

/** A profile name becomes part of its state path, so it has one safe component. */
function assertProfileName(name: string): void {
  if (!name || name === "." || name === ".." || name.includes("/") || name.includes("\\") || path.win32.basename(name) !== name) {
    throw new Error(`a workflow profile name must be one path component: \`${name}\``);
  }
}

/** The project-owned state root; phase names are appended only by the host. */
function projectRootKey(project: ProjectIdentity): string {
  const safe = createHash("sha256").update(project.root).digest("base64url");
  return `projects/${safe}`;
}

/** The one directory the project's phases share; its state stays the project's alone. */
export function artifactDirectory(profile: Pick<Profile, "project">): string | undefined {
  return profile.project ? `${projectRootKey(profile.project)}/artifacts` : undefined;
}

/**
 * The layout a version before profiles-as-data wrote, and where it went.
 *
 * The old names were the shipped profiles: `ticket-to-qa` under its own
 * directory and the two beside it. A config may declare any of those names
 * again, so the mapping only fires for a directory the config does not
 * declare — a name somebody chose is theirs, not this table's.
 */
export const LEGACY_DIRECTORIES: Record<string, string> = {
  tickets: "ticket-to-qa/records",
  queue: "ticket-to-qa/queue",
  plans: "note-to-plan/records",
  "plan-queue": "note-to-plan/queue",
};

import fs from "node:fs";
import path from "node:path";
import {
  ConfigSchema,
  ConfigField,
  Plugin,
  ProjectPhases,
  WorkflowPlugin,
  WorkRecord,
  call,
  defineWorkflow,
  declaredCallee,
  policyFor,
  validateConfig,
  withDiagram,
} from "@amykit/core";
import { PROJECT_PHASES, Profile, ProjectIdentity } from "./profiles.js";

/**
 * A project is one workflow, and amy derives it from the project's folders.
 *
 * The folders are the diagram: `brief/`, `workflow/` and `prove/` name the
 * phases in the order they walk, each a call to the workflow its folder
 * exports. Nobody writes the project's diagram, binds the calls by hand or
 * lists the edges; this module derives the one workflow the project is —
 * BRIEF, WORK and PROVE as child records of the project's record inside one
 * profile, the way any call's are — and refuses a project whose folders and
 * its declaration disagree.
 *
 * What each phase returns folds onto the project's record under its own
 * name, and what BRIEF returned is what WORK and PROVE are handed when they
 * take an input: the criteria the brief settled are exactly what the proof
 * is asked to show. PROVE refusing goes back to the phase before it,
 * carrying what did not hold.
 */

/** The state a phase walks as a project record, keyed by its folder. */
const PHASE_STATE = { brief: "BRIEF", workflow: "WORK", prove: "PROVE" } as const;
type ProjectPhaseFolder = (typeof PROJECT_PHASES)[number];

/** The folder the world before this plan used for the third phase. */
const OLD_PROVE = "test";

/** Every folder a project root may carry where a phase would be, including the misnamed one. */
function phaseFolders(root: string): ReadonlySet<string> {
  return new Set([...PROJECT_PHASES, OLD_PROVE].filter((phase) => fs.existsSync(path.join(root, phase))));
}

/** The composed workflow's plugin name, the one its config slice is read by. */
export function composedPluginName(profile: Pick<Profile, "name">): string {
  return `workflow-${profile.name}`;
}

/** The loader specs of a project's present phases, walk order, the anchor included. */
export function projectSpecs(root: string): readonly string[] {
  return [...PROJECT_PHASES].filter((phase) => fs.existsSync(path.join(root, phase))).map((phase) => path.join(root, phase));
}

/** One phase as a view reports it: where the walk puts it, or the reason it is out. */
export interface PhaseView {
  readonly phase: string;
  readonly absent: boolean;
  readonly reason: string | null;
}

/** The phases of a project's mounted workflow, or the absences a workflow declares for itself. */
export function phasesOf(
  project: ProjectIdentity | undefined,
  workflow: { readonly states: readonly string[]; readonly phases?: ProjectPhases } | undefined,
): readonly PhaseView[] | undefined {
  if (!workflow) return undefined;
  const declared = workflow.phases ?? {};
  if (project) {
    return [...PROJECT_PHASES].map((phase) => ({
      phase: PHASE_STATE[phase].toLowerCase(),
      absent: !workflow.states.includes(PHASE_STATE[phase]),
      reason: declared[phase] ?? null,
    }));
  }
  // A workflow brought by a package has no project identity, yet it says in
  // its own declaration which phases of a project's walk it does not carry;
  // the status reads those absences where they are declared, not from the
  // composed state names.
  return Object.entries(declared)
    .filter((entry): entry is [typeof PROJECT_PHASES[number], string] => entry[1] !== undefined)
    .map(([phase, reason]) => ({ phase: phase.toLowerCase(), absent: true, reason }));
}

export interface ProjectPhase {
  readonly phase: ProjectPhaseFolder;
  /** The plugin the phase folder exports, called as this project's callee. */
  readonly plugin: WorkflowPlugin;
  /** The name the plugin answers to, for the slices its settings ride. */
  readonly name: string;
}

export interface ResolvedPhases {
  /** The phases that walk, in the order they walk: brief, then work, then prove. */
  readonly walking: readonly { readonly phase: ProjectPhaseFolder; readonly spec: string }[];
  /** The phases declared absent, and why: what `amy status` reads. */
  readonly absent: ProjectPhases;
  /** The refusals the folders and the declaration disagree on, or the walk's shape cannot hold. */
  readonly problems: readonly string[];
}

/**
 * Resolves a project's phases from its folders and the declaration it names.
 *
 * Every phase is either its folder on disk or a reason in the declaration;
 * a folder named `test/` is the spelling the world before this plan used,
 * and is refused, naming `prove/`.
 */
export function resolvePhases(root: string, declared: ProjectPhases | undefined): ResolvedPhases {
  const problems: string[] = [];
  const folders = phaseFolders(root);
  if (folders.has(OLD_PROVE)) {
    problems.push(
      `${path.join(root, OLD_PROVE)} is not a phase of a project amy walks: the proving phase is named \`prove/\` — rename the folder to \`prove/\``,
    );
  }

  const walking: { phase: ProjectPhaseFolder; spec: string }[] = [];
  const declaredAbsent: Record<string, string> = {};
  for (const phase of PROJECT_PHASES) {
    const spec = path.join(root, phase);
    if (folders.has(phase)) {
      if (declared?.[phase] !== undefined) {
        problems.push(
          `\`${phase}/\` is present at ${spec}, and the project's declaration says it is absent — one of the two is wrong`,
        );
      } else {
        walking.push({ phase, spec });
      }
      continue;
    }
    if (declared?.[phase] !== undefined) {
      declaredAbsent[phase] = declared[phase]!;
      continue;
    }
    problems.push(
      `the project at ${root} has no ${phase}/ phase, and its declaration says nothing about it — add ${spec}, or declare in the workflow's \`phases:\` why it is absent`,
    );
  }

  if (walking.length === 0) {
    problems.push(`the project at ${root} declares no phase to walk: it is brief without work and proof, and nothing moves`);
  }
  const proveAt = walking.findIndex((one) => one.phase === "prove");
  if (proveAt === 0) {
    problems.push(
      `the project at ${root} walks its proving phase first: PROVE refused goes back to the phase before it, and there is none — add ${path.join(root, "workflow")}, or declare in the workflow's \`phases:\` why work is absent`,
    );
  }
  return { walking, absent: declaredAbsent as ProjectPhases, problems };
}

/**
 * The composed workflow's calls, by phase state: what the phase's folding is.
 *
 * Every phase's return folds onto the project's record under its own name,
 * at every end it returns something at — an end the callee returns nothing
 * at folds nothing, because there is nothing to fold. WORK and PROVE are
 * handed what BRIEF returned when they take an input, exactly as the brief
 * settled them.
 */
function bindingsFor(phases: readonly ProjectPhase[], contexts: ReadonlyMap<ProjectPhase, PhaseContext>): Record<string, ReturnType<typeof call>> {
  const record = (key: string) => (work: WorkRecord, out: unknown) => ({
    ...work,
    [key]: key === "prove" ? { ...(out as Record<string, unknown>), invocation: work.calling } : out,
  });
  const bindings: Record<string, ReturnType<typeof call>> = {};
  for (const one of phases) {
    const callee = declaredCallee(one.plugin);
    const output: Record<string, (work: never, out: unknown) => Record<string, unknown>> = {};
    for (const end of callee.returns) output[end] = record(one.phase);
    const settings = contexts.get(one)?.config ?? {};
    bindings[PHASE_STATE[one.phase]] = call(one.plugin, {
      ...(one === phases[0] ? { discover: true } : {}),
      ...(Object.keys(output).length > 0 ? { output: output as never } : {}),
      ...(one.phase !== "brief" && callee.input !== undefined ? { input: ((work: { brief: unknown }) => work.brief) as never } : {}),
      ...(Object.keys(settings).length > 0 ? { config: settings } : {}),
    });
  }
  return bindings;
}

/** The slice the machine derives for one callee, when it derived any. */
function sliceFor(slices: Readonly<Record<string, unknown>>, name: string): Record<string, unknown> {
  const slice = slices[name];
  return typeof slice === "object" && slice !== null && !Array.isArray(slice) ? { ...(slice as Record<string, unknown>) } : {};
}

/** The operator's own settings, kept to the ones the callee's schema declares. */
function settingsFor(schema: ConfigSchema, settings: Readonly<Record<string, unknown>>): Record<string, unknown> {
  const kept: Record<string, unknown> = {};
  for (const key of Object.keys(schema)) copySetting(key.split("."), settings, kept);
  return kept;
}

/** Copies one schema-declared setting path without carrying a sibling dotted leaf. */
function copySetting(path: readonly string[], source: Readonly<Record<string, unknown>>, target: Record<string, unknown>): void {
  const [head, ...tail] = path;
  if (head === undefined || !Object.hasOwn(source, head)) return;
  if (tail.length === 0) {
    target[head] = source[head];
    return;
  }
  const value = source[head];
  if (typeof value !== "object" || value === null || Array.isArray(value)) return;
  const nested = target[head] as Record<string, unknown> | undefined;
  const next = nested ?? {};
  target[head] = next;
  copySetting(tail, value as Record<string, unknown>, next);
}

interface PhaseContext {
  readonly config: Record<string, unknown>;
  readonly policy: object;
}

/** Validates the exact settings and policy the call will hand one phase. */
function phaseContexts(
  args: { readonly profile: Pick<Profile, "name" | "settings">; readonly slices: Readonly<Record<string, unknown>>; readonly phases: readonly ProjectPhase[] },
): { readonly contexts: ReadonlyMap<ProjectPhase, PhaseContext>; readonly problems: readonly string[] } {
  // The assembled slice has already put explicit plugin settings ahead of the
  // profile's defaults. Direct composition tests supply no slice, so retain
  // the profile's settings as the same lower-precedence source.
  const effective = { ...args.profile.settings, ...sliceFor(args.slices, composedPluginName(args.profile)) };
  const contexts = new Map<ProjectPhase, PhaseContext>();
  const problems: string[] = [];
  for (const phase of args.phases) {
    const callee = declaredCallee(phase.plugin);
    const checked = validateConfig(phase.name, callee.configSchema, settingsFor(callee.configSchema, effective));
    if (!checked.ok) {
      problems.push(...checked.problems);
      continue;
    }
    contexts.set(phase, { config: checked.config, policy: policyFor(phase.name, callee.policy, checked.config.policy) });
  }
  return { contexts, problems };
}

/** The states a project walks, the initial one first, and where each phase goes. */
function projectDiagram(
  phases: readonly ProjectPhase[],
): string {
  const state = (one: ProjectPhase) => PHASE_STATE[one.phase];
  const after = (at: number): string => (at + 1 < phases.length ? state(phases[at + 1]!) : "DONE");
  const before = (at: number): string => (at > 0 ? state(phases[at - 1]!) : "DONE");
  const lines: string[] = ["stateDiagram-v2", `  [*] --> ${state(phases[0]!)}`];
  phases.forEach((one, at) => {
    // Every end the callee can arrive at draws its edge, the folds or not:
    // an end the callee returns nothing at folds nothing, but the walk still
    // goes somewhere from it, and an edge named for no end is a refusal.
    const ends = one.plugin.workflow.terminalStates?.length
      ? one.plugin.workflow.terminalStates
      : declaredCallee(one.plugin).returns;
    for (const end of ends) {
      const to = one.phase === "prove" && end !== "refused" && phases.some((phase) => phase.phase === "brief")
        ? "PROOF_COMPLETE"
        : one.phase === "prove" && end === "refused" ? before(at) : after(at);
      lines.push(`  ${state(one)} --> ${to}: ${end}`);
    }
  });
  if (phases.some((one) => one.phase === "brief") && phases.some((one) => one.phase === "prove")) {
    lines.push("  PROOF_COMPLETE --> DONE: every criterion is answered");
    lines.push(`  PROOF_COMPLETE --> ${state(phases.find((one) => one.phase === "workflow") ?? phases[0]!)}: a criterion is unanswered`);
  }
  // The terminal line is written last, so the states the file names read in
  // walk order: the diagram's own list is the order the lines were read.
  lines.push(`  DONE --> [*]`);
  lines.push(...phases.map((one) => `  class ${state(one)} call`));
  return `${lines.join("\n")}\n`;
}

/** The schemas the project's phases declare, merged, or why they disagree. */
function mergeSchemas(phases: readonly ProjectPhase[]): { readonly schema: ConfigSchema; readonly problems: readonly string[] } {
  const merged: Record<string, ConfigField> = {};
  const problems: string[] = [];
  for (const one of phases) {
    for (const [key, entry] of Object.entries(one.plugin.configSchema ?? {})) {
      const held = merged[key];
      if (held && !agree(held, entry)) {
        problems.push(
          `\`${key}\` means two things in one project: \`${one.name}\` declares ${describe(entry)} and another phase declares ${describe(held)} — the phases of a project share the machine's one config, so their schemas must agree`,
        );
        continue;
      }
      merged[key] = entry;
    }
  }
  return { schema: merged as ConfigSchema, problems };
}

/** Whether two schema entries describe the same setting: type, default and required agree. */
function agree(one: ConfigField, other: ConfigField): boolean {
  return JSON.stringify({ type: one.type, default: one.default, required: one.required })
    === JSON.stringify({ type: other.type, default: other.default, required: other.required });
}

function describe(entry: ConfigField): string {
  return `${entry.type} defaulting to ${JSON.stringify(entry.default)}`;
}

/**
 * The project's composed plugin: one workflow derived from the phases.
 *
 * The walk's own states decide nothing — BRIEF, WORK and PROVE are calls the
 * callees decide, and DONE ends the walk, which no record ever re-asks. The
 * claims are the phases' own: the walk cannot write more than its phases do.
 */
export function composeProject(args: {
  readonly profile: Pick<Profile, "name" | "settings">;
  /** The machine's slices for this profile, computed against the composed name. */
  readonly slices: Readonly<Record<string, unknown>>;
  readonly phases: readonly ProjectPhase[];
  /** The phases declared absent, why — carried on the workflow itself. */
  readonly absent: ProjectPhases;
  /** The project root, for the refusals a phase's own shape names. */
  readonly root: string;
}): { readonly plugin: Plugin; readonly problems: readonly string[] } {
  const { schema, problems: schemaProblems } = mergeSchemas(args.phases);
  const { contexts, problems: contextProblems } = phaseContexts(args);
  return {
    ...{ plugin: build(args, schema, contexts), problems: [...schemaProblems, ...contextProblems] },
  };
}

function build(args: { readonly profile: Pick<Profile, "name" | "settings">; readonly slices: Readonly<Record<string, unknown>>; readonly phases: readonly ProjectPhase[]; readonly absent: ProjectPhases; readonly root: string }, schema: ConfigSchema, contexts: ReadonlyMap<ProjectPhase, PhaseContext>): Plugin {
  const claims = (key: "trackerWrites" | "codeHostWrites") => {
    // The claims are the phases' own: the walk cannot write more than its
    // phases do, and each phase's claim is read the way its own mount would
    // read it — a claim written as a function of its configuration is asked
    // with the settings this walk hands the phase, because that is the
    // configuration the mounted phase will actually run under.
    const claimed = new Set<string>();
    for (const one of args.phases) {
      const declared = declaredCallee(one.plugin)[key];
      const context = contexts.get(one) ?? { config: {}, policy: {} };
      const effective = typeof declared === "function" ? declared({ config: context.config as never, policy: context.policy }) : declared ?? [];
      for (const capability of effective) claimed.add(capability);
    }
    return [...claimed];
  };
  const composed = defineWorkflow({
    // A configured profile names the generated root's plugin and slice, but
    // a phase may legitimately use that same workflow declaration name.
    // Give the caller its own identity so core does not read that shape as a
    // recursive call.
    name: `project-${args.profile.name}`,
    pluginName: composedPluginName(args.profile),
    configSchema: schema,
    policy: {},
    needs: {},
    ...(Object.keys(args.absent).length > 0 ? { phases: args.absent } : {}),
    trackerWrites: claims("trackerWrites"),
    codeHostWrites: claims("codeHostWrites"),
    record: () => ({}),
    discover: async () => [],
    observe: async () => ({}),
    actions: {},
    remember: (_scope, record) => record,
    decide: {
      ...(args.phases.some((one) => one.phase === "brief") && args.phases.some((one) => one.phase === "prove") ? {
        PROOF_COMPLETE: (record) => proofAnswered(record)
          ? { kind: "advance" as const, to: "DONE", effects: [], why: "the proof answered every criterion the brief settled" }
          : { kind: "advance" as const, to: PHASE_STATE[args.phases.find((one) => one.phase === "workflow")?.phase ?? args.phases[0]!.phase], effects: [], why: "the proof left a briefed criterion unanswered" },
      } : {}),
      DONE: () => ({ kind: "settled", why: "the project's walk is over" }),
    },
    calls: bindingsFor(args.phases, contexts) as never,
  });
  return withDiagram(composed, projectDiagram(args.phases), "the project's own folders");
}

/** Whether every criterion a brief named appears in the proof's returned answer. */
function proofAnswered(record: WorkRecord & { readonly brief?: unknown; readonly prove?: unknown }): boolean {
  const criteria = criteriaOf(record.brief);
  if (criteria.length === 0) return true;
  const latest = Object.keys(record.calls ?? {}).filter((id) => id.includes("/PROVE#")).at(-1);
  const result = record.prove as { readonly invocation?: unknown } | undefined;
  if (result?.invocation !== latest) return false;
  const answered = new Set(criteriaOf(result));
  return criteria.every((criterion) => answered.has(criterion));
}

function criteriaOf(value: unknown): readonly string[] {
  if (typeof value !== "object" || value === null) return [];
  const criteria = (value as { readonly criteria?: unknown }).criteria;
  return Array.isArray(criteria) && criteria.every((criterion): criterion is string => typeof criterion === "string") ? criteria : [];
}

import fs from "node:fs";
import path from "node:path";
import { privatePackages } from "./fork.js";

/**
 * A shadcn registry item for one published package (S16): its source at its
 * version, so `npx shadcn add <url>` is a second client for the source
 * `amy add --fork` takes. shadcn only copies; amy is what records a base and
 * merges an update (S8).
 */
export interface RegistryItem {
  readonly $schema: string;
  readonly name: string;
  readonly type: "registry:lib";
  readonly title: string;
  readonly description: string;
  readonly dependencies: string[];
  readonly devDependencies: string[];
  readonly files: { path: string; type: "registry:file"; target: string; content: string }[];
  readonly meta: { package: string; version: string; repository: string; directory: string; tag: string };
}

const SCHEMA = "https://ui.shadcn.com/schema/registry-item.json";

/** Whether a tracked file is part of what a fork of the package takes: not its tests, not its changelog. */
function isSource(relative: string): boolean {
  const parts = relative.split("/");
  return !parts.some((part) => part === "tests" || part === "test" || part === "node_modules" || part === "dist")
    && parts.at(-1) !== "CHANGELOG.md"
    && !relative.endsWith(".tsbuildinfo");
}

interface PackageManifest {
  name?: string;
  version?: string;
  description?: string;
  private?: boolean;
  repository?: { url?: string; directory?: string } | string;
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
}

/**
 * The item for the package in `directory`, built from the files given
 * relative to the repository root. The target is the place `amy add --fork`
 * puts a fork for a workflow of your own, so both clients agree on where.
 */
export function registryItem(repository: string, directory: string, files: readonly string[], unpublished: ReadonlySet<string> = privatePackages(repository)): RegistryItem {
  const manifest = JSON.parse(fs.readFileSync(path.join(repository, directory, "package.json"), "utf-8")) as PackageManifest;
  const name = manifest.name ?? directory;
  const unscoped = name.split("/").at(-1)!;
  const url = typeof manifest.repository === "string" ? manifest.repository : manifest.repository?.url ?? "";
  const repositoryDirectory = typeof manifest.repository === "object" ? manifest.repository.directory ?? directory : directory;
  const within = files
    .filter((file) => file.startsWith(`${directory}/`) && isSource(file.slice(directory.length + 1)))
    .sort();
  return {
    $schema: SCHEMA,
    name: unscoped,
    type: "registry:lib",
    title: name,
    description: manifest.description ?? "",
    // A workspace's private packages were never published, so no client
    // outside it could install them.
    dependencies: installable(manifest.dependencies, unpublished),
    devDependencies: installable(manifest.devDependencies, unpublished),
    files: within.map((file) => ({
      path: file,
      type: "registry:file" as const,
      target: `forks/${unscoped}/${file.slice(directory.length + 1)}`,
      content: fs.readFileSync(path.join(repository, file), "utf-8"),
    })),
    meta: { package: name, version: manifest.version ?? "", repository: url, directory: repositoryDirectory, tag: `${name}@${manifest.version ?? ""}` },
  };
}

function installable(dependencies: Record<string, string> | undefined, unpublished: ReadonlySet<string>): string[] {
  return Object.entries(dependencies ?? {}).filter(([name]) => !unpublished.has(name)).map(([name, range]) => `${name}@${range}`);
}

/** The packages a registry item is generated for: every workspace package that is published. */
export function publicPackages(repository: string): string[] {
  const found: string[] = [];
  for (const group of ["packages", "plugins"]) {
    const parent = path.join(repository, group);
    if (!fs.existsSync(parent)) continue;
    for (const entry of fs.readdirSync(parent).sort()) {
      const manifest = path.join(parent, entry, "package.json");
      if (!fs.existsSync(manifest)) continue;
      const parsed = JSON.parse(fs.readFileSync(manifest, "utf-8")) as PackageManifest;
      if (!parsed.private) found.push(`${group}/${entry}`);
    }
  }
  return found;
}

/** Where a package's item is kept: `registry/<unscoped name>.json`. */
export function itemFile(repository: string, item: Pick<RegistryItem, "name">): string {
  return path.join(repository, "registry", `${item.name}.json`);
}

export function serialize(item: RegistryItem): string {
  return `${JSON.stringify(item, null, 2)}\n`;
}

/**
 * Every item that is missing or no longer matches its package, by the file
 * that is stale; and every file under `registry/` no package generates.
 */
export function staleItems(repository: string, files: readonly string[]): string[] {
  const stale: string[] = [];
  const expected = new Set<string>();
  for (const directory of publicPackages(repository)) {
    const item = registryItem(repository, directory, files);
    const file = itemFile(repository, item);
    expected.add(file);
    const written = fs.existsSync(file) ? fs.readFileSync(file, "utf-8") : undefined;
    if (written !== serialize(item)) stale.push(`${path.relative(repository, file)} (${item.title}@${item.meta.version})`);
  }
  const registry = path.join(repository, "registry");
  for (const entry of fs.existsSync(registry) ? fs.readdirSync(registry) : []) {
    const file = path.join(registry, entry);
    if (entry.endsWith(".json") && !expected.has(file)) stale.push(`${path.relative(repository, file)} (no package generates it)`);
  }
  return stale;
}

import fs from "node:fs";
import path from "node:path";
import { AmyConfig, loadConfig, removeProfile } from "./config.js";
import { Profile, profiles } from "./profiles.js";
import { profileOwnedDirectories } from "./paths.js";
import { pluginList, pluginSlices } from "./slices.js";
import { stillMounted } from "./remove.js";

/** What removing a profile needs from the process that asked. */
export interface RemovalDeps {
  /** The loop driving this profile, when one is. */
  running(profile: Profile): { workflow: string; pid: number } | undefined;
  /** Whether a scheduled update still owns this profile. */
  pendingUpdate(profile: Profile): boolean;
  /** Uninstalls a package the config no longer names. */
  uninstall(spec: string): Promise<void>;
  /** Asks before deleting state, and answers for a terminal nobody is at. */
  confirm(directories: readonly string[]): boolean;
  say(line: string): void;
}

/**
 * Forgets one profile: its config block, its package, and — only when asked —
 * the records and queue it kept.
 *
 * A profile and the package it names are one thing to the operator: `amy
 * remove ticket-to-qa` is the reverse of the `amy add` that wrote the block,
 * and asking two commands to undo one is how state gets left behind.
 *
 * The log is never on the list. It is append-only because the budget is
 * measured off it, so deleting what a workflow spent would move a ceiling
 * rather than tidy a directory.
 */
export async function removeProfileAndState(
  home: string,
  config: AmyConfig,
  profile: Profile,
  options: { keepState?: boolean; yes?: boolean },
  deps: RemovalDeps,
): Promise<"deleted" | "kept"> {
  const live = deps.running(profile);
  if (live) throw new Error(`${live.workflow} is running as pid ${live.pid}. Run \`amy stop\` first.`);
  if (deps.pendingUpdate(profile)) {
    throw new Error(`${profile.name} has a scheduled daemon update. Let it settle before removing it.`);
  }

  // The directories the machine actually reads, not the ones it would have
  // read by default: an override of the store or the queue moves the state,
  // and a removal that deleted the default would leave the real one behind.
  const going = ownedDirectories(home, profile, config).filter((directory) => fs.existsSync(directory));
  const deleting = options.keepState !== true && (options.yes === true || going.length === 0 || deps.confirm(going));

  for (const directory of going) {
    const held = fs.readdirSync(directory).length;
    deps.say(`${deleting ? "deleting" : "keeping"} ${path.relative(home, directory)} (${held} file(s))`);
  }

  removeProfile(home, profile.name, config);
  deps.say(`removed the \`${profile.name}\` profile for ${profile.workflow}`);
  if (!stillMounted(loadConfig(home), profile.workflow)) await deps.uninstall(profile.workflow);

  if (deleting) {
    for (const directory of going) fs.rmSync(directory, { recursive: true, force: true });
  } else {
    deps.say(`kept the state under ${profile.name}/: add --yes to delete it, or leave it for \`amy add\` to pick up`);
  }
  deps.say(`The log keeps what ${profile.name} did: nothing here touches it.`);
  return deleting ? "deleted" : "kept";
}


/**
 * Every directory this profile's state lives in, and nothing another profile
 * also lives in.
 *
 * An override can be written once and applied to every profile — a shared
 * records directory is a supported arrangement — so a directory is only this
 * profile's to delete when no remaining profile names it too. Deleting one
 * would take the other's work with it, silently, under `--yes`.
 */
function ownedDirectories(home: string, profile: Profile, config: AmyConfig): string[] {
  const mine = new Set(directoriesOf(home, profile, config, "mounted"));
  const theirs = Object.values(profiles(config, home))
    .filter((other) => other.name !== profile.name)
    .flatMap((other) => directoriesOf(home, other, config, "named"));

  // Not one another profile names, and not one holding one: deleting a parent takes what is inside it.
  return [...mine].filter((directory) => !theirs.some((other) => other === directory || other.startsWith(`${directory}${path.sep}`)));
}

/**
 * The declared directories plus the ones this profile's slices actually use.
 * A conversation adapter's directory is a deletion candidate only for a
 * profile that mounts it ("mounted"); as something to protect, a directory
 * any slice names counts ("named").
 */
function directoriesOf(home: string, profile: Profile, config: AmyConfig, counting: "mounted" | "named"): string[] {
  const slices = pluginSlices(config, profile, home);
  const mounted = pluginList(config, profile);
  const adapters = ["@amykit/plugin-slack", "@amykit/plugin-telegram"].filter((owner) => counting === "named" || mounted.includes(owner));
  const effective = ["@amykit/plugin-file-store", "@amykit/plugin-file-queue", ...adapters].flatMap((owner) => {
    const slice = slices[owner];
    if (typeof slice !== "object" || slice === null) return [];
    const directory = (slice as { directory?: unknown }).directory;
    return typeof directory === "string" ? [path.join(home, directory)] : [];
  });

  return [...new Set([...profileOwnedDirectories(home, profile), ...effective])];
}

import { CommandRunner } from "@amykit/core";
import { AmyConfig } from "./config.js";
import { installProfileRoot, profileForkDirectories } from "./fork.js";
import { paths } from "./paths.js";
import { withoutSpec } from "./add.js";
import { Profile, profiles } from "./profiles.js";
import { pluginList } from "./slices.js";

export type Carrier = { place: "profile" | "extras" | "workflow"; profile?: string };

/** Which config entry a removal edits; machine-wide extras take precedence. */
export function carriedBy(config: AmyConfig, profile: Profile, spec: string, home?: string): Carrier {
  if (config.extraPlugins.includes(spec)) return { place: "extras" };
  const owning = Object.entries(config.workflows).find(([, entry]) => entry.workflow === spec);
  if (owning) return { place: "workflow", profile: owning[0] };
  const candidates = profiles(config, home);
  const resolvedWorkflow = Object.values(candidates).find((candidate) => candidate.workflow === spec);
  if (resolvedWorkflow) return { place: "workflow", profile: resolvedWorkflow.name };
  if (pluginList(config, profile).includes(spec)) return { place: "profile", profile: profile.name };
  const elsewhere = Object.values(candidates).find((candidate) => pluginList(config, candidate).includes(spec));
  if (elsewhere) return { place: "profile", profile: elsewhere.name };
  return { place: "extras" };
}

/** The exact config `remove` would write, held in memory for its boot trial. */
export function configWithout(config: AmyConfig, profile: Profile, spec: string, carrier: Carrier, home?: string): AmyConfig {
  if (carrier.place === "extras") {
    return { ...config, extraPlugins: withoutSpec(config.extraPlugins, spec) };
  }
  if (carrier.place === "workflow" && carrier.profile) {
    return {
      ...config,
      workflows: Object.fromEntries(Object.entries(config.workflows).filter(([name]) => name !== carrier.profile)),
    };
  }

  const name = carrier.profile ?? profile.name;
  const entry = config.workflows[name];
  if (!entry) return config;
  // Freeze only the selected profile's own/recommended set. Extras remain
  // machine-wide and must not be copied into this profile by a local removal.
  const target = profiles(config, home)[name] ?? profile;
  const own = target.plugins.length > 0
    ? target.plugins
    : pluginList(config, target).filter((name) => !config.extraPlugins.includes(name));
  const suppressBriefCompatibility =
    (spec === "@amykit/plugin-file-brief-store" && !target.briefStore) || target.briefStore === spec;
  return {
    ...config,
    workflows: {
      ...config.workflows,
      [name]: {
        ...entry,
        plugins: withoutSpec(own, spec),
        ...(suppressBriefCompatibility ? { briefStore: "" } : {}),
      },
    },
  };
}

/** Whether any remaining profile still mounts this package, even by recommendation. */
export function stillMounted(config: AmyConfig, spec: string): boolean {
  return Object.values(profiles(config)).some((candidate) => pluginList(config, candidate).includes(spec));
}

/**
 * Drops a fork from a profile's root, so the name resolves to the machine's
 * published copy again. The fork's directory is the person's source, and is
 * never deleted here (A16).
 */
export async function dropFork(
  runner: CommandRunner,
  home: string,
  profile: string,
  name: string,
  specs: readonly string[],
): Promise<{ ok: true; directory: string } | { ok: false; problem: string }> {
  const forks = profileForkDirectories(home, profile);
  const directory = forks.get(name);
  if (!directory) return { ok: false, problem: `the profile \`${profile}\` does not fork ${name}` };
  forks.delete(name);
  const installed = await installProfileRoot(runner, home, paths(home).plugins, profile, forks, specs);
  return installed.ok ? { ok: true, directory } : { ok: false, problem: `${installed.command} failed:\n${installed.output || "it said nothing"}` };
}

import fs from "node:fs";
import path from "node:path";

/**
 * Which harnesses amy's skills were written into, recorded when `amy skills`
 * runs because it is a fact about this machine.
 *
 * The update that rewrites the skills needs this record rather than a guess
 * from what is installed now: `~/.claude` being present today does not mean
 * the skills were ever written into it, and writing them into a harness
 * somebody never chose is a decision nobody made. The file lives under
 * `~/.amy` beside the rest of this machine's state, so a second machine-wide
 * install (`AMY_HOME`) keeps its own.
 */
const RECORD = "skills-written.json";

export interface SkillsRecord {
  /** The harnesses the skills were written into, by name, most recent last. */
  harnesses: string[];
  /** A directory `--dir` named, which no harness table knows. */
  directories: string[];
}

function recordPath(home: string): string {
  return path.join(home, RECORD);
}

export function readSkills(home: string): SkillsRecord {
  try {
    const parsed = JSON.parse(fs.readFileSync(recordPath(home), "utf-8")) as Partial<SkillsRecord>;
    return {
      harnesses: Array.isArray(parsed.harnesses) ? parsed.harnesses : [],
      directories: Array.isArray(parsed.directories) ? parsed.directories : [],
    };
  } catch {
    return { harnesses: [], directories: [] };
  }
}

/** Adds one write to the record, keeping the order stable and unique. */
export function recordWrite(home: string, write: { harness?: string; directory?: string }): void {
  const current = readSkills(home);
  const harnesses = write.harness && !current.harnesses.includes(write.harness)
    ? [...current.harnesses, write.harness]
    : current.harnesses;
  const directories = write.directory && !current.directories.includes(write.directory)
    ? [...current.directories, write.directory]
    : current.directories;

  fs.mkdirSync(home, { recursive: true });
  fs.writeFileSync(recordPath(home), `${JSON.stringify({ harnesses, directories }, null, 2)}\n`, "utf-8");
}

/**
 * Writes the skills into every harness and directory the record names.
 *
 * Used by `amy skills` itself and by `amy update` when the CLI moved: the
 * record is the fact, the write is the same one `amy skills` performed, and a
 * directory the record names but that no longer exists is skipped with a
 * line rather than recreated — a directory an operator deleted was deleted on
 * purpose.
 */
export function writeSkills(
  home: string,
  install: (into: string, skills: readonly [string, string][]) => string[],
  shipped: () => readonly [string, string][],
  harnessSkills: (name: string) => string | undefined,
): string[] {
  const record = readSkills(home);
  const skills = shipped();
  const targets: { label: string; into: string }[] = [];

  for (const harness of record.harnesses) {
    const into = harnessSkills(harness);
    if (!into) {
      console.log(`${harness}: no longer a harness this amy knows, skipped`);
      continue;
    }
    targets.push({ label: harness, into });
  }
  for (const directory of record.directories) {
    if (!fs.existsSync(directory)) {
      console.log(`${directory}: gone, skipped`);
      continue;
    }
    targets.push({ label: directory, into: directory });
  }

  // The CLI is rolled back when this rewrite fails. Preserve every managed
  // file first, so a failure on a later target cannot leave earlier harnesses
  // describing the CLI version that did not survive.
  const before = targets.flatMap(({ into }) => skills.map(([name]) => {
    const directory = path.join(into, name);
    const file = path.join(directory, "SKILL.md");
    return { directory, file, directoryExisted: fs.existsSync(directory), body: fs.existsSync(file) ? fs.readFileSync(file, "utf-8") : undefined };
  }));
  const wrote: string[] = [];
  try {
    for (const target of targets) {
      wrote.push(...install(target.into, skills));
      console.log(`${target.label}: ${skills.length} skill(s) rewritten`);
    }
    return wrote;
  } catch (error) {
    for (const saved of before.reverse()) {
      if (saved.body !== undefined) {
        fs.mkdirSync(saved.directory, { recursive: true });
        fs.writeFileSync(saved.file, saved.body, "utf-8");
      } else {
        fs.rmSync(saved.file, { force: true });
        if (!saved.directoryExisted) fs.rmSync(saved.directory, { recursive: true, force: true });
      }
    }
    throw error;
  }
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

/**
 * The skills that travel with this version of amy.
 *
 * Read off disk beside the code rather than listed here, so adding one is a
 * directory and not an edit in two places. They are inside the package for
 * the same reason `sf` compiles its own in: a skill that tells you to run a
 * subcommand your install predates is worse than no skill.
 */
export function shipped(from: URL = new URL("../skills/", import.meta.url)): [string, string][] {
  const directory = fileURLToPath(from);
  if (!fs.existsSync(directory)) return [];

  return fs
    .readdirSync(directory)
    .map((name) => [name, path.join(directory, name, "SKILL.md")] as const)
    .filter(([, file]) => fs.existsSync(file))
    .map(([name, file]) => [name, fs.readFileSync(file, "utf-8")]);
}

import path from "node:path";
import { AmyConfig } from "./config.js";
import { Profile, directoriesFor, projectStateKey, recommendedFor } from "./profiles.js";
import { profilePaths } from "./paths.js";

/**
 * The settings each plugin gets, derived from the top-level config.
 *
 * A compatibility shim, and named as one. The config file still carries the
 * machine's own settings at the top level, so this translates those — the
 * repositories, the branches, the agent block, the engine's ceilings. A
 * workflow's own vocabulary is not translated anywhere: it lives in the
 * profile that drives it, and the mount checks it against the workflow's own
 * schema. An explicit `plugins:` slice always wins, which is the direction
 * this is moving in.
 */
export function pluginSlices(
  config: AmyConfig,
  profile: Profile,
  stateDir?: string,
  pluginNames?: ReadonlyMap<string, string>,
  composed?: { readonly name: string; readonly callees: readonly string[] },
): Record<string, unknown> {
  assertPhaseStateDirectoriesAreNotShared(config, profile);
  const dirs = stateDirectories(stateDir, profile);
  const own = pluginStateDirectories(stateDir, profile);
  const agent = effectiveAgent(config, profile);

  const derived = derivedSlices(config, profile, dirs, own, agent, stateDir);
  Object.assign(derived, slackSlice(own.slack), telegramSlice(own.telegram));
  addNotifySlices(config, derived);
  // The profile's own settings come first, and a slice written by hand wins
  // over them: that is the order the config always read in. The settings are
  // the workflow's vocabulary, checked against its configSchema at mount.
  applyOwnProfileSettings(profile, pluginNames ?? new Map(), derived);
  mergeInGivenSlices(derived, config.plugins);
  composedSlice(derived, composed);

  // The command that writes a file and the adapter that read it must agree,
  // including when somebody overrode the adapter's directory by hand. The
  // workflow's destination follows the effective adapter, not the default it
  // was derived from before the merge; the queue follows the queue adapter
  // the same way, because a note queued where the engine does not read is a
  // note the machine never sees.
  followAdapter(derived, "@amykit/workflow-errand", "tasksDirectory", "@amykit/plugin-file-tasks");
  followAdapter(derived, "@amykit/workflow-note-to-plan", "notesDirectory", "@amykit/plugin-file-notes");
  followAdapter(derived, "@amykit/workflow-errand", "queueDirectory", "@amykit/plugin-file-queue");
  followAdapter(derived, "@amykit/workflow-note-to-plan", "queueDirectory", "@amykit/plugin-file-queue");

  // The worktree adapter reads records directly to classify trees. Its path
  // is an invariant of the mounted file store, not an independent preference:
  // an explicit store directory must move both readers together.
  const recordsDirectory = effectiveRecordsDirectory(derived["@amykit/plugin-file-store"], stateDir, dirs.records);
  derived["@amykit/plugin-file-worktree"] = withWorktreeRecordsDirectory(
    derived["@amykit/plugin-file-worktree"],
    recordsDirectory,
  );

  return derived;
}

/**
 * The workspace's vocabulary, read from the plugin whose slice carries it.
 *
 * The machine keeps none of the seven keys: the repositories, the checkout
 * root and map, the two branch settings and the worktree answers live in
 * `@amykit/plugin-file-worktree`'s slice, and the gate commands in the
 * command-gate plugin's. The host hands a plugin one of these only by
 * reading that slice — never a machine level, which no longer has one.
 */
function workspaceSettings(config: AmyConfig): {
  readonly repos: readonly string[];
  readonly defaultBranch: string;
  readonly baseBranch: Readonly<Record<string, string>>;
} {
  const slice = config.plugins["@amykit/plugin-file-worktree"];
  const repos = isRecord(slice) && Array.isArray(slice.repos)
    ? slice.repos.filter((one): one is string => typeof one === "string")
    : [];
  const baseBranch = isRecord(slice) && isRecord(slice.baseBranch)
    ? (Object.fromEntries(Object.entries(slice.baseBranch).filter(([, branch]) => typeof branch === "string")) as Readonly<Record<string, string>>)
    : {};
  const defaultBranch = isRecord(slice) && typeof slice.defaultBranch === "string" && slice.defaultBranch !== ""
    ? slice.defaultBranch
    : "main";
  return { repos, defaultBranch, baseBranch };
}

/** Whether a state directory was given in, or the machine's own. */
/**
 * The slices every install derives from the machine's shape, before a hand
 * writes a slice of its own.
 */
function derivedSlices(
  config: AmyConfig,
  profile: Profile,
  dirs: ReturnType<typeof stateDirectories>,
  own: ReturnType<typeof pluginStateDirectories>,
  agent: { ladder?: unknown; ladderByStep?: unknown; budget?: unknown },
  stateDir?: string,
): Record<string, unknown> {
  const workspace = workspaceSettings(config);
  return {
    "@amykit/plugin-linear": {
      defaultRepo: workspace.repos[0] ?? "",
    },
    "@amykit/plugin-claude": harnessSlice(config, profile, "claude"),
    "@amykit/plugin-codex": harnessSlice(config, profile, "codex"),
    "@amykit/plugin-hermes-agent": harnessSlice(config, profile, "hermes"),
    "@amykit/plugin-agent-relay": {
      ladder: agent.ladder ?? [],
      ladderByStep: agent.ladderByStep ?? {},
      budget: agent.budget ?? {},
      skills: config.skills,
    },
    "@amykit/plugin-command-gate": {
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
    },
    "@amykit/plugin-file-queue": {
      directory: dirs.queue,
      retentionDays: config.retentionDays,
      staleClaimMs: config.staleClaimMs,
    },
    "@amykit/plugin-file-store": { directory: dirs.records },
    "@amykit/plugin-file-brief-store": briefStoreSlice(config, profile),
    // One workflow writes the notes and another reads them, and an install
    // running only the first would still be filing the friction the second
    // is there to pick up. Where those notes go is wherever the plan
    // workflow's own profile says work happens.
    "@amykit/plugin-file-notes": notesSlice(config),
    // The second workflow's own vocabulary — which repositories it may write
    // a plan into — is the profile's, not the machine's top level's.
    "@amykit/workflow-note-to-plan": {
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
    },
    // The third workflow's vocabulary: where an errand may be done, and the
    // ceilings its decision function reads.
    "@amykit/workflow-errand": {
      repos: workspace.repos,
      // Where `amy btw` writes: the directory the file-tasks adapter reads.
      tasksDirectory: own.tasks,
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
    },
    "@amykit/workflow-feature-grooming": {
      repos: workspace.repos,
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
    },
    // Phase-local, like the queue the tasks are put on: two phases of one
    // project mounting it must not drain each other's errands.
    "@amykit/plugin-file-tasks": {
      directory: own.tasks,
      repo: workspace.repos[0] ?? "",
    },
    "@amykit/plugin-plan-check": {
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
      ...(commandsFromCheck(profile) === undefined ? {} : { commands: commandsFromCheck(profile) }),
    },
    // The workflow's own vocabulary: which repositories it counts review
    // load across, and who a review is answered for. The ceilings its
    // decisions read and the status a ticket moves to are the profile's.
    "@amykit/workflow-ticket-to-qa": {
      repos: workspace.repos,
      ...ticketBudgetSlice(config, profile),
      // Both halves of the layout, named the way the workflow's own schema
      // does: the branch a repository without a mapping is cut from, and the
      // map that names one. Derived here so no workflow package carries a
      // branch mapping of its own.
      defaultBranch: workspace.defaultBranch,
      baseBranch: workspace.baseBranch,
      // Written under `agent:` in config.yaml, because it is how a reviewer
      // is answered, and read by the workflow whose review prompt it is.
      reviewerHints: reviewerHintsFor(config, profile),
    },
    // The workplace: where the trees live and how long finished ones stay,
    // read from the plugin's own slice — the workspace is its, and the
    // derived half adds only the paths this host owns. `workflow` names the
    // mount itself, because the tree paths carry it — the profile's name is
    // what the config calls this workflow, and two profiles must never share
    // a tree.
    "@amykit/plugin-file-worktree": {
      ...workspaceSlice(config),
      workflow: worktreeNamespace(profile),
      recordsDirectory: worktreeRecordsDirectory(stateDir, dirs.records),
    },
    // The engine's, and none of it names a domain. The concurrent engine is
    // the serial one with its lanes moved at once, and takes the same.
    "@amykit/plugin-serial-engine": engineSlice(config),
    "@amykit/plugin-concurrent-engine": engineSlice(config),
  };
}

/** A machine that asks for answers gets the adapters that deliver them. */
function addNotifySlices(config: AmyConfig, derived: Record<string, unknown>): void {
  if (config.notify.hermes) derived["@amykit/plugin-notify-hermes"] = { target: config.notify.hermes };
  if (config.notify.inbox) derived["@amykit/plugin-notify-inbox"] = { directory: "needs-input" };
}

// Merged per plugin, not replaced. A slice written by hand names the one
// or two settings somebody meant to change; replacing the whole slice would
// drop the derived ones beside them — which is how two profiles ended up
// sharing a queue, because the operator had set `retentionDays` and lost
// `directory` without being told.
function mergeInGivenSlices(derived: Record<string, unknown>, given: Record<string, unknown>): void {
  for (const [name, slice] of Object.entries(given)) {
    derived[name] = isRecord(derived[name]) && isRecord(slice) ? { ...derived[name], ...slice } : slice;
  }
}

// The profile's own settings are the workflow's vocabulary, checked against
// the workflow's own schema at mount: they beat what was derived, and an
// unknown key there is a boot refusal naming it. A workflow brought by spec
// can be named by its plugin differently — a local declaration without a
// plugin name answers to `workflow-oncall` — so the settings land on the
// name the mount reads the plugin by.
function applyOwnProfileSettings(
  profile: Profile,
  pluginNames: ReadonlyMap<string, string>,
  merged: Record<string, unknown>,
): void {
  const ownSettings = profile.settings ?? {};
  if (Object.keys(ownSettings).length === 0) return;
  const mountName = pluginNames.get(profile.workflow) ?? profile.workflow;
  const current = merged[mountName];
  merged[mountName] = isRecord(current) ? { ...current, ...ownSettings } : { ...ownSettings };
}

/**
 * The composed workflow's slice: the settings of the phases it walks, under
 * the one name the mount reads it by.
 *
 * A project's phases are called, not mounted, so their settings ride the
 * composed workflow's own config: each phase's derived slice is merged in,
 * and the composition splits it back out per call site. The machine's own
 * settings follow through the ordinary `applyOwnProfileSettings`.
 */
function composedSlice(derived: Record<string, unknown>, composed: { readonly name: string; readonly callees: readonly string[] } | undefined): void {
  if (!composed) return;
  const shared: Record<string, unknown> = {};
  for (const callee of composed.callees) {
    const slice = derived[callee];
    if (!isRecord(slice)) continue;
    mergeSlice(shared, slice);
  }
  // An entry the config wrote for the composed workflow itself survives the
  // composition: it was merged in as a given slice, and a thing written by
  // hand beats what was derived for the phases.
  const entry = derived[composed.name];
  const given: Record<string, unknown> = isRecord(entry) ? entry : {};
  mergeSlice(shared, given);
  derived[composed.name] = shared;
}

/** Merges phase slices by leaf, so sibling dotted settings reach their own callees. */
function mergeSlice(target: Record<string, unknown>, added: Record<string, unknown>): void {
  for (const [key, value] of Object.entries(added)) {
    const current = target[key];
    if (isRecord(current) && isRecord(value)) mergeSlice(current, value);
    else target[key] = copySliceValue(value);
  }
}

/** Copies mappings before a later phase adds sibling leaves to the composed slice. */
function copySliceValue(value: unknown): unknown {
  if (!isRecord(value)) return value;
  return Object.fromEntries(Object.entries(value).map(([key, nested]) => [key, copySliceValue(nested)]));
}

/**
 * The repositories the machine's notes are about, taken from the profiles
 * that turn a note into a plan.
 *
 * The notes directory is the machine's — one workflow writes a failure and
 * another reads it — so the destinations are read off every profile that
 * mounts the plan workflow, wherever in the config they now live, and an
 * install with none of them files nothing.
 */
function notesDestinations(config: AmyConfig): readonly string[] {
  const repos = new Set<string>();
  for (const one of Object.values(config.workflows)) {
    if (one.workflow !== "@amykit/workflow-note-to-plan") continue;
    const declared = one.settings?.repos;
    if (Array.isArray(declared)) {
      for (const repo of declared) if (typeof repo === "string") repos.add(repo);
    }
  }
  return [...repos];
}

function notesSlice(config: AmyConfig): Record<string, unknown> {
  const destinations = notesDestinations(config);
  return {
    directory: "notes",
    repo: destinations[0] ?? "",
    writeFailureNotes: destinations.length > 0,
  };
}

/** The plan check a profile names for its own workflow, or nothing for the default. */
function commandsFromCheck(profile: Profile): Record<string, unknown> | undefined {
  const check = (profile.settings ?? {}).check;
  return isRecord(check) ? check : undefined;
}

/** Global state-directory overrides have no profile slot, so a project's mounts cannot safely share one. */
function assertPhaseStateDirectoriesAreNotShared(config: AmyConfig, profile: Profile): void {
  if (!profile.project) return;
  for (const plugin of [
    "@amykit/plugin-file-queue",
    "@amykit/plugin-file-store",
    "@amykit/plugin-file-brief-store",
    "@amykit/plugin-file-tasks",
    "@amykit/plugin-slack",
    "@amykit/plugin-telegram",
  ] as const) {
    // Telegram is never recommended, so a project that does not name it does not mount it, and a
    // directory set for an ordinary profile's Telegram is not this project's to refuse.
    if (plugin === "@amykit/plugin-telegram" && !pluginList(config, profile).includes(plugin)) continue;
    const slice = config.plugins[plugin];
    if (isRecord(slice) && typeof slice.directory === "string") {
      throw new Error(`${plugin}.directory is shared across profiles and cannot be overridden for a project`);
    }
  }
  const worktree = config.plugins["@amykit/plugin-file-worktree"];
  if (isRecord(worktree) && typeof worktree.workflow === "string") {
    throw new Error("@amykit/plugin-file-worktree.workflow is shared across profiles and cannot be overridden for a project");
  }
}

function stateDirectories(stateDir: string | undefined, profile: Profile): { records: string; queue: string } {
  if (!stateDir) return directoriesFor(profile);
  const place = profilePaths(stateDir, profile);
  return {
    records: path.relative(stateDir, place.records),
    queue: path.relative(stateDir, place.queue),
  };
}

/** The threads a phase opened are its own; an ordinary profile's slice stays as it was. */
function slackSlice(directory: string): Record<string, unknown> {
  return directory === "slack" ? {} : { "@amykit/plugin-slack": { directory } };
}

/** The topics a phase opened are its own, as its threads are; an ordinary profile's slice stays as it was. */
function telegramSlice(directory: string): Record<string, unknown> {
  return directory === "telegram" ? {} : { "@amykit/plugin-telegram": { directory } };
}

/** Plugin-owned state directories, relative to the state root the plugin is handed. */
function pluginStateDirectories(stateDir: string | undefined, profile: Profile): { tasks: string; slack: string; telegram: string } {
  if (!stateDir) {
    const base = profile.project ? `${projectStateKey(profile.project, profile.name)}/` : "";
    return { tasks: `${base}tasks`, slack: `${base}slack`, telegram: `${base}telegram` };
  }
  const place = profilePaths(stateDir, profile);
  return {
    tasks: path.relative(stateDir, place.tasks),
    slack: path.relative(stateDir, place.slack),
    telegram: path.relative(stateDir, place.telegram),
  };
}

/** A checkout belongs to the project and its configured profile: one namespace, not one per phase. */
export function worktreeNamespace(profile: Profile): string {
  return profile.project ? projectStateKey(profile.project, profile.name) : profile.name;
}

/** The worktree adapter reads the same absolute records directory as the file store. */
function worktreeRecordsDirectory(stateDir: string | undefined, recordsDirectory: string): string {
  // The file-store provider deliberately treats its setting as a state-root
  // relative directory, even when it begins with a slash. Keep its reader on
  // that exact path rather than giving this sibling adapter path.resolve's
  // different absolute-path semantics.
  return stateDir ? path.join(stateDir, recordsDirectory) : "";
}

/** Resolve the file store's final configured directory after explicit slices win. */
function effectiveRecordsDirectory(slice: unknown, stateDir: string | undefined, fallback: string): string {
  const directory = isRecord(slice) && typeof slice.directory === "string" ? slice.directory : fallback;
  return worktreeRecordsDirectory(stateDir, directory);
}

/** Keep a valid worktree slice coupled to the mounted record store. */
function withWorktreeRecordsDirectory(slice: unknown, recordsDirectory: string): unknown {
  return isRecord(slice) ? { ...slice, recordsDirectory } : slice;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** The profile can narrow cost and model choices without changing any other host setting. */
/** The reviewer hints written under `agent:`, for the workflow whose review prompt they are. */
function reviewerHintsFor(config: AmyConfig, profile: Profile): Record<string, string> {
  return effectiveAgent(config, profile).reviewerHints ?? {};
}

function effectiveAgent(config: AmyConfig, profile: Profile): AmyConfig["agent"] {
  return { ...config.agent, ...(profile.agent ?? {}) };
}

function ticketBudgetSlice(config: AmyConfig, profile: Profile): { budget: Record<string, unknown> } {
  return { budget: effectiveAgent(config, profile).budget ?? {} };
}

/**
 * The file-store setting from before BriefStore became its own plugin.
 *
 * Keep accepting it at the old slice and carry its value to the new mount:
 * an upgrade must read the existing briefs, while a setting written directly
 * for the new provider still wins in the ordinary per-plugin merge below.
 */
function fileStoreBriefDirectory(config: AmyConfig): string | undefined {
  const fileStore = config.plugins["@amykit/plugin-file-store"];
  return isRecord(fileStore) && typeof fileStore.briefsDirectory === "string"
    ? fileStore.briefsDirectory
    : undefined;
}

/** The file BriefStore's settings, including the one-time legacy translation. */
function briefStoreSlice(config: AmyConfig, profile: Profile): { directory: string } {
  // Project phases share a host-owned artifact root. Ordinary profiles retain
  // the file-store translation, including an explicit path they already use.
  return { directory: profile.project ? "briefs" : legacyBriefDirectory(config) };
}

/** Where an ordinary profile keeps its briefs, relative to the state directory. */
function legacyBriefDirectory(config: AmyConfig): string {
  const own = config.plugins["@amykit/plugin-file-brief-store"];
  if (isRecord(own) && typeof own.directory === "string") return own.directory;
  return fileStoreBriefDirectory(config) ?? "briefs";
}

/**
 * The settings a harness plugin gets.
 *
 * The tiers come from the ladder rather than from a second list, so there is
 * one place to edit. `claude:sonnet, claude:opus` in the ladder is what makes
 * the claude plugin contribute two agents, and the relay then finds both
 * names it was told to try.
 */
function harnessSlice(config: AmyConfig, profile: Profile, harness: string): Record<string, unknown> {
  const agent = effectiveAgent(config, profile);
  const fromLadder = tiersFor(everyLadderEntry(agent), harness);

  // A harness is told how to run and nothing about where work lives: the
  // agent only answers, in the directory its caller hands it.
  return {
    model: agent.model ?? "",
    models: fromLadder.length > 0 ? fromLadder : (agent.models ?? []),
    ...(agent.timeoutMs === undefined ? {} : { timeoutMs: agent.timeoutMs }),
  };
}

/**
 * The models a ladder asks of one harness, in ladder order.
 *
 * A bare `claude` entry means "whatever model is configured", which is the
 * single-model install, so it contributes the empty tier rather than a model
 * literally named "claude".
 */
export function tiersFor(ladder: readonly string[], harness: string): string[] {
  return ladder
    .filter((entry) => entry === harness || entry.startsWith(`${harness}:`))
    .map((entry) => entry.slice(harness.length + 1));
}

/**
 * Every rung any step could reach, the default ladder and the per-step ones.
 *
 * Both, because a model named only inside `ladderByStep` is still a model the
 * harness plugin has to contribute and a harness the profile has to mount.
 * Reading only the default would refuse that mount at boot, correctly but
 * for a reason nobody could see from the config they wrote.
 */
function everyLadderEntry(agent: AmyConfig["agent"]): string[] {
  return [
    ...(agent.ladder ?? []),
    ...Object.values(agent.ladderByStep ?? {}).flat(),
  ];
}

/** Whether a ladder mentions a harness at all, which is what mounts it. */
export function ladderNames(ladder: readonly string[], harness: string): boolean {
  return ladder.some((entry) => entry === harness || entry.startsWith(`${harness}:`));
}

/** Which plugins to mount: what the profile asked for, or what is recommended. */
export function pluginList(config: AmyConfig, profile: Profile): string[] {
  if (profile.plugins.length > 0) {
    const explicit = [...profile.plugins, ...config.extraPlugins.filter((name) => !profile.plugins.includes(name))];
    return withBriefStore(profile, explicit);
  }

  const ladder = everyLadderEntry(effectiveAgent(config, profile));

  // A channel nobody configured should not be mounted, or the fan-out would
  // announce into a target that is not there. Same reasoning for a harness:
  // mounting one whose binary is not installed only produces a doctor failure
  // for a tool the operator never asked for.
  const recommended = recommendedFor(profile).filter((name) => {
    // A note needs somewhere to go. An install that named no repository to
    // write plans into would be watching a directory nothing could ever come
    // out of, so it does not watch one. Where those destinations are named
    // now lives under the plan workflow's own profile.
    if (name === "@amykit/plugin-file-notes") return notesDestinations(config).length > 0;
    if (name === "@amykit/plugin-notify-hermes") return Boolean(config.notify.hermes);
    if (name === "@amykit/plugin-notify-inbox") return config.notify.inbox;
    if (name === "@amykit/plugin-codex") return ladderNames(ladder, "codex");
    if (name === "@amykit/plugin-hermes-agent") return ladderNames(ladder, "hermes");
    return true;
  });

  // The extras ride after what was recommended, deduplicated: a plugin named
  // both places is one mount, and `mount()` would refuse the second claim of
  // a port rather than read the list as an intention.
  return withBriefStore(profile, [...recommended, ...config.extraPlugins.filter((name) => !recommended.includes(name))]);
}

/** Replaces the local BriefStore when a profile selects its own provider. */
function withBriefStore(profile: Profile, plugins: readonly string[]): string[] {
  const local = "@amykit/plugin-file-brief-store";
  // `""` is the removal trial's explicit absence: do not let the legacy
  // file-store compatibility rule recreate the provider it just removed.
  const chosen = profile.briefStore === ""
    ? undefined
    : profile.briefStore ?? (plugins.includes("@amykit/plugin-file-store") ? local : undefined);
  if (!chosen) return [...plugins];

  const replaced = plugins.map((name) => name === local ? chosen : name);
  return replaced.includes(chosen) ? replaced : [...replaced, chosen];
}

/** Where the host keeps its own state; the workspace answers where code lives. */
export function hostPaths(stateDir: string, profile?: Profile) {
  const place = profile ? profilePaths(stateDir, profile) : undefined;
  return {
    state: stateDir,
    ...(place ? { profile: path.dirname(place.records) } : {}),
    ...(place?.artifacts ? { artifacts: place.artifacts } : {}),
  };
}

/**
 * The file-worktree plugin's own slice, as the mount reads it.
 *
 * The operator's slice wins every field it wrote; what is left keeps the
 * default the machine's key carried. The branch answers are not repeated
 * here — the plugin's schema carries them, and `workspaceSettings` reads
 * them for every plugin that asks — so a slice hand-written for this plugin
 * is handed on exactly as it was.
 */
function workspaceSlice(config: AmyConfig): Record<string, unknown> {
  const slice = config.plugins["@amykit/plugin-file-worktree"];
  const given = isRecord(slice) ? slice : {};
  return {
    repos: workspaceSettings(config).repos,
    workspaceRoot: typeof given.workspaceRoot === "string" ? given.workspaceRoot : ".",
    checkouts: isRecord(given.checkouts) ? given.checkouts : {},
    root: typeof given.root === "string" ? given.root : "",
    retentionDays: typeof given.retentionDays === "number" ? given.retentionDays : 7,
    defaultBranch: workspaceSettings(config).defaultBranch,
    baseBranch: workspaceSettings(config).baseBranch,
  };
}

function engineSlice(config: AmyConfig): Record<string, unknown> {
  return {
    staleClaimMs: config.staleClaimMs,
    retentionDays: config.retentionDays,
    maxItemAttempts: config.maxItemAttempts,
    // No retryDelayMs here: how quickly the engine comes back to a failed
    // item is the engine's own answer, declared and defaulted in its schema.
    // It was once a ticket workflow's review poll, which is how tuning how
    // often a review is looked at moved how the whole machine retried.
  };
}

/** Points a workflow's destination at the directory its adapter ended up with. */
function followAdapter(
  merged: Record<string, unknown>,
  workflow: string,
  setting: string,
  adapter: string,
): void {
  const slice = merged[workflow];
  const from = merged[adapter];
  if (!isRecord(slice) || !isRecord(from) || typeof from.directory !== "string") return;
  merged[workflow] = { ...slice, [setting]: from.directory };
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

/**
 * The five shapes a plugin spec arrives in.
 *
 * `name` and `range` name a package the registry resolves; `git` and
 * `tarball` point at one from outside it; `path` is a directory on this disk.
 * Named once here rather than spelled out in `Resolved` twice, so the
 * document below and the field agree by construction.
 */
type SpecKind = "name" | "range" | "git" | "tarball" | "path";

/**
 * What one spec argument turns into.
 *
 * `install` is the string npm takes. `imported` is what the config names —
 * the string the loader passes to `import()`. Undefined for a git URL and a
 * tarball, whose name is not knowable until the package is on disk, which is
 * the caller's cue to read the installed `package.json` rather than guess.
 * For a path it is the package's own entry, as a `file:` URL, because a
 * directory is not something `import()` accepts — and `absolute` is the
 * directory the spec resolved to, so the config means the same directory from
 * wherever the command was typed.
 */
export interface Resolved {
  kind: SpecKind;
  install: string;
  imported: string | undefined;
  absolute?: string;
}

/**
 * Classifies a plugin spec into what npm installs and what the config names.
 *
 * `amy plugin add` takes one argument and calls it a spec: "anything Node can
 * import". What npm takes and what the config has to name are two different
 * strings for every form but a bare package name, and this is where the two
 * are decided once, together, instead of wherever a command happens to need
 * one of them.
 *
 * A Windows-shaped spec is a path, not a name with a range: a drive letter
 * and a backslash are a directory, so the backslashes are normalized away and
 * the rest is judged like any other path.
 *
 * A path that is not a package is refused here, before anything is run, and
 * the refusal names the missing `package.json`.
 */
export function classify(spec: string, cwd: string): Resolved {
  if (spec.trim().length === 0) {
    throw new Error("a plugin spec is empty; name a package, a URL or a path");
  }

  const candidate = spec.replace(/\\/g, "/");

  const filed = localFileOf(candidate);
  if (filed) return resolvePath(filed, cwd);

  if (isGitSpec(candidate)) return { kind: "git", install: candidate, imported: undefined };
  // What is left of http(s) is a download, whatever the suffix: the shape is
  // the tarball, and npm is the one that finds out what the URL served.
  if (/^https?:\/\//.test(candidate)) {
    return { kind: "tarball", install: candidate, imported: undefined };
  }

  const named = parseName(candidate);
  if (named) return named;

  return resolvePath(candidate, cwd);
}

/**
 * A scope or a package name, with everything after a second `@` as the range.
 *
 * A name is one segment with no slash in it, which is what keeps `./plugin-x`
 * and `packages/plugin-x` out of here: they are paths, and the path half
 * decides them. A bare `.` or `..` is a path too — npm reads both as the
 * caller's directory, and neither is a name any registry carries.
 */
function parseName(spec: string): Resolved | undefined {
  if (spec === "." || spec === "..") return undefined;

  // eslint-disable-next-line security/detect-unsafe-regex -- literal regex, linear
  const scoped = /^@([\w.-]+)\/([\w.-]+)(?:@(.+))?$/s.exec(spec);
  if (scoped) {
    const name = `@${scoped[1]}/${scoped[2]}`;
    return scoped[3] === undefined
      ? { kind: "name", install: spec, imported: name }
      : { kind: "range", install: spec, imported: name };
  }

  // eslint-disable-next-line security/detect-unsafe-regex -- literal regex, linear
  const unscoped = /^([\w.-]+)(?:@(.+))?$/s.exec(spec);
  if (!unscoped) return undefined;

  return unscoped[2] === undefined
    ? { kind: "name", install: spec, imported: unscoped[1] }
    : { kind: "range", install: spec, imported: unscoped[1] };
}

/**
 * Git is what npm cannot answer from the registry: a scheme naming git or
 * ssh, npm's own `github:` shorthand and the ones npm copies it from, the
 * scp-like `host:owner/repo` shape, and an https endpoint that ends in `.git`
 * or carries a ref fragment. Every other http(s) URL is a download.
 */
function isGitSpec(spec: string): boolean {
  return (
    /^(?:git|git\+ssh|git\+https?|git\+file|ssh):\/\//.test(spec) ||
    /^(?:github|gitlab|bitbucket|gist):/.test(spec) ||
    /^[^:/]+@[^:/]+:/.test(spec) ||
    // eslint-disable-next-line security/detect-unsafe-regex -- literal regex, linear
    /^https?:\/\/.+\.git(#.*)?$/.test(spec) ||
    /^https?:\/\/[^#]+#/.test(spec)
  );
}

/**
 * A `file:` spec is npm's own word for a package on this disk, and the
 * documentation this repository carries promises it beside the path form.
 *
 * An absolute `file:` URL is decoded by Node itself — `fileURLToPath` is what
 * turns `file:///C:/...` into `C:\...` on Windows and reads UNC hosts and
 * percent escapes the way an import would. A bare `file:` prefix is npm's
 * relative shorthand: what follows is exactly what a caller could have typed
 * as a path, and the path half decides it.
 */
function localFileOf(candidate: string): string | undefined {
  const absolute = /^file:\/\/(.+)$/.exec(candidate);
  if (absolute?.[1]) {
    try {
      return fileURLToPath(new URL(candidate));
    } catch (error) {
      throw new Error(`${candidate} is not a file URL a package can live at`, { cause: error });
    }
  }

  const bare = /^file:(?!\/\/)(.+)$/.exec(candidate);
  return bare?.[1];
}

/** A path the package manager can find a package in, or the refusal. */
function resolvePath(candidate: string, cwd: string): Resolved {
  const absolute = isHomeRelative(candidate)
    ? path.join(os.homedir(), candidate.slice(2))
    : path.resolve(cwd, candidate);

  if (!isPackageDirectory(absolute)) {
    throw new Error(`${candidate} is not a package: its package.json is missing at ${absolute}`);
  }

  return { kind: "path", install: absolute, imported: packageEntrySpecifier(absolute), absolute };
}

/**
 * Only a bare `~` or a path under it names the home directory.
 *
 * `~owner/plugin` is npm's user shorthand and this program has no user
 * database to ask, so it stays relative to the caller's directory, where a
 * directory literally named `~owner` would be.
 */
function isHomeRelative(candidate: string): boolean {
  return candidate === "~" || candidate.startsWith("~/");
}

/** A directory carrying a readable `package.json` file, not a directory named so. */
function isPackageDirectory(directory: string): boolean {
  try {
    return fs.statSync(path.join(directory, "package.json")).isFile();
  } catch {
    return false;
  }
}

/**
 * The file the loader can import, read off the package's own entry.
 *
 * The entry follows Node's exports algorithm for the package root:
 * an `exports` field present is authoritative — a string, or its `.`
 * member walked in declaration order through nested conditions, and an
 * `exports` that names no root is a refusal, because Node itself cannot
 * import the package root then. Without `exports`, `main` decides, and
 * the `index.js` both npm and Node fall back to is last. A
 * `package.json` that cannot be read or parsed is refused with the
 * error carried as its cause rather than resolved past.
 */
export function packageEntrySpecifier(directory: string): string {
  const manifestPath = path.join(directory, "package.json");
  let manifest: unknown;
  try {
    manifest = JSON.parse(fs.readFileSync(manifestPath, "utf-8"));
  } catch (error) {
    throw new Error(`${directory} carries a package.json that cannot be read`, { cause: error });
  }

  const exported = (manifest as { exports?: unknown }).exports;
  const entry =
    exported === undefined
      ? (entryFromMain((manifest as { main?: unknown }).main, directory) ?? "./index.js")
      : entryFromExports(exported, directory);

  if (entry === undefined) {
    throw new Error(
      `${directory} carries an exports map that names no root, so nothing can import the package`,
    );
  }
  // `main` is Node's legacy field and its values are ordinary relative
  // paths — "dist/index.js" without the `./` is common and valid there.
  // Only an `exports` target is held to the `./` form.
  if (exported === undefined) {
    return pathToFileURL(path.join(directory, entry)).href;
  }
  return pathToFileURL(path.join(directory, packageTarget(directory, entry))).href;
}

/**
 * A target `exports` may name, held to Node's own constraints.
 *
 * A target must be a relative specifier into the package: it starts with
 * `./`, carries no `..` segment and no absolute body. Node refuses anything
 * else, and so does this half — a target like `./../../outside.js` would
 * otherwise have the loader import a file that is not in the package at all,
 * and a bare `dist/index.js` is invalid to Node outright.
 */
function packageTarget(directory: string, entry: string): string {
  if (!entry.startsWith("./")) {
    throw new Error(`${directory} carries an exports target Node cannot take: ${entry}`);
  }
  const inside = path.resolve(directory, entry);
  if (path.relative(directory, inside).startsWith("..")) {
    throw new Error(`${directory} carries an exports target outside the package: ${entry}`);
  }
  return entry;
}

/** The entry the `exports` field names, by Node's exports algorithm. */
function entryFromExports(exports: unknown, directory: string): string | undefined {
  // A bare string is the whole map for the root: Node reads
  // `exports: "./x.js"` exactly as `exports: { ".": "./x.js" }`.
  if (typeof exports === "string" && exports.length > 0) return exports;

  const map = exports as Record<string, unknown> | undefined;
  const dot = map?.["."];
  // A top-level member named `import`, `node` or `default` is the root
  // condition map itself — Node reads `{"import": "./x.js"}` as the root
  // entry, and only a key starting with `.` names a subpath.
  const entry =
    dot === undefined && Object.keys(map ?? {}).some((key) => !key.startsWith("."))
      ? entryFromRoot(map)
      : entryFromRoot(dot);
  // A `null` arm is Node's terminal refusal for the root: not resolvable,
  // which is a different answer from "no root member at all".
  if (entry === null) {
    throw new Error(`${directory} carries an exports arm that is null, which Node takes as no target`);
  }
  return entry;
}

/**
 * The entry one member of `exports` names, following Node's own walk.
 *
 * A string is the target. An array is Node's fallback list: the first
 * member that names a valid target wins — validity is the `./` form Node
 * demands, not the file's existence, which Node never checks at resolve
 * time and only reports when the import actually runs. A `null` member
 * inside an array is that member's refusal, and the walk moves on. An
 * object is conditions in declaration order: the first arm named
 * `import`, `node` or `default` wins, recursing into a nested condition
 * object the way Node does — so `{"node": {"import": "./node.js"},
 * "default": "./b.js"}` answers `./node.js`, and `{"node": "./a.js",
 * "default": "./b.js"}` answers `./a.js` rather than the fallback that
 * happens to be read later. An explicit `null` arm at the root is Node's
 * word for "no target here" and is terminal, not an invitation to fall
 * through to whatever is declared beside it.
 */
function entryFromRoot(member: unknown): string | undefined | null {
  if (typeof member === "string" && member.length > 0) return member;
  if (member === null) return null;
  if (Array.isArray(member)) return entryFromFallbacks(member);
  if (!member || typeof member !== "object") return undefined;
  for (const [condition, value] of Object.entries(member as Record<string, unknown>)) {
    if (!["import", "node", "default"].includes(condition)) continue;
    const resolved = entryFromRoot(value);
    if (resolved !== undefined) return resolved;
  }
  return undefined;
}

/**
 * Node's fallback list: the first member that names a valid target wins.
 *
 * Validity is the `./` form Node demands of a target, checked once where
 * the whole entry is validated; the file's existence is never part of the
 * walk — Node answers the first valid member and lets the import itself
 * fail on a file that is not there. A `null` member inside an array is
 * that member's refusal, and the walk moves on to the next.
 */
function entryFromFallbacks(members: unknown[]): string | undefined {
  for (const fallback of members) {
    const resolved = entryFromRoot(fallback);
    if (resolved === undefined || resolved === null) continue;
    return resolved;
  }
  return undefined;
}

/**
 * The file `main` names, by Node's legacy resolution.
 *
 * `main` is not an `exports` target: its value is an ordinary relative
 * path, where `dist/index.js` without the `./` is common and valid, and
 * Node falls back the legacy way when the value names no file outright —
 * `dist/index` resolves to `dist/index.js` beside it, and `./dist` to
 * `dist/index.js` inside it. The file must be there: Node fails the
 * resolve outright when it is not.
 */
function entryFromMain(main: unknown, directory: string): string | undefined {
  if (typeof main !== "string" || main.length === 0) return undefined;
  const declared = path.join(directory, main);
  if (fs.existsSync(declared) && fs.statSync(declared).isFile()) return main;
  if (fs.existsSync(`${declared}.js`)) return `${main}.js`;
  if (fs.existsSync(path.join(declared, "index.js"))) return path.join(main, "index.js");
  return main;
}

import fs from "node:fs";
import { BuildStamp, stampFrom } from "@amykit/core";

/**
 * Where `npm pack` leaves this build's identity, beside the code it built.
 *
 * There is no compile step to substitute anything into, so the identity is
 * written into the tarball at pack time, and **its absence is what a checkout
 * looks like** — which is the whole point. Reading the version out of
 * `package.json` instead would make a working tree claim to be a release, and
 * the stamp exists to tell those two apart.
 */
const STAMP_FILE = "stamp.json";

interface WrittenStamp {
  version?: string;
  commit?: string;
  builtAt?: string;
}

/**
 * What this install is: a release, or a checkout.
 *
 * The directory is a parameter so a test can point it somewhere real. In
 * production it is the directory this module was loaded from, which is
 * `dist/` in an installed package and `src/` in a checkout — and only the
 * first of those ever has a stamp in it.
 */
export function installedStamp(from: URL = new URL("./", import.meta.url)): BuildStamp {
  const written = read(new URL(STAMP_FILE, from));
  return stampFrom({
    version: written?.version,
    commit: written?.commit,
    builtAt: written?.builtAt,
  });
}

/**
 * Returns nothing rather than throwing.
 *
 * A stamp that will not parse is a build that cannot say what it is, and
 * `stampFrom` already has a name for that: `dev`. Failing to start over it
 * would be refusing to run over a cosmetic detail.
 */
function read(file: URL): WrittenStamp | undefined {
  try {
    return JSON.parse(fs.readFileSync(file, "utf-8")) as WrittenStamp;
  } catch {
    return undefined;
  }
}

import { Empty, Section, Stack, Table, Text, type Node } from "@amykit/ui";
import type { Transition } from "@amykit/core";
import type { UsageResult } from "@amykit/agent-kit";
import { recordsToShow, standing } from "./status-view.js";

/** One record as `amy status --json` reports it. */
export interface StatusRecord {
  readonly id: string;
  readonly state: string;
  readonly waiting: boolean | null;
  readonly finished: boolean | null;
  readonly repo: string | null;
  readonly pullRequest: number | null;
  readonly updatedAt: string;
  readonly attempts: Readonly<Record<string, number>>;
  readonly history: readonly Transition[];
  /** Every record this one is waiting on through its calls, deepest last, each with its own trail. */
  readonly calls?: readonly StatusCall[];
  /** Whether the deepest record is waiting on its owner, which makes the root what needs them. */
  readonly attention?: boolean | null;
  /** Whether the deepest record is waiting on the world, which is what its root is doing too. */
  readonly waitingInACall?: boolean | null;
  /** The lanes of the fork the record waits in, side by side, each where its own record is. */
  readonly lanes?: readonly StatusLane[];
}

/** One lane of a fork, as `amy status --json` reports it. */
interface StatusLane {
  readonly lane: string;
  readonly id: string;
  readonly state: string;
  readonly ended: boolean;
  readonly attention: boolean;
  readonly history: readonly Transition[];
}

/** One phase of a project as `amy status --json` reports it: where it walks, or why it is out. */
interface StatusPhase {
  readonly phase: string;
  readonly absent: boolean;
  readonly reason: string | null;
}

/** One call a record is waiting on, as `amy status --json` reports it. */
interface StatusCall {
  readonly id: string;
  readonly state: string;
  readonly history: readonly Transition[];
}

/** The loop that is running, as its own record says. */
interface StatusLoop {
  readonly pid: number;
  readonly startedAt: string;
  readonly workflow: string;
}

/** Everything `amy status` knows, which is exactly what `--json` prints. */
export interface StatusSnapshot {
  readonly at: string;
  readonly home: string;
  readonly profile: string;
  readonly workflow: string;
  readonly mounted: boolean;
  readonly problems: readonly string[];
  readonly states: readonly string[];
  readonly waitingStates: readonly string[];
  readonly terminalStates: readonly string[];
  readonly records: readonly StatusRecord[];
  readonly queue: { readonly due: number; readonly pending: number; readonly running: number; readonly finished: number };
  /** The project's phases: the ones this walk drives, and the ones declared out, with the reason. */
  readonly phases?: readonly StatusPhase[];
  readonly loop: StatusLoop | null;
  readonly paused: string | null;
  readonly notes: number;
  readonly needsInput: number;
  /** Each mounted harness subscription, read only for this inspection. */
  readonly usage: readonly SubscriptionUsage[];
}

/** One reader's on-demand answer, kept beside the reader's stable label. */
export interface SubscriptionUsage {
  readonly subscription: string;
  readonly result: UsageResult;
}

/**
 * The provider windows, then the moment to read everything else at. An
 * account request can take seconds; a clock read before it would date the
 * queue, the ledger and the snapshot to before the wait.
 */
export async function usageThenNow(
  usage: () => Promise<readonly SubscriptionUsage[]>,
  clock: () => Date = () => new Date(),
): Promise<{ readonly usage: readonly SubscriptionUsage[]; readonly now: Date }> {
  const answered = await usage();
  return { usage: answered, now: clock() };
}

/** What the page is asked for beyond the snapshot: finished work too, and where the questions wait. */
export interface StatusOptions {
  readonly all: boolean;
  readonly inbox: string;
}

// Widths a terminal has always lined the listing up on. `optional` is what
// lets a row with no repository and no pull request end after its standing.
const COLUMNS = [{ width: 28 }, { width: 18 }, { width: 8 }, { width: 30, optional: true }, { optional: true }];

function Records(props: { readonly snapshot: StatusSnapshot; readonly all: boolean }): Node {
  const { records, mounted, waitingStates, terminalStates } = props.snapshot;
  // Without a mount there are no states to compare against, and the page
  // says `?` rather than guess; the snapshot carries empty lists then.
  const waiting = mounted ? waitingStates : undefined;
  const terminal = mounted ? terminalStates : undefined;
  const view = recordsToShow(records, terminal, props.all);

  if (records.length === 0) return <Empty>nothing tracked yet</Empty>;
  if (view.shown.length === 0) return <Empty>nothing open</Empty>;

  const rows = view.shown.map((record) => [
    record.id,
    [record.state, ...(record.calls ?? []).map((call) => call.state), ...lanesOf(record)].join(" › "),
    record.attention ? "attention" : record.waitingInACall ? "waiting" : standing(record.state, waiting, terminal),
    record.repo ?? "",
    record.pullRequest ? `#${record.pullRequest}` : "",
  ]);
  return <Table columns={COLUMNS} rows={rows} />;
}

/**
 * The lanes of a fork, drawn as lines side by side, each with where its own
 * record is, and how many have arrived at the join.
 */
function lanesOf(record: StatusRecord): string[] {
  const lanes = record.lanes ?? [];
  if (lanes.length === 0) return [];
  const arrived = lanes.filter((lane) => lane.ended).length;
  return [`${lanes.map((lane) => `${lane.lane} ${lane.state}`).join(" ∥ ")} (${arrived}/${lanes.length} arrived)`];
}

/**
 * Work that stopped inside a call, shown with its root: where in the tree it
 * stopped, and the move that put it there, so nobody has to open the record
 * to find out which call is waiting on them.
 */
function Stopped(props: { readonly records: readonly StatusRecord[] }): Node {
  const stopped = props.records.filter(stoppedInACall);
  return (
    <Section>
      {stopped.map((record) => {
        const lane = record.lanes?.find((candidate) => candidate.attention);
        if (lane) {
          const last = lane.history.at(-1);
          return <Text tone="warning">{`${record.id} needs you: the lane ${lane.lane} (${lane.id}) stopped in ${lane.state}${last ? ` — ${last.why}` : ""}`}</Text>;
        }
        const deepest = record.calls!.at(-1)!;
        const last = deepest.history.at(-1);
        return <Text tone="warning">{`${record.id} needs you: ${deepest.id} stopped in ${deepest.state}${last ? ` — ${last.why}` : ""}`}</Text>;
      })}
    </Section>
  );
}

function stoppedInACall(record: StatusRecord): boolean {
  return Boolean(record.attention) && ((record.calls?.length ?? 0) > 0 || (record.lanes ?? []).some((lane) => lane.attention));
}

function loopLine(snapshot: StatusSnapshot): string {
  const paused = snapshot.paused ? ` (paused: ${snapshot.paused})` : "";
  const live = snapshot.loop;
  return live
    ? `loop:  running since ${live.startedAt}, driving ${live.workflow}, pid ${live.pid}${paused}`
    : `loop:  not running${paused}`;
}

function Usage(props: { readonly usage: readonly SubscriptionUsage[] }): Node | null {
  if (props.usage.length === 0) return null;
  return (
    <Section>
      {props.usage.map(({ subscription, result }) => (
        <Text>{usageLine(subscription, result)}</Text>
      ))}
    </Section>
  );
}

/** One subscription stays separate from Amy's rolling ledger. */
function usageLine(subscription: string, result: UsageResult): string {
  if ("unavailable" in result) return `${subscription}: unavailable — ${result.unavailable}`;
  const unofficial = result.unofficial ? " unofficial" : "";
  const windows = result.windows.map((window) => {
    const period = window.startsAt || window.resetsAt
      ? [window.startsAt ? `starts ${window.startsAt}` : "", window.resetsAt ? `resets ${window.resetsAt}` : ""].filter(Boolean).join(", ")
      : "period unknown";
    return `${window.label} ${window.usedPercent}% (${period})`;
  });
  return `${subscription}${unofficial}: ${windows.join("; ")}`;
}

/**
 * `amy status`, as a view: a pure function from the snapshot `--json` prints
 * to a tree of primitives. The text renderer draws the page a terminal has
 * always printed; a window draws the same tree, so the two cannot disagree.
 */
export function statusView(snapshot: StatusSnapshot, options: StatusOptions): Node {
  const records = recordsToShow(snapshot.records, snapshot.mounted ? snapshot.terminalStates : undefined, options.all);
  const { queue } = snapshot;

  return (
    <Stack gap={1}>
      <Records snapshot={snapshot} all={options.all} />
      {records.finished > 0 && <Text tone="muted">{`${records.finished} finished, not shown. \`amy status --all\` lists them.`}</Text>}
      <Phases snapshot={snapshot} />
      <Usage usage={snapshot.usage} />
      <Section>
        <Text>{`queue: ${queue.due} due, ${queue.pending} pending, ${queue.running} in flight, ${queue.finished} finished`}</Text>
        <Text>{loopLine(snapshot)}</Text>
        {snapshot.notes > 0 && <Text>{`notes: ${snapshot.notes} written down`}</Text>}
      </Section>
      {records.shown.some(stoppedInACall) && <Stopped records={records.shown} />}
      {snapshot.needsInput > 0 && (
        <Text tone="warning">{`${snapshot.needsInput} question(s) waiting for you in ${options.inbox}`}</Text>
      )}
    </Stack>
  );
}

/**
 * The phases of a project, said on one line: the ones the walk drives in
 * order, then every phase declared absent with the reason its declaration
 * gave, which is what a project without that phase loses.
 */
function Phases(props: { readonly snapshot: StatusSnapshot }): Node | null {
  const phases = props.snapshot.phases ?? [];
  if (phases.length === 0) return null;
  const walking = phases.filter((one) => !one.absent).map((one) => one.phase);
  const absent = phases.filter((one) => one.absent).map((one) => `${one.phase} is out: ${one.reason}`);
  return (
    <Section>
      {walking.length > 0 && <Text>{`phases: ${walking.join(" › ")}`}</Text>}
      {absent.map((line) => <Text tone="muted">{line}</Text>)}
    </Section>
  );
}

/** What a status listing needs from a record, and nothing else. */
export interface RecordLine {
  readonly state: string;
}

/** The records to print, and how many were left out for having ended. */
export interface RecordsView<R> {
  readonly shown: readonly R[];
  readonly finished: number;
}

/**
 * Which records `amy status` prints.
 *
 * A record in a terminal state is work that is over. `Worker.discover` already
 * refuses to re-enqueue it, so keeping it costs no agent — but it never leaves
 * the listing on its own, and the one page somebody keeps open becomes the
 * page they stop reading. Work that has ended is counted here rather than
 * printed, and `--all` prints it anyway.
 *
 * Counted and not deleted, because the terminal record is the safeguard that
 * stops rediscovery. Removing it while the tracker still returns the id starts
 * the whole lifecycle over; that is retention's job, not this function's.
 *
 * `terminal` is undefined when the workflow would not mount. Nothing is hidden
 * then: a mount that failed is exactly when somebody wants every row, and
 * guessing which states are terminal would invent the answer the workflow was
 * going to give.
 */
export function recordsToShow<R extends RecordLine>(
  records: readonly R[],
  terminal: readonly string[] | undefined,
  all: boolean,
): RecordsView<R> {
  if (all || !terminal) return { shown: records, finished: 0 };

  const shown = records.filter((record) => !terminal.includes(record.state));
  return { shown, finished: records.length - shown.length };
}

/**
 * The one word the listing puts against a state.
 *
 * Terminal is asked before waiting, because a workflow may well call the same
 * state both — `DONE` is where nothing happens until the world moves, and the
 * world is never going to move. "Waiting" would read as something outstanding.
 *
 * `?` when the workflow would not mount, which is the honest answer: without
 * it there are no states to compare against.
 */
export function standing(
  state: string,
  waiting: readonly string[] | undefined,
  terminal: readonly string[] | undefined,
): string {
  if (!waiting && !terminal) return "?";
  if (terminal?.includes(state)) return "finished";
  return waiting?.includes(state) ? "waiting" : "active";
}

import fs from "node:fs";
import yaml from "yaml";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { CommandRunner } from "@amykit/core";
import { PLUGINS_ROOT_FLAGS, packageManager, shellCommand } from "./install.js";
import { paths } from "./paths.js";
import { type AmyConfig, DEFAULT_CONFIG } from "./config.js";
import { type Profile } from "./profiles.js";
import { pluginList } from "./slices.js";

/**
 * One package this machine's two roots hold, and what the range in them
 * points at.
 *
 * The two roots are the plugins root — `<home>/plugins`, where the config's
 * packages are installed — and the install root that resolved the CLI
 * itself. The version installed is read off the copy on disk. The version
 * the range points at is asked of the range, through npm, which is what
 * makes an update an answer rather than a guess.
 */
export interface Held {
  /** The package the root's manifest names. */
  readonly name: string;
  /** The spec in the root's manifest: the range this install pinned. */
  readonly range: string;
  /** Which of the two roots holds it. */
  readonly root: "plugins" | "install";
  /** The version on disk right now. */
  readonly have: string;
  /** What the range now points at; nothing when npm could not be asked. */
  readonly want?: string;
  /**
   * The manifest entry as the root held it before this update, which is
   * what a rollback writes back. Nothing for a global root, which keeps no
   * manifest.
   */
  readonly spec?: string;
}

/**
 * A root npm installs into: a directory with its own manifest, or npm's
 * global prefix, which has none.
 *
 * `dir` is what npm is pointed at — the root itself, or the prefix for
 * `--global` — and `modules` is where the packages it installs land: the
 * root's own `node_modules`, or the global root npm reports.
 */
export interface Root {
  readonly kind: "local" | "global";
  readonly dir: string;
  readonly modules: string;
}

/** A root with its own manifest, whose packages sit in its own `node_modules`. */
export function localRoot(dir: string): Root {
  return { kind: "local", dir, modules: path.join(dir, "node_modules") };
}

/**
 * The release the machine moves to: every first-party package, in both
 * roots, at one version.
 *
 * `@amykit/*` is released as one fixed group, so the packages always share a
 * version and a machine holding two of them is half-updated by definition.
 * The release is asked once, of the CLI's registry intent, rather than of
 * each package's caret — on 0.x a caret never crosses a minor, and while
 * this project is on 0.x every release is a minor.
 */
export interface Release {
  /** What the intent resolves to: the version every first-party package moves to. */
  readonly version: string;
  /** The CLI's registry intent it was resolved from. */
  readonly intent: string;
  /** The newest published release, when the intent holds the machine below it. */
  readonly newest?: string;
}

/** What `update` reads off a machine: every package held, and the release. */
export interface Survey {
  readonly held: Held[];
  readonly release?: Release;
}

/** Whether a package is one of this project's own, released in lockstep. */
export function firstParty(name: string): boolean {
  return name.startsWith("@amykit/");
}

/** What one root's manifest asks npm for, by direct package name. */
export function manifestOf(root: string): Record<string, string> {
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf-8")) as Record<
      string,
      unknown
    >;
    const dependencies = parsed.dependencies;
    return typeof dependencies === "object" && dependencies !== null
      ? { ...(dependencies as Record<string, string>) }
      : {};
  } catch {
    return {};
  }
}

/**
 * The registry intent an installed machine carries beside a local tarball.
 *
 * `install.sh` must bootstrap unpublished packages from local tarballs, but
 * the CLI itself still has a registry lifecycle after it is published. This
 * metadata keeps the bootstrap source as the manifest dependency while giving
 * `amy update` the explicit range it may safely resolve and install.
 */
export function updateRangeOf(root: string, name: string, fallback: string): string {
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf-8")) as {
      amyUpdateRanges?: Record<string, unknown>;
    };
    const range = parsed.amyUpdateRanges?.[name];
    return typeof range === "string" ? range : fallback;
  } catch {
    return fallback;
  }
}

/** The version one root's copy of a package carries, or nothing when it is not there. */
export function versionIn(root: string, name: string): string | undefined {
  return versionAt(path.join(root, "node_modules"), name);
}

/** The version the copy under one `node_modules` carries, or nothing. */
function versionAt(modules: string, name: string): string | undefined {
  try {
    const parsed = JSON.parse(
      fs.readFileSync(path.join(modules, ...name.split("/"), "package.json"), "utf-8"),
    ) as { version?: string };
    return typeof parsed.version === "string" ? parsed.version : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Whether a manifest range can move at all.
 *
 * `file:` specs, URLs, git forms and paths are pins: what they name is one
 * place on one machine, and what would move is whatever that place holds
 * now, which no command can discover. A bare name or a semver range is a
 * registry range, and `latest` is one too — an operator who wrote it wants
 * the newest one npm finds. The tilde of `~2.1.0` is a range; only a tilde
 * followed by a slash is a path into the home directory. Spaces do not make
 * a range a pin: `>=1.0.0 <2.0.0` is one registry range npm answers as a
 * whole, and the prefixes above already name every pin form.
 */
export function isRange(range: string): boolean {
  return !(
    /^(?:file:|https?:\/\/|git:\/\/|git\+(?:ssh|https?|file):\/\/|ssh:\/\/|github:|gitlab:|bitbucket:|gist:)/.test(range) ||
    /^[^:/]+@[^:/]+:/.test(range) ||
    /^(?:\/|\.{1,2}\/|~(?:\/|$)|[A-Za-z]:[\\/])/.test(range)
  );
}

/**
 * The version a range points at, asked through npm.
 *
 * `npm view <name>@<range> version` is the question in npm's own words; its
 * answer is the version that satisfies the range today. A machine with no
 * network, or a range npm cannot read, gets an unset `want` rather than a
 * guess, and `--check` reports it as unknown rather than as current.
 */
async function resolveTo(
  runner: CommandRunner,
  name: string,
  range: string,
): Promise<string | undefined> {
  const result = await runner.run(packageManager(), ["view", `${name}@${range}`, "version", "--json"], {
    timeoutMs: 60 * 1000,
  });
  if (!result.ok) return undefined;
  return oneVersion(result.stdout);
}

/** The one version npm reported, when that is what it reported. */
export function oneVersion(stdout: string): string | undefined {
  try {
    const parsed = JSON.parse(stdout) as unknown;
    if (typeof parsed === "string") return parsed;
    // A range that matches several answers with the list, oldest first; the
    // newest one is what the range moves to.
    if (Array.isArray(parsed)) {
      const versions = parsed.filter((entry): entry is string => typeof entry === "string");
      return versions[versions.length - 1];
    }
  } catch {
    return undefined;
  }
  return undefined;
}

/**
 * Every package this machine's two roots hold, with what the ranges in them
 * now point at, and the release the first-party ones move to.
 *
 * A third-party package moves within the range the operator wrote: a 0.x
 * workflow at `^0.1.0` does not jump to 0.2.0, because that is the
 * operator's call. A first-party one moves to the release, whatever caret
 * npm saved for it, and never backwards: a copy already past the release is
 * held where it is.
 */
export async function survey(runner: CommandRunner, home: string, install?: Root): Promise<Survey> {
  const pluginsRoot = path.join(home, "plugins");
  const intent = cliIntent(pluginsRoot, install);
  // Asked once, and only when a first-party package is held at all.
  let release: Release | undefined;
  let asked: Promise<Release | undefined> | undefined;
  const wantFor = async (name: string, range: string, have: string): Promise<string | undefined> => {
    if (!isRange(range)) return undefined;
    if (!firstParty(name) || intent === undefined) return resolveTo(runner, name, range);
    asked ??= releaseFor(runner, intent);
    release = await asked;
    if (release === undefined) return undefined;
    return compareVersions(release.version, have) > 0 ? release.version : have;
  };
  const found: Held[] = [];

  for (const [name, spec] of Object.entries(manifestOf(pluginsRoot))) {
    const have = versionIn(pluginsRoot, name);
    if (!have) continue;
    found.push({ name, range: spec, root: "plugins", have, want: await wantFor(name, spec, have), spec });
  }

  if (install?.kind === "local") {
    for (const [name, dependency] of Object.entries(manifestOf(install.dir))) {
      const range = updateRangeOf(install.dir, name, dependency);
      const have = versionAt(install.modules, name);
      if (!have) continue;
      found.push({ name, range, root: "install", have, want: await wantFor(name, range, have), spec: dependency });
    }
  } else if (install?.kind === "global") {
    // A global prefix keeps no manifest: the CLI is the one package amy put
    // there, and what it moves to is the release.
    const have = versionAt(install.modules, CLI);
    if (have) found.push({ name: CLI, range: intent ?? "latest", root: "install", have, want: await wantFor(CLI, intent ?? "latest", have) });
  }

  return release === undefined ? { held: found } : { held: found, release };
}

/** Every package this machine's two roots hold, without the release around them. */
export async function held(runner: CommandRunner, home: string, install?: Root | string): Promise<Held[]> {
  return (await survey(runner, home, typeof install === "string" ? localRoot(install) : install)).held;
}

const CLI = "@amykit/cli";

/**
 * The CLI's registry intent: the range `update` resolves the release from.
 *
 * The operator's own word comes first — `amyUpdateRanges` in the plugins
 * root's manifest, the one manifest a global install has — then the install
 * root's, which is what `install.sh` writes beside its bootstrap tarball,
 * then that root's dependency, and `latest` when nothing says otherwise. A
 * pin is no intent: a CLI installed from a path has no release to reach, and
 * its first-party packages move within their own ranges as before.
 */
function cliIntent(pluginsRoot: string, install: Root | undefined): string | undefined {
  const local = install?.kind === "local" ? install.dir : undefined;
  // The dependency is only an intent when it is a pin. A registry range there
  // is whatever npm saved — or the `^<release>` this command wrote after the
  // last move — and on 0.x that caret would hold the machine on one minor
  // forever, so the intent stays `latest` unless the operator wrote one.
  const dependency = local === undefined ? undefined : manifestOf(local)[CLI];
  const fallback = dependency !== undefined && !isRange(dependency) ? dependency : "latest";
  const fromInstall = local === undefined ? "latest" : updateRangeOf(local, CLI, fallback);
  const intent = updateRangeOf(pluginsRoot, CLI, fromInstall);
  return isRange(intent) ? intent : undefined;
}

/** The release an intent resolves to, and the newest one when the intent holds below it. */
async function releaseFor(runner: CommandRunner, intent: string): Promise<Release | undefined> {
  const version = await resolveTo(runner, CLI, intent);
  if (version === undefined) return undefined;
  if (intent === "latest") return { version, intent };
  const newest = await resolveTo(runner, CLI, "latest");
  return newest !== undefined && compareVersions(newest, version) > 0 ? { version, intent, newest } : { version, intent };
}

/**
 * Versions by SemVer precedence: the three numbers, then a prerelease before
 * its release, then the prerelease identifiers one by one — numeric ones by
 * value and below any alphanumeric one, a shorter list before a longer one
 * it prefixes. Build metadata is ignored. Without the identifiers, `rc.2`
 * and `rc.1` compare equal and a prerelease tag never moves.
 */
export function compareVersions(a: string, b: string): number {
  const split = (version: string) => {
    const [core = "", ...pre] = version.split("+", 1)[0]!.split("-");
    const numbers = core.split(".").slice(0, 3).map((part) => Number.parseInt(part, 10) || 0);
    return { numbers, pre: pre.length === 0 ? [] : pre.join("-").split(".") };
  };
  const [x, y] = [split(a), split(b)];
  for (let i = 0; i < 3; i += 1) {
    const difference = (x.numbers[i] ?? 0) - (y.numbers[i] ?? 0);
    if (difference !== 0) return difference;
  }
  if (x.pre.length === 0 || y.pre.length === 0) return Number(x.pre.length === 0) - Number(y.pre.length === 0);
  for (let i = 0; i < Math.min(x.pre.length, y.pre.length); i += 1) {
    const difference = compareIdentifiers(x.pre[i]!, y.pre[i]!);
    if (difference !== 0) return difference;
  }
  return x.pre.length - y.pre.length;
}

function compareIdentifiers(a: string, b: string): number {
  const numeric = /^\d+$/;
  if (numeric.test(a) && numeric.test(b)) return Number(a) - Number(b);
  if (numeric.test(a) !== numeric.test(b)) return numeric.test(a) ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** One first-party copy on disk: what it is, and where. */
export interface Copy {
  readonly name: string;
  readonly version: string;
  readonly at: string;
  /** The package whose own `node_modules` holds it; nothing for a root's top level. */
  readonly within?: string;
}

/**
 * Every first-party copy under one `node_modules`, nested copies included.
 *
 * Every package directory is descended into, third-party ones too: a
 * workflow from elsewhere can carry its own `@amykit/core` in its own
 * `node_modules`, and that copy is on the machine as much as the hoisted
 * one. `only` narrows the top level to one package's tree — a global
 * prefix holds the operator's other tools, which are not amy's to read.
 */
export function firstPartyCopies(modules: string, only?: string): Copy[] {
  const found: Copy[] = [];
  const seen = new Set<string>();
  const visit = (directory: string, within: string | undefined): void => {
    const real = realpath(directory);
    if (seen.has(real)) return;
    seen.add(real);
    let own: string | undefined;
    try {
      const { name, version } = JSON.parse(fs.readFileSync(path.join(directory, "package.json"), "utf-8")) as {
        name?: unknown;
        version?: unknown;
      };
      if (typeof name === "string") own = name;
      if (typeof name === "string" && typeof version === "string" && firstParty(name)) {
        found.push(within === undefined ? { name, version, at: directory } : { name, version, at: directory, within });
      }
    } catch {
      // A directory without a readable manifest is not a package; its
      // `node_modules`, if any, is still walked below.
    }
    walk(path.join(directory, "node_modules"), own ?? within);
  };
  const walk = (tree: string, within: string | undefined): void => {
    for (const directory of packagesIn(tree)) visit(directory, within);
  };
  if (only === undefined) walk(modules, undefined);
  else if (fs.existsSync(path.join(modules, ...only.split("/")))) visit(path.join(modules, ...only.split("/")), undefined);
  return found;
}

/** The package directories directly under one `node_modules`, scoped ones included. */
function packagesIn(modules: string): string[] {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(modules, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.flatMap((entry) => {
    if (entry.name.startsWith(".") || !(entry.isDirectory() || entry.isSymbolicLink())) return [];
    const directory = path.join(modules, entry.name);
    return entry.name.startsWith("@") ? packagesIn(directory) : [directory];
  });
}

/**
 * The first-party copies a move left above the release.
 *
 * The CLI and each plugin are installed at the release exactly, but what
 * they depend on is a caret: with 0.7.0 the intent and 0.7.1 published, npm
 * answers their `^0.7.0` with 0.7.1, and the machine holds two versions of
 * one group. No flag constrains that for a global install, so the update
 * reads the trees it wrote and refuses to call such a machine moved. A
 * package the survey held past the release is held there on purpose, and is
 * not a stray.
 */
export function aboveRelease(trees: readonly Copy[], release: string, heldPast: ReadonlySet<string>): Copy[] {
  return trees.filter((copy) => !heldPast.has(copy.name) && compareVersions(copy.version, release) > 0);
}

/**
 * The first-party copies a third-party package holds below the release.
 *
 * A workflow from elsewhere that depends on `@amykit/core@^0.6.0` keeps its
 * own 0.6 core when the machine moves to 0.7.0, and nothing this command can
 * install changes that: the range is that package's, and moving it is its
 * author's release, or the operator's choice to drop it. Refusing would hold
 * the whole machine on the old release until somebody else publishes, so
 * these are named rather than refused.
 */
export function belowRelease(trees: readonly Copy[], release: string): Copy[] {
  return trees.filter((copy) => copy.within !== undefined && !firstParty(copy.within) && compareVersions(copy.version, release) < 0);
}

/**
 * Where the plugins root and the install root are, for this running CLI.
 *
 * The plugins root is state, under amy's home. The install root is derived
 * from where this module resolved from: an installed CLI sits at
 * `<modules>/@amykit/cli/dist/`, so the walk up from this file is one level
 * to `dist`, one to the package, one to the scope and one to the
 * `node_modules` holding it. When a manifest sits beside that `node_modules`
 * it is a local root. When none does, npm is asked for its global root —
 * once, and only then — and a match by real path is the global prefix
 * `npm install -g` wrote. Anything else is a checkout (`packages/cli/dist/`
 * never sits under a `node_modules`), and `update` has no CLI half to move
 * there and says so rather than running npm against a repository.
 */
export async function roots(
  home: string,
  runner: CommandRunner,
  from: URL = new URL(import.meta.url),
  platform: NodeJS.Platform = process.platform,
): Promise<{ plugins: string; install?: Root }> {
  const plugins = path.join(home, "plugins");
  const packageDir = path.dirname(path.dirname(fileURLToPath(from)));
  const modules = path.dirname(path.dirname(packageDir));
  if (path.basename(modules) !== "node_modules") return { plugins };
  if (fs.existsSync(path.join(path.dirname(modules), "package.json"))) {
    return { plugins, install: localRoot(path.dirname(modules)) };
  }
  const global = await globalModules(runner);
  if (global === undefined || realpath(global) !== realpath(modules)) return { plugins };
  // The prefix comes from the path npm reported, not from where this module
  // resolved: Node hands an ES module its real path, so a global
  // `node_modules` that is a symlink would put the prefix under the link's
  // target, and every install and rollback would land in the wrong place.
  return { plugins, install: { kind: "global", dir: globalPrefix(global, platform), modules } };
}

/** npm's global `node_modules`, or nothing when npm could not say. */
async function globalModules(runner: CommandRunner): Promise<string | undefined> {
  const result = await runner.run(packageManager(), ["root", "--global"], { timeoutMs: 60 * 1000 });
  const answer = result.stdout.trim();
  return result.ok && answer !== "" ? answer : undefined;
}

/**
 * The prefix `npm install -g` writes under, from the global root it wrote:
 * `<prefix>/lib/node_modules` on Unix, `<prefix>\node_modules` on Windows.
 */
export function globalPrefix(modules: string, platform: NodeJS.Platform): string {
  const parent = platform === "win32" ? path.win32.dirname(modules) : path.dirname(modules);
  return platform === "win32" ? parent : path.dirname(parent);
}

function realpath(directory: string): string {
  try {
    return fs.realpathSync(directory);
  } catch {
    return path.resolve(directory);
  }
}

/** One line of the report, `--check` and the move's own log the same. */
export function line(held: Held): string {
  const where = held.root === "plugins" ? "plugins" : "install";
  if (!isRange(held.range)) return `${held.name}  ${held.have}  (${where}, pinned: ${held.range})`;
  const wanted = held.want ?? "unknown";
  return `${held.name}  ${held.have} -> ${wanted}  (${where}, ${held.range})`;
}

/**
 * Moves one package to the exact version its range now points at, and
 * writes the root's manifest entry the move leaves behind.
 *
 * The install names the version, not the range: npm is free to answer a
 * range with whatever already satisfies it, which on a machine whose
 * lockfile still holds the old version is the old version — a no-op that
 * reads as success. Naming the version is the one form that moves. The
 * manifest entry is written afterwards, because an install also rewrites it
 * to the exact thing that was installed — and the root's manifest is the
 * operator's record of *why* the package is there. A third-party package
 * keeps the range the operator wrote; a first-party one is given
 * `^<release>`, so the root keeps naming the release it is on rather than a
 * caret that will never reach the next one. A global root keeps no
 * manifest, so there is nothing to write.
 *
 * A refused write is a machine changed past its manifest: the caller must
 * treat the move as `moved` — not merely `failed` — so the update's
 * rollback path puts the whole root back, package and manifest together.
 */
export interface MoveOutcome {
  ok: boolean;
  /** The package was installed, even when the outcome is not ok. */
  installed: boolean;
  command: string;
  output: string;
}

export async function move(
  runner: CommandRunner,
  root: Root | string,
  name: string,
  keep: string | undefined,
  to: string,
): Promise<MoveOutcome> {
  return installExact(runner, typeof root === "string" ? localRoot(root) : root, name, to, keep, "installed");
}

/**
 * Rolls one package back to the version that was on disk, the same way, with
 * the manifest entry it held before the update — or, given none, the one it
 * holds now.
 */
export async function restore(
  runner: CommandRunner,
  root: Root | string,
  name: string,
  to: string,
  keep?: string,
): Promise<MoveOutcome> {
  return installExact(runner, typeof root === "string" ? localRoot(root) : root, name, to, keep, "restored");
}

async function installExact(
  runner: CommandRunner,
  root: Root,
  name: string,
  to: string,
  keep: string | undefined,
  verb: "installed" | "restored",
): Promise<MoveOutcome> {
  const global = root.kind === "global";
  const before = global ? {} : manifestOf(root.dir);
  const outcome = await runWith(runner, [
    "install",
    ...(global ? ["--global"] : []),
    "--prefix",
    root.dir,
    // The plugins root takes every install with the same flags, a restore
    // too: an install without `--install-links` turns a workflow copied in
    // from a path back into a link, whose core import then does not resolve.
    ...(global ? ["--no-audit", "--no-fund"] : PLUGINS_ROOT_FLAGS),
    "--",
    `${name}@${to}`,
  ]);
  if (!outcome.ok) return { ...outcome, installed: false };
  if (global) return { ...outcome, installed: true };
  const writeProblem = writeManifestEntry(root.dir, name, keep ?? before[name]);
  if (writeProblem) {
    return {
      ...outcome,
      ok: false,
      installed: true,
      output: [outcome.output, `${verb} ${name}@${to}, but could not restore its manifest range: ${writeProblem}`]
        .filter(Boolean)
        .join("\n"),
    };
  }
  return { ...outcome, installed: true };
}

async function runWith(
  runner: CommandRunner,
  args: readonly string[],
): Promise<Omit<MoveOutcome, "installed">> {
  const result = await runner.run(packageManager(), [...args], { timeoutMs: 10 * 60 * 1000 });
  return {
    ok: result.ok,
    command: shellCommand(packageManager(), [...args]),
    output: [result.stdout, result.stderr].filter(Boolean).join("\n").trim(),
  };
}

/** Writes one manifest entry: the spec the move or the rollback leaves behind. */
function writeManifestEntry(root: string, name: string, range: string | undefined): string | undefined {
  const file = path.join(root, "package.json");
  try {
    const manifest = JSON.parse(fs.readFileSync(file, "utf-8")) as Record<string, unknown>;
    const dependencies = manifest.dependencies;
    if (typeof dependencies !== "object" || dependencies === null) {
      return "package.json has no dependencies object";
    }
    if (typeof range !== "string") return `package.json had no prior range for ${name}`;
    (dependencies as Record<string, string>)[name] = range;
    fs.writeFileSync(file, `${JSON.stringify(manifest, null, 2)}\n`, "utf-8");
    return undefined;
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
}

/**
 * The config the machine has, rewritten into the shape what reads it expects.
 *
 * A release that stops reading a workflow's vocabulary off the top level
 * still owes the machine its tuned values: the update is the one moment an
 * operator is already accepting changes, so this is where the old blocks
 * move — under the profiles mounting the workflow that reads each, or beside
 * the plugin whose slice names them — and the file as it was is kept at
 * `config.yaml.moved`, for the person to read and for a rollback to point at.
 * A file with none of the moved keys left changes nothing, so running this
 * twice is one move.
 *
 * The edit goes through the document, not a restringify of parsed values:
 * the comments that explain each setting are most of the file's value, and
 * they are kept the way every other config writer keeps them.
 */
export interface SettingsMoved {
  ok: boolean;
  /** What moved, said the way the operator would read it. */
  said: string[];
  /** The file the original was kept at, when it moved. */
  movedTo?: string;
}

/** The first-party workflows that read each of the moved top-level keys. */
const READ_BY_WORKFLOW: ReadonlyMap<string, readonly string[]> = new Map([
  ["policy", ["@amykit/workflow-ticket-to-qa"]],
  ["qaStatusName", ["@amykit/workflow-ticket-to-qa"]],
  ["plans", ["@amykit/workflow-note-to-plan"]],
  ["errands", ["@amykit/workflow-errand"]],
  // The tracker's two did not move under a workflow at all: the profile that
  // reads them is wherever the linear plugin mounts, so the migration puts
  // them under `plugins: "@amykit/plugin-linear"` whether or not the machine
  // had named a plugins block.
  ["workingStatusName", ["@amykit/plugin-linear"]],
  ["repoByTeam", ["@amykit/plugin-linear"]],
]);

/** What `settings` under one profile gets for one moved top-level key. */
function settingsFor(key: string, value: unknown): Record<string, unknown> | undefined {
  if (key === "plans") return plansSettings(value);
  if (key === "qaStatusName") {
    return typeof value === "string" ? { qaStatusName: value } : undefined;
  }
  if (key === "policy" || key === "errands") return ceilingSettings(key, value);
  return undefined;
}

/** The plans block's repos, gate keepers and ceilings, as the planner's settings. */
function plansSettings(value: unknown): Record<string, unknown> | undefined {
  if (!isPlain(value)) return undefined;
  const block = value as { repos?: unknown; check?: unknown; policy?: unknown };
  const settings: Record<string, unknown> = {};
  if (Array.isArray(block.repos)) settings.repos = block.repos;
  if (isPlain(block.check)) settings.check = block.check;
  // The ceilings the planner reads rode under this block too, and they are
  // the workflow's policy, which today lives under `settings.policy`.
  if (isPlain(block.policy)) settings.policy = block.policy;
  return Object.keys(settings).length > 0 ? settings : undefined;
}

/** The ceilings block, or the ceilings nested under the errands block, as-is. */
function ceilingSettings(key: string, value: unknown): Record<string, unknown> | undefined {
  const policy = key === "errands" ? (isPlain(value) ? (value as { policy?: unknown }).policy : undefined) : value;
  if (!isPlain(policy)) return undefined;
  return Object.keys(policy).length > 0 ? { policy } : undefined;
}

function isPlain(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * The workspace's moved keys, each under the plugin whose slice carries it.
 *
 * The machine keeps none of the seven: the repositories, the checkout root
 * and map, the two branch settings and the worktrees are the file-worktree
 * plugin's slice, and the gate commands the command-gate plugin's — the same
 * move the workflows' vocabulary took, one layer down.
 */
const READ_BY_PLUGIN: ReadonlyMap<string, readonly string[]> = new Map([
  ["repos", ["@amykit/plugin-file-worktree"]],
  ["workspaceRoot", ["@amykit/plugin-file-worktree"]],
  ["checkouts", ["@amykit/plugin-file-worktree"]],
  ["defaultBranch", ["@amykit/plugin-file-worktree"]],
  ["baseBranch", ["@amykit/plugin-file-worktree"]],
  ["worktrees", ["@amykit/plugin-file-worktree"]],
  ["gate", ["@amykit/plugin-command-gate"]],
]);

export function migrateSettingsFile(home: string): SettingsMoved {
  const place = paths(home).config;
  if (!fs.existsSync(place)) return { ok: true, said: [] };
  const text = fs.readFileSync(place, "utf-8");
  const document = yaml.parseDocument(text);
  if (document.errors.length > 0) {
    return { ok: false, said: [`could not parse ${place}: ${document.errors[0]!.message}`] };
  }
  const top = document.contents;
  if (!yaml.isMap(top)) return { ok: true, said: [] };

  const said: string[] = [];
  const workflows = entryOf(top, "workflows");
  const dropped = moveRetiredKeys(document, top, workflows, said);
  const parsed = { ...DEFAULT_CONFIG, ...(document.toJS() as Record<string, unknown>) } as AmyConfig;
  const foldedByName = convergeProjectProfiles(home, workflows, said, parsed);
  foldDefaultWorkflow(top, foldedByName, said);
  const converged = foldedByName.size > 0;

  // An old EXAMPLE always named the QA status, but a hand-written ticket
  // profile can name none of the retired keys and still lean on the
  // implicit default the old loader supplied: materializing it changes the
  // file even when nothing moved from place to place, so it is answered
  // before deciding that no migration is needed at all.
  const materialized = materializeTicketStatus(document, top, said);
  // A command-gate slice an older install wrote is put right whether or not
  // a top-level key moved into it: its `commands` and `checkouts` were valid
  // there, and the slice's schema now refuses both by name at boot.
  const normalized = normalizeCommandGateSlice(document, top, said);

  if (dropped.length === 0 && !materialized && !converged && !normalized) return { ok: true, said: [] };

  const movedTo = `${place}.moved`;
  // The kept file is the machine's config before its first move, a byte the
  // operator can always go back to; rewriting it now would archive a state
  // that already moved the way the file beside it now says it did.
  if (!fs.existsSync(movedTo)) fs.writeFileSync(movedTo, text, "utf-8");
  fs.writeFileSync(place, String(document), "utf-8");
  return { ok: true, said, movedTo };
}

/** One retired key's journey from the top level to the workflow that reads it.
 *
 * Every retired key is taken off the top: where something mounted reads it,
 * the move places it and says so; where nothing does, the file it would make
 * unmountable loses it and the backup keeps the operator's bytes. The walk
 * returns what it moved off, so the caller knows whether the file changed at
 * all — materializing a default the file never had is a change the move did
 * not make, and only the two kinds together decide that no update is due. */
function moveRetiredKeys(
  document: yaml.Document,
  top: yaml.YAMLMap,
  workflows: ReturnType<typeof entryOf>,
  said: string[],
): string[] {
  const dropped: string[] = [];
  for (const [key, readers] of [...READ_BY_WORKFLOW, ...READ_BY_PLUGIN]) {
    const entry = entryOf(top, key);
    if (entry === undefined) continue;
    const value = unwrap(entry.value);

    const moved = (readers !== undefined ? moveIntoWorkflows(workflows, key, value, readers) : false) ||
      moveToTrackerSlice(document, top, key, entry) ||
      moveIntoPluginSlice(document, top, key, entry);

    if (!moved) {
      // An init-era block nobody mounted still names itself at the top
      // level, and a later boot refuses it by name: the move takes it out
      // of the file it would break, keeps the original beside the move, and
      // says what became of it rather than leaving a machine that cannot
      // mount after the one command built to fix the file.
      top.delete(key);
      dropped.push(key);
      said.push(`${key}: nothing mounted reads it; kept only in the backup`);
      continue;
    }
    top.delete(key);
    dropped.push(key);
    const where = key === "workingStatusName" || key === "repoByTeam"
      ? "the linear plugin's slice"
      : READ_BY_PLUGIN.has(key)
        ? `the ${READ_BY_PLUGIN.get(key)![0]!.replace("@amykit/", "")} plugin's slice`
        : `the ${readers.map((one) => one.replace("@amykit/", "")).join(", ")} workflow's profile settings`;
    said.push(`${key}: moved to ${where}`);
  }
  return dropped;
}

/**
 * A machine the old EXAMPLE wrote always named its QA status, but one edited
 * by hand may not have: the ticket schema requires the status, no slice
 * supplies it any more, and a machine this update touches cannot be left
 * without a value the mount will refuse. The ticket's profile gains what
 * init would have written, said the way a move is said.
 */
function materializeTicketStatus(document: yaml.Document, top: yaml.YAMLMap, said: string[]): boolean {
  const workflowsMap = entryOf(top, "workflows");
  if (workflowsMap === undefined || !yaml.isMap(workflowsMap.value)) return false;
  let wrote = false;
  for (const item of workflowsMap.value.items) {
    const profile = item.value;
    if (!yaml.isMap(profile) || unwrap(profile.get("workflow")) !== "@amykit/workflow-ticket-to-qa") continue;
    if (entryOf(top, "qaStatusName") !== undefined) continue;
    const settingsMap = profile.get("settings");
    // A profile that already names the status was placed by the move above,
    // not left behind by init: saying so again would rewrite a file that did
    // not drift, and an update nobody sees say something twice.
    if (yaml.isMap(settingsMap) && settingsMap.has("qaStatusName")) continue;
    if (yaml.isMap(settingsMap)) {
      settingsMap.add(new yaml.Pair("qaStatusName", "In QA"));
    } else {
      profile.add(new yaml.Pair("settings", toMap({ qaStatusName: "In QA" })));
    }
    said.push("qaStatusName: set to In QA, the value init wrote, which the ticket workflow requires");
    wrote = true;
  }
  return wrote;
}

/**
 * Places one moved key's settings under every profile that declares a
 * workflow known to read it, and says whether any profile took it.
 */
function moveIntoWorkflows(
  workflows: yaml.Pair | undefined,
  key: string,
  value: unknown,
  readers: readonly string[],
): boolean {
  if (workflows === undefined || !yaml.isMap(workflows.value)) return false;

  let placed = false;
  for (const item of workflows.value.items) {
    const profile = item.value;
    if (!yaml.isMap(profile)) continue;
    const workflow = profile.get("workflow");
    if (typeof workflow !== "string" || !readers.includes(workflow)) continue;
    const settings = settingsFor(key, value);
    if (settings === undefined) continue;
    if (!placeProfileSettings(profile, settings)) continue;
    placed = true;
  }
  return placed;
}

/** Adds the moved settings to a profile's own map, as `amy add` would write them. */
function placeProfileSettings(profile: yaml.YAMLMap, settings: Record<string, unknown>): boolean {
  const settingsMap = profile.get("settings");
  if (yaml.isMap(settingsMap)) {
    for (const [name, to] of Object.entries(settings)) if (!settingsMap.has(name)) settingsMap.add(new yaml.Pair(name, to));
    return true;
  }
  profile.add(new yaml.Pair("settings", toMap(settings)));
  return true;
}

/**
 * Puts the tracker's two moved keys in the mounted tracker's slice, and when
 * the machine never named a plugins block, writes one the way `amy add`
 * would — the tracker's slice beside whatever else lands there later.
 *
 * Read fresh each time the function runs: the first of the tracker's keys
 * may have created the plugins block that the second needs.
 */
function moveToTrackerSlice(
  document: yaml.Document,
  top: yaml.YAMLMap,
  key: string,
  entry: yaml.Pair,
): boolean {
  if (key !== "workingStatusName" && key !== "repoByTeam") return false;

  const mounted = entryOf(top, "plugins");
  if (mounted !== undefined && yaml.isMap(mounted.value)) {
    const linear = mounted.value.get("@amykit/plugin-linear");
    if (yaml.isMap(linear)) {
      if (linear.get(key) === undefined) linear.add(new yaml.Pair(key, entry.value));
    } else {
      mounted.value.add(new yaml.Pair("@amykit/plugin-linear", toMap({ [key]: entry.value })));
    }
  } else {
    // Built through the document, so the nodes the parser would have made
    // are the nodes the file gets written back with. The write goes
    // through the document's own type, which the parser narrows further
    // than a node made now can satisfy.
    const block = document.createNode({ "@amykit/plugin-linear": { [key]: unwrap(entry.value) } });
    const added = new yaml.Pair(document.createNode("plugins"), block);
    top.set?.(added.key as never, added.value as never);
  }
  return true;
}

/**
 * Puts one moved workspace key in the plugin slice that reads it now, and
 * when the machine never named a plugins block, writes one the way `amy add`
 * would — the owner's slice beside whatever else lands there later.
 *
 * A block moves whole: the worktrees block splits into the root and the
 * retention the slice spells, and the gate's slice takes the gate key. The
 * walk reads the plugins block fresh each time, the way the tracker's move
 * does, because the first key may have created it.
 */
function moveIntoPluginSlice(
  document: yaml.Document,
  top: yaml.YAMLMap,
  key: string,
  entry: yaml.Pair,
): boolean {
  const owner = READ_BY_PLUGIN.get(key);
  if (!owner) return false;
  const plugin = owner[0]!;

  // The value moves under its owner's slice, spelled the way that slice
  // does: the worktrees block splits into the root and the retention, and
  // every other key keeps its name.
  const value = unwrap(entry.value);
  const carried: Record<string, unknown> =
    key === "worktrees" && isPlain(value)
      ? Object.fromEntries(Object.entries(value).filter(([name]) => name === "root" || name === "retentionDays"))
      : { [key]: value };

  const mounted = entryOf(top, "plugins");
  if (mounted !== undefined && yaml.isMap(mounted.value)) {
    const slice = mounted.value.get(plugin);
    if (yaml.isMap(slice)) {
      // The retired name goes first, so a value the machine carries beside
      // it lands on the name it now answers to.
      renameRetiredCommands(plugin, slice);
      for (const [name, moved] of Object.entries(carried)) {
        const existing = slice.get(name);
        if (existing === undefined) {
          slice.add(new yaml.Pair(name, moved));
          continue;
        }
        // A leaf the slice already names is the operator's own; what the
        // machine carried merges in beside it, the slice winning where both
        // name the same thing.
        const merged = mergeLeaves(unwrap(moved), unwrap(existing));
        if (merged !== undefined) {
          // The map's own setter keeps the pair in place; a raw key is what
          // `add` wrote before it, which `set` matches the same way.
          slice.set(name, document.createNode(merged));
        }
      }
    } else {
      mounted.value.add(new yaml.Pair(plugin, toMap(carried)));
      renameRetiredCommands(plugin, mounted.value.get(plugin) as yaml.YAMLMap);
    }
  } else {
    const block = document.createNode({ [plugin]: carried });
    const added = new yaml.Pair(document.createNode("plugins"), block);
    top.set?.(added.key as never, added.value as never);
  }
  return true;
}

/** What the two records carry together, the slice's own leaves winning over the machine's. */
function mergeLeaves(moved: unknown, existing: unknown): Record<string, unknown> | undefined {
  if (!isPlain(moved) || !isPlain(existing)) return undefined;
  return { ...moved, ...existing };
}

/**
 * The gate's commands were the slice's only name for the gate, and the top
 * level `gate:` was the machine's; both names now are one. A slice an older
 * install wrote as `commands:` is carried onto `gate:` with nothing left
 * behind, so a machine the move touches keeps running its checks.
 */
function renameRetiredCommands(plugin: string, slice: yaml.YAMLMap): void {
  if (plugin !== "@amykit/plugin-command-gate") return;
  const commands = slice.get("commands");
  if (commands !== undefined && slice.get("gate") === undefined) {
    slice.delete("commands");
    slice.add(new yaml.Pair("gate", commands));
  }
}

/**
 * The command-gate slice as an older install wrote it, put into the shape
 * its schema reads now.
 *
 * `commands` is the gate under its retired name: it becomes `gate`, and
 * where the slice already names a gate the two merge with the gate's own
 * leaves winning. `checkouts` is the workspace's answer now: it moves into
 * the file-worktree plugin's slice, whose own entries win, and an empty one
 * is simply dropped. Says each change; a slice already in shape is left
 * untouched, so a second update moves nothing.
 */
function normalizeCommandGateSlice(document: yaml.Document, top: yaml.YAMLMap, said: string[]): boolean {
  const mounted = entryOf(top, "plugins");
  if (mounted === undefined || !yaml.isMap(mounted.value)) return false;
  const slice = mounted.value.get(COMMAND_GATE);
  if (!yaml.isMap(slice)) return false;
  const renamed = renameSliceCommands(document, slice, said);
  const moved = moveSliceCheckouts(document, mounted.value, slice, said);
  return renamed || moved;
}

const COMMAND_GATE = "@amykit/plugin-command-gate";
const FILE_WORKTREE = "@amykit/plugin-file-worktree";

/** `commands` onto `gate`, the gate's own leaves winning where the slice names both. */
function renameSliceCommands(document: yaml.Document, slice: yaml.YAMLMap, said: string[]): boolean {
  const commands = slice.get("commands");
  if (commands === undefined) return false;
  const gate = slice.get("gate");
  slice.delete("commands");
  if (gate === undefined) {
    slice.add(new yaml.Pair("gate", commands));
  } else {
    const merged = mergeLeaves(unwrap(commands), unwrap(gate));
    if (merged !== undefined) slice.set("gate", document.createNode(merged));
  }
  said.push(`${COMMAND_GATE} commands: renamed to gate`);
  return true;
}

/** `checkouts` into the file-worktree slice, whose own entries win; an empty one is dropped. */
function moveSliceCheckouts(document: yaml.Document, plugins: yaml.YAMLMap, slice: yaml.YAMLMap, said: string[]): boolean {
  const checkouts = slice.get("checkouts");
  if (checkouts === undefined) return false;
  slice.delete("checkouts");
  const carried = unwrap(checkouts);
  if (!isPlain(carried) || Object.keys(carried).length === 0) {
    said.push(`${COMMAND_GATE} checkouts: empty, and the workspace answers it now; dropped`);
    return true;
  }
  const workspace = plugins.get(FILE_WORKTREE);
  if (yaml.isMap(workspace)) {
    const existing = workspace.get("checkouts");
    const merged = existing === undefined ? carried : mergeLeaves(carried, unwrap(existing));
    if (merged !== undefined) workspace.set("checkouts", document.createNode(merged));
  } else {
    plugins.add(new yaml.Pair(FILE_WORKTREE, toMap({ checkouts: carried })));
  }
  said.push(`${COMMAND_GATE} checkouts: moved to the plugin-file-worktree plugin's slice`);
  return true;
}

/** The top-level entry one key names, whether or not it has a value. */
function entryOf(map: yaml.YAMLMap, key: string): yaml.Pair | undefined {
  return map.items.find((item) => yaml.isPair(item) && isKey(item, key)) as yaml.Pair | undefined;
}

/** Groups the config's profiles by the project root their workflow folder names. */
function projectGroupsOf(
  home: string,
  workflows: yaml.Pair,
): Map<string, { name: string; profile: yaml.YAMLMap; spec: string }[]> {
  const groups = new Map<string, { name: string; profile: yaml.YAMLMap; spec: string }[]>();
  for (const item of (workflows.value as yaml.YAMLMap).items) {
    if (!yaml.isPair(item) || !yaml.isScalar(item.key)) continue;
    if (!yaml.isMap(item.value)) continue;
    const spec = unwrap(item.value.get("workflow"));
    const root = projectRootOf(home, spec);
    if (root === undefined) continue;
    const group = groups.get(root) ?? [];
    group.push({ name: String(item.key.value), profile: item.value, spec: String(spec) });
    groups.set(root, group);
  }
  return groups;
}

/** Folds one project's phase profiles into the single entry the walk is driven by. */
function foldOneProject(
  home: string,
  root: string,
  group: { name: string; profile: yaml.YAMLMap; spec: string }[],
  workflows: yaml.Pair,
  said: string[],
  parsed: AmyConfig,
): { readonly kept: string; readonly folded: readonly string[] } {
  const kept = group.find((one) => path.basename(one.spec) === "workflow") ?? group[0]!;
  const others = group.filter((one) => one !== kept);
  const workFolder = path.join(root, "workflow");
  for (const one of others) said.push(`${one.name}: folded into \`${kept.name}\`, the single profile the project at ${root} walks`);
  const keptWorkflow = unwrap(kept.profile.get("workflow"));
  const keepsWorkPhase = typeof keptWorkflow === "string" && path.resolve(home, keptWorkflow) === workFolder;
  if (fs.existsSync(workFolder) && !keepsWorkPhase) {
    const field = (kept.profile as yaml.YAMLMap).items.find((item) => yaml.isPair(item) && isKey(item, "workflow")) as yaml.Pair | undefined;
    if (field) field.value = new yaml.Scalar(workFolder);
    said.push(`${kept.name}: names ${workFolder} now, the project's work phase`);
  }
  for (const one of others) {
    carryProfileFields(home, root, { name: kept.name, profile: kept.profile }, one.profile, one.name, said, parsed);
    (workflows.value as yaml.YAMLMap).delete(one.name);
  }
  return { kept: kept.name, folded: others.map((one) => one.name) };
}

/**
 * Turns one project's phase profiles into the project's single profile.
 *
 * A project is one profile and one daemon now: its phases are child records
 * of the project's record, walked by the one workflow the project's folders
 * compose. A config that still names the brief, the work and the proof as
 * three entries is rewritten down to the one entry naming the work folder —
 * the entry the walk is driven by — and everything the dropped entries
 * carried is carried into it or said. Nothing is moved twice: a config
 * already carrying one entry per project changes nothing.
 */
function convergeProjectProfiles(
  home: string,
  workflows: yaml.Pair | undefined,
  said: string[],
  parsed: AmyConfig,
): Map<string, string> {
  if (workflows === undefined || !yaml.isMap(workflows.value)) return new Map();
  const foldedByName = new Map<string, string>();
  for (const [root, group] of projectGroupsOf(home, workflows)) {
    if (group.length < 2) continue;
    const folded = foldOneProject(home, root, group, workflows, said, parsed);
    for (const name of folded.folded) foldedByName.set(name, folded.kept);
  }
  return foldedByName;
}

/**
 * Where a config's top-level selector points, once one of the profiles it
 * named folded: at the single profile the project walks now. A selector left
 * on a folded name leaves every command without `--workflow` failing to
 * resolve the one profile that survived.
 */
function foldDefaultWorkflow(
  top: yaml.YAMLMap,
  foldedByName: Map<string, string>,
  said: string[],
): void {
  const defaultEntry = entryOf(top, "defaultWorkflow");
  const wanted = defaultEntry && yaml.isScalar(defaultEntry.value) ? defaultEntry.value.value : undefined;
  const kept = typeof wanted === "string" ? foldedByName.get(wanted) : undefined;
  if (kept === undefined || defaultEntry === undefined) return;
  defaultEntry.value = new yaml.Scalar(kept);
  said.push(`the default workflow \`${wanted}\` folded into \`${kept}\` and names what the project walks now`);
}

/** Carries a folded profile's agent block when the single one carried none. */
function carryAgent(
  kept: { name: string; profile: yaml.YAMLMap },
  folded: yaml.YAMLMap,
  name: string,
  said: string[],
): void {
  if (kept.profile.get("agent") !== undefined) return;
  const agent = folded.get("agent");
  if (agent === undefined) return;
  kept.profile.add(new yaml.Pair("agent", agent));
  said.push(`${name}: its agent block moved to \`${kept.name}\`, which carried none`);
}

/** A phase's work is the project's alone: flags, brief store, plugins and settings it carried move in, each said. */
function carryOwnState(
  home: string,
  root: string,
  kept: { name: string; profile: yaml.YAMLMap },
  folded: yaml.YAMLMap,
  said: string[],
  parsed: AmyConfig,
): void {
  for (const flag of ["notes", "tasks"] as const) {
    if (folded.get(flag) !== true) continue;
    const ownFlag = kept.profile.get(flag);
    // A flag the survivor never said is carried; an explicit value the
    // survivor wrote by hand is a choice, and is left standing, said.
    if (ownFlag === undefined) kept.profile.add(new yaml.Pair(flag, true));
    else if (ownFlag !== true) said.push(`\`${kept.name}\` keeps \`${flag}\` off by hand, so the folded phase's want for it is left off`);
  }
  const briefStore = folded.get("briefStore");
  if (briefStore !== undefined && kept.profile.get("briefStore") === undefined) kept.profile.add(new yaml.Pair("briefStore", briefStore));
  carryPlugins(home, root, kept, folded, said, parsed);
  carrySettings(kept, folded);
}

/** Mounts a folded phase's plugins, keeping only the ones another project does not already mount. */
function carryPlugins(
  home: string,
  root: string,
  kept: { name: string; profile: yaml.YAMLMap },
  folded: yaml.YAMLMap,
  said: string[],
  parsed: AmyConfig,
): void {
  const plugins = folded.get("plugins");
  if (!yaml.isSeq(plugins)) return;
  const foldedSpecs = plugins.items.map((item) => String(unwrap(item)));
  let mounted = kept.profile.get("plugins");
  if (!yaml.isSeq(mounted)) {
    // A survivor that says nothing about what it mounts picks what the
    // machine can serve at boot, the way the mount would have picked it —
    // a channel nobody configured does not ride along — and the folded
    // phases' plugins ride beside that set.
    const effective = parsed;
    const survivor = {
      name: kept.name,
      workflow: String(kept.profile.get("workflow") ?? ""),
      plugins: [],
      takesNotes: false,
      takesTasks: false,
      settings: {},
      ...(kept.profile.get("agent") !== undefined ? { agent: unwrap(kept.profile.get("agent")) as Profile["agent"] } : {}),
    } as Profile;
    mounted = new yaml.YAMLSeq();
    const seen = new Set<string>();
    for (const spec of [...pluginList(effective, survivor), ...foldedSpecs]) {
      if (projectRootOf(home, spec) !== undefined && path.resolve(spec) !== path.resolve(survivor.workflow)) continue;
      if (seen.has(spec)) continue;
      seen.add(spec);
      (mounted as yaml.YAMLSeq).add(new yaml.Scalar(spec));
    }
    kept.profile.set("plugins", mounted);
    said.push(`${kept.name}: keeps the mounts it was going to be recommended, and carries the folded phases' plugins beside them`);
  }
  for (const spec of foldedSpecs) {
    if (projectRootOf(home, spec) === root) continue;
    if (!(mounted as yaml.YAMLSeq).items.some((one) => unwrap(one) === spec)) (mounted as yaml.YAMLSeq).add(new yaml.Scalar(spec));
  }
}

/** Carries a folded phase's settings into the single profile's own, filling only what is unset. */
function carrySettings(
  kept: { name: string; profile: yaml.YAMLMap },
  folded: yaml.YAMLMap,
): void {
  const settings = folded.get("settings");
  if (!yaml.isMap(settings)) return;
  const own = kept.profile.get("settings");
  if (yaml.isMap(own)) {
    mergeUnsetSettings(own, settings);
  } else if (kept.profile.get("settings") === undefined) {
    kept.profile.add(new yaml.Pair("settings", settings));
  } else {
    kept.profile.set("settings", settings);
  }
}

/** Carries only leaves the survivor did not write, including within nested setting groups. */
function mergeUnsetSettings(kept: yaml.YAMLMap, folded: yaml.YAMLMap): void {
  for (const pair of folded.items) {
    const key = String(unwrap(pair.key));
    const own = kept.get(key, true);
    if (own === undefined) {
      kept.add(new yaml.Pair(pair.key, pair.value));
    } else if (yaml.isMap(own) && yaml.isMap(pair.value)) {
      mergeUnsetSettings(own, pair.value);
    }
  }
}

/** Carries one folded profile's agent, flags, brief store, plugins and settings into the single one, saying every carry. */
function carryProfileFields(
  home: string,
  root: string,
  kept: { name: string; profile: yaml.YAMLMap },
  folded: yaml.YAMLMap,
  name: string,
  said: string[],
  parsed: AmyConfig,
): void {
  // The project's one profile carries the work phase's agent when it has
  // one; a folded phase's own block is said, because the ladder it tuned is
  // not the ladder the single profile drives.
  carryAgent(kept, folded, name, said);
  carryOwnState(home, root, kept, folded, said, parsed);
}

/** Whether a spec is one of the project's own phase folders, which the walk calls and nothing mounts. */
function projectRootOf(home: string, spec: unknown): string | undefined {
  if (typeof spec !== "string") return undefined;
  const resolved = spec.startsWith(".") ? path.resolve(home, spec) : path.resolve(spec);
  if (!fs.existsSync(resolved)) return undefined;
  const folder = path.basename(resolved);
  if (!["brief", "workflow", "prove", "test"].includes(folder)) return undefined;
  return path.resolve(resolved, "..");
}

/** Whether a document item's key is this string, however it was parsed. */
function isKey(item: yaml.Pair, key: string): boolean {
  const name = item.key;
  return yaml.isScalar(name) && name.value === key;
}

/** A plain value for a YAML node, when it holds one. */
function unwrap(node: unknown): unknown {
  if (yaml.isScalar(node)) return node.value;
  if (yaml.isMap(node) || yaml.isSeq(node)) return node.toJSON();
  return node;
}

function toMap(value: Record<string, unknown>): yaml.YAMLMap {
  const map = new yaml.YAMLMap();
  for (const [key, item] of Object.entries(value)) map.add(new yaml.Pair(key, item));
  return map;
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { CommandRunner, DIAGRAM_FILE } from "@amykit/core";
import { packageEntrySpecifier } from "./spec.js";
import { workflowsDirectory } from "./workflow.js";
import { fetchSource, sourceOfManifest } from "./fork.js";

interface Manifest {
  name?: string;
  main?: unknown;
  exports?: unknown;
  dependencies?: Record<string, string>;
}

/** Where a copied callee comes from: its root, its entry, and what it says it depends on. */
interface Source {
  readonly root: string;
  readonly entry: string;
  readonly manifest: Manifest;
}

/** One file to copy, and the relative specifiers in it that have to be rewritten to the file they reached. */
interface Copied {
  readonly file: string;
  readonly rewrites: ReadonlyMap<string, string>;
}

export interface AddInto {
  readonly runner: CommandRunner;
  /** Where a package specifier is resolved from: the plugins amy installed. */
  readonly pluginsRoot?: string;
}

export interface AddedInto {
  /** The directory the copy is in. */
  readonly directory: string;
  /** The copied entry, which is what the caller imports. */
  readonly entry: string;
}

/**
 * Copies a workflow into another one's directory, so the caller owns it: its
 * diagram, its entry and every file the entry imports by a relative path,
 * and its manifest — and the same for any workflow it imports in turn. What
 * it depends on is added to the caller's manifest and installed, and a
 * dependency that cannot be resolved, or that the caller already holds at a
 * version the copy cannot use, refuses the copy before anything is written.
 *
 * Nothing updates the copy afterwards. That is the point of it — the way
 * shadcn/ui hands out a component: the source becomes the caller's to read
 * and change — and it is called the same way the package would be.
 */
export async function addWorkflowInto(home: string, spec: string, into: string, options: AddInto): Promise<AddedInto> {
  const caller = path.join(workflowsDirectory(home), into);
  const callerManifest = path.join(caller, "package.json");
  if (!fs.existsSync(callerManifest)) {
    throw new Error(`there is no workflow of your own called \`${into}\` under ${workflowsDirectory(home)}; write one with \`amy workflow new ${into}\``);
  }
  const located = await sourceOf(spec, options.pluginsRoot ?? path.join(home, "plugins"), options.runner);
  try {
    return await copyInto(caller, callerManifest, located.source, spec, options);
  } finally {
    located.dispose();
  }
}

async function copyInto(caller: string, callerManifest: string, source: Source, spec: string, options: AddInto): Promise<AddedInto> {
  const name = copyName(source);
  const target = path.join(caller, "workflows", name);
  if (fs.existsSync(target)) throw new Error(`${target} already exists; it is yours to edit there, or remove it first`);

  const files = filesOf(source);
  const owned = JSON.parse(fs.readFileSync(callerManifest, "utf-8")) as Manifest;
  const needed = await dependenciesToInstall(source, files, owned, caller, options.runner, spec);

  for (const { file, rewrites } of files) {
    const to = path.join(target, path.relative(source.root, file));
    fs.mkdirSync(path.dirname(to), { recursive: true });
    if (rewrites.size === 0) {
      fs.copyFileSync(file, to);
      continue;
    }
    let text = fs.readFileSync(file, "utf-8");
    for (const [written, reached] of rewrites) text = text.split(`"${written}"`).join(`"${reached}"`).split(`'${written}'`).join(`'${reached}'`);
    fs.writeFileSync(to, text, "utf-8");
  }
  const entry = path.join(target, path.relative(source.root, source.entry));
  if (needed.length === 0) return { directory: target, entry };
  const installed = await options.runner.run("npm", ["install", "--no-audit", "--no-fund", ...needed], { cwd: caller });
  if (!installed.ok) {
    throw new Error(`copied ${name} into ${target}, and installing what it depends on failed: ${installed.stderr || installed.stdout}`);
  }
  return { directory: target, entry };
}

/**
 * A path to a directory or an entry, or a package installed where amy keeps
 * its plugins. An installed package is copied from its source, not its
 * `dist`: the repository its manifest names, at the tag its installed version
 * was released under (S12), so the copy is code a person reads and edits.
 */
async function sourceOf(spec: string, pluginsRoot: string, runner: CommandRunner): Promise<{ source: Source; dispose: () => void }> {
  const local = path.resolve(spec);
  if (fs.existsSync(local)) {
    const directory = fs.statSync(local).isDirectory();
    const root = directory ? local : packageRootOf(path.dirname(local)) ?? path.dirname(local);
    const manifest = manifestAt(root);
    return { source: { root, entry: directory ? entryOf(root, manifest) : local, manifest }, dispose: () => {} };
  }
  // Read off the directory rather than resolved through the package: a
  // package whose `exports` names only `.` refuses `pkg/package.json`.
  const installed = path.join(pluginsRoot, "node_modules", ...spec.split("/"));
  if (!fs.existsSync(path.join(installed, "package.json"))) {
    throw new Error(`${spec} is neither a path nor a package installed under ${pluginsRoot}; \`amy add ${spec}\` installs it first`);
  }
  const fetched = await fetchSource(runner, sourceOfManifest(manifestAt(installed), spec), spec);
  try {
    const manifest = manifestAt(fetched.directory);
    return { source: { root: fetched.directory, entry: sourceEntryOf(fetched.directory, manifest), manifest }, dispose: fetched.dispose };
  } catch (error) {
    fetched.dispose();
    throw error;
  }
}

/**
 * The source file a package's built entry is compiled from: the declared
 * entry when it is there, and otherwise the same path under the tsconfig's
 * `rootDir` instead of its `outDir`, as TypeScript rather than JavaScript.
 */
function sourceEntryOf(root: string, manifest: Manifest): string {
  if (manifest.exports === undefined && manifest.main === undefined) return entryOf(root, manifest);
  // The source a declared entry is compiled from wins over the entry itself:
  // a repository that also commits its build would otherwise hand out `dist`.
  const declared = fileURLToPath(packageEntrySpecifier(root));
  const options = tsconfigOptions(root);
  const outDir = path.resolve(root, options.outDir ?? "dist");
  const rootDir = path.resolve(root, options.rootDir ?? "src");
  const relative = path.relative(outDir, declared);
  const candidates = relative.startsWith("..") ? [] : [path.join(rootDir, relative.replace(/\.js$/, ".ts")), path.join(rootDir, relative)];
  const entry = [...candidates, declared].find((candidate) => fs.existsSync(candidate));
  if (!entry) throw new Error(`${root} declares ${path.relative(root, declared)} as its entry, and its source has neither it nor the file it is compiled from`);
  return entry;
}

function tsconfigOptions(root: string): { outDir?: string; rootDir?: string } {
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(root, "tsconfig.json"), "utf-8")) as { compilerOptions?: { outDir?: string; rootDir?: string } };
    return parsed.compilerOptions ?? {};
  } catch {
    return {};
  }
}

function manifestAt(root: string): Manifest {
  const file = path.join(root, "package.json");
  return fs.existsSync(file) ? (JSON.parse(fs.readFileSync(file, "utf-8")) as Manifest) : {};
}

function packageRootOf(from: string): string | undefined {
  for (let directory = from; ; directory = path.dirname(directory)) {
    if (fs.existsSync(path.join(directory, "package.json"))) return directory;
    if (path.dirname(directory) === directory) return undefined;
  }
}

/**
 * The file a workflow is entered by: what its manifest declares, read the way
 * Node reads it, or the index beside it when it declares nothing.
 */
function entryOf(root: string, manifest: Manifest): string {
  if (manifest.exports !== undefined || manifest.main !== undefined) {
    const declared = fileURLToPath(packageEntrySpecifier(root));
    if (!fs.existsSync(declared)) throw new Error(`${root} declares ${path.relative(root, declared)} as its entry, which is not there`);
    return declared;
  }
  const entry = ["index.ts", "index.js"].map((file) => path.join(root, file)).find((file) => fs.existsSync(file));
  if (!entry) throw new Error(`${root} has no entry: no \`exports\`, \`main\`, index.ts or index.js`);
  return entry;
}

/** The directory a copy goes into: the package's unscoped name without its `workflow-` prefix. */
function copyName(source: Source): string {
  const named = source.manifest.name?.split("/").at(-1) ?? path.basename(source.root);
  return named.replace(/^workflow-/, "");
}

/**
 * Every file the copy needs: the entry with every file it reaches by a
 * relative import, however deep, and for each directory those files sit in,
 * the diagram and manifest it holds — so a workflow imported by the one being
 * copied keeps its own shape and its own package boundary. A file outside the
 * source's root is refused, because the copy could not keep its path.
 */
function filesOf(source: Source): Copied[] {
  const copied = new Map<string, Copied>();
  const pending = [source.entry];
  while (pending.length > 0) {
    const file = pending.pop()!;
    if (copied.has(file)) continue;
    if (path.relative(source.root, file).startsWith("..")) {
      throw new Error(`${file} is imported from outside ${source.root}, so a copy could not keep its path`);
    }
    const rewrites = new Map<string, string>();
    for (const written of relativeImports(fs.readFileSync(file, "utf-8"))) {
      const reached = resolved(path.dirname(file), written, file);
      const asWritten = path.resolve(path.dirname(file), written);
      // Node imports the file a specifier names and nothing else, so a
      // `.js` that stood for its `.ts` is rewritten to the file copied.
      if (reached !== asWritten) rewrites.set(written, relativeSpecifier(path.dirname(file), reached));
      pending.push(reached);
    }
    copied.set(file, { file, rewrites });
  }
  for (const directory of directoriesOf(source.root, [...copied.keys()])) {
    for (const boundary of [DIAGRAM_FILE, "package.json"]) {
      const file = path.join(directory, boundary);
      if (fs.existsSync(file) && !copied.has(file)) copied.set(file, { file, rewrites: new Map() });
    }
  }
  const diagram = [path.dirname(source.entry), source.root].map((directory) => path.join(directory, DIAGRAM_FILE)).find((candidate) => copied.has(candidate));
  if (!diagram) throw new Error(`${source.root} has no ${DIAGRAM_FILE}, so what it would copy is not a workflow`);
  return [...copied.values()];
}

/** Every directory from the source's root down to each file. */
function directoriesOf(root: string, files: readonly string[]): Set<string> {
  const directories = new Set<string>([root]);
  for (const file of files) {
    for (let directory = path.dirname(file); directory.startsWith(root); directory = path.dirname(directory)) {
      directories.add(directory);
      if (directory === root) break;
    }
  }
  return directories;
}

/**
 * The relative specifiers a module imports: the string after `from`, after a
 * bare `import`, or inside `import(…)`. Read token by token, so a comment
 * between the tokens is skipped and an import written inside a comment or
 * another string is not one.
 */
export function relativeImports(text: string): string[] {
  const found = new Set<string>();
  let previous = "";
  for (const token of tokens(text)) {
    if (token.kind === "string" && ["from", "import", "import("].includes(previous) && /^\.{1,2}\//.test(token.value)) found.add(token.value);
    previous = token.kind === "punctuation" && token.value === "(" && previous === "import" ? "import(" : token.kind === "string" ? "string" : token.value;
  }
  return [...found];
}

type Token = { readonly kind: "string" | "word" | "punctuation"; readonly value: string };

/** A module's code as words, punctuation and plain strings, with comments and template literals left out. */
function* tokens(text: string): Generator<Token> {
  for (let at = 0; at < text.length;) {
    const [token, next] = tokenAt(text, at);
    if (token) yield token;
    at = next;
  }
}

/** The token that starts at `at`, if any, and where the next one may start. */
function tokenAt(text: string, at: number): [Token | undefined, number] {
  const char = text[at]!;
  if (char === "/" && text[at + 1] === "/") return [undefined, lineEnd(text, at)];
  if (char === "/" && text[at + 1] === "*") return [undefined, commentEnd(text, at)];
  if (char === "\"" || char === "'" || char === "`") {
    const end = stringEnd(text, at, char);
    return [char === "`" ? { kind: "punctuation", value: "`" } : { kind: "string", value: text.slice(at + 1, end) }, end + 1];
  }
  if (/\s/.test(char)) return [undefined, at + 1];
  const word = /^[A-Za-z_$][\w$]*/.exec(text.slice(at, at + 64))?.[0];
  return word ? [{ kind: "word", value: word }, at + word.length] : [{ kind: "punctuation", value: char }, at + 1];
}

function lineEnd(text: string, from: number): number {
  const end = text.indexOf("\n", from);
  return end < 0 ? text.length : end;
}

function commentEnd(text: string, from: number): number {
  const end = text.indexOf("*/", from + 2);
  return end < 0 ? text.length : end + 2;
}

/** Where a string that opens at `from` closes, past every escaped quote. */
function stringEnd(text: string, from: number, quote: string): number {
  for (let at = from + 1; at < text.length; at += 1) {
    if (text[at] === "\\") at += 1;
    else if (text[at] === quote) return at;
  }
  return text.length;
}

/** A relative specifier as a file: as written, or the TypeScript a `.js` specifier stands for. */
function resolved(directory: string, specifier: string, from: string): string {
  const exact = path.resolve(directory, specifier);
  const candidates = [exact, exact.replace(/\.js$/, ".ts"), `${exact}.ts`, `${exact}.js`, path.join(exact, "index.ts"), path.join(exact, "index.js")];
  const file = candidates.find((candidate) => fs.existsSync(candidate) && fs.statSync(candidate).isFile());
  if (!file) throw new Error(`${from} imports ${specifier}, which is not there`);
  return file;
}

function relativeSpecifier(from: string, to: string): string {
  const relative = path.relative(from, to).split(path.sep).join("/");
  return relative.startsWith(".") ? relative : `./${relative}`;
}

/**
 * What the copy depends on that its caller does not, as `name@range`, every
 * one checked against the registry before anything is written. A dependency
 * the caller already holds is skipped only when the version it holds is one
 * the copy can use; one it cannot is refused, because the copy would resolve
 * the caller's.
 */
async function dependenciesToInstall(
  source: Source,
  files: readonly Copied[],
  owned: Manifest,
  caller: string,
  runner: CommandRunner,
  spec: string,
): Promise<string[]> {
  const needed: string[] = [];
  const problems: string[] = [];
  for (const [dependency, ranges] of wantedBy(files)) {
    // Every copied module resolves the caller's one copy of a package, so
    // two ranges for it are one too many.
    if (ranges.size > 1) {
      problems.push(`${dependency} at both ${[...ranges].join(" and ")}, and the copy can only hold one`);
      continue;
    }
    const [range] = [...ranges] as [string];
    const held = owned.dependencies?.[dependency];
    const problem = held === undefined
      ? await unresolvable(runner, dependency, range)
      : unusable(caller, dependency, range, held);
    if (problem) problems.push(problem);
    else if (held === undefined) needed.push(`${dependency}@${range}`);
  }
  if (problems.length > 0) {
    throw new Error(`${source.manifest.name ?? spec} depends on ${problems.join("; ")}; nothing was copied`);
  }
  return needed;
}

/** Every range any manifest in the copy asks of each dependency. */
function wantedBy(files: readonly Copied[]): Map<string, Set<string>> {
  const wanted = new Map<string, Set<string>>();
  for (const { file } of files) {
    if (path.basename(file) !== "package.json") continue;
    for (const [dependency, range] of Object.entries(manifestAt(path.dirname(file)).dependencies ?? {})) {
      wanted.set(dependency, (wanted.get(dependency) ?? new Set()).add(range));
    }
  }
  return wanted;
}

async function unresolvable(runner: CommandRunner, dependency: string, range: string): Promise<string | undefined> {
  return (await resolvable(runner, dependency, range)) ? undefined : `${dependency}@${range}, which cannot be resolved`;
}

/** Why the version the caller holds will not do for the copy, or nothing when it will. */
function unusable(caller: string, dependency: string, range: string, declared: string): string | undefined {
  if (declared === range) return undefined;
  const held = installedVersion(caller, dependency);
  if (held !== undefined && satisfies(held, range)) return undefined;
  return `${dependency}@${range}, and ${path.basename(caller)} holds ${held ?? declared}`;
}

function installedVersion(caller: string, dependency: string): string | undefined {
  const file = path.join(caller, "node_modules", ...dependency.split("/"), "package.json");
  if (!fs.existsSync(file)) return undefined;
  return (JSON.parse(fs.readFileSync(file, "utf-8")) as { version?: string }).version;
}

/** A plain `x.y.z`; a prerelease or build suffix is not compared, so it is not read. */
function versionOf(value: string): number[] | undefined {
  const parts = /^(\d+)\.(\d+)\.(\d+)$/.exec(value);
  return parts ? parts.slice(1, 4).map(Number) : undefined;
}

/** Negative, zero or positive, as `a` sorts before, with or after `b`. */
function compared(a: readonly number[], b: readonly number[]): number {
  return a[0]! - b[0]! || a[1]! - b[1]! || a[2]! - b[2]!;
}

/**
 * Whether a version is in a range, for the ranges a workflow's manifest
 * writes: exact, `^`, `~` and `*`. Anything else is not guessed at.
 */
function satisfies(version: string, range: string): boolean {
  if (range === "*" || range === "latest") return true;
  const operator = /^[\^~]/.exec(range)?.[0] ?? "";
  const held = versionOf(version);
  const floor = versionOf(range.slice(operator.length));
  if (!held || !floor) return false;
  if (operator === "") return compared(held, floor) === 0;
  // A tilde keeps the minor fixed; a caret keeps the leftmost non-zero part.
  const fixed = operator === "~" ? 1 : floor.findIndex((part, index) => part > 0 || index === 2);
  return compared(held, floor) >= 0 && held.slice(0, fixed + 1).every((part, index) => part === floor[index]);
}

/** Whether the registry knows a version of a dependency in the range a callee asks for. */
async function resolvable(runner: CommandRunner, dependency: string, range: string): Promise<boolean> {
  const asked = await runner.run("npm", ["view", `${dependency}@${range}`, "version", "--json"]);
  return asked.ok && asked.stdout.trim() !== "" && asked.stdout.trim() !== "[]";
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { applyPlan, BRANCH_SETTINGS, Builds, callPath, cameFrom, CommandRunner, connects, DIAGRAM_FILE, DrawnTransition, expandDiagram, lendCheckouts, isDeferred, isPortBinding, markState, movedBy, notWrittenIn, Plan, Plugin, PluginContext, readDiagram, Registry, undeclaredIn, Workflow, WorkflowRuntime, WorkRecord } from "@amykit/core";
import { AmyConfig, writeWorkflowProfile } from "./config.js";
import { drawn } from "./drawn.js";

/** The directory where one machine keeps workflows that belong only to it. */
export function workflowsDirectory(home: string): string {
  return path.join(home, "workflows");
}

/**
 * A local workflow wins over a package with the same unscoped name.
 *
 * Scoped names remain package names: `@acme/oncall` is how an owner shares a
 * workflow later, while `oncall` stays a directory they can edit in place.
 * `index.ts` is what the scaffold writes and Node runs unbuilt; `index.js` is
 * what a workflow written before that, or by hand, still has.
 */
export function localWorkflow(home: string, spec: string): string | undefined {
  if (!isLocalName(spec)) return undefined;

  const directory = path.join(workflowsDirectory(home), spec);
  const entry = ["index.ts", "index.js"].map((file) => path.join(directory, file)).find((file) => fs.existsSync(file));
  return entry ? pathToFileURL(entry).href : undefined;
}

/** Makes an import specifier prefer this machine's workflow directory. */
export function workflowSpecifier(home: string, spec: string): string {
  return localWorkflow(home, spec) ?? spec;
}

/**
 * Writes the smallest complete workflow: a package that runs before editing.
 *
 * TypeScript, because a workflow is typed against the core it plugs into and
 * `sf` reads the shape of TypeScript and not of JavaScript. Node strips the
 * types and runs it from this directory as it is; it refuses TypeScript under
 * `node_modules`, so what is published is what `npm run build` compiles.
 */
export function writeWorkflow(home: string, name: string, config: AmyConfig, from?: string): string {
  if (!isLocalName(name)) {
    throw new Error("a workflow name is one directory name: letters, numbers, hyphens and underscores");
  }
  // Read before anything is written, so a diagram amy cannot read is refused
  // with its line and leaves no half-made directory behind.
  const drawn = from === undefined
    ? readDiagram(scaffoldDiagram(), `${name}/${DIAGRAM_FILE}`)
    : readDiagram(fs.readFileSync(from, "utf-8"), from);

  const directory = path.join(workflowsDirectory(home), name);
  if (fs.existsSync(directory)) {
    throw new Error(`${directory} already exists; choose another name or edit the workflow there`);
  }

  fs.mkdirSync(directory, { recursive: true });
  fs.writeFileSync(path.join(directory, "package.json"), JSON.stringify({
    name: `workflow-${name}`,
    version: "0.1.0",
    private: true,
    type: "module",
    main: "./dist/index.js",
    types: "./dist/index.d.ts",
    // The diagram is the workflow's shape: a package without it cannot mount.
    files: ["dist", DIAGRAM_FILE],
    scripts: { build: "tsc", typecheck: "tsc --noEmit", test: "node --test", prepack: "npm run build" },
    // A dependency, not a dev one: the published `dist/index.d.ts` imports
    // its types, as every shipped workflow package does.
    dependencies: { "@amykit/core": `^${groupVersion()}` },
    devDependencies: { [TESTKIT]: `^${groupVersion()}`, typescript: TYPESCRIPT },
  }, null, 2) + "\n", "utf-8");
  fs.writeFileSync(path.join(directory, "tsconfig.json"), JSON.stringify(SCAFFOLD_TSCONFIG, null, 2) + "\n", "utf-8");
  fs.writeFileSync(path.join(directory, DIAGRAM_FILE), drawn.text, "utf-8");
  const pieces = from === undefined ? scaffold(name) : scaffoldFromDiagram(name, drawn.states);
  for (const [file, text] of Object.entries(pieces)) fs.writeFileSync(path.join(directory, file), text, "utf-8");
  linkCore(directory);
  writeGuardrails(directory);
  writeWorkflowProfile(home, name, name, config);
  return directory;
}

/** Makes the declaration runnable before the workflow installs its package dependencies. */
function linkCore(directory: string): void {
  const entry = fileURLToPath(import.meta.resolve("@amykit/core"));
  const core = path.resolve(path.dirname(entry), "..");
  const scope = path.join(directory, "node_modules", "@amykit");
  fs.mkdirSync(scope, { recursive: true });
  fs.symlinkSync(core, path.join(scope, "core"), process.platform === "win32" ? "junction" : "dir");
}

/** The rules every workflow needs and no author should have to rediscover, shipped with this command. */
const GUARDRAILS = fileURLToPath(new URL("../guardrails/", import.meta.url));

/**
 * Gives a workflow its own `sf` policy: the guardrails as repo-local rules,
 * and one fixture per rule that `sf verify` proves it fires on. Each fixture
 * is a repository of its own, so it carries the one rule it trips.
 */
function writeGuardrails(directory: string): void {
  const factory = path.join(directory, ".software-factory");
  fs.cpSync(path.join(GUARDRAILS, "policy.yaml"), path.join(factory, "policy.yaml"));
  fs.cpSync(path.join(GUARDRAILS, "rules"), path.join(factory, "rules"), { recursive: true });

  for (const [id, file] of guardrailRules()) {
    const fixture = path.join(factory, "mutations", id);
    fs.cpSync(path.join(GUARDRAILS, "mutations", id), fixture, { recursive: true });
    fs.cpSync(path.join(GUARDRAILS, "rules", file), path.join(fixture, ".software-factory", "rules", file));
    fs.writeFileSync(path.join(fixture, ".software-factory", "policy.yaml"), fixturePolicy(id), "utf-8");
  }
}

/** Each guardrail's id, beside the file that declares it. */
export function guardrailRules(): Array<[id: string, file: string]> {
  return fs.readdirSync(path.join(GUARDRAILS, "rules")).sort().map((file) => {
    const id = /^id: (\S+)$/m.exec(fs.readFileSync(path.join(GUARDRAILS, "rules", file), "utf-8"))?.[1];
    if (!id) throw new Error(`guardrail ${file} declares no id`);
    return [id, file];
  });
}

function fixturePolicy(id: string): string {
  return `# Mutation fixture for ${id}. It is supposed to fail.\nversion: 1\nproject:\n  name: mutation-${id}\n  languages: [typescript]\ndocs:\n  scan: []\ngates: {}\nrules:\n  ${id}:\n    enabled: true\n`;
}

export async function checkWorkflow(
  home: string,
  name: string,
  config: AmyConfig,
  resolve: (spec: string) => string = (spec) => workflowSpecifier(home, spec),
): Promise<string[]> {
  return [...(await inspectWorkflow(home, name, config, resolve)).problems];
}

/** What a check found: what is wrong, and what is only not written or not walked yet. */
export interface WorkflowCheck {
  readonly problems: readonly string[];
  /** States whose decision is still a `notWritten()` stub. */
  readonly stubs: readonly string[];
  /** Arrows the diagram draws that the walkthrough never took. */
  readonly drawnNotWalked: readonly DrawnTransition[];
}

/**
 * Drives a workflow's lifecycle against its stub world, holding every move
 * to its diagram when it has one, and says what is left to write.
 *
 * A move the diagram does not draw is a problem, naming both ends. A
 * decision that is still a stub and an arrow nothing walked are the to-do
 * list of a workflow being written, not a failure of one.
 */
export async function inspectWorkflow(
  home: string,
  name: string,
  config: AmyConfig,
  resolve: (spec: string) => string = (spec) => workflowSpecifier(home, spec),
): Promise<WorkflowCheck> {
  const profile = config.workflows[name];
  if (!profile) return { problems: [`there is no \`${name}\` workflow in the config`], stubs: [], drawnNotWalked: [] };

  const registered = await registeredWorkflow(home, homeRelative(home, profile.workflow), resolve);
  if (typeof registered === "string") return { problems: [registered], stubs: [], drawnNotWalked: [] };
  return drive(registered);
}

/**
 * A configured workflow's diagram, as text that renders anywhere Mermaid
 * does, with one state marked when a piece of work is given.
 *
 * Expanded, each call is drawn as what it calls, and a piece of work is
 * marked at every depth of the calls it is in.
 */
export async function exportWorkflow(
  home: string,
  name: string,
  config: AmyConfig,
  options: {
    readonly state?: string;
    readonly record?: WorkRecord;
    readonly expand?: boolean;
    readonly resolve?: (spec: string) => string;
  } = {},
): Promise<string> {
  const profile = config.workflows[name];
  if (!profile) throw new Error(`there is no \`${name}\` workflow in the config`);
  const workflow = await shapeOf(home, homeRelative(home, profile.workflow), options.resolve ?? ((spec) => workflowSpecifier(home, spec)));
  const diagram = workflow.diagram;
  if (!diagram) throw new Error(`${name} has no ${DIAGRAM_FILE}, so there is no diagram to export`);
  if (options.expand) return expandDiagram(workflow, options.record ?? (options.state === undefined ? undefined : { id: name, state: options.state, updatedAt: "", attempts: {}, history: [] }));
  const state = options.state ?? options.record?.state;
  return state === undefined ? diagram.text : markState(diagram, state);
}

/**
 * The workflow a configured spec was bound to, read the cheapest way that
 * says it: a declaration carries its workflow unregistered, so nothing reads
 * a configuration only the mount validates. A declaration with no diagram
 * says so when it is read, and a plugin that registers its workflow by hand
 * is registered to be refused.
 */
async function shapeOf(home: string, spec: string, resolve: (spec: string) => string): Promise<Workflow> {
  const plugin = await importedPlugin(spec, resolve);
  if (typeof plugin === "string") throw new Error(plugin);
  const declared = (plugin as { workflow?: Workflow }).workflow;
  if (declared) return declared;
  const registered = await registration(home, spec, resolve);
  if (typeof registered === "string") throw new Error(registered);
  return registered.workflow;
}

/** A configured path is relative to amy's home, as the mount resolves it, not to wherever the command runs. */
function homeRelative(home: string, spec: string): string {
  return spec.startsWith(".") ? path.resolve(home, spec) : spec;
}

interface RegisteredWorkflow {
  workflow: Workflow;
  runtime: WorkflowRuntime;
  now: () => Date;
}

async function registeredWorkflow(home: string, spec: string, resolve: (spec: string) => string): Promise<RegisteredWorkflow | string> {
  const registered = await registration(home, spec, resolve);
  if (typeof registered === "string") return registered;
  const { workflow, contributions, builds, problems, now } = registered;

  builds.buildAll();
  if (problems.length > 0) return problems.join("; ");

  const runtime = contributions.get("workflow-runtime")?.get(workflow.name) as WorkflowRuntime | undefined;
  return runtime ? { workflow, runtime, now } : `${workflow.name}: contributed no runtime, so nothing here knows how to run its actions`;
}

interface Registration {
  workflow: Workflow;
  contributions: Map<string, Map<string, object>>;
  builds: Builds;
  problems: string[];
  now: () => Date;
}

/**
 * The workflow a plugin registers, with nothing deferred built yet.
 *
 * Enough to read its shape: building its runtime would ask for the ports it
 * needs, and only a mount has them.
 */
async function registration(home: string, spec: string, resolve: (spec: string) => string): Promise<Registration | string> {
  const plugin = await importedPlugin(spec, resolve);
  if (typeof plugin === "string") return plugin;

  let workflow: Workflow | undefined;
  const contributions = new Map<string, Map<string, object>>();
  // Deferred contributions are built the way the mount builds them: once
  // registration is over, each once, a dependency on demand, a circle refused.
  const problems: string[] = [];
  const builds = new Builds(problems);
  const registry = recordingRegistry(plugin.name, (value) => { workflow = value; }, contributions, builds);
  const now = () => new Date("2026-01-01T00:00:00.000Z");
  try {
    await plugin.register(registry, context(home, now, contributions, builds, () => workflow));
  } catch (error) {
    return `${spec}: failed to register — ${message(error)}`;
  }
  return workflow ? { workflow, contributions, builds, problems, now } : `${spec}: registered no workflow`;
}

async function importedPlugin(spec: string, resolve: (spec: string) => string): Promise<Plugin | string> {
  try {
    const specifier = resolve(spec);
    const loaded = (await import(specifier)) as { plugin?: Plugin };
    return loaded.plugin ? drawn(loaded.plugin, specifier) : `${spec}: imported, but exports no \`plugin\``;
  } catch (error) {
    const unbuilt = (error as { code?: unknown }).code === "ERR_UNKNOWN_FILE_EXTENSION"
      ? "; this Node cannot run TypeScript unbuilt, which takes 22.18 or later"
      : "";
    return `${spec}: could not be imported — ${message(error)}${unbuilt}`;
  }
}

function recordingRegistry(
  plugin: string,
  setWorkflow: (workflow: Workflow) => void,
  contributions: Map<string, Map<string, object>>,
  builds: Builds,
): Registry {
  return {
    queue: () => undefined, store: () => undefined, engine: () => undefined,
    workflow: setWorkflow, port: () => undefined, action: () => undefined,
    contribute: (collection, name, value) => {
      const values = contributions.get(collection) ?? new Map<string, object>();
      values.set(name, value);
      contributions.set(collection, values);
      if (isDeferred(value)) builds.defer(value, plugin, `\`${name}\` in \`${collection}\``, (built) => values.set(name, built));
    },
  };
}

function context(
  home: string,
  now: () => Date,
  contributions: Map<string, Map<string, object>>,
  builds: Builds,
  workflow: () => Workflow | undefined,
): PluginContext {
  const runner: CommandRunner = { run: async () => ({ ok: true, exitCode: 0, stdout: "", stderr: "" }) };
  return {
    config: {}, runner, now,
    paths: { state: home },
    readOnly: false,
    contributions: (collection) => builds.collection(contributions.get(collection)),
    port: () => undefined,
    checkouts: () => lendCheckouts(runner, { workspaceRoot: home, defaultBranch: BRANCH_SETTINGS.defaultBranch.default }),
    workflow: () => workflow() as Workflow<never, never> | undefined,
  };
}

async function drive({ workflow, runtime, now }: RegisteredWorkflow): Promise<WorkflowCheck> {
  const unimplemented = unimplementedActions(workflow, runtime);
  if (unimplemented.length > 0) return { problems: unimplemented, stubs: [], drawnNotWalked: [] };
  const created = recordFor(workflow, runtime, now);
  if (typeof created === "string") return { problems: [created], stubs: [], drawnNotWalked: [] };
  let record = created;
  const reached = new Set<string>();
  const walked = new Set<string>();
  let stopped = false;
  const problems = record.state === workflow.initialState ? [] : [`${workflow.name}: newRecord starts at \`${record.state}\`, not \`${workflow.initialState}\``];

  for (let move = 0; move < 32 && problems.length === 0; move += 1) {
    reached.add(record.state);
    lanesOf(workflow, record, reached, walked);
    const next = await moveOnce(workflow, runtime, record, now);
    if (typeof next === "string") { problems.push(next); break; }
    if (next.kind === "stub") { stopped = true; break; }
    if (next.kind === "settled" || next.kind === "wait") break;
    walked.add(`${record.state}\u0000${next.record.state}`);
    record = next.record;
  }
  const stubs = await stubsIn(workflow, runtime, created);
  const inside = insideCalls(workflow, record, "", walked);
  return {
    // A walk that stopped at a decision nobody has written yet says nothing
    // about where the finished workflow ends: the stubs are the to-do list.
    problems: [...problems, ...inside, ...(stopped ? [] : completionProblems(workflow, record, reached))],
    stubs,
    drawnNotWalked: drawnEdges(workflow, "").filter((edge) => !walked.has(`${edge.from}\u0000${edge.to}`)),
  };
}

/**
 * Every move each call made, held to the diagram of the workflow it called
 * and added to what was walked, named by the call state it happened in
 * (`REVIEW/READING`). A child keeps its whole history, so the record the walk
 * ended with says every move made inside it.
 */
function insideCalls(workflow: Workflow, record: WorkRecord, prefix: string, walked: Set<string>): string[] {
  const problems: string[] = [];
  for (const child of Object.values(record.calls ?? {})) {
    const state = /\/([A-Za-z_]\w*)#\d+$/.exec(child.id)?.[1];
    const callee = state ? workflow.calls?.[state] : undefined;
    if (!state || !callee) continue;
    const at = `${prefix}${state}/`;
    for (const move of child.history) {
      walked.add(`${at}${move.from}\u0000${at}${move.to}`);
      if (callee.diagram && !connects(callee.diagram, move.from, move.to, cameFrom(child.history.slice(0, child.history.indexOf(move)), move.from))) {
        problems.push(`${workflow.name} → ${state}: \`${move.from}\` moves to \`${move.to}\`, and ${callee.name}'s ${DIAGRAM_FILE} draws no arrow from \`${move.from}\` to \`${move.to}\``);
      }
    }
    problems.push(...insideCalls(callee, child, at, walked));
  }
  return problems;
}

/**
 * A record waiting in a fork reaches every lane it started, and walks the
 * arrow into each and, once a lane has ended, the one out of it to the join:
 * a lane is never a record's own state, so the walk would never see either.
 */
function lanesOf(workflow: Workflow, record: WorkRecord, reached: Set<string>, walked: Set<string>): void {
  const fork = workflow.diagram?.forks[record.state];
  for (const lane of fork?.lanes ?? []) {
    const call = record.lanes?.[lane]?.call;
    const child = call === undefined ? undefined : record.calls?.[call];
    if (!child) continue;
    reached.add(lane);
    walked.add(`${record.state}\u0000${lane}`);
    if (workflow.calls?.[lane]?.terminalStates.includes(child.state)) walked.add(`${lane}\u0000${fork!.join}`);
  }
}

/** The arrows a workflow draws, and those of every workflow it calls, named by the call state they sit in. */
function drawnEdges(workflow: Workflow, prefix: string): DrawnTransition[] {
  const own = (workflow.diagram?.transitions ?? []).map((edge) => ({ ...edge, from: `${prefix}${edge.from}`, to: `${prefix}${edge.to}` }));
  const called = Object.entries(workflow.calls ?? {}).flatMap(([state, callee]) => drawnEdges(callee, `${prefix}${state}/`));
  return [...own, ...called];
}

/** Every drawn state whose decision is still a stub, asked one state at a time. */
async function stubsIn(workflow: Workflow, runtime: WorkflowRuntime, first: WorkRecord): Promise<string[]> {
  const stubs: string[] = [];
  for (const state of workflow.diagram?.states ?? []) {
    try {
      const record = { ...first, state };
      if (notWrittenIn(workflow.plan(record, await runtime.observe(record), runtime.policy)) === state) stubs.push(state);
    } catch {
      // A decision that cannot be asked out of turn is written; it is the
      // walk's to judge, not this list's.
    }
  }
  return stubs;
}

/** Declared actions with nothing behind them, which the mount would refuse at boot. */
function unimplementedActions(workflow: Workflow, runtime: WorkflowRuntime): string[] {
  if (runtime.actions === null || typeof runtime.actions !== "object") {
    return [`${workflow.name}: its runtime declares no \`actions\` — one map from each action it emits to what runs it`];
  }
  return Object.entries(runtime.actions)
    .filter(([, implementation]) => typeof implementation !== "function" && !isPortBinding(implementation))
    .map(([name]) => `${workflow.name}: declares \`${name}\` with no implementation — give it a handler, or a port and a method`);
}

function recordFor(workflow: Workflow, runtime: WorkflowRuntime, now: () => Date): WorkRecord | string {
  try { return runtime.newRecord("workflow-check", now()); }
  catch (error) { return `${workflow.name}: newRecord failed — ${message(error)}`; }
}

async function moveOnce(workflow: Workflow, runtime: WorkflowRuntime, record: WorkRecord, now: () => Date): Promise<{ kind: "advance"; record: WorkRecord } | { kind: "settled" } | { kind: "stub" } | { kind: "wait" } | string> {
  try {
    const observation = await runtime.observe(record);
    const plan = workflow.plan(record, observation, runtime.policy);
    const [missing] = undeclaredIn(runtime, plan);
    if (missing) return `${workflow.name}: plan emits \`${missing}\`, which its runtime never declared in \`actions\``;
    if (plan.kind === "settled") return notWrittenIn(plan) === record.state ? { kind: "stub" } : { kind: "settled" };
    if (plan.kind === "wait") return waitingProblem(workflow, runtime, record);
    if (plan.kind === "act") return movedInACall(workflow, runtime, record, plan, observation, now);
    if (!workflow.states.includes(plan.to)) return `${workflow.name}: advances to undeclared state \`${plan.to}\``;
    const diagram = workflow.diagram;
    if (diagram && !connects(diagram, record.state, plan.to, cameFrom(record.history, record.state))) {
      return `${workflow.name}: \`${record.state}\` moves to \`${plan.to}\`, and ${DIAGRAM_FILE} draws no arrow from \`${record.state}\` to \`${plan.to}\``;
    }
    const folded = runtime.apply(applyPlan(record, plan, now()), plan, {}, observation, now(), movedBy(record, plan));
    return folded.state === plan.to ? { kind: "advance", record: folded } : `${workflow.name}: one look did not make the transition it claimed`;
  } catch (error) { return `${workflow.name}: could not plan \`${record.state}\` — ${message(error)}`; }
}

/**
 * A look inside a call is its caller's `act`: the caller stays where it is
 * while the workflow it called moves. That is progress, not acting in place,
 * when the record's path through its calls changed.
 */
function movedInACall(workflow: Workflow, runtime: WorkflowRuntime, record: WorkRecord, plan: Plan, observation: unknown, now: () => Date): { kind: "advance"; record: WorkRecord } | string {
  const folded = runtime.apply(applyPlan(record, plan, now()), plan, {}, observation, now(), null);
  // A lane's move changes its own record and no call path, so lanes count too.
  const where = (current: WorkRecord) => callPath(current).flatMap((step) => [
    `${step.id}@${step.state}`,
    ...Object.values(step.lanes ?? {}).map((lane) => `${lane.call}@${step.calls?.[lane.call]?.state}`),
  ]).join(">");
  return where(folded) === where(record)
    ? `${workflow.name}: did not settle; it kept acting in \`${record.state}\``
    : { kind: "advance", record: folded };
}

async function waitingProblem(workflow: Workflow, runtime: WorkflowRuntime, record: WorkRecord): Promise<{ kind: "wait" } | string> {
  const again = workflow.plan(record, await runtime.observe(record), runtime.policy);
  return again.kind === "wait" ? { kind: "wait" } : `${workflow.name}: a waiting state moved before the world did`;
}

function completionProblems(workflow: Workflow, record: WorkRecord, reached: Set<string>): string[] {
  const problems = workflow.terminalStates.includes(record.state) ? [] : [`${workflow.name}: did not settle in a terminal state`];
  return [...problems, ...workflow.states.filter((state) => !reached.has(state)).map((state) => `${workflow.name}: declares \`${state}\`, but its walkthrough never reaches it`)];
}

function isLocalName(value: string): boolean {
  return /^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(value);
}

function message(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** The kit the scaffold's own suite runs, which moves in the same version group as this command. */
const TESTKIT = "@amykit/workflow-testkit";

/** The first TypeScript with `erasableSyntaxOnly`, which holds the scaffold to what Node can strip; it also rewrites `.ts` imports. */
const TYPESCRIPT = "^5.8.0";

/**
 * Compiles `index.ts` and the pieces it imports for publishing; the suite
 * imports it by its `.ts` name and is never built. Each piece is imported by
 * its `.ts` name too, which Node runs as it is and the build rewrites.
 */
const SCAFFOLD_TSCONFIG = {
  compilerOptions: {
    target: "ES2022",
    module: "NodeNext",
    moduleResolution: "NodeNext",
    strict: true,
    erasableSyntaxOnly: true,
    verbatimModuleSyntax: true,
    rewriteRelativeImportExtensions: true,
    declaration: true,
    outDir: "dist",
    skipLibCheck: true,
  },
  include: ["index.ts"],
};

/**
 * This command's version, which is every `@amykit` package's version: they
 * move as one fixed group (`.changeset/config.json`), so the core and the
 * testkit a scaffold names always exist at it.
 */
function groupVersion(): string {
  const manifest = JSON.parse(fs.readFileSync(new URL("../package.json", import.meta.url), "utf-8")) as { version: string };
  return manifest.version;
}

/**
 * The three pieces a workflow is, each in the file that says it: where work
 * can go in `workflow.mmd`, where it goes next in `decide.ts`, what happens
 * in the world in `actions.ts`, and the one `defineWorkflow` call that joins
 * them in `index.ts`.
 */
interface Scaffold {
  readonly "decide.ts": string;
  readonly "actions.ts": string;
  readonly "index.ts": string;
  readonly "index.test.ts": string;
}

function scaffold(name: string): Scaffold {
  return {
    "decide.ts": `// One decision per state workflow.mmd draws: where this piece of work goes
// next, given what the world says. Pure: nothing here awaits anything.
import { act, advance, settled, type Plan, type WorkRecord } from "@amykit/core";

export const decide: Record<string, (record: WorkRecord) => Plan> = {
  received: () => advance("done", "the work was received"),
  done: () => settled("the workflow is complete"),
};
`,
    "actions.ts": actionsFile(),
    "index.ts": indexFile(name, `// This workflow belongs to this machine. Edit workflow.mmd, decide.ts and
// actions.ts; this file only joins them. \`amy workflow check ${name}\` drives
// it before it drives real work, and \`npm test\` runs the machine's own suite
// over it. Node runs it as it is; \`npm run build\` compiles it for publishing.`),
    "index.test.ts": suite(),
  };
}

function scaffoldDiagram(): string {
  return `stateDiagram-v2
    [*] --> received
    received --> done: the work was received
    done --> [*]
`;
}

/**
 * A workflow whose shape is somebody's diagram, copied in beside it.
 *
 * It declares no states: the host reads them from `workflow.mmd`. Every
 * decision is a `notWritten()` stub, so it mounts as it is, settles rather
 * than guesses a move, and `amy workflow check` lists what is left to write.
 */
function scaffoldFromDiagram(name: string, states: readonly string[]): Scaffold {
  const decisions = states.map((state) => `  ${JSON.stringify(state)}: notWritten(),`).join("\n");
  return {
    "decide.ts": `// One decision per state workflow.mmd draws: where this piece of work goes
// next, given what the world says. Each is a stub until it is written;
// \`amy workflow check ${name}\` lists what is left to write.
import { notWritten, type Plan, type WorkRecord } from "@amykit/core";

export const decide: Record<string, (record: WorkRecord) => Plan> = {
${decisions}
};
`,
    "actions.ts": actionsFile(),
    "index.ts": indexFile(name, `// This workflow's shape is workflow.mmd beside this file: the states, where
// work starts, waits and ends. Its decisions are decide.ts and what they do
// in the world is actions.ts; this file only joins them.`),
    "index.test.ts": suite(),
  };
}

function actionsFile(): string {
  return `// What happens in the world. Every action a decision may emit, keyed by
// name: a handler given (scope, work, effect), whose \`scope.ports\` are the
// ports index.ts \`needs\`, bound to this piece of work, and whose
// \`scope.announce\` says a word to the operator; or { port, method } for a
// mounted port the host calls.
import type { WorkRecord } from "@amykit/core";

export const actions = {};

// What the actions produced, folded into the record. \`record\` has already
// moved: read where it came from in \`moved.from\`, never in \`record.state\`.
export function remember(record: WorkRecord): WorkRecord { return record; }
`;
}

function indexFile(name: string, header: string): string {
  return `${header}
import { defineWorkflow, type ConfigSchema } from "@amykit/core";
import { actions, remember } from "./actions.ts";
import { decide } from "./decide.ts";

export const plugin = defineWorkflow({
  name: ${JSON.stringify(name)},
  configSchema: {} satisfies ConfigSchema,
  policy: {},
  // The ports the actions use, each \`port<T>()\` or \`optional<T>()\`.
  needs: {},
  record: () => ({}),
  decide,
  discover: async () => ["example"],
  observe: async () => ({}),
  actions,
  remember: (_scope, record) => remember(record),
});
`;
}

/**
 * The suite every workflow needs and nobody writes, from its first commit.
 *
 * `node:test` because it is the runner a machine with node already has; the
 * kit takes whichever runner it is handed. A world is one situation the
 * workflow can be in, and adding one is how a new state gets proven. The
 * workflow is mounted the way amy mounts it, so its runtime is the one the
 * pieces build, and a state with no decision is refused by name here too.
 */
function suite(): string {
  return `import { describe, it } from "node:test";
import os from "node:os";
import { mount, withDiagramBeside, WORKFLOW_RUNTIME, type WorkflowRuntime } from "@amykit/core";
import { conforms } from "${TESTKIT}";
import { plugin } from "./index.ts";

// The workflow as amy mounts it: its states read from workflow.mmd beside it,
// its runtime built from decide.ts and actions.ts. Red until every decision
// is written; each finding is one left to write.
const drawn = withDiagramBeside(plugin, import.meta.url);
const mounted = await mount([drawn], {}, {
  runner: { run: async () => ({ ok: true, exitCode: 0, stdout: "", stderr: "" }) },
  now: () => new Date(),
  paths: { workspace: os.tmpdir(), checkouts: {}, state: os.tmpdir() },
});
if (!mounted.ok) throw new Error(mounted.problems.join("; "));
const runtime = mounted.mounted.contributions.get(WORKFLOW_RUNTIME)?.get(drawn.workflow.name) as WorkflowRuntime;

conforms(drawn.workflow, {
  runner: { describe, it },
  runtime: () => runtime,
  worlds: [{ name: "a piece of work arrives" }],
});
`;
}

